window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["27154533"]={"book":{"id":27154533,"title":"终身成长","author":"[美] 卡罗尔·德韦克","translator":"楚祎楠","publisher":"后浪丨江西人民出版社","pubdate":"2017-11","isbn":"9787210096528","tags":["自我提升","成长","思维方式","个人管理","心理学","思维","思维哲学-思维方法","心理"],"memCount":6},"np":1,"pb":[39],"idx":[{"i":19837,"t":"终身成长","l":"TF3-3","c":"鱼渔todo","g":1,"p":1},{"i":19758,"t":"固定思维和成长性思维","l":"TF3-2","c":"鱼渔todo","g":1,"p":1},{"i":19315,"t":"终身成长","l":"TF3-2","c":"周舟小太阳","g":1,"p":1},{"i":18688,"t":"走向成长型思维模式","l":"TF3-2","c":"天空粉黑","g":1,"p":1},{"i":18590,"t":"迈出第一步","l":"TF1-1","c":"封邑","g":1,"p":1},{"i":18182,"t":"思维转变和行为调整，促进目标达成","l":"TF3-3","c":"倩倩.","g":1,"p":1},{"i":17964,"t":"让计划可实行的三步法","l":"TF2-3","c":"罗启明","g":1,"p":1},{"i":16626,"t":"成长三步法","l":"TF2-3","c":"闪电侠","g":1,"p":1},{"i":16189,"t":"在两性关系中如何进行有效沟通","l":"TF3-1","c":"拆书家十八","g":1,"p":1},{"i":15864,"t":"如何了解固定型思维、如何正确有效传递成长型思维","l":"TF2-4","c":"拆书家十八","g":1,"p":1},{"i":15722,"t":"如何识别固定型思维、如何有效传授成长型思维模式","l":"TF2-4","c":"拆书家十八","g":1,"p":1},{"i":15663,"t":"如何理解固定性思维和成长型思维，如何影响他人拥有成长型思维","l":"TF2-4","c":"拆书家十八","g":1,"p":1},{"i":15425,"t":"如何用成长型思维模式进行表扬","l":"TF3-2","c":"紫珺","g":1,"p":1},{"i":14430,"t":"面对挫折三步法","l":"TF3-1","c":"windy琴","g":1,"p":1},{"i":14076,"t":"通往成功之路","l":"TF2-3","c":"春儿","g":1,"p":1},{"i":13099,"t":"两种思维之下的不同生活","l":"TF1-1","c":"如心","g":1,"p":1},{"i":13079,"t":"用成长型思维改善关系","l":"TF3-1","c":"陈松波","g":1,"p":1},{"i":12143,"t":"如何识别固定型思维，并引导转变","l":"TF3-2","c":"曾燕","g":1,"p":1},{"i":12024,"t":"如何用成长型思维表扬孩子。","l":"TF3-2","c":"毛群","g":1,"p":1},{"i":11943,"t":"成长型思维","l":"TF3-1","c":"毛群","g":1,"p":1},{"i":11320,"t":"培养成长型思维","l":"TF3-1","c":"DorisPGY","g":1,"p":1},{"i":11164,"t":"培养成长型思维","l":"TF3-1","c":"DorisPGY","g":1,"p":1},{"i":10374,"t":"孩子受挫时，如何抓住时机培养成长型思维？","l":"TF3-1","c":"付盈盈","g":1,"p":1},{"i":9730,"t":"夸孩子聪明，难道错了吗？","l":"TF3-3","c":"吴佳音","g":1,"p":1},{"i":9504,"t":"发现你的思维模式","l":"TF1-1","c":"卷毛小蓝","g":0,"p":1},{"i":9493,"t":"通过制定“可实施计划”提升行动力  ","l":"TF2-3","c":"灵君","g":1,"p":1},{"i":9294,"t":"终身成长：培养成长型思维模式","l":"TF3-2","c":"alisa33","g":1,"p":1},{"i":8654,"t":"夸孩子聪明，难道我错了吗？","l":"TF3-3","c":"吴佳音","g":1,"p":1},{"i":8491,"t":" 如何打破固定思维","l":"TF3-1","c":"原来的原","g":1,"p":1},{"i":8481,"t":"如何打破固定型思维，让自己终身成长","l":"TF3-1","c":"原来的原","g":1,"p":1},{"i":8480,"t":"如何打破固定型思维","l":"TF3-1","c":"原来的原","g":1,"p":1},{"i":7753,"t":"用成长型思维改善关系","l":"TF3-1","c":"陈松波","g":1,"p":1},{"i":7719,"t":"夸孩子聪明，我错了吗？","l":"TF3-3","c":"吴佳音","g":1,"p":1},{"i":7333,"t":"走向成长性思维模式","l":"TF3-2","c":"龚婷","g":1,"p":1},{"i":7153,"t":"成长型思维","l":"TF3-1","c":"李佩璇","g":1,"p":1},{"i":6699,"t":"走向成长性思维","l":"TF3-2","c":"龚婷","g":1,"p":1},{"i":6208,"t":"运用成长型思维不再执着于眼前的成败，从学习和成长中获得快乐","l":"TF3-1","c":"张琢","g":1,"p":1},{"i":5841,"t":"转变思维，改变人生","l":"TF3-2","c":"宋福珍（豆豆）","g":1,"p":1},{"i":5496,"t":"如何打破固定型思维，让自己具有成长型思维","l":"TF3-1","c":"瞌睡的猫","g":1,"p":1}],"ms":[{"id":19837,"topic":"终身成长","learn_goal":"","remark":"精准识别自己的思维模式，在亲友 孩子遇到挫折时，能用成长型思维启发对方直面失败，保持正向成长","level":"TF3-3","duration":45,"status":30,"type":0,"chaishujia":{"username":"鱼渔todo","city":""},"club":{"name":"宁波不服书分舵","city":"宁波"},"prologue":"\u003cp>3-3过级主题《我们不是不会失败，而是会如何面对失败》\u003c/p>\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>大家好，我叫鱼渔，我是一个十几年财务工作者，两个孩子的妈妈，一个二级拆书家，正向3级拆书家努力奋斗着。基于后续需要现场演练，目前除了观察家拿铁，只有3人（追梦、阿辉、壹壶咖啡）现在做一个分组。\u003c/p>\u003cp>【学习目标\u003c/p>\u003cp>学习总目标：学习者跟随我完成本次学习后，在面临失败、困难、挫折时，能判断出你当时的思维模式，能正确面对失败，持续成长。\u003c/p>\u003cp>拆页一学习目标：学习者在完成第一个拆页学习后，在遇到困难、挫败时，能够运用（行为）成长型思维和固定型思维的不同表现，区分出自己的不同的思维模式，并现场能够用“成长型思维模式四步法”编写剧本（界定）。\u003c/p>\u003cp>拆页二学习目标：学习者学习完第二个拆页后能在孩子、亲友或下属遇到失败、挫折的场景中，能使用“建设性反馈四步法”引导对方直面失败。\u003c/p>\u003cp>第二个拆页是第一个拆页的具体场景运用，二者是递进关系。\u003c/p>\u003cp>\u003cstrong>【场景法图书介绍】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【事件场景】\u003c/strong>\u003c/p>\u003cp>我讲一个发生不久的让我恨铁不成钢的故事。2月28日周六，我们在上班孩子还没上学，孩子的围棋兴趣班开始了，由于我们在上班没办法送孩子去上课，就给四年级的大宝打了一个滴滴送去商场上课。一般商场是10点开门，我们上课老师由于下午有事就把课程调整在了9点半。孩子到了商场，可商场的大门还没开门，孩子就很生气给我打电话，说：“商场门还没开，没办法进去，打车把我送回去”。\u003c/p>\u003cp>我跟他说：“我们经常进出的大门的旁边就有一个电梯，可以直达教室，没有时间限制。”\u003c/p>\u003cp>孩子这时已经生气了：“我怎么知道怎么走？”\u003c/p>\u003cp>“往我们停车的入口走，往前5米就是。我们上次看电影刚刚走过的。”\u003c/p>\u003cp>“我不知道！”孩子生气地挂掉电话。再打电话就不接电话了。\u003c/p>\u003cp>我很生气，也知道孩子陷入了固定性思维。在遇到小问题小困难就退缩，不肯努力想办法去解决，还把问题推给别人。\u003c/p>\u003cp>\u003cstrong>【提问】\u003c/strong>：请问各位伙伴，您家孩子有没有跟我家孩子一样陷入“固定性思维”的时刻？你自己有没有遇事第一直觉是自己做不到的时刻？比如认为你天生感性、天生理性、天生具备某方面能力或不具备某方面能力？比如认为智力天生的，后天难以改变？\u003c/p>\u003cp>\u003cstrong>【影响】\u003c/strong>：如果你在某个时刻存在“固定性思维”，那这种“固定型思维模式”必定会给你带来一些负面影响：比如害怕挑战、忽视努力的价值、不能接受批评等。\u003c/p>\u003cp>\u003cstrong>【解决】\u003c/strong>：有没有改变思维模式的方法呢？有的，卡罗尔·德韦克的《终身成长》就给出了答案，用成长型思维模式的四步骤，可以帮我们转换思维，从而可以帮我们拥抱挑战，重新定义失败，最终实现长期成长。\u003c/p>\u003cp>听了我以上的介绍，大家一定很想了解自己到底属于固定型思维模式还是成长型思维模式。\u003c/p>\u003cp>接下来请大家做一个简单的测试题。以下是一套5道题的思维模式测试题，每题按“完全不符合（1分）\u003c/p>\u003cp>— 不太符合（2分）— 一般（3分）— 比较符合（4分）— 完全符合（5分）”计分，测试一下自己属\u003c/p>\u003cp>于哪种思维。根据自己的第一直觉为自己打分，并汇总分数，做好的小伙伴可以在屏幕打1示意我。\u003c/p>\u003cp>\u003cbr>5—10分：成长型思维倾向明显\u003c/p>\u003cp>你更相信能力可以通过努力提升，面对失败和挑战时，会关注“如何进步”而非“否定自己”。\u003c/p>\u003cp>这种思维让你更愿意突破舒适区，从错误和他人的成功中学习，长期来看更容易实现持续成长。\u003c/p>\u003cp>11—15分：两种思维混合存在\u003c/p>\u003cp>你在某些情境下会展现成长型思维（比如主动尝试新事物），但在压力或挫折中可能陷入固定型思维\u003c/p>\u003cp>（比如怀疑自己的能力）。可以有意识地调整对“失败”和“能力”的认知，比如把“我做不到”换成“我还没做到，需要哪些方法”。\u003c/p>\u003cp>16—25分：固定型思维倾向明显\u003c/p>\u003cp>你可能更倾向于认为能力是“天生的”，害怕挑战带来的“失败标签”，对批评和他人的成功也更容易产生负面情绪。\u003c/p>\u003cp>建议从微小的挑战开始，记录自己通过努力取得的进步，逐步培养“能力可成长”的信念——就像《终身成长》中说的，思维模式的改变，本身就是成长的开始。\u003c/p>\u003cp>当然以上测评仅供参考，分数只代表对曾经的自己的评分，相信通过今天的学习，我们对自己更了解，同时，能更好地运用今天学到的技能，让自己的状态变得越来越好。\u003c/p>","ratings_count":3,"texts":[{"id":24271,"quote":"\u003cp>《终身成长》P308\u003c/p>","explains":"\u003cp>WHAT:\u003c/p>\u003cp>提问一：这个图片讲述了哪两种不同思维模式？对智力的看法是怎样的呢？有没有小伙伴回答一下（互动）\u003c/p>\u003cp>学习者回答：成长性思维和固定性思维。\u003c/p>\u003cp>这张图描述了1.在面对挑战时，这2种不同思维的有什么不一样的表现呢？\u003c/p>\u003cp>学习者回答：固定性思维：倾向于回避挑战。他们认为挑战意味着暴露自己的不足，可能会失败，而失败会直接证明自己“能力不行”。因此，他们更愿意停留在自己熟悉的、安全的领域。\u003c/p>\u003cp>成长性思维：欢迎并拥抱挑战。他们将挑战视为学习和成长的机会，是让大脑变得更聪明的必经之路。即使失败，也是一次有价值的反馈。\u003c/p>\u003cp>拆书家回应：看来大家对原文图片观察的很仔细，对固定型思维模式和成长型思维模式有了很清晰的认识了。（针对原文的提问式回应）\u003c/p>\u003cp>2.固定性思维和成长性思维是如何看待努力的呢？\u003c/p>\u003cp>固定性思维：认为努力是徒劳的，甚至是丢脸的。他们觉得“如果你需要努力，说明你天生不擅长这个”。天才不需要努力，努力反而证明了你不够聪明或有天赋。\u003c/p>\u003cp>成长性思维：认为努力是通往精通的必经之路。他们相信“天才也需要努力”，能力就像肌肉，需要通过刻苦练习来锻炼和增强。努力和策略是成长的关键部分。\u003c/p>\u003ch3>3.固定性思维和成长性思维在面对挫折与失败有什么不同呢？\u003c/h3>\u003cp>固定性思维：轻易放弃。遭遇挫折时，他们会认为这已经到了自己能力的极限，并因此否定自己（“我果然不行”）。失败是一个身份标签（“我是个失败者”）。\u003c/p>\u003cp>成长性思维：在挫折面前坚持不懈。他们将挫折视为需要解决问题、调整策略的信号，而不是个人能力的定论。失败是一个事件、一次经历（“我这次失败了”），是获取信息的来源。\u003c/p>\u003ch3>4固定性思维和成长性思维在对待批评与反馈有什么不同的反应呢？\u003c/h3>\u003cp>固定性思维：忽视有用的负面反馈，或对批评产生强烈的防御和敌意。因为他们将批评视为对自身价值的攻击，而不是对行为的改进建议。\u003c/p>\u003cp>成长性思维：从批评中学习。他们会主动听取反馈，即使感到不快，也能剥离情绪，分析其中是否有可以帮助自己进步的部分。\u003c/p>\u003ch3>5.固定性思维和成长性思维在看到他人成功时有什么不同的看法呢？\u003c/h3>\u003cp>固定性思维：感到威胁和嫉妒。他人的成功仿佛一面镜子，照出了自己的不足。他们可能会通过贬低他人的成功（“他只是运气好”）来维护自己的自我价值感。\u003c/p>\u003cp>成长性思维：从中获得启发和新知。他们将他人的成功视为一个学习榜样，会思考：“他是怎么做到的？我可以从中学到什么？”\u003c/p>\u003cp>总结如下：\u003c/p>\u003cp>文中给了两个相反概念，为了验证一下我们是否真的掌握了他的差别。我们做一下下面的辨析题，从而更清晰适用边界：\u003c/p>\u003cp>1、前面讲到在遇到挫折时，固定性思维会轻易放弃。成长性思维则在挫折面前坚持不懈。那是不是意味着成长性思维的人在任何情况下都不能放弃。比如：已经验证了方向错误、投入产出比极低、或者环境发生了不可逆的恶化，在这些情况下依旧不能放弃吗？还是说在这种情况下及时止损也是一种明智的选择？如果说 “这个路径行不通，我需要换一种方法或换一个目标。”，这个时候是不是也具备的成长性思维模式了呢？所以说在很多情况下，成长型思维和固定型思维的界限也没有那么大。\u003c/p>\u003cp>A:遇到第一个困难、感到枯燥、或者短期内看不到回报就直接放弃。通常源于情绪（恐惧、懒惰、畏难），还伴随着心理安慰“这太难了，我不适合做这个。”后果： 往往伴随着后悔，且同样的问题会在下一次遇到时重复出现。这个是成长型思维还是固定型思维？\u003c/p>\u003cp>学习者：---这是轻易放弃，是固定型思维的体现。\u003c/p>\u003cp>B:我结合现在种种情况，思虑再三决定放弃，之前的投入彻底归零且毫无经验积累。\u003c/p>\u003cp>学习者：---这是二者的结合。\u003c/p>\u003cp>C: 我结合现在种种情况，思虑再三决定放弃，并能够从失败中提取反馈，吸取到部分经验，不断修正行动。那这也是成长型思维的体现。\u003c/p>\u003cp>学习者：---这个是成长型思维。\u003c/p>\u003cp>看来大家掌握得非常牢固了，我们接下来看下一个：\u003c/p>\u003cp>2.面对批评、指责，固定型思维会产生敌意、防御心里，成长型思维会从中学习。那不是所有的批评都有价值。\u003c/p>\u003cp>A:“你这个报告的数据来源没标注，导致客户不信任”.对方指出了具体的错误、逻辑漏洞或行为后果。\u003c/p>\u003cp>一种觉得他懂什么？不懂装懂！---固定型思维的体现。\u003c/p>\u003cp>一种觉得对我有益，可帮助我们直接解决问题。 “他指出的这个问题，我自己为什么没发现？是我的能力短板，还是我的习惯不好？”收获： 这是一个修补你性格或能力漏洞的机会。---成长型思维\u003c/p>\u003cp>B： “你这个人真蠢/笨”、“你总是这样”，“XX地区的人就是落后”类似这种人身攻击、情绪宣泄、没有具体事实。\u003c/p>\u003cp>一种：我真的这么差？我为什么这么笨？陷入了内耗中。---固定型思维\u003c/p>\u003cp>一种：他在宣泄情绪，这是对方的情绪垃圾，要隔绝开来。---成长型思维。\u003c/p>\u003cp>\u003cbr>所以固定性思维像“法官”：时刻在评判自己——“我聪明吗？我表现得好吗？别人会怎么看我？” 目标是证明自己。\u003c/p>\u003cp>成长性思维像“教练”：时刻在指导自己——“我怎样才能做得更好？我还能从中学到什么？” 目标是发展自己。\u003c/p>\u003cp>WHY:\u003c/p>\u003cp>固定性思维对我们成长有什么影响呢？成长性思维对我们又有什么样的影响呢？是固定性思维能帮助我们成长还是成长型思维呢？\u003c/p>\u003cp>固定性思维：会让人害怕挑战、回避困难、忽视努力、拒绝学习等消极的表现，所以固定型思维模式会阻碍我们成长的脚步，也是我们今天学习成长型思维模式去转换的必要性。\u003c/p>\u003cp>成长型思维：不怕挑战、主动寻找办法、减少自我否定、主动突破舒适区等积极表现，总之成长型思维模式它是助力我们成长的。\u003c/p>\u003cp>HOW：如何用“成长型思维”来帮助我们从消极负面的表现调整为积极正向的表现？可以按以下四步骤来进行。\u003c/p>\u003cp>1、先接受。我们每个人身上都存在两种思维，只是在不同情况下体现不一样，倾向性不同而已。\u003c/p>\u003cp>2、找原因。是什么触发了我的固定性思维的出现？是压力、困难、紧张、没有动力、失败、批判等让固定性思维出现了。\u003c/p>\u003cp>3、转思维。问问自己百分之百是这样的吗？我每次都是这样的吗？有没有在哪个时刻是不一样的？破除原来的固有思维，向“成长型思维”调整，从而认知改变。\u003c/p>\u003cp>4、调行动。运用成长思维，思考我能做些什么来改变这一现状，何时何地什么方法来做。\u003c/p>\u003cp>自我案例分享：\u003c/p>\u003cp>我自己以前总是觉得自己不会讲话，特别是在公众场合。所以有讲话的机会都推掉，能逃避的就逃避。我一直认为我天生不会讲话，这一点改变不了。这就是我的固定型思维在作怪。直到去年7月我参加了头马演讲。后续慢慢地在里面浸泡，一个月讲一次。慢慢地好多同事都夸我改变了很多自信大胆了很多。\u003c/p>\u003cp>反思：1：先接受：对公众讲话这件事我陷入了固定型思维模式，一直觉得自己不敢讲话，不会讲话是天生的。\u003c/p>\u003cp>2：找原因：我认为我性格内向，不爱表达。脑袋笨，反应慢说话也慢，面对公众时那么多眼睛看着我，压力更大了。索性就不说话，这样就陷了恶性循环。\u003c/p>\u003cp>3：转思维：我发现我在跟父母在斗嘴的时候并没有出现说话慢的情况下，斗嘴也是表达能力的体现呀。你看我并不是百分百地不会讲话。这个是给了自己贴标签了呀。又有朋友告诉我演讲能力是可以锻炼出来的，我想要成长要改变，该怎么办？\u003c/p>\u003cp>4：调行动：在头马演讲中，锻炼自己。\u003c/p>\u003cp>WHERE：成长型思维的适用范围很广，无论是工作、学习还是生活，只要涉及“需要进步、可能遇到挫折、需要主动改变”的事，成长型思维都能提供关键支撑。但是在一些紧急或高压的情况下，可能很难及时运用成长型思维模式去应对。\u003c/p>\u003cp>预防异议：有些伙伴会认为人的思维模式建立需要很长时间，难道四个步骤就能把固定型思维模式转变为成长型思维模式，是否不太可能？\u003c/p>\u003cp>确实，人的思维习惯建立是一个长期的过程，并不是一蹴而就的事情。这四个步骤是“转变的起点与工具”而非一键切换的终点，思维模式的转变需要长期的实践而来。\u003c/p>\u003cp>也有小伙伴会质疑，是不是有了成长性思维，是不是每个人都变成了科学家，爱恩斯坦、达芬奇、贝多芬之类的？并不是的，人类的潜能是未知的，人类在长时间的热情、辛苦奋斗及训练后能取得什么样的成就也是不可知的。\u003c/p>","interaction":"\u003cp>其实我们陷入固定型思维的时刻有很多，比如我驾照十年不敢上路、英语学了十年还不敢开口说、朋友跑步三天觉得太难就放弃、画画学了三个月觉得自己没天赋就放弃了等等。现在请大家编写一个小剧本：\u003c/p>\u003cp>要求描写未来一月可能遇到的陷入固定性思维的时刻具体场景，要写明时间、地点、人物、情景变化（包括：起因、经过、结果）和双方对话、动作等。情景变化要用到我们刚才学习了成长型思维模式的四个步骤：先接受-找原因-转思维-调行动，将故事写在便签上。\u003c/p>\u003cp>设计的时候，只要自己思考就可以了，不需要跟同伴讨论。设计完之后，可以在小组内相互分享一下。时间 3分钟。3 分钟后我们邀请小组代表来分享。分享的时候，只要分享自己设想的案例，一个人预演一下设想的对话就可以了。\u003c/p>\u003cp>为了方便大家思考，给大家做一个示范案例：\u003c/p>\u003cp>壹壶咖啡分享：\u003c/p>\u003cp>背景：我女儿5岁，在上一些兴趣班。以前都是很感兴趣，对上课我女儿很喜欢上画画课、思维课。最近不知道她从哪里听来了“请假”一词，最近就闹着要我给她请假。也许他是觉得请假很好玩。\u003c/p>\u003cp>时间：明天上思维课之前\u003c/p>\u003cp>人物：我和女儿\u003c/p>\u003cp>地点：家里\u003c/p>\u003cp>经过：先接受她有请假这一思想了（先接受），请假的原因是估计他觉得好玩，也可能是其他的原因（找原因），问问他是否真的理解请假的意思，再跟她解释请假是什么意思，什么情况下可以请假。请假了就拿不到上学期一样的全勤奖了。你不是生病了或其他原因等特殊原因，不能轻易请假。（转思想）我们上课有很多好玩的东西。（调节行动）\u003c/p>\u003cp>拆书家回应：这个孩子请假思维跟固定型思维和成长型思维的不同的运用不是很贴切，但我们把女儿想请假思维理解为孩子有了畏难产生逃避情绪时，这时候解释就贴切一些了，你觉得呢？（回应与反馈）我们现场其他小伙伴还有分享的吗？时间关系，我们把分享机会留在后面哈。\u003c/p>\u003cp>过渡：\u003c/p>\u003cp>不知道有没有伙伴家里有孩子的，当孩子期末考试取得好成绩时，我们怎么赞扬孩子呢？表扬孩子时不要夸孩子的天赋，比如你真聪明。而是要夸他的行动，比如你的好成绩是努力的结果。大家知道为什么要这样做吗？\u003c/p>\u003cp>夸孩子聪明，孩子会觉得自己的聪明会来了好的成绩而放弃努力，这就会让孩子西陷入固定性思维模式。那夸孩子的行动夸他努力，他下次会更努力，从而取得更好的成绩，就是成长型思维模式了。孩子取得好成绩夸孩子很容易，那孩子如果失败了呢？我们怎么运用成长型思维启发他让他成长呢？大家有没有想知道答案的？那我们接下进入第二个拆页的学习。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":24272,"quote":"\u003cp>《终身成长》P219-220---关于失败的信息\u003c/p>\u003cp>九岁的伊丽莎白第一次参加了体操运动会。她身材修长，柔韧性好，充满活力，非常适合练体操，她自己也非常热爱体操。当然，她对参加比赛有一点紧张，但是她的水平很高，并且对自己的表现很自信。她甚至已经想好要将她赢得的彩带挂在家里的哪个位置。\u003c/p>\u003cp>在第一个项目自由体操中，伊丽莎白第一个登场。尽管她表现得很不错，但在后来几个女孩出场之后，得分出现了变化，伊丽莎白输掉了比赛。在其他项目中，伊丽莎白同样表现得很好，但是依然没能赢得比赛。那天晚上比赛结束时，她一条彩带也没能得到，她感到很沮丧。\u003c/p>\u003cp>如果你是伊丽莎白的父母，你会怎么做？\u003c/p>\u003cp>1.告诉伊丽莎白，你认为她是最棒的。\u003c/p>\u003cp>2.告诉她是裁判的不公平让她丢掉了原本属于她的彩带。\u003c/p>\u003cp>3.安慰她说体操其实没那么重要。\u003c/p>\u003cp>4.告诉她她有足够的能力，下一次肯定能赢。\u003c/p>\u003cp>5.告诉她她本来就不该赢。\u003c/p>\u003cp>在当今社会中，对于如何增强孩子的自信心，存在着一种强有力的信息，这种信息的一个重要内容就是：保护孩子们免遭失败！但是这种做法或许能够暂时防止孩子们失望，但是从长远来看，却有着很大的危害。为什么这么说呢？\u003c/p>\u003cp>让我们从思维模式的角度看看对刚才五句话的五种可能的反应，倾听其中传达的信息：\u003c/p>\u003cp>第一种（你认为她是最棒的）：这种说法从根本上说并不是真心的。她并不是最好的——你知道这一点，她自己也清楚这一点，这对于她的恢复和进步一点帮助都没有。\u003c/p>\u003cp>第二种（她受到不公平待遇）：这是责备他人的做法。当事实的真相是，问题的根本在她的表现而不在裁判时，难道你希望她以后变成喜欢将自己的不足归咎于他人的人吗？\u003c/p>\u003cp>第三种（安慰她体操其实没那么重要）：这种说法会教给她，当她有什么事做不好时，贬低这些事情本身就对了。难道你真想告诉她这些吗？\u003c/p>\u003cp>第四种（她有能力）：这可能是所有信息里最危险的一个。难道是能力自动带领你走向成功的吗？如果是这样，伊丽莎白这次没能赢，为什么下一次就能赢呢？\u003c/p>\u003cp>第五种（告诉她她本来就不该赢）：在这种情况下说这样的话的确有些无情。当然，你可以不用这么直白的方式表达，不过伊丽莎白具有成长型思维模式的父亲基本上就对她表达了这个意思。\u003c/p>\u003cp>下面是她父亲的原话：“伊丽莎白，我知道你的感受。你对比赛寄予了如此大的希望，而且拿出了自己最好的表现，但是依然没能赢，你一定感到很失望。但是你要知道，你并没有付出100%的努力。有很多女孩练习体操的时间都比你长，而且比你更努力。如果这是你真心想要的东西，那么你就要全身心地为此付出努力。”拿体操当个乐趣，那也没有问题。但如果她想在比赛中有所成就，那么就必须付出更多。\u003c/p>","explains":"\u003cp>What：\u003c/p>\u003cp>这个案例描述的这个场景非常典型，也很有现实意义。文章给出的五句话，以及随后对每种回应背后思维模式的分析，已经很清晰地揭示了固定型思维与成长型思维的差别。\u003c/p>\u003cp>写了当孩子面临失败挫折时，做父母不是一味批评孩子让孩子陷入自责中，也不是说找各种理由借口为孩子的失败推脱，来将孩子保护起来，而是想办法如何启发孩子，给孩子真实而有建设性的反馈，让孩子认识到自己的不足，勇敢地改变行动，为下一次成功打下基础。\u003c/p>\u003cp>Why：\u003c/p>\u003cp>为什么“保护孩子免遭失败”从长远看有害，其实核心在于：\u003cbr>这种做法剥夺了孩子从失败中学习的机会，也剥夺了他们建立真正自信的途径。\u003cbr>真正的自信，不是来自别人告诉他“你是最棒的”，而是来自他经历过挫折、付出过努力、看到了自己的进步，从而确信“我有能力应对挑战”。\u003cbr>如果每次失败都被解释为“裁判不公”或“这件事不重要”，孩子就学不会为自己负责，也难以发展出面对真实世界的韧性。\u003c/p>\u003cp>所以说如果引导得当的话，每次失败都是学习进步的机会。\u003c/p>\u003cp>这次失败对9岁的伊丽莎白其实是给她的一份很好的礼物——得益于他爸爸恰当的引导。她会在这次失落中，慢慢理解：努力与结果之间的关系不是直线的，但努力是唯一可控的部分。\u003c/p>\u003cp>How：\u003c/p>\u003cp>在孩子面对失败时，我希望我们做父母的都能向伊丽莎白的父亲一样有智慧，即第五种所代表的成长型思维的回应方式启发孩子、引导孩子，但会结合孩子的年龄和情绪状态，用更温柔、更有引导性的方式表达出来。\u003c/p>\u003cp>这里我们叫做建设性批评四步法：\u003c/p>\u003cp>第一步：先共情，接纳情绪。\u003cbr>我会蹲下来，看着她的眼睛，说：\u003cbr>“小宝，我看到你今天非常努力，每个项目都那么认真地去完成。结果出来的时候，我看到你很难过。换作是我，付出了这么多却没能拿到彩带，我也会非常失落。你想哭就哭一会儿，我在这里陪着你。”\u003c/p>\u003cp>这一步很重要：不急着解决问题，先让她感到被理解和接纳。她的沮丧是真实的，不是需要被“否定”或“转移”的东西。\u003c/p>\u003cp>第二步：等她情绪平复后，引导她回顾过程。\u003cbr>我会在当天晚上或第二天，找一个轻松的时刻，说：\u003cbr>“我特别欣赏你今天在自由体操里的那个后手翻，比练习时还要稳。你自己觉得今天哪个动作做得最让自己满意？哪个项目你觉得还没有发挥出最好水平？”\u003c/p>\u003cp>通过这样的提问，把焦点从“结果（有没有赢）”转向“过程（自己的表现和感受）”，让她开始用自我评价代替对外部评价（裁判、名次）的依赖。\u003c/p>\u003cp>第三步：用成长型思维的方式解释结果，但不说“你本来就不该赢”。\u003cbr>我会这样说：\u003cbr>“你知道吗，比赛里有很多很棒的选手。我看到有的女孩同样的动作练了上千次，她们能赢，是因为她们在背后付出了非常多的时间。你今天做得很好，但如果你想像她们一样站在领奖台上，可能还需要在几个动作上再练得更稳、更有力。这不是因为你不够好，而是因为你想要的那个高度，需要更多的努力来匹配。如果你只是把体操当作一件开心的事，那我们就开开心心地练，不用管比赛结果。但如果你真的特别想赢彩带，那我们可以一起想想，接下来可以在哪方面多下功夫。”\u003c/p>\u003cp>这样既没有否定她的能力，也没有给她虚假的承诺（“下次一定能赢”），而是把控制感交还给她：你想走哪条路，由你决定，但每条路对应的付出是真实的。\u003c/p>\u003cp>第四步：尊重她的选择，并给予支持。\u003cbr>如果她说“我还是想赢”，那我们就一起制定一个具体的、可执行的小目标，比如每周增加一次柔韧训练，或者请教练指出一个最需要改进的动作。如果她说“我只是喜欢体操，不想那么累”，那我也完全接受，并告诉她：“那我们就享受体操带来的快乐，比赛只是一次体验。”\u003c/p>\u003cp>案例分享：\u003c/p>\u003cp>那回到课程开头我家孩子的案例中（大家可以回顾下），我当时特别气愤，恨不得当场把孩子打一顿。但冷静下来想想，我们日常并没有教过孩子遇到这类的事情怎么处理，怎么可以指望孩子一下子做得很好呢。\u003c/p>\u003cp>运用我们建设性批评四步法怎么来做呢？\u003c/p>\u003cp>1、接纳情绪。妈妈知道你第一次遇到这种事情，肯定会觉得老师考虑不周。你当时肯定很慌乱，我能理解你的心情。\u003c/p>\u003cp>2、引导回顾过程。等我们双方都冷静下来，耐心地问他:“当时发现门没开，你有什么想法”。---很害怕。\u003c/p>\u003cp>那给你打电话说往哪个方向走时，你怎么没有跟着做呢？---“因为找不到你说的那个方向”。\u003c/p>\u003cp>“我们经常停车的方向，你知道吗？”---“我平时去没有注意。”\u003c/p>\u003cp>3、用成长型思维解释结果。那如果以后又遇到这样的事情，要怎么办呢？我们是不是去认认其他的大门，以后即使走失了也能找到方向。你说是不是呢？\u003c/p>\u003cp>4、给予行动支持。带着孩子各个大门也走一步。去其他的地方去也是注意引导孩子如何走。比如坐公交如何看方向，如何在公交车站看到哪里去坐哪一辆车。\u003c/p>\u003cp>Where：任何涉及“失败—回应—成长”的领域，只要我们希望对方（或自己）在挫折之后变得更强，而不是更脆弱、更逃避或更依赖外部认可，这套“共情 + 归因于可控因素 + 尊重自主选择给予支持”的成长型思维回应方式就适用。\u003c/p>\u003ch3>比如一、家庭教育与亲子沟通\u003c/h3>\u003cp>孩子在学习、兴趣班、比赛中遇到挫折时（如考试失利、竞选落选、演出失误、比赛未晋级）\u003c/p>\u003ch3>二、学校教育与师生互动\u003c/h3>\u003cp>学生考试成绩不理想、竞赛未获奖、项目未评上优秀等情境\u003c/p>\u003ch3>三、职场管理与团队领导\u003c/h3>\u003cp>员工在项目竞标失败、绩效考核不理想、晋升未果时\u003c/p>\u003ch3>四、个人成长与自我对话\u003c/h3>\u003cp>当自己在工作、学习、关系或重要目标上遭遇挫折时。\u003c/p>\u003cp>此方法不适用于关系一般朋友、同事之间，这样会让人觉得你好为人师。\u003c/p>","interaction":"\u003cp>我们刚才学习了在失败情况下，运用“建设性批评四步法：接纳情绪、引导回归过程、解释结果、给予支持”引导我们成长。\u003c/p>\u003cp>，现在请大家回想一个自己或孩子遇的挑战、失败、阻碍、被批评的场景，然后用建设性批评四步法引导孩子或自己进一步成长，请写在便签纸上，时间三分钟。注意需要写一个现在的你还没有解决的，正在困扰你的事情。\u003cbr>【微行动步骤】\u003c/p>\u003cp>\u003cstrong>一【明确问题】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>我想请问一下大家在刚才写的过程中，觉得这四步哪一步比较难？或者有疑问的？\u003c/p>\u003cp>现在请大家轮流在小组内用一句话讲一下刚才写下的事件，然后投票选出一个你们最有兴趣去解决的事件。给大家3分钟时间。\u003c/p>\u003cp>阿辉分享的案例：最近遇到的挫折是跟父母的沟通，父母老是催婚，逼我去相亲。我父母语言的攻击性就比较强，我也比较暴躁，就比较容易上头，我们关系就紧张。\u003c/p>\u003cp>怎么来处理这个事呢？第一接纳情绪，那双方上头了呢，我也不是一下就能接受我的情绪，需要时间和一个过程去消化。那要多长时间去消化呢？这个是我觉得比较难的一步。还有就是接纳父母的情绪，我会说我知道你很焦虑。然后引导回归过程，我会说我相亲的这个女生我们没有结果，对这个事情你有什么想法。第三解释结果：我自己呢，最近比较忙，又是换工作阶段又是装修房子。我没有工作他们也很焦虑，因为有稳定的工作对相亲是一个加分项，我现在想先把工作稳定下来。装修房子也是很耗费精力的事情。第四步：给予支持。把我耗费精力的事情处理完，我会马上去相亲。\u003c/p>\u003cp>追梦分享的案例：我儿子在篮球比赛中没有拿到好的结果的场景。在7岁组中比赛前是一个种子选手，有很大可能拿到奖项的。可在比赛中可能没有配合好，进球有些失误。最终没拿到结果，最后他就哭了。我的引导回归过程：没有配合好，但是我们尽力了。别人配合得比我们好，我们后续呢，需要在练习时多磨合，相互配合。\u003c/p>\u003cp>我觉得最难的一步：让孩子接纳情绪让孩子从情绪中出来。因为他在情绪上头的时候很难听进去别人讲的任何话。\u003c/p>\u003cp>壹壶咖啡分享的案例：四岁女儿识字，开始很开心。后面字越来越难，他就受到挫折了，不想去认字了。先接纳情绪：我知道你遇到比较难的字了，产生这样的情绪是正常的。引导过程:开始笔画比较少的字就是很开心的。现在笔画比较多，记住他确实不容易。那我们不用一次记住那么多，我们一天认2个简单的2个难一点的，慢慢来就行了。觉得最难的一步是解释结果。\u003c/p>\u003cp>拆书家：我看我们三个案例都是比较经典的案例。那我们投票选出一个最有兴趣去解决的案例做为我们今天晚上需要讨论的案例。\u003c/p>\u003cp>三人一致认为最典型的案例是：孩子学习中遇到困难，父母如何引导孩子。最终选定讨论追梦的案例：孩子篮球比赛失利，孩子哭了。父母如何引导孩子。\u003c/p>\u003cp>\u003cstrong>【重述并明确问题】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>好的,我们以追梦分享的案例今晚要讨论的场景，我在这里重述并明确一下问题：孩子篮球比赛失利，孩子有情绪了。父母要通过接纳情绪，引导孩子回归比赛过程中是因为没有配合好导致没有拿到好的结果，后续需要加强团队的配合这几步来引导孩子正确积极面对比赛失利这一件事。其中最难的一步是让孩子感受到情绪被接纳。\u003c/p>\u003cp>\u003cstrong>二【引导分组讨论问题本质\u003c/strong> \u003cstrong>】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>请在大家小组内讨论接纳情绪为什么难？有什么困扰？找一下是什么原因造成的？可以多问几个为什么来深挖原因，找到最本根本的原因。3分钟时间大家畅所欲言哈。\u003c/p>\u003cp>学习者讨论：1.他已经破防了很难听进去别人的话，很难走出情绪。\u003c/p>\u003cp>2.可以理解为孩子的情绪脑占据大脑时，理性脑被挤走了，他需要一个情绪释放的过程。这个过程结束后才能进入第二步。\u003c/p>\u003cp>3.孩子情绪脑占据上,很难理解到他已经被大人理解了。即使理解了，也很难做到。\u003c/p>\u003cp>4.要跟孩子达成共识，“这个识字本身就太难了”。接纳孩子当时的情绪。\u003c/p>\u003cp>5.我们站在大人角度跟孩子沟通，没有站在孩子的角度来理解这个事情。比如过多的讲道理。\u003c/p>\u003cp>6.他的情绪没有释放出来，即使能理解到你说的也没有用，这时我们可以抱抱他，陪她呆一会儿，陪她一起发泄。\u003c/p>\u003cp>\u003cstrong>三【明确问题本质】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>经过刚才的讨论我们初步讨论了让孩子理解到我没理解他了是比较难的一步，里面的原因有：1.我们没有理解到孩子，跟孩子沟通的问题，站在的大人的角度跟还解释了很多。第二就是理解孩子的情绪：共情他，理解他，陪同他。第三让他发泄出来。然而几个原因中，哪一个是最重要最本质的原因，是跟孩子沟通问题还是发泄情绪问题释放情绪问题？现在请大家继续讨论，从中找到一个最重要、最根本的一个原因。\u003c/p>\u003cp>学习者：沟通问题。我认为是沟通。\u003c/p>\u003cp>拆书家：我们站在了大人的角度跟孩子讲了很多大道理，跟孩子沟通不畅是吗？\u003c/p>\u003cp>学习者：沟通不就是含了站在孩子角度思考吗？\u003c/p>\u003cp>学习者：沟通不一定站在孩子角度思考。我们要以小孩子的角度来跟孩子讲这个事情。\u003c/p>\u003cp>拆书家：那我们可以理解最本质的原因是跟孩子如何沟通，如何让孩子理解到我理解你了，之后才是释放情绪。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>我们已经明确了沟通问题是这个事情的本质，请大家针对这个问题本质讨论一下解决方案，请将解决方案写着便签纸上或者现场发现。\u003c/p>\u003cp>\u003cstrong>四【分组讨论解决方案】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>1.请他情绪平复一下，抱抱他，让他想哭就哭一会儿。\u003c/p>\u003cp>2.不跟他讲道理。不要说“这有什么好哭的！别哭了”\u003c/p>\u003cp>3.让他自己呆一会儿，或者陪着他呆一会儿。\u003c/p>\u003cp>4.讲讲自己7岁时候遇到类似情况的经历，以及当时的心情和做法。\u003c/p>\u003cp>5.换个环境，转移孩子的注意力：一起搓一顿，跟孩子一起打一把游戏。\u003c/p>\u003cp>\u003cstrong>五【拆书家引导总结方案】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>我总结一下，今天的讨论的案例是7岁的儿子打篮球比赛输了，作为父母要引导他正确面对失败。其中最难的一步是理解他，让孩子走出情绪的困扰。最本质的原因是跟孩子的沟通问题。那解决方法是：\u003c/p>\u003cp>1.不跟他讲道理，讲讲自己遇到类似情况的心情和做法。\u003c/p>\u003cp>2.让他自己呆一会儿，或者陪着他呆一会儿。\u003c/p>\u003cp>3.换个环境，转移孩子的注意力，让孩子走出情绪困境。再去引导事情发生经过，讨论下一步应该加强的行动。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>请问追梦，这些解决方案你满意吗？能解决你的问题吗？\u003c/p>\u003cp>\u003cstrong>追梦：\u003c/strong>可以\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>再次感谢小伙伴们的思考和分享，因为时间关系，今天我们就先讨论到这里。\u003c/p>\u003cp>\u003cstrong>A2你给出一个未来可能出现的场景.\u003c/strong>\u003cbr>\u003cstrong>需要学习者去设计角色，有起因经过，对话的故事\u003c/strong>\u003c/p>\u003cp>A2:特定作业\u003c/p>\u003cp>为了让大家更好的掌握今天的学习内容，我给大家布置一个小作业，在接下来的一周内，你可能遇到的你或者朋友家人孩子遇到挫折、失败，能用到“建设性反馈四步法”给予对方（自己）反馈的情景。\u003c/p>\u003cp>请将情节变化（包括：起因、经过、结果）和双方的对话、动作等写在小剧本模板中，其中部分对话用到“建设性的反馈”四步法。\u003c/p>\u003cp>请完成的小伙伴请把作业（包括时间、地点、人物、事件经过和主要对话内容）编辑好，通过微信发给我，谢谢大家。\u003c/p>\u003cp>追梦分享：故事背景：一年级的小宝口算题永远都是99分，每次都必错一个。并且他认为他的数学每次都99分。\u003c/p>\u003cp>人物：我 和小宝\u003c/p>\u003cp>地址：家里书房\u003c/p>\u003cp>时间：明天晚上7点，做作业开始之前\u003c/p>\u003cp>对话：\u003c/p>\u003cp>我：小宝，我发现你口算连续5次都是99哦。为什么这么神奇呀？怎么都对了99道呢。（理解）\u003c/p>\u003cp>小宝：我就是只能老99分，已经注定了。还有一道怎么做都不会。\u003c/p>\u003cp>我：哦，你有尝试过努力保证一道都不错吗？你有没有分析过原因呢？（回顾过程）\u003c/p>\u003cp>小宝：没有呢！\u003c/p>\u003cp>我:那我们把这5张卷子都拿出来，看看到底错到哪里了，好吗？是粗心还是有一类题就是没有掌握呢？这个51-1=5？这个是为什么呀？当时怎么想的呢？\u003c/p>\u003cp>小宝：我脑袋里想的是50呀！不知道为什么写出来就是5。\u003c/p>\u003cp>我：那你做完有检查过吗？（解释结果）\u003c/p>\u003cp>小宝：没有。\u003c/p>\u003cp>我：那你发现问题了吗？我们做完还有时间的话要干什么呀？（引导行动）\u003c/p>\u003cp>小宝：要去检查一遍。\u003c/p>\u003cp>结果：我们约定下次做题更仔细、养成检查的习惯。\u003c/p>\u003ch3>结束语：\u003c/h3>\u003cp>本次分享给大家带来了2种思维模式对我们成长的影响以及我们如何运用成长型思维帮助一个人建立起对失败的健康认知：失败不是对身份的判决，而是对当前策略或投入程度的反馈；真正持久的自信，不是来自从未失败，而是来自知道自己能应对失败。最后希望大家都能运用成长型思维，持续成长。感谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1777073646000,"updated_at":1779025959000,"ria":true},{"id":19758,"topic":"固定思维和成长性思维","learn_goal":"","remark":"你认可“三岁看小，七岁看老”的说法吗？你相信智力是天生的吗？命运是上天注定的吗？你有什么不同的观点？我们一起来看看卡罗尔·德韦克会有什么不一样的看法吧。","level":"TF3-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"鱼渔todo","city":""},"club":{"name":"宁波幸福虚度分舵","city":"宁波"},"prologue":"\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>大家好，我叫鱼渔，我是一个十几年财务工作者，两个孩子的妈妈，一个二级拆书家，正向3级拆书家努力奋斗着。基于后续需要现场演练，现在做一个分组，3-5人一组。\u003c/p>\u003cp>【学习目标】\u003c/p>\u003cp>学习者跟随我完成本次学习后，能够运用（行为）“成长型思维模式”四步法（澄清），识别出自己的固定型思维模式，现场能够用成长型思维模式四步法进行小组演练（界定）。\u003c/p>\u003cp>\u003cstrong>【场景法图书介绍】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【事件场景】\u003c/strong>\u003c/p>\u003cp>在开课之前我讲一个昨天发生的让我恨铁不成钢的故事。昨天是2月28日周六，我们在上班孩子还没上学，孩子的围棋兴趣班开始了，由于我们在上班没办法送孩子去上课，就给四年级的大宝打了一个滴滴送去商场上课。一般商场是10点开门，我们上课老师由于下午有事就把课程调整在了9点半。孩子到了商场，可商场的大门还没开门，孩子就很生气给我打电话，说：“商场门还没开，没办法进去，现在打个车把我送回去”。\u003c/p>\u003cp>我跟他说：“我们经常进出的大门的旁边就有一个电梯，可以直达教室，没有时间限制。”\u003c/p>\u003cp>孩子这时已经生气了：“我怎么知道怎么走？！”\u003c/p>\u003cp> 我耐着性子：“往我们停车的入口方向走，往前5米就是。我们上次看电影刚刚走过的。”\u003c/p>\u003cp>“我不知道！”孩子生气地挂掉电话。再打电话就不接电话了。\u003c/p>\u003cp>我很生气，知道孩子陷入了固定性思维。在遇到小问题小困难就退缩，不肯努力想办法去解决，还把问题推给别人。\u003c/p>\u003cp>【\u003cstrong>提问\u003c/strong>】：请问各位伙伴，您家孩子有没有跟我家小宝一样陷入“固定性思维”的时刻？你自己有没有遇事第一直觉是自己做不到的时刻？比如认为你天生感性、天生理性、天生具备某方面能力或不具备某方面能力？比如认为智力天生的，后天难以改变？\u003c/p>\u003cp>\u003cstrong>【影响】\u003c/strong>：如果你在某个时刻存在“固定性思维”，那这种“固定型思维模式”必定会给你带来一些负面影响：比如害怕挑战、忽视努力的价值、不能接受批评等。\u003c/p>\u003cp>\u003cstrong>【解决】\u003c/strong>：有没有改变思维模式的方法呢？有的，卡罗尔·德韦克的《终身成长》就给出了答案，用成长型思维模式的四步骤，可以帮我们转换思维，从而可以帮我们拥抱挑战，重新定义失败，最终实现长期成长。\u003c/p>\u003cp>听了我以上的介绍，大家一定很想了解自己到底属于固定型思维模式还是成长型思维模式。\u003c/p>\u003cp>接下来请大家做一个简单的测试题。以下是一套5道题的思维模式测试题，每题按“完全不符合（1分）\u003c/p>\u003cp>— 不太符合（2分）— 一般（3分）— 比较符合（4分）— 完全符合（5分）”计分，测试一下自己属\u003c/p>\u003cp>于哪种思维。根据自己的第一直觉为自己打分，并汇总分数，做好的小伙伴可以在屏幕打1示意我。\u003c/p>\u003cp>大家汇总完毕的可以把最终分数打在公屏上，参照下面的分类看你的思维是属于哪一类？\u003c/p>\u003cp>\u003cbr> 5—10分：成长型思维倾向明显\u003c/p>\u003cp>你更相信能力可以通过努力提升，面对失败和挑战时，会关注“如何进步”而非“否定自己”。\u003c/p>\u003cp>这种思维让你更愿意突破舒适区，从错误和他人的成功中学习，长期来看更容易实现持续成长。\u003c/p>\u003cp>11—15分：两种思维混合存在\u003c/p>\u003cp>你在某些情境下会展现成长型思维（比如主动尝试新事物），但在压力或挫折中可能陷入固定型思维\u003c/p>\u003cp>（比如怀疑自己的能力）。可以有意识地调整对“失败”和“能力”的认知，比如把“我做不到”换成“我还没做到，需要哪些方法”。\u003c/p>\u003cp>16—25分：固定型思维倾向明显\u003c/p>\u003cp>你可能更倾向于认为能力是“天生的”，害怕挑战带来的“失败标签”，对批评和他人的成功也更容易产生负面情绪。\u003c/p>\u003cp>建议从微小的挑战开始，记录自己通过努力取得的进步，逐步培养“能力可成长”的信念——就像《终身成长》中说的，思维模式的改变，本身就是成长的开始。\u003c/p>\u003cp>当然以上测评仅供参考，分数只代表对曾经的自己的评分，相信通过今天的学习，我们对自己更了解，同时，能更好地运用今天学到的技能，让自己的状态变得越来越好。\u003c/p>","ratings_count":1,"texts":[{"id":24185,"quote":"\u003cp>阅读原文:\u003c/p>\u003cp>本次拆页内容选自《终身成长》P308，是一幅图哈。如下：\u003c/p>","explains":"\u003cp>WHAT:\u003c/p>\u003cp>提问一：这个图片讲述了哪两种不同思维模式？对智力的看法是怎样的呢？我们选择壹壶咖啡小伙伴回答一下:（互动）\u003c/p>\u003cp>壹壶咖啡：这幅图写了成长性思维和固定性思维，两种不同的思维模式。固定型思维认为智力是不变的，成长型思维认为智力是可以通过学习改变的。\u003c/p>\u003cp>拆书家：非常不错。看来小伙伴对这个图看得很仔细。\u003c/p>\u003cp>我再带领大家看看不同思维模式下在不同情景下的表现有什么不一样？\u003c/p>\u003cp>1.在面对挑战时，这2种不同思维的不一样的表现：\u003c/p>\u003cp>固定性思维：倾向于回避挑战。他们认为挑战意味着暴露自己的不足，可能会失败，而失败会直接证明自己“能力不行”。因此，他们更愿意停留在自己熟悉的、安全的领域。\u003c/p>\u003cp>成长性思维：欢迎并拥抱挑战。他们将挑战视为学习和成长的机会，是让大脑变得更聪明的必经之路。即使失败，也是一次有价值的反馈。\u003c/p>\u003cp>2.固定性思维和成长性思维是如何看待努力的呢？\u003c/p>\u003cp>固定性思维：认为努力是徒劳的，甚至是丢脸的。他们觉得“如果你需要努力，说明你天生不擅长这个”。天才不需要努力，努力反而证明了你不够聪明或有天赋。\u003c/p>\u003cp>成长性思维：认为努力是通往精通的必经之路。他们相信“天才也需要努力”，能力就像肌肉，需要通过刻苦练习来锻炼和增强。努力和策略是成长的关键部分。\u003c/p>\u003ch3>3.固定性思维和成长性思维在面对挫折与失败有什么不同呢？\u003c/h3>\u003cp>固定性思维：轻易放弃。遭遇挫折时，他们会认为这已经到了自己能力的极限，并因此否定自己（“我果然不行”）。失败是一个身份标签（“我是个失败者”）。\u003c/p>\u003cp>成长性思维：在挫折面前坚持不懈。他们将挫折视为需要解决问题、调整策略的信号，而不是个人能力的定论。失败是一个事件、一次经历（“我这次失败了”），是获取信息的来源。\u003c/p>\u003ch3>4固定性思维和成长性思维在对待批评与反馈有什么不同的反应呢？\u003c/h3>\u003cp>固定性思维：忽视有用的负面反馈，或对批评产生强烈的防御和敌意。因为他们将批评视为对自身价值的攻击，而不是对行为的改进建议。\u003c/p>\u003cp>成长性思维：从批评中学习。他们会主动听取反馈，即使感到不快，也能剥离情绪，分析其中是否有可以帮助自己进步的部分。\u003c/p>\u003ch3>5.固定性思维和成长性思维在看到他人成功时有什么不同的看法呢？\u003c/h3>\u003cp>固定性思维：感到威胁和嫉妒。他人的成功仿佛一面镜子，照出了自己的不足。他们可能会通过贬低他人的成功（“他只是运气好”）来维护自己的自我价值感。\u003c/p>\u003cp>成长性思维：从中获得启发和新知。他们将他人的成功视为一个学习榜样，会思考：“他是怎么做到的？我可以从中学到什么？”\u003c/p>\u003cp>对上述内容我也总结了一个图：\u003c/p>\u003cp>所以固定性思维像“法官”：时刻在评判自己——“我聪明吗？我表现得好吗？别人会怎么看我？” 目标是证明自己。\u003c/p>\u003cp>成长性思维像“教练”：时刻在指导自己——“我怎样才能做得更好？我还能从中学到什么？” 目标是发展自己。\u003c/p>\u003cp>WHY:\u003c/p>\u003cp>提问二：固定性思维对我们成长有什么影响呢？成长性思维对我们又有什么样的影响呢？是固定性思维能帮助我们成长还是成长型思维呢？我们有请苏杭小伙伴回答 一下：（互动）\u003c/p>\u003cp>苏杭：固定性思维是阻碍我们发展。成长性思维会帮助我们不断成长，获得更大的成绩。\u003c/p>\u003cp>原因是固定性思维会轻易放弃，不会努力，不会想着怎么进步，而成长型思维认为努力是有用的，想着有什么办法可以解决问题。\u003c/p>\u003cp>拆书家：非常不错，看来苏杭对这个拆页掌握得非常熟练了。\u003c/p>\u003cp>例子\u003c/p>\u003cp>我自己以前总是觉得自己不会讲话，特别是在公众场合。所以有讲话的机会都推掉，能逃避的就逃避。我一直认为我天生不会讲话，这一点改变不了。这就是我的固定型思维在作怪。直到去年7月我参加了头马演讲。后续慢慢地在里面浸泡，一个月讲一次。慢慢地好多同事都夸我改变了很多自信大胆了很多。\u003c/p>\u003cp>反思：1：先判断：对公众讲话这件事我陷入了固定型思维模式，一直觉得自己不敢讲话，不会讲话是天生的。\u003c/p>\u003cp>2：找原因：我认为我性格内向，不爱表达。脑袋笨，反应慢说话也慢。索性就不说话，这样就陷了恶性循环。\u003c/p>\u003cp>3：转思维：我发现我在跟父母在斗嘴的时候并没有出现说话慢的情况下，斗嘴也是表达能力的体现呀。你看我并不是百分百地不会讲话。这个是给了自己贴标签了呀。又有朋友告诉我演讲能力是可以锻炼出来的，我想要成长要改变，该怎么办？\u003c/p>\u003cp>4：调行动：在头马演讲中，锻炼自己。\u003c/p>\u003cp>HOW：如何用“成长型思维”来帮助我们从消极负面的表现调整为积极正向的表现？可以按以下四步骤来进行。\u003c/p>\u003cp>1、先判断。我们每个人身上都存在两种思维，只是在不同情况下体现不一样，倾向性不同而已。看看此情此景下我们处于什么思维中？如果是固定性思维，就需要转变了。\u003c/p>\u003cp>2、找原因。找找是什么原因让你产生了固定型思维模式，你是不是给自己贴了负面标签？\u003c/p>\u003cp>3、转思维。问问自己百分之百是这样的吗？我每次都是这样的吗？有没有在哪个时刻是不一样的？破除原来的固有思维，向“成长型思维”调整，从而认知改变。\u003c/p>\u003cp>4、调行动。运用成长思维，思考我能做些什么来改变这一现状。\u003c/p>\u003cp>WHERE：成长型思维的适用范围很广，无论是工作、学习还是生活，只要涉及“需要进步、可能遇到挫折、需要主动改变”的事，成长型思维都能提供关键支撑。但是在一些紧急或高压的情况下，可能很难及时运用成长型思维模式去应对。\u003c/p>\u003cp>预防异议：有些伙伴会认为人的思维模式建立需要很长时间，难道四个步骤就能把固定型思维模式转变为成长型思维模式，是否不太可能？\u003c/p>\u003cp>确实，人的思维习惯建立是一个长期的过程，并不是一蹴而就的事情。这四个步骤是“转变的起点与工具”而非一键切换的终点，思维模式的转变需要长期的实践而来。\u003c/p>\u003cp>也有小伙伴会质疑，是不是有了成长性思维，是不是每个人都变成了科学家，爱恩斯坦、达芬奇、贝多芬之类的？并不是的，人类的潜能是未知的，人类在长时间的热情、辛苦奋斗及训练后能取得什么样的成就也是不可知的。\u003c/p>","interaction":"\u003cp>A现场演练：\u003c/p>\u003cp>我们刚才学习了成长型思维模式的四个步骤：先判断-找原因-转思维-调行动。现在我们一起运用刚才学到的方法结合场景案例现场演练，把学到的知识运用起来，才能落地解决问题。\u003c/p>\u003cp>【场景设计】小明是职场新秀，干劲十足。但在年底竞聘“管理岗”时，没有被领导批准认可。自此他垂头丧气，觉得自己不是管理的料。职场是灰暗的，因此开始躺平职场生涯。作为他的好友小张，用成长型思维如何来引导他。\u003c/p>\u003cp>给大家5分钟时间分组扮演一个扮演小张，一个扮演小明，5分钟后请一组来现场演练。根据线上人数我们一组在会议里讨论哈。\u003c/p>\u003cp>为了方便大家的讨论，给大家做一个示范案例：\u003c/p>\u003cp>小张：你最近怎么了？垂头丧气的，是发生了什么事吗？\u003c/p>\u003cp>小明：哎，上次不是竞聘主管岗位嘛，没有通过，我是不是天生不是管理的料呀。\u003c/p>\u003cp>小张：哦？那你觉得管理能力天生吗？\u003c/p>\u003cp>小明：······\u003c/p>\u003cp>小张：·····\u003c/p>\u003cp>小明：······\u003c/p>\u003cp>小张：······\u003c/p>\u003cp>现场演示：苏杭扮演小张，壹壶咖啡扮演小明。\u003c/p>\u003cp>小张：你最近怎么了？垂头丧气的，是发生了什么事吗？\u003c/p>\u003cp>小明：嗯，上次竞聘主管没有成功嘛，我是不是天生不是管理的料呀。\u003c/p>\u003cp>小张：哦？那你觉得管理能力天生吗？(做判断）\u003c/p>\u003cp>小明：对呀，大家都能做好，就有我做不好。肯定是他天生就这么厉害。\u003c/p>\u003cp>小张：那你觉得是什么原因呢？除了是天生的外，还有没有其他的什么原因呢？（找原因）\u003c/p>\u003cp>小明：他们做事比较认真，比较负责吧。\u003c/p>\u003cp>小张：虽然说你目前这一块有所欠缺，那你如果努力一下补足这一块是不是也是可以提高你的管理能力呢？（转变思维）\u003c/p>\u003cp>小明：是的，估计是自己还不够努力吧。\u003c/p>\u003cp>小张：那你看看你是不是有什么方法可以去改变这一现状呢？（调行动）\u003c/p>\u003cp>小明：我觉得我先去观察下我的领导们平时是如何做的吧？找一找我跟他们身上的差距再去补足。\u003c/p>\u003cp>小张：嗯，这也是一个非常不错的方法。那我们就去行动吧。\u003c/p>\u003cp>A2催化应用:\u003c/p>\u003cp>为了让大家能够学以致用，给大家留一道课外作业，写下最近一件让自己产生“我不行/再试也没用的事情（如我英语学了十几年还是不会说/考试评职称好几次都没有通过，我不是学习的料等）运用成长型思维模式转换的四步骤，给自己制定行动规划，并在未来的一周里实施。\u003c/p>\u003cp>壹壶咖啡的课后作业：我学画画学了三个月了，可是怎么画都画不出我想要的感觉，我一度怀疑是不是天生就不适合画画（做判断）。而和我一起学习的人，他们画的都非常的吸引人。有可能是因为我没有多花时间在课外（找原因），只利用上课的这段时间联系下课之后就没有拿过笔，我学英语这么难的学科都能搞定，我认为我学画画肯定也是没问题的（转思维）。在接下来的一周时间里，除了上课的2小时，我要额外每天花1个小时进行临摹和联系，在一周时间内，可以做到线条清楚，在三周内做到阴影，色彩都和参考图几乎接近。（调行动）\u003c/p>\u003cp>最后感谢伙伴的陪伴和支持。做一个小的总结：\u003c/p>\u003cp>固定性思维关注“看起来聪明”，成长性思维关注“变得聪明”。前者让你困在原地，后者则为你打开持续成长的大门。\u003c/p>\u003cp>每个人都是混合体：很少有人是纯粹的固定或成长思维，可能在某个领域（如艺术）是成长思维，在另一个领域（如数学）是固定思维。\u003c/p>\u003cp>思维模式可以改变：思维模式是一种信念，可以通过有意识的觉察和练习来改变。了解这两种表现本身，就是迈向成长性思维的第一步。再次感谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1772717302000,"updated_at":1772796287000,"ria":true},{"id":19315,"topic":"终身成长","learn_goal":"","remark":"成长史思维模式转换","level":"TF3-2","duration":30,"status":30,"type":0,"chaishujia":{"username":"周舟小太阳","city":"台州市"},"club":{"name":"宁波幸福虚度分舵","city":"宁波"},"prologue":"\u003cp>\u003cstrong>【开场】\u003c/strong>\u003c/p>\u003cp>大家好，我叫周舟，来自浙江台州。我用三个数字介绍我自己270：2代表我是一名2级拆书家，目前正向三级拆书家努力。\u003c/p>\u003cp>7代表我是一个有着7年公益践行的公益人。\u003c/p>\u003cp>0，代表我是一名终身学习者，保持空杯心，不断归零重新出发。\u003c/p>\u003cp>周舟的寓意是希望以“轻舟”般的心境应对生活的”万重山”。我觉得拆书帮就像一艘轻舟，在这里我们同舟共济，共同应对生活的万重山。\u003c/p>\u003cp>\u003cstrong>学习目标包含学习者可被观察到/被测量到的行为或动作，线上学习者设计清晰体现了该目标。\u003c/strong>\u003c/p>\u003cp>【学习目标】学习者跟随我完成RIA学习后，能够运用（行为）“成长型思维模式”三步法（澄清），识别出自己的固定型思维模式，\u003c/p>\u003cp>现场能够用成长型思维模式”三步法进行演练或讨论形成方案（界定）。\u003c/p>\u003cp>\u003cstrong>【场景法图书介绍】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>实用类图书或理论类图书\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者场景介绍法中，能够清晰辨别出聚焦于图书和学习主题的时间、提问、影响和解决四个步骤\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【事件场景】\u003c/strong>\u003c/p>\u003cp>我有个朋友叫王城，在一家上市公司上班。在一次竞聘部门主管的时候落选了，这事对他影响很大，他认为自己“天生不擅长管理”，\u003c/p>\u003cp>从此对晋升失去信心，不再参加任何岗位竞选，工作也变得消极——遇到有挑战性的任务就回避，觉得自己能力有限，再努力也没用。\u003c/p>\u003cp>\u003cstrong>【提问】\u003c/strong>：请问各位伙伴，王城的失败真的是他没有管理的天赋吗？还是他对“能力”的理解存在误区？\u003c/p>\u003cp>\u003cstrong>【影响】\u003c/strong>：如果你也像王城一样，认为“能力是固定的”，这种“固定型思维模式”必定会给你带来一些负面影响：比如害怕挑战\u003c/p>\u003cp>、忽视努力的价值、甚至对他人的成功产生嫉妒等消极想法。\u003c/p>\u003cp>\u003cstrong>【解决】\u003c/strong>：有没有改变思维模式的方法呢？有的，《终身成长》第八章就给出了答案，用成长型思维模式的三步骤，可以帮我们转换思维\u003c/p>\u003cp>，从而可以帮我们拥抱挑战，重新定义失败，最终实现长期成长。\u003c/p>\u003cp>\u003cstrong>A1环节的量表题清晰设置了多个选项，学习者通过自测可以了解在某一种情况下自己的表现。\u003c/strong>\u003c/p>\u003cp>听了我以上的介绍，大家一定很想了解自己到底属于固定型思维模式还是成长型思维模式.都说自己是\u003c/p>\u003cp>自己最大的敌人，说到底还得先了解自己，才能战胜自己。\u003c/p>\u003cp>接下来请大家做一个简单的测试题。以下是一套5道题的思维模式测试题，每题按“完全不符合（1分）\u003c/p>\u003cp>— 不太符合（2分）— 一般（3分）— 比较符合（4分）— 完全符合（5分）”计分，测试一下自己属\u003c/p>\u003cp>于哪种思维。根据自己的第一直觉为自己打分，并汇总分数，做好的小伙伴可以在屏幕打1示意我。\u003c/p>\u003cp>(得分分析供参考)：\u003c/p>\u003cp> 看到大家大部分都做完了，大家的得分情况怎么样？下面分析一下得分情况。\u003c/p>\u003cp>5—10分：成长型思维倾向明显\u003c/p>\u003cp>你更相信能力可以通过努力提升，面对失败和挑战时，会关注“如何进步”而非“否定自己”。\u003c/p>\u003cp>这种思维让你更愿意突破舒适区，从错误和他人的成功中学习，长期来看更容易实现持续成长。\u003c/p>\u003cp> 11—15分：两种思维混合存在\u003c/p>\u003cp>你在某些情境下会展现成长型思维（比如主动尝试新事物），但在压力或挫折中可能陷入固定型思维\u003c/p>\u003cp>（比如怀疑自己的能力）。可以有意识地调整对“失败”和“能力”的认知，比如把“我做不到”换成“我还没做到，需要哪些方法”。\u003c/p>\u003cp> 16—25分：固定型思维倾向明显\u003c/p>\u003cp>你可能更倾向于认为能力是“天生的”，害怕挑战带来的“失败标签”，对批评和他人的成功也更容易产生负面情绪。\u003c/p>\u003cp>建议从微小的挑战开始，记录自己通过努力取得的进步，逐步培养“能力可成长”的信念——就像《终身成长》中说的\u003c/p>\u003cp>，思维模式的改变，本身就是成长的开始。\u003c/p>\u003cp>当然以上测评仅供参考，分数只代表对曾经的自己的评分，相信通过今天的学习，我们对自己更了解，同时，能更好地\u003c/p>\u003cp>运用今天学到的技能，让自己的状态变得越来越好。\u003c/p>","ratings_count":1,"texts":[{"id":23672,"quote":"\u003cp>\u003cstrong>【拆书技能】\u003c/strong>\u003cbr>\u003cstrong>选择图书是实用类或理论类图书，拆页内容未超过\u003c/strong> \u003cstrong>2 页图书内页，原书拆页【R】为 why 或者 what 的内容，或原书一个完整的案例。\u003c/strong>\u003c/p>\u003cp>【R原文】《终身成长》江西人民出版社P282-283状元秀\u003c/p>\u003cp>困境2：我压力太大了。你迫切渴望上场比赛，但每次他们让你上场，想看看你的本事，你却因为过于紧张而无法集中精神。\u003c/p>\u003cp>你以前在压力下总能保持冷静，但这是职业联赛。现在你眼里只有向你冲来的那些大个子--体重加起来足有一吨的大个子们\u003c/p>\u003cp>想要把你撞飞。这些大个子的动作快得超乎你的想象。你感觉被包围了，而且孤立无援。\u003c/p>\u003cp>\u003cstrong>固定型思维模式的反应\u003c/strong>：四分卫是队伍的领袖，而你不是领袖材料。你用这个想法折磨着自己。如果你连一个好球都传不出去，\u003c/p>\u003cp>连几码距离都无法推进，还怎么去鼓舞队友的信心呢？雪上加霜的是，赛场广播的评论员还在问：那个神奇的小伙子去哪里了？\u003c/p>\u003cp>赛后，为了让羞辱减到最低，你一言不发。为了逃避评论员，你径直进了更衣室。\u003c/p>\u003cp>但你这样就成功了吗？你能采取哪些措施，让事情产生转机？想想你有哪些资源，要如何应用他们。但首先，你要转变你的思维模式。\u003c/p>\u003cp>\u003cstrong>成长型思维模式的解决办法\u003c/strong>：在成长型思维模式下，你告诉自己，进入职业联赛代表着一个巨大的进步，需要进行很多调整和学习。\u003c/p>\u003cp>有很多事你不可能一下子了解，现在你最好开始努力了解它们。\u003c/p>\u003cp>你试着去花更多时间和经验丰富的四分卫相处，向它们取经，和它们一起观看比赛录像。你不再隐瞒自己的不安全感，而是告诉它们\u003c/p>\u003cp>这与大学联赛相比有多么不同。它们则会向你坦白，它们当年的感觉和你一模一样。实际上，他们还会给你讲述自己当年受辱的故事。\u003c/p>\u003cp>你问它们当年是如何克服起步阶段的困难的，他们会传授给你精神和身体上的技巧。当你开始感觉更能融入球队时，你会意识到你\u003c/p>\u003cp>是这个集体的一部分。这个集体想要帮助你成长，而不是评判或者轻视你。你不再担忧球队为你的才能复出了过高的代价，你开始\u003c/p>\u003cp>用高度努力的工作和团队精神来回报球队为你付的钱了。\u003c/p>\u003cp>那这个片段到底讲了什么？我们为什么要学习“成长型思维三步骤”？它到底对我们有什么帮助？下面我通过三个提问进行一一解答。\u003c/p>","explains":"\u003cp>\u003cstrong>【互动提问】\u003c/strong>\u003c/p>\u003cp>提问1\u003c/p>\u003cp>拆书家：这个片段我们提到了哪两种思维模式？\u003c/p>\u003cp>学习者：固定型思维和成长型思维\u003c/p>\u003cp>答案：对，固定型思维模式和成长型思维模式\u003c/p>\u003cp>提问2：\u003c/p>\u003cp>拆书家：固定型思维有哪些坏处？\u003c/p>\u003cp>学习者：消极、逃避，不敢面对现实困境\u003c/p>\u003cp>拆书家：是的，会让人害怕挑战、回避困难、忽视努力、拒绝学习等消极的表现，所以固定型思维模式会阻碍我们成长的脚步，也是我们今天学习成长型思维模式去转换的必要性。\u003c/p>\u003cp>提问3：\u003c/p>\u003cp>\u003cstrong>拆\u003c/strong>书家：成长型思维有哪些好处？\u003c/p>\u003cp>学习者：积极、正能量，敢于突破、敢于挑战\u003c/p>\u003cp>拆书家：是的，不怕挑战、主动寻找办法、减少自我否定、主动突破舒适区等积极表现，总之成长型思维模式它是助力我们成长的。\u003c/p>\u003cp>How：如何用“成长型思维”三步骤来帮助学习者从消极负面的表现调整为积极正向的表现？可以按以下三步骤来进行。\u003c/p>\u003cp>先接受。接受我们每个人身上都存在两种思维，只是倾向性不同。\u003c/p>\u003cp>2、再明确。明确是什么激发了你的固定型思维模式。\u003c/p>\u003cp>3、后调整。用“成长型思维”调整，通过认知改变和具体行动。\u003c/p>\u003cp>【反例变正例】以王城的例子说明。\u003c/p>\u003cp>1、先接受。接受自己身上存在两种思维，但固定型思维占了上峰。\u003c/p>\u003cp>王城首先要接受自己身上的固定型思维占了上峰，所以：“觉得自己天生不擅长管理”是固定型思维在作祟，不是事实。\u003c/p>\u003cp>2、再明确。明确是什么激发了你的固定型思维模式。\u003c/p>\u003cp>王城需要找触发点，明确是什么激发了自己的固定型思维模式。王城的固定型思维是被“竞聘主管落选”这件事激活的。他要清楚：\u003c/p>\u003cp>不是“落选”本身定义了他，而是他对“落选”的解读让自己陷入了困境。\u003c/p>\u003cp>3、用“成长型思维”调整。\u003c/p>\u003cp>这也是关键的步骤。\u003c/p>\u003cp> 第一步：从认知方面去转变。\u003c/p>\u003cp>改写对“失败”的解读。失败，只是说明目前自己的能力还没达到要求，正好提醒自己还需努力。\u003c/p>\u003cp> 第二步：针对差距找具体行动\u003c/p>\u003cp>把大目标进行分解，先从小目标入手：报名基础的管理课程（比如沟通、协调类），补自己的短板；遇到困难不逃避，\u003c/p>\u003cp>想着干就是了，都是为了积累经验；主动找领导请教。\u003c/p>\u003cp>异议：有些伙伴会认为人的思维模式建立需要很长时间，难道三个步骤就能把固定型思维模式转换为成长型思维模式，\u003c/p>\u003cp>是否不太现实？\u003c/p>\u003cp>确实人的思维习惯建立是一个长期而\u003c/p>\u003cp>艰难的过程，并不是一蹴而就的事情。这三个步骤是“转变的起点与工具”而非一键切换的终点，思维模式的转变需要步骤引导+持续实践的结合。\u003c/p>\u003cp>Where：成长型思维的适用范围很广，无论是工作、学习还是生活，只要涉及“需要进步、可能遇到挫折、需要主动改变”的事，\u003c/p>\u003cp>成长型思维都能提供关键支撑。但是在一些紧急或高压的情况下，可能很难及时运用成长型思维模式去应对。\u003c/p>","interaction":"\u003cp>\u003cstrong>学习者根据拆书家设定的案例场景，进行小组讨论并形成一个解决方案，或是应用知识点进行组内角色扮演\u003c/strong>。\u003c/p>\u003cp>我们刚才学习了成长型思维模式的三个步骤：接受-明确-调整。现在我们一起运用刚才学到的方法进行现场讨论或演练，把学到的\u003c/p>\u003cp>知识能形成方案，做到能落地解决问题。\u003c/p>\u003cp>【场景设计】小敏经常吃外卖，她想摆脱“外卖依赖”，决定学做妈妈常做的“番茄炖牛腩”。她第一次做时，出现了问题\u003c/p>\u003cp>牛腩炖得咬不动，番茄煮成了糊，汤还发咸。小敏想：“我天生就不是做饭的料，连最简单的炖菜都做砸，以后还是吃外\u003c/p>\u003cp>卖吧，再试也没用。”她把没做好的牛腩倒进垃圾桶，从此再也没碰过炖菜，做饭计划直接放弃。\u003c/p>\u003cp>【指令】\u003c/p>\u003cp>接下来我们先分一下组，在组内一起演练下，1人扮演引导者，1个人扮演小敏，引导者要帮小敏用成长型思维转换的三步骤进行引导，\u003c/p>\u003cp>一起制定解决方案。\u003c/p>\u003cp>请在小组内交流和演练，3分钟后，我们邀请一组小伙伴来演示下。\u003c/p>\u003cp>引导者（深蓝）\u003c/p>\u003cp>小敏（馃子）\u003c/p>\u003cp>引导者：小敏，刚才看你把炖好的牛腩倒了，怎么回事，做坏了吗？\u003c/p>\u003cp>小敏：别提了，第一次尝试做番茄炖牛腩，就失败了。牛腩硬的咬不动，番茄也被我烧糊了，汤也很咸。我发现我天生就不是做饭的料，连这么简单的菜都做砸，以后还是老老实实吃外卖吧。\u003c/p>\u003cp>引导者：我特别理解你的这种挫败感，不过，毕竟是第一次嘛，别灰心，咱们先试着接受它，好吗？\u003c/p>\u003cp>小敏：嗯，看到自己做菜这么差劲，真的很难过，感觉自己干什么都不行。\u003c/p>\u003cp>引导者：你先别着急否定自己嘛，咱们先来找找原因，到底是因为“你没做饭的天赋”，还是做饭的有些细节没掌握呀？比如牛腩你有没有提前焯水、炖的时间够不够，番茄什么时候放的，还有盐放了多少这些细节你都注意了吗。\u003c/p>\u003cp>小敏：牛腩好像没提前焯水，我直接切了就炖了，盐也是凭感觉放的，炖了大概半小时就关火了。\u003c/p>\u003cp>引导者：你看，其实不是你没天赋，是你没掌握做这道菜的关键步骤。那接下来我们一起想想有什么改进的方法？比如下次做之前，先查下教程，提前把牛腩焯水去血沫，炖的时候用小火多炖一会儿，盐不要一次性放，分多次少量放，番茄分一半早点放炖出汁，另一半晚点放，这样可以保持口感，你觉得怎么样？\u003c/p>\u003cp>小敏：这样好像真的能行？我之前都没考虑过这些细节，就想着跟着感觉做。\u003c/p>\u003cp>引导者：当然啦，谁第一次做新菜都不可能完美。重要的是去找失败的原因，找到原因了，我们下次就能调整方法，说不定就能成功了。要不要下次再试一下，需要我和你一起动手的话，我随时奉陪。 \u003c/p>\u003cp>小敏：好呀！那我明天再买些牛腩和番茄，按你说的方法再试试。\u003c/p>\u003cp>【布置作业】催化应用\u003c/p>\u003cp>\u003cstrong>学习者根据指令，写出自己未来的一个具体的要做的应用（比如：某个特定任务、和人分享、事后复盘或找人陪练）\u003c/strong>\u003c/p>\u003cp>为了让大家能够学以致用，给大家留一道课外作业，写下最近一件让自己产生“我不行/再试也没用的事情（如背单词总记不住，\u003c/p>\u003cp>觉得自己没有语言天赋）运用成长型思维模式转换的三步骤，给自己制定行动规划，并在未来的一周里实施。\u003c/p>\u003cp>成长型思维转换作业：深蓝同学的作业。我以前对于上台演讲很恐惧，所以特意参加演讲俱乐部为了突破自己，现在有所改善，但依然还会紧张。下周又有一场演讲等着我，我决定试试成长型思维模式去突破公开演讲困境。\u003c/p>\u003cp>1. 接受：我有固定与成长型思维模式，面对公开演讲时前者更强，所以我会存在“我没天赋，我做不好”的想法，但这很正常，无需自我否定。\u003c/p>\u003cp>2. 明确：接到演讲任务就会想让我想到过往的失误，我一失败就会想到是自己自己没天赋，这种想法会很强烈；看见那些擅长者，就会他们是先天有演讲天赋，而忽略他们在背后默默付出的努力。\u003c/p>\u003cp>3. 调整：认知上，认识到因紧张失误的原因还在于平时练习的太少。明白演讲能力是可以通过后天刻意练习习得。行动上，一周内：1-2天定3分钟演讲目标、学技巧；3-4天写稿录音改、镜前练；5-6天找友模拟、空房练；7天录视频复盘，记录进步。\u003c/p>\u003cp>结束语：非常感谢大家的积极参与，共同陪伴。学了今晚的课程大家是否都明白了，其实，我们每个人的身上都有2种思维模式，固定型思维和成长型思维，我们接纳固定型思维的存在，但我们不接纳它给我们带来的负面影响，当固定型思维占上峰时，我们要\u003c/p>\u003cp>积极地运用成长型思维模式转换三步骤来引导它，这三步骤是什么？接受、明确、调整。希望大家在今后的生活工作中能运用起\u003c/p>\u003cp>来，让它成为你的护身法宝。谢谢！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1757905982000,"updated_at":1758031090000,"ria":true},{"id":18688,"topic":"走向成长型思维模式","learn_goal":"","remark":"身处这个vuca（瞬息万变的）时代，我们即是这个时代的受益者，也是这个时代的边缘者，往前一步是等着你去开拓的新天地，原地踏步是被动等待时代淘汰的命运。我们还能怎么做，帮助自己不管在什么情况下，自己都不是被淘汰的那个？我们去哪里寻找那份别人拿不走的笃定，迎难而上？\n\n《终身成长》作者德伟克提出的成长型思维，是改变的起点，是不怕改变的法宝。只有自己不断改变、迭代、革新、与时俱进，我们才不害怕改变，不害怕任何瞬息万变的挑战，把不利因素转化成有利因素，抓住每一个机遇。","level":"TF3-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"天空粉黑","city":"深圳市"},"club":{"name":"深圳智行分舵","city":"深圳"},"prologue":"\u003cp>【自我介绍】\u003c/p>\u003cp>\u003cstrong>大家晚上好，我是粉黑天空，我的三个标签是：二级拆书家、智行分舵品宣长老、媒体人。\u003c/strong>\u003c/p>\u003cp>【分组】\u003c/p>\u003cp>今天是我TF3-2拆书，预计时长为20~25分钟。为方便后续讨论和演练，我们就近两两为一个学习小组。\u003c/p>\u003cp>【事件】\u003c/p>\u003cp>最近，我有一个朋友升职做了部门经理，但她非但没有很开心，反而感觉压力山大。上任后她主持召开第一次部门大会时，她越想好好表现就越紧张，结果大脑一片空白，很草率就结束了会议。她开始自我怀疑，觉得也许领导看走眼了，她并不是部门经理的最佳人选。\u003c/p>\u003cp>【提问】\u003c/p>\u003cp>大家是否遇到过类似的场景？当机会来临的时候总是无法把握？陷入自我怀疑，不想面对压力，你有思考过问题出在哪里吗？\u003c/p>\u003cp>【影响】\u003c/p>\u003cp>如果你也出现过类似的情况，很大部分原因是思维模式的问题。类似前面这种思维模式会影响到你的事业、家庭，甚至整个人生状态，导致你的人生充满悲观、负能量，很难取得成功。\u003c/p>\u003cp>【解决】\u003c/p>\u003cp>斯坦福大学心理学博士卡罗尔·德韦克对“成功”进行了数十年的研究，他发现了思维模式的力量。在他写的《终身成长》这本书里，介绍了两种思维模式：固定型思维和成长型思维。在面对恐惧、失败时，只有用正确的思维方式去看待问题，才能更好地达成你的人生和职业目标。\u003c/p>\u003cp>【学习目标】\u003c/p>\u003cp>通过今天的学习，希望大家能够（澄清）辨识出（行为）成长型和固定型思维模式；在面对失败与挑战时，能够（澄清）采用（行为）成长型思维模式的“成长四步曲”来应对（界定）。\u003c/p>\u003cp>到这，你是不是开始好奇自己当下的思维模式到底如何呢？正好，我给大家准备了测试题，就在我们手中拆页片段第一页。请大家用1分钟来给自己评分，不需要深度思考，凭直觉来填就可以了。1分代表完全不符合，6分代表非常符合。做完请举手示意下我。\u003c/p>\u003cp>好，大家都做完了，我们来看下整体得分的情况：\u003c/p>\u003cp>得分在24分以上的小伙伴请举手？\u003c/p>\u003cp>说明你具有高水平的成长型思维模式，不怕失败，喜欢挑战；\u003c/p>\u003cp>12—24分之间的呢？\u003c/p>\u003cp>你虽然具备一定的成长型思维模式，但有时候也会在固定型思维模式上徘徊。如果能借助一些方法和工具，会让你更偏向成长型思维模式，那今天分享的内容就特别适合你来学习了；\u003c/p>\u003cp>12分以下的有吗？没关系，结果只是说明你现在的思维习惯偏向固定型思维，今天的课程是专门为你打造的。\u003c/p>","ratings_count":1,"texts":[{"id":22997,"quote":"\u003cp>下面请大家用1分半钟的时间快速阅读下手中的原文拆页，读完的小伙伴可以举手示意我。\u003c/p>\u003cp>\u003cstrong>【R】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>R便签 \u003c/strong>\u003cu>选自《终身成长》\u003c/u> \u003cu> P308    作者：卡罗尔·德韦克\u003c/u>\u003c/p>\u003cp>\u003cstrong>困境2：压力太大了。\u003c/strong>你迫切渴望上场比赛，但每次他们让你上场，想看看你的本事，你却因为过于紧张而无法集中精神。你以前在压力下总能保持冷静，但这是职业联赛。现在你眼里只有向你冲来的那些大个子——体重加起来足有一吨的大个子们想要把你撞飞。这些大个子的动作快得超乎你的想象。你感觉被包围了，而且孤立无援。\u003c/p>\u003cp>\u003cstrong>固定型思维模式的反应：\u003c/strong>四分卫是队伍的领袖，而你不是领袖的材料。你用这个想法折磨着自己。如果你连一个好球都传不出去，连几码距离都无法推进，还怎么去鼓舞队友的信心呢？雪上加霜的是，赛场广播的评论员还在问：那个神奇的小伙子去哪了？\u003c/p>\u003cp>赛后，为了让羞辱减到最低，你一言不发。为了逃避评论员，你径直躲进了更衣室。\u003c/p>\u003cp>但你这样就成功了吗？你能采取哪些措施，让事情产生转机？想想你有哪些资源，要如何应用它们。但首先，你要转变你的思维模式。\u003c/p>\u003cp>\u003cstrong>成长型思维模式的解决办法：\u003c/strong>在成长型思维模式下，你告诉自己，进入职业联赛代表着一个巨大的进步，需要进行很多调整和学习。有很多事你不可能一下子了解，现在你最好开始努力了解它们。\u003c/p>\u003cp>你试着去花更多时间和经验丰富的四分卫相处，向他们取经，和他们一起观看比赛录像。你不再隐瞒自己的不安全感，而是告诉他们这与大学联赛相比有多么不同。他们则会向你坦白，他们当年的感觉和你一模一样。实际上，他们还会给你讲述自己当年受辱的故事。\u003c/p>\u003cp>  你问他们当年是如何克服起步阶段的困难的，他们会传授给你精神和身体上的技巧。当你开始感觉更能融入球队时，你会意识到你是这个集体的一部分。这个集体想要帮助你成长，而不是评判或者轻视你。你不再担忧球队为你的才能付出了过高的代价，你开始用高度努力的工作和团队精神来回报球队为你付的钱了。\u003c/p>\u003cp>（阅读2分钟）\u003c/p>","explains":"\u003cp>好的，时间到了，请大家跟随我再回顾下。\u003c/p>\u003cp>【what】&lt;概念&amp;匹配例子&gt;\u003c/p>\u003cp>在这个拆页中，提到了在面对压力过大的情况下，我们可能会出现固定型思维和成长型思维两种不同思维模式，导致截然不同的两种做法。那怎么理解这两种思维模式呢？\u003c/p>\u003cp>\u003cstrong>固定型思维模式认为，\u003c/strong>人的智商是天生的，后天再怎么努力也不会改变。他们倾向于回避失败与挑战，更看中自己的身份标签：在他人眼中我是个什么样的人；\u003c/p>\u003cp>\u003cstrong>而成长型思维模式认为\u003c/strong>，人的能力是可以通过后天努力来培养的。不管你的天赋如何，相信通过练习，都是可以改变提高的。他们不怕失败和挑战，更专注于成长的过程，考虑的是：下一步该做什么事。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>无论是工作还是生活中，固定型思维都会让我们安于现状，害怕挑战和失败，遇到挫折容易放弃，也比较固执，不轻易接受他人的建议。这样下去，我们人生和职业目标都会难以实现，离“成功”也将渐行渐远。\u003c/p>\u003cp>\u003cstrong>【互动提问】\u003c/strong>\u003c/p>\u003cp>再回到拆页中，请大家来回答我的问题。\u003c/p>\u003cp>在面对压力、挑战时，成长型思维模式的人是如何应对的呢？是选择接纳自己，转变思维？还是逃避呢？\u003cstrong>互动\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者：（接纳自己、转变思维）\u003c/strong>\u003c/p>\u003cp>拆页提到，这个新人四分卫认识到自己的水平跟职业联赛存在的巨大差距，有很多需要学习和调整的地方。而在固定型思维模式下，会对自己全盘否定，选择逃避。\u003c/p>\u003cp>接下来，成长型思维模式的人还做了那些动作呢？他是不是开始花更多时间和经验丰富的四分卫相处，向他们取经。\u003c/p>\u003cp>\u003cstrong>学习者：（是的）\u003c/strong>\u003c/p>\u003cp>他通过向他人请教还有自我分析等方式，试图分析出使自己紧张、在场上无法集中精神的原因。\u003c/p>\u003cp>找到原因后，他做的最重要的动作，是什么呢？给大家一个小提示，我们经常说：想要改变，就得（行动）？\u003cstrong>互动\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者：立即行动。\u003c/strong>\u003c/p>\u003cp>对，他开始主动向有经验的队友们请教如何克服起步阶段的困难，并将这些方法运用到了比赛中去。\u003c/p>\u003cp>【HOW】（细化步骤）\u003c/p>\u003cp>在这，真的要给大家点一个大大的赞！大家已经从原文提炼出了很多关键信息，这和我归纳总结的怎么将“固定型思维模式”转化为“成长型思维模式”的步骤已经非常接近了。为了方便大家记忆，我们可以叫它：“成长四步曲”——我变原形。\u003c/p>\u003cp>\u003cstrong>我——接纳自我。\u003c/strong>世界本无完人，我们要勇敢接纳当下的自己。\u003c/p>\u003cp>\u003cstrong>变——转变思维。\u003c/strong>做事前留意自己内心的想法，是积极主动，还是消极被动？有意识将想法由“消极”往“积极”去转变；\u003c/p>\u003cp>\u003cstrong>原——分析原因。\u003c/strong>分析是哪些原因和想法导致自己停滞不前的。我们可以自己分析，也请教他人。\u003c/p>\u003cp>\u003cstrong>形——立即行动。\u003c/strong>找到了原因，就要采取行动，积极改变。这里，同样可以请教他人，借助工具。要相信“只要思想不滑坡，办法总比困难多。”\u003c/p>\u003cp>【个人案例】\u003c/p>\u003cp>来举个我自己的例子吧。在需要公众演讲的场合，我经常会不自觉陷入到固定型思维中。我常因为紧张没有把自己的想法完全表达出来，更别提通过发言给他人留下好印象了。那学习了“成长四步曲——我变原形”后，我准备作出以下改变：\u003c/p>\u003cp>\u003cstrong>我——接纳自我：\u003c/strong>每次发言前，接纳当下的自己。我现在的演讲水平比起那些演讲达人，确实存在较大的差距；\u003c/p>\u003cp>\u003cstrong>变——转变思维：\u003c/strong>当出现“我不行”，“讲不好太丢人”等想法时，停下来，有意识把这一类“固定型思维”向“成长型思维”去转变。比如：“错就错呗，没有人是什么都懂的”，“就是因为讲得不好，所以才更不能放过每一次演讲锻炼机会”；\u003c/p>\u003cp>\u003cstrong>原——分析原因：\u003c/strong>想想为什么我每次会紧张。是缺乏公众演讲的技能，练习得太少，还是我太在乎别人的看法和评价了；\u003c/p>\u003cp>\u003cstrong>形——立即行动：\u003c/strong>找到根源后，我参加了专门的演讲课程，向专业的老师请教并刻意练习；平时参加活动，也要求自己至少发言一次。\u003c/p>\u003cp>相信通过使用“成长四步曲”，我的公众发言能力会逐步提升。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>\u003cstrong>适用范围：\u003c/strong>\u003c/p>\u003cp>1、学习领域：获取知识和技能培养。\u003c/p>\u003cp>2、工作上：职业发展和团队协作。\u003c/p>\u003cp>3、人际方面：友情维护和社交拓展。\u003c/p>\u003cp>\u003cstrong>不适用范围：\u003c/strong>\u003c/p>\u003cp>1、基本道德和伦理原则的情境中不适用。比如像考试作弊这种行为，不能用成长型思维来辩解。\u003c/p>\u003cp>2、客观存在不可变因素的情况。比如地球引力的存在等。\u003c/p>","interaction":"\u003cp>好的，现在我们来拆为己用。大家还记得我们的分组吗？请大家在小组内进行角色扮演。\u003c/p>\u003cp>\u003cstrong>四分钟到，现在我想邀请一组小伙伴上台来角色扮演，时间是两分钟。\u003c/strong> 接下来我们邀请施老师和婷婷老师，大家给他们一些掌声鼓励好不好？\u003c/p>\u003cp>\u003cstrong>施老师(导演)：\u003c/strong>下面由婷婷老师担任小白，我担任导演。下面开始。小白，最近我们拆书帮智行分舵准备举办一次年会，所以我非常想邀请你来担任我们的主持人，请问可以吗？\u003c/p>\u003cp>\u003cstrong>婷婷老师（小白）：\u003c/strong>我主持过六个人的，但是一下子主持拆书帮年会，由几十个人，我感觉我可能胜任不了，有点害怕。\u003c/p>\u003cp>\u003cstrong>施老师(导演)：\u003c/strong>没关系，我最近刚好学习了一本书，叫做 《终身成长》，这本书里面刚好有两个概念，一个是固定型思维，一个是成长型思维，其实我们每个人都会有固定型思维，我们应该怎么成长为成长型思维呢？分为四步：\u003c/p>\u003cp>\u003cstrong>第一步，接纳自我。\u003c/strong>其实我们每个人都要学会接纳自我，接纳自己，我们每个人就没有那么大压力了。\u003c/p>\u003cp>\u003cstrong>第二步，转变思维。\u003c/strong>我们要怎么从固定性思维，转化成成长型思维呢？其实每次活动，都是一次学习的机会，你经历了你就成长了；\u003c/p>\u003cp>\u003cstrong>第三步，分析原因。\u003c/strong>比如说，你刚才提到只主持过六个人的，没有主持过二、三十人的活动，那你需要分析下问题，我遇到这些问题，要怎么去练习和解决这些问题。\u003c/p>\u003cp>\u003cstrong>第四步，立即行动。\u003c/strong>当你有足够的准备后，就大胆去试吧，在拆书帮这个平台上，犯错没关系，大家会给你掌声，只有在这个平台上，你不断地犯错，你到外面的平台，才能获得更多的掌声和鲜花。所以，小白同志，大胆去试吧！\u003c/p>\u003cp>\u003cstrong>婷婷老师（小白）：\u003c/strong>听完您的话，我想立马去采取行动了。\u003c/p>\u003cp>\u003cstrong>【简单回应】\u003c/strong>\u003c/p>\u003cp>好的，谢谢两位，我觉得大家的掌声已经说明一切了，我觉得这个版本非常全面，意简言赅，施老师功力深厚，婷婷老师非常有空杯心态，感谢两位带来的完美示范。时间关系，我们就不听另外一组举手小伙伴的分享了，一会可以进行私下的交流。\u003c/p>\u003cp>\u003cstrong>为巩固学习，我给大家布置一个课后作业。\u003c/strong>接下来的一周，你或者你的身边是否会出现因面对压力太大想要放弃的场景。比如：\u003c/p>\u003cp>1、你花了很多心思去辅导孩子学业，结果成绩还是不见起色，让你感觉好沮丧不想管孩子了；\u003c/p>\u003cp>2、公司有挑战性的项目时，你总会躲远，生怕不小心砸到自己，搞得头破血流；\u003c/p>\u003cp>3、最近朋友职称考试又没有通过，觉得太难了，想想还是不要再折腾了。\u003c/p>\u003cp>\u003cstrong>请大家回去后，尝试用今天学到\u003c/strong>\u003cstrong>“成长四部曲”，去帮助自己或者他人从这一类的“固定型思维”转变为“成长型思维”。\u003c/strong>完成任务的小伙伴，请在下周五前将你的案例通过微信发给我，我会针对你的实践做出反馈，非常期待大家的作业。\u003c/p>\u003cp>\u003cstrong>一洲课后提交作业\u003c/strong>\u003c/p>\u003cp> 作为一名大学生，我即将要期末考试了，因为课程内容难度大，在这之前的学习过程中，没有很好地掌握，考试即将到来，我不免有担忧和沮丧的情绪，觉得自己肯定考不好。结合学习的成长四部曲，我会这么去做：\u003c/p>\u003cp>\u003cstrong>第一步，接纳自我。\u003c/strong>此前确实没有好好去掌握，现在知识点多，时间紧，有些负面情绪是难免的。考试是客观存在的，无论我是否选择面对，它都会如期到来，而我希望自己取得好成绩。\u003c/p>\u003cp>\u003cstrong>第二步，转变思维。\u003c/strong>我要相信现状不是不可以改变的，只要我付出时间去学习，一定能提高自己的水平和成绩。\u003c/p>\u003cp>\u003cstrong>第三步，分析原因。\u003c/strong>分析我不想面对的原因，是因为过去的学习给我留下了不好的学习痕迹，在复习的过程中不断想起过往不好的经历，觉得自己这次也不会考好。但我不能停留在原地，任由过往吞没自己，我一定要告别舒适区，做出尝试，相信自己。\u003c/p>\u003cp>\u003cstrong>第四步，立即行动。\u003c/strong>知行合一，抓紧时间认真复习，并自己给自己反馈。\u003c/p>\u003cp>【强有力的结束语】\u003c/p>\u003cp>最后，送给大家一句话：知不足，然后才能有进步，未来的你一定比现在的你更优秀！感谢大家的参与，也期待收到大家的作业。我的分享到此结束，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1741579746000,"updated_at":1767238627000,"ria":true},{"id":18590,"topic":"迈出第一步","learn_goal":"","remark":"不同的思维方式会遇到不同的自己，改变选择才能遇到完整的自己。","level":"TF1-1","duration":12,"status":30,"type":0,"chaishujia":{"username":"封邑","city":""},"club":{"name":"湖州吴越分舵","city":"湖州"},"prologue":"\u003cp>【自我介绍】\u003c/p>\u003cp>大家好！我是吕营，双口吕营业的营，我的名字里四个口字，下面我想带大家认识一个生僻字，众口为【㗊：jí】意为喧哗，也念【㗊：léi】同雷声的雷，指声音大。我希望自己的语言可以像雷声一样刺穿天空。下面我用3个标签来介绍\u003c/p>\u003cp>第一个标签是【终身学习】，我希望自己始终保持学习的状态，感受这个新鲜的世界。\u003c/p>\u003cp>第二个标签是【问题分析师】，因为我的职业是软件需求分析，所以我特别喜欢分析和解决问题。\u003c/p>\u003cp>第三个标签是【新晋拆书家】，拆书学习法是我非常认可的一种学习方法，希望可以把书里的知识拆分己用，然后用自己学到的技能影响身边的人，改变自己就是改变世界。\u003c/p>\u003cp>【拆书帮介绍】\u003c/p>\u003cp>说到新晋拆书家，可能大家对拆书比较陌生，下面我用3分钟的时间来介绍什么是拆书、拆书法、拆书帮。\u003c/p>\u003cp>拆书：拆解书中知识为己所用。简单来说就是学以致用。（是目的）\u003c/p>\u003cp>拆书法：是大家为了达到学以致用的目的，所使用的一种学习方法。那么这种学习方法是什么样的呢？主要是通过RIA3种便签的写作来完成学习。\u003c/p>\u003cp>R代表reading即阅读，选择要重述的书页，把书页转化为可阅读拆页。\u003c/p>\u003cp>I代表interpretation即理解，重述要理解的拆页，把拆页转化为可使用的方法。\u003c/p>\u003cp>A代表appropriation即致用，使用要使用的方法，把方法转化为可应用的场景。\u003c/p>\u003cp>说清楚了拆书和拆书法，那么可能有人还好奇什么是拆书帮，下面我来说明一下我们拆书帮\u003c/p>\u003cp>拆书帮：\u003c/p>\u003cp>我们这个帮里有什么样的人：是一群以拆书法为学习方法组织起来的社群。\u003c/p>\u003cp>我们的目的是什么：是一个非营利性青年自组织，致力于培养拆书家，互助陪伴，助人达己。\u003c/p>","ratings_count":1,"texts":[{"id":22893,"quote":"\u003cp>【R】阅读原书拆页1~2分钟\u003c/p>\u003cp>大家看一下手里，我为大家准备的今天要阅读的书页，下面我们每个人用1~2分钟的时间来快速的通读一遍书页内容，读完的同学可以举手示意我一下。\u003c/p>\u003cp>片段1来源：微信阅读的电子书《终身成长》P647~P648\u003c/p>","explains":"\u003cp>【I：重述知识点】5分钟\u003c/p>\u003cp>我今天读到的书页内容是介绍如何向成长型思维迈出第一步的方法。那我们为什么要向成长型思维迈出第一步呢？我选不向成长型思维迈出第一步行不行呢？当然行这是每一个人对自己人生的选择权力。只是我们要知道我们错过了什么，当我们开始停止成长的那一刻我们的世界就停在了那。从那以后的每一天都是在重复过去。我们可以用成长型思维模式打破自己世界的边界走向新世界。\u003c/p>\u003cp>相信大家已经开始对成长型思维模式开始有了一点兴趣，那么今天就让我们来体验一下成长型思维模式的在困境下的行动过程。\u003c/p>\u003cp>首先我们来学习一下成型思维模式在困境下的解决办法：\u003c/p>\u003cp>第1步：认真考虑清楚，并写下自己的目标。\u003c/p>\u003cp>第2步：认真考虑为了达成目标，自己需要做哪些行动，并且把需要做的行动写下来。\u003c/p>\u003cp>第3步：选择一项可以立刻去做的行动，并开始行动\u003c/p>","interaction":"\u003cp>【A1：联系具体经验】1~2分钟\u003c/p>\u003cp>我最近就遇到了一个困境，就是在写A1便签时，无法回忆起相似的或者有关联的经历。我为了完成A1便签的写，使用了成长型思维模式的解决办法。\u003c/p>\u003cp>首先写下目标：快速的完成A1便签写作\u003c/p>\u003cp>然后列举了一些行动：（1）认真回忆当天所经历的每一场景（2）回忆自己有畏难情绪出现的场景\u003c/p>\u003cp>最后选择了场景2，回忆自己有畏难情绪的场景。\u003c/p>\u003cp>然后把畏难场景写成A1便签\u003c/p>\u003cp>【A2：具体应用设计】3分钟\u003c/p>\u003cp>下面是我的A2便签。\u003c/p>\u003cp>困难是：行动缓慢\u003c/p>\u003cp>第1步写下目标：计划用1个月的时间，通过AI模型搭建MBTI的性格测试应用，发布再抖音小程序。\u003c/p>\u003cp>第2步写可行动的：\u003c/p>\u003cp>（1） 收集AI模型的相关的培训教程\u003c/p>\u003cp>（2） 自己摸索尝试大语言模型的应用使用\u003c/p>\u003cp>（3） 学习AI模型的原理\u003c/p>\u003cp>第3步选择行动，立刻去做：\u003c/p>\u003cp>（1） 第1周完成AI模型的相关培训教程的收集工作\u003c/p>\u003cp>（2） 第2周筛选出符合自己需求的教程进行学习\u003c/p>\u003cp>（3） 第3周尝试使用理论搭建应用\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1736944409000,"updated_at":1744066406000,"ria":true},{"id":18182,"topic":"思维转变和行为调整，促进目标达成","learn_goal":"","remark":"“这个太难、那个我不会、我天生就这样……”这样的想法每天都会产生，面对困难、挑战、批评等你是如何处理的呢？是知难而退，拒绝改变，还是直面挑战，想办法去解决呢？《终身成长》这本书详细的描述了固定型思维和成长型思维是如何影响你的想法和行为，及如何行动起来，发现人生更多的可能性。","level":"TF3-3","duration":80,"status":30,"type":0,"chaishujia":{"username":"倩倩.","city":""},"club":{"name":"郑州轩辕分舵","city":"郑州"},"prologue":"\u003cp>【自我介绍】大家好，非常开心大家来参加我的3-3过级，我是二级拆书家倩倩、轩辕分舵的组织长老，还是一个乐器新手。\u003c/p>\u003cp>【流程】我先简单介绍一下拆书大体流程，本次拆书共两个片段，时间大概一个多小时，第一个片段大约50分钟，第二个片段大约20分钟。\u003c/p>\u003cp>【学习总目标】希望通过今天的分享，大家在面对一些困境时，可以识别出固定型思维，并将固定型思维转变为成长型思维，然后通过成长型思维解决问题的办法，将一个模糊想法转变成为一个具体的行动。这两个片段是递进关系。\u003c/p>\u003cp>【分组】为了一会儿互动方便，咱们分成两组，左手是一组，右手是一组。\u003c/p>\u003cp>\u003cem>拆书技能观察点2：选择图书是实用类或理论类图书。\u003c/em>\u003c/p>\u003cp>\u003cem>拆书技能点观察5：学习者场景介绍法中，能够清晰辨别出事件，提问，影响和解决4个步骤。\u003c/em>\u003c/p>\u003cp>【场景】接下来我先给大家分享几个场景：\u003c/p>\u003cp>①一个15岁的孩子学游泳，他说：“游泳太难了”，然后不再学了。\u003c/p>\u003cp>②一个18岁的孩子学英语，他说：“这一堆字母，记不住”，然后放弃英语。\u003c/p>\u003cp>③一个35岁的员工在工作中遇到了新的设备，他想：“我年龄大了，学不会。”于是拒绝去学习新设备。\u003c/p>\u003cp>【提问】在坐的小伙伴，你曾有过类似的经历没？你是如何处理的呢？是知难而退，拒绝改变，还是直面挑战，想办法去解决呢？\u003c/p>\u003cp>【影响】一个人的思维会影响一个人的发展，甚至整个人生状态。那个15岁觉得游泳难放弃学游泳的孩子到18岁遇到一个喜欢的人约他游泳，他只好说“我不会耶”。那个18岁觉得单词记不住放弃英语的学生，28岁时出现一个很棒但要会英文的工作，他只好说“我不会呀”。那个35岁觉得新设备难的员工，38岁出现在公司的裁员名单上。\u003c/p>\u003cp>【解决】那么怎样才能找到更好的应对方法呢？在卡罗尔.德韦克写的《终身成长》这本书中，可以看到固定型思维和成长型思维是如何影响你的想法和行为，并告诉你在固定型思维模式中，如何行动起来，发现人生更多的可能性。\u003c/p>\u003cp>\u003cem>拆书技能点观察4：学习目标中包含学习者要完成行为的具体内容和完成程度，现场学习设计清晰，体现了该学习目标。\u003c/em>\u003c/p>\u003cp>【\u003cstrong>学习目标\u003c/strong>】接下来学习第一个片段，希望大家跟随我学习完第一个片段后，可以在需要突破困境时（界定），可以识别出（行为）思维方式（澄清）。\u003c/p>\u003cp>\u003cem>拆书技能点观察10：使用【A1】技能点环节的量表题清晰设置了多个选项，学习者通过自测可以了解在某种情况下自己的表现。\u003c/em>\u003c/p>\u003cp>在此之前我们先来做一个小测试，判断一下自己处在成长型思维的哪个阶段。这里有5道自测题，请大家花1分钟时间，仔细阅读下面表格中的每句话，根据自己的实际情况为自己打分，1代表完全不符合，6代表非常符合。然后计算出总分。现在开始。\u003c/p>\u003cp>//我看大家都做完了，都算出自己的总分了哈。\u003c/p>\u003cp>\u003cstrong>【自测解释】\u003c/strong>\u003c/p>\u003cp>有没有得分在25分以上的伙伴？请举手。\u003c/p>\u003cp>哇，超级厉害，高水平的成长型思维模式。\u003c/p>\u003cp>有没有得分在16-24分之间的伙伴？请举手。\u003c/p>\u003cp>总分在16-24分，你具有一定水平的成长型思维模式，可以借助一些方法和工具，通过练习，不断向成长型思维模式去转变。\u003c/p>\u003cp>15分以下的有吗？\u003c/p>\u003cp>没有，恭喜大家。\u003c/p>\u003cp>\u003cstrong>在这里给大家解释一下\u003c/strong>：我们每个人都同时拥有成长型和固定型两种思维模式，只是表现得方面不一样而已，今天的测试也并不代表永远不变，它也可以通过学习而改变的。\u003c/p>\u003cp>//现在我们已经了解了我们成长型思维模式的现状,接下来请大家花2分钟时间看一拆页，读完后抬头示意我下。\u003c/p>","ratings_count":2,"texts":[{"id":22448,"quote":"\u003cp>\u003cem>拆书技能点观察3：每个拆页未超过2页图书内页，至少有一个拆页不包括how的内容，两个拆页是有逻辑关系的，比如递进关系。\u003c/em>\u003c/p>\u003cp>请想象一下，尽可能生动地去想，你是一个年轻人，经历了非常糟糕的一天：\u003c/p>\u003cp>你去上一门对你来说很重要的课，而且你非常喜欢这门课。你的教授公布了期中考试成绩，你得了C+。你非常失望，等到晚上准备回家的时候，你发现自己的车上贴了一张违章停车罚单。你感到非常泄气，打电话给最好的朋友想要倾诉，但是却没有打通。\u003c/p>\u003cp>你会怎么想？你会有什么样的感受？你会怎么做？当我问固定型思维模式者时，他们是这样对我说的：“我感到被拒绝了。”“我是个失败者。”“我是个傻瓜。”“我感到自己很没用而且愚蠢——所有人都比我优秀。”“我太差劲了。”换句话说，他们会把发生的事当作一个衡量自己的能力和价值的直接的标尺。\u003c/p>\u003cp>他们会这样看待自己的生活：“我的人生太可悲了。”“我没有人生。”“楼上的那个人不喜欢我。”“这个世界跟我过不去。”“有人想要毁掉我。”“没有人爱我，所有人都恨我。”“生活是不公平的，所有的努力都是白费。”“生活太糟糕了，我太傻了。”“我身上没发生过什么好事。”“我是地球上最不幸的人。”\u003c/p>\u003cp>他们是如何应对这些烦心事的呢？“我就不应该浪费这么多时间和精力去办一件事。”（换句话说，不会再让任何人来评判我。）“什么都不做。”“吃东西。”“找机会冲别人大吼。”“边听音乐边郁闷。”“躲到壁橱里坐着。”“找人打一架。”“哭。”“摔东西。”“还能怎么办？”\u003c/p>\u003cp>还能怎么办！你知道，在模拟这个情景的时候，我特意将成绩写成了C+而不是F，只把考试设定成期中考试而不是期末考试，你的车只是被贴了罚单而不是被毁了，打电话给朋友倾诉之举只是没有成功，你并没有被朋友直接拒绝。没有什么灾难性或不可逆转的事情发生，但仅仅是在这些情况的影响下，\u003cstrong>固定型思维模式者就已经产生了这种彻底的失败感和无力感。\u003c/strong>\u003c/p>\u003cp>当我把这些情况原封不动地拿给那些成长型思维模式者看后，他们是这样说的：\u003c/p>\u003cp>“我会更努力地学习，下次停车的时候我要更加小心一些，不知道我的朋友是不是今天过得不开心。”\u003c/p>\u003cp>“C+这个成绩告诉我，我必须在课堂上加倍付出努力，我依然有半个学期的时间来提高我的成绩。”\u003c/p>\u003cp>那么，他们会如何应对呢？\u003c/p>\u003cp>“我必须开始考虑，为了下一次测验，我要更努力地学习（或者换个学习方法），我会缴清罚款，下次再给朋友打电话的时候，我们再好好聊聊。”\u003c/p>\u003cp>“我会总结我在期中考试到底犯了哪些错误，下一次要做的更好。”\u003c/p>\u003cp>“下一次停车的时候，我要小心一些。”\u003c/p>\u003cp>不是说你必须拥有某种思维模式，而拥有另一种思维模式的人就会产生挫败感。谁不是这样呢？糟糕的成绩、朋友或爱人的拒绝都不是什么开心的事，没有人会喜欢这些糟糕的事情。只是这些有着\u003cstrong>成长型思维的人不会给自己贴上标签，或对自己失去信心。即使他们感到沮丧，他们也准备好了去承担风险，直面挑战，继续为此奋斗。\u003c/strong>\u003c/p>","explains":"\u003cp>\u003cem>拆书技能点观察8：有体现【I】环节的互动，且拆书家能精准掌控。\u003c/em>\u003c/p>\u003cp>\u003cstrong>【简短互动】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>好的，我看大家都看完了，我们一起来看一下，这个片段中说了哪两种思维模式？\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>固定型思维和成长型思维\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>固定型思维会让人产生什么感觉？\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>失败感和无力感\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>成长型思维的人面对困难挑战是什么状态？\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>承担风险，直面挑战，继续为此奋斗。\u003c/p>\u003cp>\u003cem>拆书技能点观察7：【I】讲解引导时，拆书家举出了案例，并通过概念与匹配例子之间的对比,引出知识点逻辑、步骤;或者【1】讲解引导时，拆书家主动给出貌似相近或相反的概念，并辨析了易混淆概念之间细微差异，从而让学习者更清晰知识点的适用边界(达到其一即可打勾)。\u003c/em>\u003c/p>\u003cp>\u003cstrong>【辨析概念】\u003c/strong>这个片段，通过“倒霉的一天”，展示了对待同样的事情“固定型思维模式”和“成长型思维模式”典型想法和行为。固定型思维认为人的能力是先天的，成长型思维认为人的能力可以通过后天努力培养的，所以面对相同的事情会有不同的反应。具体的区别我们可以看一下这个图：\u003c/p>\u003cp>从这个图上我们可以看到：\u003c/p>\u003cp> 遇到挑战时：固定型思维会避免挑战，成长型思维会迎接挑战\u003c/p>\u003cp> 遇到阻碍时：固定型思维会自我保护或轻易放弃，而成长型思维会面对挫折坚持不懈\u003c/p>\u003cp> 对努力的看法：固定型思维认为努力是不会有结果的或者会带来更坏的结果，而成长型思维认为熟能生巧\u003c/p>\u003cp> 对批评的看法：固定型思维会忽视有用的负面反馈信息，而成长型思维会从批评中学习。\u003c/p>\u003cp> 他人成功时：固定型思维感到他人的成功对自己造成了威胁，而成长型思维会从他人的成功中学到新知，获得灵感。\u003c/p>\u003cp>\u003cstrong>【案例与概念相互参照】\u003c/strong>下面我们一起来看几个例子：\u003c/p>\u003cp>\u003cstrong>例1: 小A被分配了一个具有挑战性的项目，他找借口推脱，不想干。这是哪种思维模式?\u003c/strong>\u003c/p>\u003cp>固定性思维，往往面对阻碍、挑战会放弃来逃避挑战。\u003c/p>\u003cp>而成长性思维会积极迎接挑战，渴望通过挑战来提升自己。\u003c/p>\u003cp>比如，主动申请参与重要项目，即使知道会面临很多困难。\u003c/p>\u003cp>\u003cstrong>例2：小A新项目干了几天，觉得太难，就放弃了，认为自己不是那块料。这是哪种思维模式?\u003c/strong>\u003c/p>\u003cp>固定性思维，认为能力是天生的，努力不一定能带来成功，面对阻碍也轻易放弃。而成长型思维认为努力是取得成功的关键。通过持续的努力和学习，可以不断提升自己的能力。\u003c/p>\u003cp>比如，为了完成新项目，会坚持不懈地学习，不怕困难。\u003c/p>\u003cp>\u003cstrong>例3：小A项目结束提交了一份报告，而这份报告在团队会议上遭到了其他成员的批评，指出报告中的一些数据错误和逻辑问题。小A很生气，觉得别人在挑刺。这是哪种思维模式?\u003c/strong>\u003c/p>\u003cp>固定型思维，认为批评是对他的个人攻击。\u003c/p>\u003cp>成长型思维会感谢团队提供的反馈，并认真对待这些批评。\u003c/p>\u003cp>他会想：“虽然这次的数据有误，但我现在知道了需要更仔细地检查，下次我会更加注意细节。\u003c/p>\u003cp>\u003cstrong>例4：项目结束，团队中的小B因为工作出色获得了晋升。小A想：“为什么是他而不是我？是我不如他聪明？”这是哪种思维模式?\u003c/strong>\u003c/p>\u003cp>固定型思维，认为别人的成功，显示自己的不足，对自己造成威胁。\u003c/p>\u003cp>成长型思维会庆祝他人的成功，并从中寻找可以学习的地方。\u003c/p>\u003cp>他会想：“我很好奇他是怎么做到的，我可以向他学习什么？也许我可以跟他聊聊，看看是否能学到一些新的技能或方法。”\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>这里再强调一下,这两种思维是每个人都会有的，并不是说你有这种表现就是一个固定型思维的人，而是在面对挑战、失败、批评等这样的情况下表现出了固定型思维倾向。\u003c/p>\u003cp>\u003cem>拆书技能点观察6：【I】讲解引导时，拆书家给出了与学习目标相关的具体行动建议或具体步骤。\u003c/em>\u003c/p>\u003cp>\u003cstrong>【How】\u003c/strong>从例子中我们可以看出成长型思维更有利于个人的发展和进步，那么在需要突破困境时，如何转换我们的思维模式呢?共需四步：\u003c/p>\u003cp>\u003cstrong>1、\u003c/strong> \u003cstrong>接受。\u003c/strong>接受我们每个人都拥有两种思维模式的事实。这一步非常重要，因为接受是转变的开始。比如：我们面对挑战想逃避而不是迎接，或者被批评时感到受到威胁而不是看到改进的机会，这都是正常的表现。\u003c/p>\u003cp>\u003cstrong>2、\u003c/strong> \u003cstrong>观察。\u003c/strong>观察自己在遇到挑战、困难或失败时的内心想法是什么？?把想法参考着上面固定型思维的表现，找到这件事背后的固定型思维是什么。(是挑战?别人批评?失败?巨大压力?)。比如：我前段工作调整，新工作总是有些不熟悉，一遇到不会的，我就开始烦躁不想做。这件事中我的想法是不会干就不想做。对应固定思维就是遇见阻碍就想放弃，逃避他。\u003c/p>\u003cp>\u003cstrong>3、\u003c/strong> \u003cstrong>命名。\u003c/strong>给自己的固定型思维模式起一个中性而不是贬低自己的拟人化名字。比如“小固”。\u003c/p>\u003cp>\u003cstrong>4、\u003c/strong> \u003cstrong>教育。\u003c/strong>像教育孩子一样教育“小固”，让它按照成长型思维的方式行动。比如：小固，我们一起来看看成长型思维怎么做？成长型思维面对阻碍时会坚持不懈地努力，不怕困难，我们要和它一样，继续努力。\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>无论是在工作还是生活中，当我们需要突破困境时，特别是当我们出现逃避挑战、害怕失败、觉得努力无用、批评很生气这些想法感受时，就要反思是否陷入了固定思维模式，并争取将其转化为成长型思维。\u003c/p>\u003cp>\u003cstrong>【举例子】\u003c/strong>我举一个自己的例子，我孩子最近开始有作业了，但是每次孩子写作业，我都是左催右催，我感觉孩子不会自己主动写、没有自驱力，很无奈只想打一顿。但是我又想打了也解决不了问题，我能改变的只有自己，就开始从自己身上找原因找方法，是不是我的想法有什么问题？是不是陷入固定型思维？然后就发现了自己陷入了固定型思维模式，并用接受-观察-命名-教育四步进行了转变。\u003c/p>\u003cp>\u003cstrong>一、接受：\u003c/strong>我有固定型思维，是正常的，每个人都有。\u003c/p>\u003cp>\u003cstrong>二、观察:\u003c/strong>我察觉了一下，这件事我背后的想法是，我很担心孩子，担心她未来没自驱力怎么办？对比着上面的图，我发现这件事我的固定型思维是1、对能力：我认为孩子的自驱力是不会变化的，是天生的。2、对挑战：面对提高孩子自驱力这个问题，我不知道怎么做、觉得很难，在这个巨大的挑战面前，我逃避了这个挑战。\u003c/p>\u003cp>\u003cstrong>三、命名：\u003c/strong>给这个固定型思维模式起个名字叫“小固”。\u003c/p>\u003cp>\u003cstrong>四、教育：\u003c/strong>我给它说：小固，你又出来了，成长型思维认为能力可以提升，并会积极应对挑战，我们一起想想有什么办法和工具可以培养孩子学习自驱力。\u003c/p>\u003cp>通过“接受-确定-命名-教育”这四步转换思维后，我想法及关注点从抱怨孩子变成了积极寻找提升孩子学习自驱力方法，并将这些方法进行运用调整。\u003c/p>","interaction":"\u003cp>\u003cem>拆书技能点观察11：在未包含how拆页的【A3】环节指令清晰，学习者在拆书家主持的微行动学习环节，讨论出了这类问题的解决方案。其中，微行动学习环节包含了5个步骤：1）拆书家引导学习者提出，并明确一个需要解决的问题；2）拆书家引导学习者分组讨论问题本质；3）拆书家引导学习者明确出问题本质；4）拆书家引导学习者分组讨论问题解决方案；5）请每组学习者代表讲解自己组的讨论成果。\u003c/em>\u003c/p>\u003cp>\u003cstrong>&lt;拆书家&gt;\u003c/strong> 类似的事情还有很多，比如我驾照十年不敢上路、考证没考过不想继续、运动三天觉得太难就放弃、被批评了觉得他人挑刺、想学摄影一直没开始，这些都是我经历的事情，现在请大家回想一个自己遇的挑战、失败、阻碍、被批评固定型思维出现的场景，然后用转变四步法进行转变思维，请写在学习手册上，时间三分钟。注意需要写一个现在的你还没有解决的，正在困扰你的事情。\u003c/p>\u003cp>【微行动步骤】\u003c/p>\u003cp>\u003cstrong>一【明确问题】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>我想请问一下大家在刚才写的过程中，觉得这四步哪一步比较难？或者有疑问的？ \u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>教育/观察最难。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>现在请大家轮流在小组内用一句话讲一下刚才写下的事件，然后投票选出一个你们最有兴趣去解决的事件。给大家3分钟时间。\u003c/p>\u003cp>(学习者小组内讨论，投票)\u003c/p>\u003cp>\u003cstrong>【重述并明确问题】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>好的,我们确认了每组要讨论的场景，我们重述并明确一下问题：\u003c/p>\u003cp>\u003cstrong>小组一卡卡的问题是：\u003c/strong>在运动减肥这件事情上，觉得教育自己用成长型思维去行动这一步最难，是这样吗？\u003c/p>\u003cp>\u003cstrong>案主/学习者：\u003c/strong>是的。\u003c/p>\u003cp>\u003cstrong>小组二潇潇荷问题也是：\u003c/strong>在运动减肥这件事情上，觉得教育自己用成长型思维去行动这一步最难，是这样吗？\u003c/p>\u003cp>\u003cstrong>案主/学习者：\u003c/strong>对。\u003c/p>\u003cp>\u003cstrong>二【引导分组讨论问题本质 】\u003c/strong> \u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>请案主在小组内用1分钟的时间描述一下这件事情，及为什么难？有什么困扰？\u003c/p>\u003cp>以下为第一小组记录:\u003c/p>\u003cp>\u003cstrong>卡卡（以下用案主）描述：\u003c/strong>我早上晨跑，担心自己坚持不了，拉着家人一起跑，但是就是没有瘦，体重还增加了，控制不住嘴，教育自己减肥太难，想放弃了，但是又想减肥。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>现在我们一起结合自己的经验来向案主进行追问和讨论，对案主而言，是什么原因导致刚才问题的产生，问题真正的原因究竟是什么，追问的方法很多，建议大家可以用连续几个“为什么”向案主进行追问，比如你觉得难在哪里？为什么对你来说很难？你觉得自己卡在了哪里？也可以说一说自己的理解，认为有哪些原因。请组长将原因写着便签纸上。\u003c/p>\u003cp>\u003cstrong>学习者1：\u003c/strong>那你为什么觉得很难？\u003c/p>\u003cp>\u003cstrong>案主：\u003c/strong>因为坚持跑步了三个月，体重没下降，反而涨了五斤，就觉得没啥效果，没有收到正向反馈。\u003c/p>\u003cp>\u003cstrong>学习者1：\u003c/strong>你爱运动吗？\u003c/p>\u003cp>\u003cstrong>案主：\u003c/strong>不爱，运动的目的性非常强，就是减肥。\u003c/p>\u003cp>\u003cstrong>学习者2：\u003c/strong>你是为什么想到要减肥呢？\u003c/p>\u003cp>\u003cstrong>案主：\u003c/strong>因为想健康\u003c/p>\u003cp>\u003cstrong>学习者2：\u003c/strong>体征正常？\u003c/p>\u003cp>\u003cstrong>案主：\u003c/strong>是的\u003c/p>\u003cp>\u003cstrong>学习者3：\u003c/strong>你还做了什么运动？坚持了多长时间？\u003c/p>\u003cp>\u003cstrong>案主：\u003c/strong>三个月\u003c/p>\u003cp>\u003cstrong>学习者3：\u003c/strong>你早上能起的来吗？\u003c/p>\u003cp>\u003cstrong>案主：\u003c/strong>还好 \u003c/p>\u003cp>\u003cstrong>学习者1：\u003c/strong>你本身不爱运动，你有尝试过换个其他方式吗？比如练个瑜伽，跳个操？\u003c/p>\u003cp>\u003cstrong>案主：\u003c/strong>没有，可能我需要换另外一种方式\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>那经过这些追问和讨论，大家可以总结一下都有哪些原因？\u003c/p>\u003cp>\u003cstrong>案主：\u003c/strong>原因有：1、实践后没效果、没正反馈。2、不爱运动、不擅长运动。3、目标不是减肥，是身体指征正常。4、坚持不够长。5、方式比较单一（晨跑）。\u003c/p>\u003cp>\u003cstrong>三【明确问题本质】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>经过刚才的讨论我们初步讨论了一些原因，然而这么多原因中，只有一个是最重要最本质的原因，现在请大家继续讨论，从中找到一个最重要、最根本的一个原因，时间5分钟。 \u003c/p>\u003cp>\u003cstrong>学习者1：\u003c/strong>我们刚讨论出来的原因有：1、实践后没效果、没正反馈。2、不爱运动、不擅长运动。3、目标不是减肥，是身体指征正常。4、坚持不够长。5、方式比较单一（晨跑）。你觉得这里面那个是最重要的原因？\u003c/p>\u003cp>\u003cstrong>案主：\u003c/strong>可能是方式单一。\u003c/p>\u003cp>\u003cstrong>学习者1：\u003c/strong>就是你还是希望通过运动来减重？\u003c/p>\u003cp>\u003cstrong>案主：\u003c/strong>是的，晨跑遇到困难后我就停止了，没有按照成长型思维坚持不懈，换个方法去尝试。\u003c/p>\u003cp>\u003cstrong>学习者1：\u003c/strong>还有其他原因吗？\u003c/p>\u003cp>\u003cstrong>案主：\u003c/strong>没有\u003c/p>\u003cp>\u003cstrong>学习者2：\u003c/strong>所以你的原因是，没有按照按照成长型思维多次尝试，是这样吗？\u003c/p>\u003cp>\u003cstrong>案主：\u003c/strong>是的\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>大家本质原因讨论出来了吗？\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>本质原因是没有按照成长型思维面对困难时，坚持不懈，多次尝试。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>请问案主同意吗？ \u003c/p>\u003cp>\u003cstrong>案主：\u003c/strong>同意\u003c/p>\u003cp>\u003cstrong>四【分组讨论解决方案】\u003c/strong> \u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>既然我们已经明确了问题的本质，请大家针对这个问题本质讨论一下解决方案，请记录员将解决方案写着便签纸上。\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>你的目标是什么？减肥还是什么？\u003c/p>\u003cp>\u003cstrong>案主：\u003c/strong>我的目标是体重减少10斤\u003c/p>\u003cp>\u003cstrong>学习者1：\u003c/strong>你可以请私教，就是贵。\u003c/p>\u003cp>\u003cstrong>学习者2：\u003c/strong>抖音上可多keep、运动手环健身环游戏，边玩边健身。\u003c/p>\u003cp>\u003cstrong>学习者3：\u003c/strong>还可以贴穴位\u003c/p>\u003cp>\u003cstrong>学习者1：\u003c/strong>对，按摩不用动。\u003c/p>\u003cp>\u003cstrong>学习者2：\u003c/strong>瑜伽\u003c/p>\u003cp>\u003cstrong>学习者1：\u003c/strong>减脂餐，美味还不减量。\u003c/p>\u003cp>\u003cstrong>学习者1：\u003c/strong>早睡早起你能做到吗？\u003c/p>\u003cp>\u003cstrong>案主：\u003c/strong>可以。\u003c/p>\u003cp>\u003cstrong>学习者1：\u003c/strong>跳绳你喜欢吗？\u003c/p>\u003cp>\u003cstrong>案主：\u003c/strong>我膝盖受过伤，不能跳。\u003c/p>\u003cp>\u003cstrong>学习者1：\u003c/strong>你愿意尝试的运动方式呢？比如游泳呢？或者瑜伽？上个体验课试试\u003c/p>\u003cp>\u003cstrong>案主：\u003c/strong>我比较感兴趣的是跳舞之类\u003c/p>\u003cp>\u003cstrong>学习者1：\u003c/strong>那尝试广场舞，还有什么？\u003c/p>\u003cp>\u003cstrong>案主：\u003c/strong>拉丁舞、现代舞、\u003c/p>\u003cp>\u003cstrong>学习者1：\u003c/strong>还有吗？\u003c/p>\u003cp>\u003cstrong>案主：\u003c/strong>太极、八段锦。\u003c/p>\u003cp>\u003cstrong>学习者1：\u003c/strong>每月尝试一个。\u003c/p>\u003cp>\u003cstrong>学习者2：\u003c/strong>找一个最喜欢的。\u003c/p>\u003cp>\u003cstrong>五【每组派代表讲解成果】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>大家讨论这么热烈，由于时间原因，我们先暂停了\u003cstrong>，\u003c/strong>现在请各小组分享一下我们的成果。\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>我们组案主的问题是在运动减肥这件事上教育自己用成长型思维去行动挺难的，原因就是1、实践后没效果、没正反馈。2、不爱运动、不擅长运动。3、目标不是减肥，是身体指征正常。4、坚持不够长。5、方式比较单一只有晨跑这一项。案主认为本质原因是：方法单一，失败后没有按照成长型思维面对困难，坚持不懈，换个方法，多次尝试。目标是体重减少10斤。方案就是：1、请私教。2、keep、运动手环健身环通过游戏方式提升兴趣。3、推拿按摩。4、美味减脂餐。5、早睡早起。6、尝试拉丁舞、现代舞、太极、八段锦等感兴趣的运动，每月尝试一个。\u003c/p>\u003cp>\u003cstrong>【总结】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>我总结一下，有三个方面：\u003c/p>\u003cp>1、外部：私教、keep、推拿\u003c/p>\u003cp>2、生活习惯调整：减脂餐、早睡早起。\u003c/p>\u003cp>3、运动方式多样化。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>请问案主，这些解决方案你满意吗？能解决你的问题吗？\u003c/p>\u003cp>\u003cstrong>案主：\u003c/strong>可以\u003c/p>\u003cp>\u003cem>拆书技能点观察12：对学习者的分享和提问，有体现通过向学习者提问来进行回应式反馈。\u003c/em>\u003c/p>\u003cp>\u003cstrong>【回应式反馈】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>非常好，看来经过我们的讨论，已经解决了案主的的问题了。大家怎么看？是否解决了这个问题? \u003c/p>\u003cp>\u003cstrong>学习者\u003c/strong>：解决了\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>再次感谢小伙伴们的思考和分享，因为时间关系，今天我们就先讨论到这里。\u003c/p>\u003cp>\u003cstrong>【总结过渡】\u003c/strong>录音位置：53：00\u003c/p>\u003cp>刚才我们经过接受、观察、命名和教育这四个步骤，我们已经启动了向成长思维模式的转变，并制定了方案。然而，许多人在实施过程中常常会遇到一个问题：即开始时充满热情，却难以维持持久的动力，最终导致行动力的减弱。这背后的一个关键原因，往往是我们在设定目标时未能做到足够具体和实际可行。接下来，让我们探讨如何制定更明确、更易达成的计划，以增强我们的持续行动能力。\u003c/p>\u003cp>\u003cem>拆书技能点观察4：学习目标中包含学习者要完成行为的具体内容和完成程度，现场学习设计清晰，体现了该学习目标。\u003c/em>\u003c/p>\u003cp>\u003cstrong>【学习目标2】\u003c/strong>希望大家跟随我学习片段二后，通过成长型思维解决问题的“可实行的计划”三步法（界定），制定（行动）一个行动计划（澄清）。\u003c/p>\u003cp>下面请花2分钟时间看一下拆页二，读完请示意一下我。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}},{"id":22450,"quote":"\u003cp>\u003cem>拆书技能观察点3：每个拆页未超过 2页图书内页，至少有一个拆页不包括 how 的内容。两个拆页是有逻辑关系的，比如递进关系。\u003c/em>\u003c/p>\u003cp>这本书剩下的内容都是关于你的。这是一些思维模式练习，请与我一同面对一系列困境。在每个例子里，你会先看到固定型思维模式的反应，然后体验成长型思维模式的解决办法。\u003c/p>\u003cp>困境 1：假设你报考了一所研究生院。你在志愿上只填了这一家学院，因为这是你唯一心仪的选择。你对录取充满自信，因为很多人都认为你在这个领域的研究工作独具创见，令人兴奋。但是，你的申请被拒绝了。\u003c/p>\u003cp>固定型思维模式的反应：一开始你告诉自己，竞争太激烈了，所以被拒绝不能反映你的真实水平。也许有太多条件优秀的申请者，研究生院无法全部接受。然后，你脑海深处那个声音开始说话了。那个声音说，你是在骗自己，为自己找借口。它对你说，招生委员会认为你的研究工作不尽如人意。过了一阵，你对自己说，这可能是真的。你的工作也许真的平庸乏味，不值一提。他们发现了这一点。毕竟他们都是专家。对方已经做出了裁决——你配不上这所学院。\u003c/p>\u003cp>在一番努力之后，你又说服自己相信了一开始的结论。这个结论也很合理，而且对你更有利。你感觉好一点了。在固定型思维模式下（在大多数认知疗法中也一样），事情到这一步就结束了。你重新找到了自尊，所以不用再多想了。但在成长型思维模式下，这只是一个开始：你之前只是在自说自话，现在要开始学习和自我提高了。\u003c/p>\u003cp>成长型思维模式的解决办法：\u003cstrong>考虑好你的目标，然后想想你要怎么做才能实现它。\u003c/strong>你能采取哪些措施让自己获得成功？你能收集到什么信息？\u003c/p>\u003cp>也许下次你该多申请几个学校。也许与此同时，你应该去广泛收集信息，让你的申请书更具竞争性：他们希望招收什么样的学生？他们最看重哪些经验？在进行下一次申请前，你要多积累这方面的经验。\u003c/p>\u003cp>这是一个真实的故事，我知道那位被拒绝的学生采取了哪些措施她听取了一些有力的成长型思维模式的建议。几天后，她给那所学校打了一个电话。她找到了相关负责人，并把自己的情况告诉了他。她说:“我不想质疑您的决定。我只是想问一下，如果下次我想再申请这所学校，我该怎么改进自己的申请书。如果您能在这方面给我一些反馈和建议，我将感激不尽。”\u003c/p>\u003cp>这位申请者最关键的反应就是给学校打电话收集更多信息，这并不容易。人们每天都计划着去做一些困难的事，但他们往往不会真的将其付诸行动。他们会想“我明天再做吧”，并发誓第二天一定要完成任务。但彼得•戈尔维策（Peter Gollwitzer）及其同事们的研究却显示，誓言，甚至是强烈的誓言，往往是没有一点用的。明天之后还有明天。\u003c/p>\u003cp>\u003cstrong>有效的做法是制定一个清晰具体的计划:“明天，在我休息的时候，我要喝杯茶，关上办公室的门，给学校打电话。”或者换个例子:“周三早上，我起床刷牙后，要马上坐在书桌前开始写报告。”或者是:“今天晚上，吃过晚饭洗完碗后，我要和我的妻子在客厅坐下，和她谈话。我会对她说:‘亲爱的，我想和你说点事，我想这会让我们更幸福。’”\u003c/strong>\u003c/p>\u003cp>想想你要去做的某件事，去学习的某些知识，或是要面对的某个问题。先明确目标，然后制定一个具体的计划。你要在何时实行计划?你将在哪里实行计划?你准备怎样实行计划?要考虑到具体的细节。这些具体的、可以设想的计划涉及你做事的时间、地点和方式。这会让你保持高效的行动力，当然会提高成功的概率。所以，不仅要制定一个成长型思维模式计划，更要设想具体细节，设想你要如何实行它。有效的做法是制定一个清晰具体的计划:“明天，在我休息的时候，我要喝杯茶，关上办公室的门，给学校打电话。”或者换个例子:“周三早上，我起床刷牙后，要马上坐在书桌前开始写报告。”或者是:“今天晚上，吃过晚饭洗完碗后，我要和我的妻子在客厅坐下，和她谈话。我会对她说:‘亲爱的，我想和你说点事，我想这会让我们更幸福。’”\u003c/p>\u003cp>想想你要去做的某件事，去学习的某些知识，或是要面对的某个问题。先明确目标，然后制定一个具体的计划。你要在何时实行计划?你将在哪里实行计划?你准备怎样实行计划?要考虑到具体的细节。这些具体的、可以设想的计划涉及你做事的时间、地点和方式。这会让你保持高效的行动力，当然会提高成功的概率。所以，不仅要制定一个成长型思维模式计划，更要设想具体细节，设想你要如何实行它。\u003c/p>","explains":"\u003cp>\u003cem>拆书技能点观察7：【I】讲解引导时，拆书家举出了案例，并通过概念与匹配例子之间的对比,引出知识点逻辑、步骤;或者【1】讲解引导时，拆书家主动给出貌似相近或相反的概念，并辨析了易混淆概念之间细微差异，从而让学习者更清晰知识点的适用边界(达到其一即可打勾)。\u003c/em>\u003c/p>\u003cp>\u003cstrong>【What】\u003c/strong>这个片段中提出了一个成长性思维的解决问题的办法：“可实行的计划”三步法，即通过设想具体细节，设想你要如何实行它，提前规划具体情境下的具体行为来实现目标。\u003c/p>\u003cp>\u003cstrong>【Why】\u003c/strong>当我们行动计划模糊不清时，很容易出现两个情况，一个就是计划始终停在脑子中，或者就是干着干着停了。而成长性思维的解决问题会通过一个清晰具体的计划，将目标细化为具体可操作的步骤，这样一个模糊的想法转变成了一个明确的行动计划，不仅能够使任务变得易于管理，还能增强执行的决心和效率，提高目标达成率。\u003c/p>\u003cp>\u003cstrong>【How】\u003c/strong>那么这个三步法具体如何操作呢？\u003c/p>\u003cp>\u003cstrong>一、明确目标。\u003c/strong>清晰地定义你想达到的目标是什么。比如，“我想提高我的工作效率”，或者“我想改善我和家人的沟通”。\u003c/p>\u003cp>\u003cstrong>二、决定行为。\u003c/strong>决定一个特定的行为或行动，这个行为将帮助你朝着目标前进。比如，“每天早晨安排半小时处理电子邮件”，或者“每周至少和家人共进一次晚餐”\u003c/p>\u003cp>\u003cstrong>三、制定计划。\u003c/strong>目标、行为清晰后，我们需要匹配具体的计划，可以从以下四个方面着手。\u003c/p>\u003cp>①行动的时间。比如，周三早上，我在起床刷牙后\u003c/p>\u003cp>②行动的地点。比如，书桌前、客厅里。\u003c/p>\u003cp>③行动的方式。比如，我要喝杯茶，关上办公室的门，给学校打电话。\u003c/p>\u003cp>④设想细节。细节越完善，越容易提升行动力。可以想象自己在这个时间地点做这件事的情景。考虑可能会遇到的任何挑战，以及如何克服它们。\u003c/p>\u003cp>\u003cstrong>【举例子】\u003c/strong>下面我举一个自己的例子，我和大家一样想锻炼身体。\u003c/p>\u003cp>\u003cstrong>一、明确目标。\u003c/strong>我的目标是锻炼身体。\u003c/p>\u003cp>\u003cstrong>二、决定行为。\u003c/strong>我的行为是在每天练习10分钟的瑜伽。\u003c/p>\u003cp>\u003cstrong>三、制定计划。\u003c/strong>\u003c/p>\u003cp>- 时间：每天早晨起床第一件事。\u003c/p>\u003cp>- 地点：在客厅瑜伽垫上。\u003c/p>\u003cp>- 方式：设定闹钟提醒我起床立即去客厅瑜伽垫上开始锻炼。\u003c/p>\u003cp>- 设想细节：假如我正在运动时，孩子醒的话，我给他看10分钟动画片，不让他打扰我。\u003c/p>\u003cp>//好，我对拆页的讲解就到这里。\u003c/p>","interaction":"\u003cp>\u003cstrong>【场景演练】\u003c/strong>\u003c/p>\u003cp>现在，我们一起想一下在未来一个月的生活或工作中你可能遇到的你或者朋友家人想做但是没有行动的一件事情，比如运动、习惯养成、学习等等。请在转变思维模式后再制定一个行动计划，促进行动。现在请大家编写一个小剧本，请将情节变化（包括：起因、经过、结果）和双方的对话、动作等写在小剧本模板中，其中部分对话用到“可实行的计划”三步法。5分钟后我们请一位伙伴分享自己的剧本。\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>时间：\u003c/strong>下个月月初\u003c/p>\u003cp>\u003cstrong>地点：\u003c/strong>办公室\u003c/p>\u003cp>\u003cstrong>人物：\u003c/strong>我和同事\u003c/p>\u003cp>\u003cstrong>起因：\u003c/strong>同事想提高会议记录的速度和总结能力。\u003c/p>\u003cp>\u003cstrong>对话：\u003c/strong>\u003c/p>\u003cp>同事：我想提高自己会议总结水平，但是总是做不好，会议后即完成总是做不好。\u003c/p>\u003cp> 我：你在这过程怎么训练自己的呢？\u003c/p>\u003cp>同事：练习打字，但是练习后会议还是不行，我都想放弃，都想换个岗了。\u003c/p>\u003cp> 我：是不是方法不太合适，咱换个思维方式，换个想法，比如成长型思维有个可实行的计划的三步法。\u003c/p>\u003cp>同事：好\u003c/p>\u003cp> 我：你的目标是什么？\u003c/p>\u003cp>同事：训练我同步输入记录速度（\u003cstrong>明确目标）\u003c/strong>\u003c/p>\u003cp> 我：你看做点什么能达到这个目标？\u003c/p>\u003cp>同事：那我就听讲座，然后做同步记录讲座视频来锻炼自己记录速度。\u003cstrong>（决定行为）。\u003c/strong>\u003c/p>\u003cp> 我：现在我们明确和目标和行动，什么时候做呢？做多久？\u003c/p>\u003cp>同事：晚饭后，每天半小时\u003cstrong>（时间）\u003c/strong>\u003c/p>\u003cp> 我：你在哪里做？\u003c/p>\u003cp>同事：家里\u003cstrong>（地点）\u003c/strong>\u003c/p>\u003cp> 我：你怎么做？\u003c/p>\u003cp>同事：每天选一个会议视频做一个记录\u003cstrong>（方式）\u003c/strong>\u003c/p>\u003cp> 我：有特殊情况，比如孩子生病了怎么办呢？\u003c/p>\u003cp>同事：调整到早起的时间来做。\u003cstrong>（设想细节）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>预计结果：\u003c/strong>同事每天饭后在家做视频同步录入，提升自己的速度。\u003c/p>\u003cp>\u003cstrong>反馈\u003c/strong>：感谢大米的分享，我觉得经过大米的帮助，同事的同步录入速度会有改善。\u003c/p>\u003cp>\u003cstrong>【特定任务】\u003c/strong>为了让大家更好的掌握今天的学习内容，我给大家布置一个小作业，在接下来的一周内，对一直困扰自己的一件事，进行思维转变，并在转变思维模式后用“可实行的计划”三步法帮助我们的朋友或者家人或者自己制定一个行动计划，促进行动。请完成的小伙伴请把作业（包括时间、地点、人物、事件经过和主要对话内容）编辑好，通过微信发给我，谢谢大家。\u003c/p>\u003cp>&lt;学习者案例记录&gt;\u003c/p>\u003cp>多加自己一直想做酒水相关的短视频推广，然而一直迟迟没有做。学到周日的内容，打算自己跟内在的“小我”沟通下：\u003c/p>\u003cp>我：你不是想做短视频为啥没做啊\u003c/p>\u003cp>小我：担心自己花太多时间，最后没有结果\u003c/p>\u003cp>我：对自己没信心：担心付出和收获不成比例？\u003c/p>\u003cp>小我：对，是的\u003c/p>\u003cp>我：那你内心到底想做这个事吗？\u003c/p>\u003cp>小我：当然了\u003c/p>\u003cp>我：想做那就简单了，用可实行的计划的三步法来制定个计划。\u003c/p>\u003cp>小我：有道理，那我如何来做呢？\u003c/p>\u003cp>我：那我接下来给先明确一下目标：目标是做酒水的短视频推广？\u003cstrong>（明确目标）\u003c/strong>\u003c/p>\u003cp>小我：是的\u003c/p>\u003cp>我：接下来，决定一个行动，你打算怎么推广？\u003c/p>\u003cp>小我：我打算每天做一个短视频并发在账号里。\u003cstrong>（决定行为）。\u003c/strong>\u003c/p>\u003cp>我：那我们的行为就确定了，接下来我们定一个具体的计划。\u003c/p>\u003cp>我：你每天什么时间可以拿出来做短视频？\u003c/p>\u003cp>小我：上午那会相关时间宽裕\u003cstrong>（时间）\u003c/strong>\u003c/p>\u003cp>我：在哪里？\u003c/p>\u003cp>小我：物流园\u003cstrong>（地点）\u003c/strong>\u003c/p>\u003cp>我：你打算用什么方式做？\u003c/p>\u003cp>小我：我打算用剪映去做\u003cstrong>（方式）\u003c/strong>\u003c/p>\u003cp>我：具体的该怎么办？\u003cstrong>（设想细节）\u003c/strong>\u003c/p>\u003cp>小我：我打算定个闹钟，每天上午10:00开始拍视频，拍完就把视频导入到剪映进行编辑，编辑完就发账号里。\u003c/p>\u003cp>我：假如这个时间有意外情况怎么办？\u003c/p>\u003cp>小我：那我就调整到晚上下班前做。\u003c/p>\u003cp>我：不错，挺详细\u003c/p>\u003cp>结果：小我可以行动每天中午发小短视频\u003c/p>\u003cp>\u003cstrong>【结束语】\u003c/strong>录音位置： 72：38\u003c/p>\u003cp> 总结一下，我们今天学习了一种自我提升的方法， 首先通过接受-观察-命名-转变四步在思想层面进行了转变，并通过明确目标-决定行为-制定计划三步，在行动上促进目标达成。\u003c/p>\u003cp> 通过内在的反思与外在的实践，我们不仅在思想层面升华，更在行动中确立了清晰的目标导向路径。正是这样由内而外的改变，引领我们不断前进，实现自我超越。希望大家在人生道路，一直拥有和保持“我可以学”的勇气和态度，不论是在职业生涯中还是个人生活中，都能够持续成长和发展。\u003c/p>\u003cp> 最后希望大家18岁遇到一个你喜欢的人约你去游泳，你说“好的，我们一起去”。28岁出现一个很棒但要会英文的工作，你说“我正好适合”。38岁出现职场危机时，你说“展示我新技能的时候到了”。\u003c/p>\u003cp> 今天我的分享到此结束，谢谢大家的陪伴和参与。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1728889724000,"updated_at":1730558820000,"ria":true},{"id":17964,"topic":"让计划可实行的三步法","learn_goal":"","remark":"面对失败时，你是否曾经怀疑自己的能力?面对较难的挑战时，你是否担心被证实智力、能力较差，而选择放弃?生活中我们的压力往往来源于以上的思维方式，《终身成长》里推崇我们用“成长型思维”看问题，在面对失败、挑战时，相信能通过自己的努力，不断提升。拥有“成长型思维”的人会从失败中总结经验，重新设立目标，制定切实可行的计划来帮自己走出困境。今天的拆页将会告诉大家，如何制定“可实行的计划”，提升行动力，达到解决问题的目的。","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"罗启明","city":"荆州市"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"\u003cp>\u003cstrong>一、自我介绍及图书介绍（2分钟）\u003c/strong>\u003c/p>\u003cp>各位伙伴，大家好！我是罗启明，我的三个标签是：1、爱分享的阅读者。2、终身学习者。3、公益爱好者。\u003c/p>\u003cp>（F）今天我们学习的拆页来源于《终身成长》，作者是美国资深心理学家卡罗尔· 德韦克，主要讲述了“成长型思维”模式相对于智商、能力，更容易让人发挥潜能、获得成功。\u003c/p>\u003cp>（A）本书蝉联美国亚马逊心理类畅销榜10年，累计印刷180万册。相对于其他成长类图书，本书的内容来源于作者数十年的研究，有大量实验数据做支撑。不仅全方位展示了“成长型思维”的优势，还提供了切实可行的方法论，帮助人们建立 “成长型思维”。\u003c/p>\u003cp>（B1）通过阅读本书，学习运用书中所推崇的用“成长型思维”看问题，将教会我们在面对失败、挑战时，及时总结经验，重新设立目标，制定切实可行的计划来帮自己走出困境。\u003c/p>\u003cp>（Ｂ2）今天的拆页将告诉我们如何制定“可实行的计划”，让我们保持高效的行动力，提高成功的概率。\u003c/p>\u003cp>\u003cstrong>二、学习目标（1分钟）\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者可以使用“可实行的计划”三步法，来制定具体的计划，解决在工作或生活中计划难以实行的问题。\u003c/p>\u003cp>\u003cstrong>三、学习分组\u003c/strong>\u003c/p>\u003cp>今天的学习将会有讨论和演练环节，现在我们分一下组，由于现场的学习者只有3人，那3人自成一组。\u003c/p>","ratings_count":1,"texts":[{"id":22202,"quote":"\u003cp>\u003cstrong>四、R 阅读原文（2分钟）\u003c/strong>\u003c/p>\u003cp>【过渡语】那现在请大家用2分钟的时间阅读一下我刚才发的拆页，看完的小伙伴们用眼神示意我一下。\u003c/p>\u003cp>\u003cstrong>片段来源:《终身成长》P281\u003c/strong>\u003c/p>\u003cp>有效的做法是制定一个清晰具体的计划:“明天，在我休息的时候我要喝杯茶，关上办公室的门，给学校打电话。”或者换个例子:“周三早上，我起床刷牙后，要马上坐在书桌前开始写报告。”或者是:“今天晚上，吃过晚饭洗完碗后，我要和我的妻子在客厅坐下，和她谈话。我会对她说:‘亲爱的，我想和你说点事，我想这会让我们更幸福。’”\u003c/p>\u003cp>想想你要去做的某件事，去学习的某些知识，或是要面对的某个问题。\u003cstrong>先明确目标，然后制定一个具体的计划。你要在何时实行计划?你将在哪里实行计划?你准备怎样实行计划?要考虑到具体的细节。\u003c/strong>\u003c/p>\u003cp>这些具体的、可以设想的计划涉及你做事的时间、地点和方式。这会让你保持高效的行动力，当然会提高成功的概率。\u003c/p>\u003cp>所以，不仅要制定一个成长型思维模式计划，更要设想具体细节设想你要如何实行它。\u003c/p>\u003cp>【过渡语】好的，大部分伙伴已经阅读完毕，没有读完也没有关系，我们一同学习。\u003c/p>","explains":"\u003cp>\u003cstrong>五、【拆书家讲解引导I】（4分钟）\u003c/strong>\u003c/p>\u003cp>【Why】不知大家是否有过以下的烦恼：想要解决学习、工作中的问题，目标制定了，行动也开起了，可就是龙头起蛇尾落没办法坚持，导致你行动力差的原因有很多，但极有可能是你在制定目标和规划时，不够具体和切实可行。\u003c/p>\u003cp>【What】今天的拆页提出了一个好的方法“可实行的计划”三步法，通过这三步能帮助我们保持高效的行动力，提高目标达成率。\u003c/p>\u003cp>【How】（细化原文步骤）那么这个三步法具体如何操作呢？\u003c/p>\u003cp>\u003cstrong>1、明确目标。\u003c/strong>俗话说，心中有目标，行动才有方向。在开始行动前，可以从以下两点明确目标：\u003c/p>\u003cp>①我的目标是什么？ 在什么时间，达成什么结果。\u003c/p>\u003cp>②为何要实现这个目标？ 只有清晰认识到目标对自己的意义，才能为制定计划打好基础。\u003c/p>\u003cp>\u003cstrong>2、制定具体计划。\u003c/strong>目标清晰后，我们需要匹配具体的计划，可以从以下四个方面着手。\u003c/p>\u003cp>①行动的时间。比如，周三早上，我在起床刷牙后；\u003c/p>\u003cp>②行动的地点。比如，书桌前、客厅里。\u003c/p>\u003cp>③行动的步骤。比如，我要喝杯茶，关上办公室的门，给学校打电话。具体的行动步骤会让减少我们的压力感，促进行动。\u003c/p>\u003cp>④完善细节。细节越完善，越容易提升行动力。\u003c/p>\u003cp>\u003cstrong>3、实施计划。\u003c/strong>完成前两步后，在预计的时间内督促自己完成行动即可。如果想要更好的促进自己完成，也可以增加奖励机制。\u003c/p>\u003cp>【Where】本方法适用于工作生活中想要通过有计划的行动去达成目标、提高成功概率的情形，如想要做成某件事、学会某个知识或解决某个问题等。但对于无需计划就可以行动达成目标的情形就不适合了，如下班后选择走路回家，周末去看场喜剧电影放松心情等。\u003c/p>\u003cp>举例子\u003c/p>\u003cp>两年前我在做公益宣讲时，因为不会做PPT ,宣讲呈现的内容模式单一，效果不太理想。于是我决定去学，计划反反复复定了几次，也有过几次行动，最后还是没有学会。机缘巧合今年年初我读到了本书《终身成长》，决定3月份再给自己一次机会，我使用了“可实施的计划”三步法，具体做法如下：\u003c/p>\u003cp>\u003cstrong>1、明确目标：\u003c/strong>\u003c/p>\u003cp>①我的目标是什么？ 在一个月内学会制作5到10页的PPT。\u003c/p>\u003cp>②为何要实现这个目标？ 在做公益宣讲等活动时，PPT图文并茂更直观，听众更容易理解宣讲内容，学习效果会更好。\u003c/p>\u003cp>\u003cstrong>2、制定具体计划：\u003c/strong>\u003c/p>\u003cp>目标清晰后，我就开启了学习计划制定：\u003c/p>\u003cp>①行动的时间。3月1日咨询了PPT制作达人袁老师，按照她的建议，我明确了学习时间：3月2日至10日熟悉操作页面、工具运用、快捷键使用等。3月11日至31日开始分主题学习制作PPT。\u003c/p>\u003cp>②行动的地点。书房里的电脑前。\u003c/p>\u003cp>③行动的步骤。设定闹钟，每天晚锻炼结束后，稍作休息，九点开始利用半个多小时的时间学习相关知识，遇到不懂或不会的地方记下来，一周两次向袁老师请教，后期还将作品发给他看，以求指正不足。\u003c/p>\u003cp>④完善细节。在电脑旁放了盆我喜欢的绿植，买了个可爱的卡通笔记本做笔记。\u003c/p>\u003cp>\u003cstrong>3、实施计划：\u003c/strong>\u003c/p>\u003cp>在完成前两步后，我每天按部就班，认真学习。通过1个月的努力，我学会制作PPT,5月份在做宣讲时，呈现模式就有了突破。\u003c/p>","interaction":"\u003cp>\u003cstrong>六、【A3促动学习者现场演练】\u003c/strong>（13分钟）\u003c/p>\u003cp>为了更好地运用“可实行的计划”三步法来制定计划，提升行动力，现在我们来实地演习一下。\u003c/p>\u003cp>\u003cstrong>场景设计\u003c/strong>\u003c/p>\u003cp>A公司美女财务小贝,因工作需要在电脑前工作的时间比较长，三十出头的她前不久头昏脑涨，腰酸背痛，感觉身体各种不舒服。医生根据检查报告，建议她改变久坐不动的工作方式，加强有氧运动，最好还减重5到10斤。小贝听从了医生的建议，决定开始运动，计划用一个月的时间减重5斤，刚开始的半个月，她有时早起在附近的小公园慢跑，有时下班后在家跳绳、跳操，或是周末去健身房踩单车......在后半个月，就因为上班比较忙、累，周末朋友要聚会等各种原因，没有坚持运动，计划搁浅了，身体也还会时不时出点小状况。她想要解决这个问题，怎样让运动计划可实行呢？小贝决定向运动达人、活力满满的玲姐请教。\u003c/p>\u003cp>\u003cstrong>演练环节\u003c/strong>\u003c/p>\u003cp>根据以上场景，现在先请大家开始进行组内对话演练，一人扮演小贝，寻求坚持运动让身体更健康的好方法，一人扮演玲姐，运用今天学的“可实行的计划三步法”，来帮助小王梳理行动计划，提高行动力。一人可以当观察者，做一下记录。那现在开始在小组内进行对话演练，演练时间4分钟。稍后我会请两位伙伴分别饰演玲姐和小贝上台进行演练。\u003c/p>\u003cp>（4分钟后）大家讨论得很热烈，基本的建议也差不多达成了，现在我邀请两位伙伴上台演练一下。\u003c/p>\u003cp>【\u003cstrong>演练现场内容\u003c/strong>】（高玲扮演玲姐，玲英扮演小贝）\u003c/p>\u003cp>小贝：玲姐，我需要你的帮助，前段时间，我想通过运动减重5斤，每天都在运动，有时早起在附近的小公园慢跑，有时下班后在家跳绳、跳操，或是周末去健身房踩单车，可是半个月后，就因为上班比较忙、累，周末朋友要聚会等各种原因，没有坚持运动，我现在想请教你，怎样重新制定计划，让我在8月份减重5斤，达成目标。\u003c/p>\u003cp> 玲姐：好的，我想先问你个问题，你的目标是什么？\u003c/p>\u003cp>小贝：我的目标是想利用8月份一个月的时间，每天早上跳操，健身减重5斤。\u003cstrong>（1、明确目标：①我的目标是什么？）\u003c/strong>\u003c/p>\u003cp>玲姐：那我再问你，你为何要实现这个目标？\u003c/p>\u003cp>小贝：我最近身体各种不舒服，因为上班久坐也长胖了，我想要身体健康，夏天瘦几斤后穿衣服更好看...但又担心像前段时间一样，坚持不下来，你有好的建议吗？\u003cstrong>（1、明确目标：②为何要实现这个目标？)\u003c/strong>\u003c/p>\u003cp>玲姐：看来你的目标还蛮明确的，那我建议你定一个具体计划，在8月份每天早上5点多起床开始跳操。\u003c/p>\u003cp>小贝：每天可能不行，那每周六天吧！\u003c/p>\u003cp>玲姐：每周六天也可以，那我建议你：早上5点多\u003cstrong>（2、制定具体计划：①行动的时间\u003c/strong>\u003cstrong>）\u003c/strong>起床简单洗漱后，步行去你家附近的小公园\u003cstrong>（2、制定具体计划：\u003c/strong>②\u003cstrong>行动的地点\u003c/strong>\u003cstrong>）\u003c/strong>去跳操半个小时，然后回家洗个澡吃个营养早餐来上班，时间应该来得及，\u003cstrong>（2、制定具体计划：\u003c/strong>\u003cstrong>③行动的步骤）\u003c/strong>穿上你喜欢的运动服、戴上你喜欢的导汗头巾，播放你喜欢的音乐，这样也有利于你提升行动力哟！\u003cstrong>（2、制定具体计划：\u003c/strong>\u003cstrong>④完善细节）\u003c/strong>如果能够坚持，一周后还可以给自己一个奖励...\u003c/p>\u003cp>小贝: 你的建议好全面啦！如果我的计划能够坚持，我决定奖励自己一套运动服。\u003c/p>\u003cp>玲姐：今天离8月份还有4天，你不是准备开始行动?\u003c/p>\u003cp>小贝：我今天回家就开始做准备,从8月1起我就严格按你的建议来行动！\u003cstrong>（3、实施行动）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>七、【结束语】\u003c/strong>\u003c/p>\u003cp>谢谢两位的精彩演练！你们的现场演练完整完美的展示、运用了今天所学的三步法！通过今天的学习和演练，希望大家在遇到想要通过有计划的行动去达成目标时，运用“可实行的计划”三步法，理清目标，制定出具体的计划，开启坚定不移的行动，去提高成功概率！那我今天2-3的分享就到此结束，谢谢大家的陪伴！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1723714116000,"updated_at":1725000014000,"ria":true},{"id":16626,"topic":"成长三步法","learn_goal":"","remark":"成长三步法","level":"TF2-3","duration":20,"status":30,"type":0,"chaishujia":{"username":"闪电侠","city":"马鞍山市"},"club":{"name":"南京玄武分舵","city":"南京"},"prologue":"\u003cp>（Step1、把事先准备好的复印原书拆页发给现场学习者，人手一份。 ）\u003c/p>\u003cp>先将本次分享的拆页发给大家，人手一份。\u003c/p>\u003cp>（Step2、站到大家面前，跟大家打个招呼。分好组。 ）\u003c/p>\u003cp>各位书友，大家好，今天我带来的是《终身成长》拆页，题目是“成长三步法”。\u003c/p>\u003cp>【分组】为了更好的参与拆为己用，首先我们分一下组，左手边3位书友为一组，右手边3位为一组。\u003c/p>\u003cp>【自我介绍】\u003c/p>\u003cp>首先做一个自我介绍。我叫付贝贝，支付宝的付，花呗的贝，简称为“付呗”。三个标签介绍我自己，1名国家注册质量体系审核员，曾经为本田、宝马服务，从业18年；1名热爱跑步的运动达人，无伤跑步1946公里；1名企业优秀内训师，正努力成为三级拆书家，将自己活成一道光，影响身边的人。\u003c/p>\u003cp>【设定学习目标】\u003c/p>\u003cp>本次拆书的学习目标是，通过学习让我们通过掌握“成长三步法，习得“成长型思维”，在遇到挫折时，能坚定目标、审视自我、刻意练习、以做到不断精进，终身成长，享受人生。\u003c/p>\u003cp>（Step3、用FAB 法介绍图书，1-2 分钟。）\u003c/p>\u003cp>【图书介绍】\u003c/p>\u003cp>【F特征】《终身成长》是由资深心理学家卡罗尔 德韦克撰写的，基于10年研究提出“成长型思维”模式，重新定义成功的思维模式。\u003c/p>\u003cp>【A优势】本书蝉联美国亚马逊心理类畅销榜10年，180万册的累计，比尔·盖茨、赵帮主撰文推荐。本书通过对各行各业中的案例研究，她提出了“成长型思维”的概念。不仅全方位展示了“成长型思维”的优势，还提供了切实可行的方法论，帮助人们建立 “成长型思维”。\u003c/p>\u003cp>【B利益】成功不在先天，不靠外在，关键在于思维模式。拥有“成长型思维”的人会从失败中总结经验，制定、实施对策，使得自己走出困境。\u003c/p>\u003cp>我们是不是遇到碰到困难时，认为外界因素有所干扰，或者认为自己的能力有限，我做不到。实际上这都是源于我们的思维习惯，《终身成长》这本书给我们一个很好的思维模型，使得我们失败的案例中可以很好的总结，通过总结制定一些措施方法，最终实现自己不断的提升。\u003c/p>\u003cp>今天我将通过具体案例和你学习如何运用“成长三步法”通往成功，同时还将邀请你一起演练演绎。\u003c/p>\u003cp>【过渡语】\u003c/p>\u003cp>下面让我们花2分钟时间看一下原文拆页《终身成长》&quot;冠军的思维模式 迈克尔·乔丹&quot;片段，看完后请抬头示意我一下。\u003c/p>","ratings_count":1,"texts":[{"id":20737,"quote":"\u003cp>（Step4、【R】环节，让大家阅读你复印好的原书拆页。 ）\u003c/p>\u003cp>【R阅读原文拆页】\u003c/p>\u003cp>书名：《终身成长》第4章 冠军的思维模式 迈克尔·乔丹。 P236-238\u003c/p>\u003cp>大家都知道，迈克尔·乔丹在高中时被校队淘汰了，现在我们会嘲笑当年踢他出校队的教练。他没有进入他想要效力的北卡罗来纳州立大学。这些人是不是太蠢了？最初可以选择他的两家NBA球队也没有签下他。多么愚蠢的错误！那是因为现在我们知道他是有史以来最棒的篮球运动员，于是认为在当初这一点应该也是显而易见的。现在，我们看着他的时候，看到的是了不起的篮球巨星迈克尔·乔丹，但在当初，他只是普通的小球员迈克尔·乔丹。\u003cbr> 被高中校队淘汰后，乔丹非常郁闷。他的母亲说：“我对他说，让他回学校好好训练。”他真的按照母亲说的做了。他每天早上六点就离开家，在上课前抽空练习。在北卡罗来纳大学的时候，他不断弥补自己的弱点——他的防守动作、控球能力和投篮。他的教练对他远超他人的努力深感惊讶。一次，在球队输掉季后赛最后一场比赛后，乔丹不断地练习了好几个小时的投篮。他是在为下一年的比赛做准备。即使他后来功成名就——让自己成为别人眼中的运动奇才，他的艰苦训练仍然是出了名的。公牛队之前的助理教练约翰·巴赫（John Bach）就说他是“一个不断想提高自己天赋的天才”。\u003cbr> 对乔丹来说，成功源于人的头脑。“坚韧的意志和决心比某些身体上的优势更强有力。我经常这么说，我也是一直这样认为的。”但是其他人并不这么认为。他们看到乔丹时，只能看到他完美的身体素质带领他走向成功。\u003c/p>","explains":"\u003cp>（Step5、【I】环节，3-4 分钟，要体现出把原书拆页的建议加工出具体步骤，或体现出意译原书案例。 ）\u003c/p>\u003cp>【过渡语】 好，我看到书友们都已经阅读完了，让我进入重述知识点的环节\u003c/p>\u003cp>新技能【I】拆书家讲解引导：原书拆页的行动建议，加工出流程步骤；把原书案例意译为学习者更亲切的案例。\u003c/p>\u003cp>新技能【I】之意译原书案例\u003c/p>\u003cp>拆页告诉了我们迈克尔乔丹的励志故事，在他最初的时候也没有我们心目中的所向无敌，他被学校球队劝退，没有人看好他，使得他深深地失望痛哭起来。这种失望像一道伤口，深深的刺痛他，把梦想和现实残忍地割开。他通过刻意练习，早上练球，中午练球，下午练球，晚上练球，夜里还在练球，甚至晚上睡在球馆，融入了血液，最终取得6次NBA总冠军、2次奥运会冠军、各单项的最佳各位。\u003c/p>\u003cp>案例向我们展示了乔丹为了追求去NBA打球的\u003cstrong>目标\u003c/strong>，遇到被学校球队劝退的挫折，在妈妈的帮助下有一定的\u003cstrong>自我审视\u003c/strong>，对防守动作、控球能力和投篮等不足进行\u003cstrong>刻意练习\u003c/strong>，实现不断成长。\u003c/p>\u003cp>看到这个案例使我联想到俞敏洪，他是新东方的创始人，被称为“留学教父”，他也有我们不为人知的经历。在最初考大学的时候，第一次英语仅仅考了33分，经过努力第二次也仅仅是55分，没有考进中专学校，在她母亲引导，在他自己立志考取大学的决心，对英语进行不断的刻意练习，上了一个英语补习班，用了20多天的时间，把这300道考题，共800个句子背了个滚瓜烂熟，达到了倒背如流的地步。第三次高考，俞敏洪的英语一下考了99分，实现了从33分到99分的跨越。这一次，起初连普通的示范学院都没考上的俞敏洪，考上了北京大学外语系。其实考取北大后口语比不过同学，几乎与疯狂的练习，最终达成我们做熟知的成功。\u003c/p>\u003cp>案例向我们展示了俞敏洪为了追求去考取大学的\u003cstrong>目标\u003c/strong>，遇到接连两次考试失败的挫折，在妈妈的帮助下有一定的\u003cstrong>自我审视\u003c/strong>，对英语进行\u003cstrong>刻意练习\u003c/strong>，实现不断成长。\u003c/p>\u003cp>对比乔丹和俞敏洪，虽然在不同的领域，但成长经历有相似之处，拥有成长型思维，坚持梦想，明确目标、审视自我、刻意练习，最终获得成功。下面我对步骤进行了提炼：\u003c/p>\u003cp>新技能【I】之细化行动步骤：加工出流程步骤\u003c/p>\u003cp>\u003cstrong>1、明确目标-有规划\u003c/strong>\u003c/p>\u003cp>第一步我们要知道想要做什么，明确目标，在过程中针对现状有分阶段的策划。正如案例中乔丹为了追求去NBA打球的目标，俞敏洪为了追求去考取大学的目标，指引前进的方向。\u003c/p>\u003cp>\u003cstrong>2、自我审视-识机会\u003c/strong>\u003c/p>\u003cp>第二步我们要知道自己的长板坚定信心，短板识别改进机会。在任何的过程中都不可能顺风顺水，我们遇到困难时要自我审视，识别我们的长板也要识别短板，短板是我们的改进机会，为成长型思维所关注。当然我们有不足，但是我们有强大的一面，识别长板增强我们的信心。正如案例中乔丹防守动作、控球能力和投篮不足，俞敏洪英语不及格均为短板，是后续改进的机会。\u003c/p>\u003cp>\u003cstrong>3、刻意练习-促精进\u003c/strong>\u003c/p>\u003cp>第三步我们要知道自己该做什么，突破我们的舒适圈，有目标的，有反馈的刻意练习。按照目标一步一步达成，最终实现成长。正如案例中乔丹练习防守动作、控球能力和投篮，俞敏洪练习英语，他们都采用了有针对性的刻意练习。\u003c/p>\u003cp>以上就是我所拆解的成长三步法。\u003c/p>","interaction":"\u003cp>【A拆为己用】\u003c/p>\u003cp>（Step6、【A3】环节，10-15 分钟。给出一个预先设计好的案例场景，请大家在小组内讨论演练，最后邀请各组做当众表达或角色扮演。 ）\u003c/p>\u003cp>新技能【A3】之场景设计：事件背景，符合适用边界\u003c/p>\u003cp>好的，接下来进入第三个环节拆为己用。我们将设定一个场景，促使大家运用“成长三步法”\u003c/p>\u003cp>\u003cstrong>1、明确目标-有规划\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2、自我审视-识机会\u003c/strong>\u003c/p>\u003cp>\u003cstrong>3、刻意练习-促精进\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小章\u003c/strong>是一名企业内训师，勤奋好学，乐于培训分享，参加公司专业比赛成绩垫底，被信誓旦旦的同事打趣道“一紧张就结巴、不是这块料”，她被这种反馈所困扰，不知道自己适不适合做内训师，否继续坚持。特意找同为内训师的王姐请教。\u003c/p>\u003cp>\u003cstrong>王姐\u003c/strong>是一个具有成长型思维的人，一名优秀的内训师，她运用自我成长的三步法来帮小章指点迷津，通过谈话识别小章的现状，明确目标，规划发展，助力成长。\u003c/p>\u003cp>新技能【A3】之小组讨论：组内讨论\u003c/p>\u003cp>下面给大家5分钟时间组内讨论，先来分配一下角色，各组中一位书友来扮演小章，一位书友扮演王姐，通过“成长三步法”进行指导。\u003c/p>\u003cp>（分组讨论中……）\u003c/p>\u003cp>新技能【A3】之角色扮演，人员饰演\u003c/p>\u003cp>好，我看到大家都讨论很充分，我想请第一组的两位书友现场角色扮演，杨柳扮演王姐，名纹扮演小章。\u003c/p>\u003cp>王姐（杨柳）：小章，听说你最近内训工作做得不太顺利，是遇到什么事情了吗？\u003c/p>\u003cp>小章（名纹）：以前我都是日常培训的，现在让我参加专业比赛，要演讲我有点紧张。\u003c/p>\u003cp>王姐（杨柳）：你有没有想过未来自己的发展路径，是想成为一名内训师还是演讲家呀？\u003c/p>\u003cp>小章（名纹）：我想做内训师，但是现在我只有二级，我想做五星级内训师。\u003c/p>\u003cp>王姐（杨柳）：你在成为内训师方面还有什么难处吗？你有没有想到可以做改进和练习的方面？\u003c/p>\u003cp>小章（名纹）：如果内训师的话，如果做得好，演讲还真的要练。王姐我应该怎么办呀？有三个问题困扰我，比如第一我普通话还不够标准；第二我上台还有些紧张害怕；第三有时候忘词，这三个我怎么办呀？\u003c/p>\u003cp>王姐（杨柳）：我看你对自己的问题点已经很了解了，第一个普通话还要练习；第二个上台有些恐惧；第三还有一点忘词。每天早上你可以读半小时的书练习普通话，多练习演讲现场互动，最后忘词紧张都需要勤加练习解决。\u003c/p>\u003cp>小章（名纹）：哪是不是有句话讲得好“台上一分钟，台下十年功”，我还得刻意练习。\u003c/p>\u003cp>王姐（杨柳）：是的，演讲对内训工作也有帮助。\u003c/p>\u003cp>小章（名纹）：我想做五星级内训师，只要对内训工作有帮助，我就好好去做，谢谢王姐。\u003c/p>\u003cp>（现场热烈掌声）\u003c/p>\u003cp>感谢我们第一组的精彩表演，惟妙惟肖地演绎了“成长三步法”，非常感谢。下面让我们有请第二组上台表演，华姐扮演王姐，雪娇扮演小章。\u003c/p>\u003cp>小章（雪娇）：王姐，你好！\u003c/p>\u003cp>王姐（华姐）：小章，最近垂头丧气地，是不是遇到什么事情了？\u003c/p>\u003cp>小章（雪娇）：对，工作不太顺利。\u003c/p>\u003cp>王姐（华姐）：我知道你一直想做内训师的。\u003c/p>\u003cp>小章（雪娇）：是的，我非常想做，这是我的目标，但是我遇到很多的问题。\u003c/p>\u003cp>王姐（华姐）：王姐问你一个问题，你是一定要做好内训师，还是说可做可不做呢？\u003c/p>\u003cp>小章（雪娇）：我的梦想是做内训师。\u003c/p>\u003cp>王姐（华姐）：非常棒！如果是梦想，我们就一定要坚持。你在坚持的过程中有什么困难吗？\u003c/p>\u003cp>小章（雪娇）：但是我遇到很多的问题，我一上台就紧张，大脑空白，别人说什么话我接不上。\u003c/p>\u003cp>王姐（华姐）：小章，你做内训师多久了？\u003c/p>\u003cp>小章（雪娇）：刚开始做。\u003c/p>\u003cp>王姐（华姐）：其实这很正常，任何一行想做好的话，需要5年到10年。你看你刚开始做，而且很有勇气做，给你点赞。目前我们练得还不够，正所谓“台上一分钟，台下十年功”，其实现在你已经认识到问题所在。我们刚刚听了乔丹被劝退，俞敏洪英语考试33分、55分，最终通过努力成就梦想。所以说你也想和他们一样，就需要刻意练习，形成肌肉记忆。王姐相信你经过不懈的刻意练习，一定能成为最厉害的内训师。\u003c/p>\u003cp>小章（雪娇）：谢谢，王姐！\u003c/p>\u003cp>感谢我们第二组的精彩表演，活灵活现演绎了“成长三步法”，非常感谢。\u003c/p>\u003cp>两组书友对“成长三步法”的把握都非常清晰和精准，使得我们受益良多。\u003c/p>\u003cp>【结束语】\u003c/p>\u003cp>今天我们拆解了《终身成长》“成长三步法”，基于学习目标我们回顾一下三个步骤：\u003c/p>\u003cp> 1、明确目标-有规划\u003c/p>\u003cp>2、自我审视-识机会\u003c/p>\u003cp>3、刻意练习-促精进\u003c/p>\u003cp> 1、明确目标-有规划生活中大家可以运用起来，以成长型思维，获取更多的喜悦，助力终身成长，享受人生。我今天的拆页分享结束了，非常感谢大家的聆听，谢谢。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1694527882000,"updated_at":1695200443000,"ria":true},{"id":16189,"topic":"在两性关系中如何进行有效沟通","learn_goal":"","remark":"在两性关系中如何进行有效沟通","level":"TF3-1","duration":26,"status":30,"type":0,"chaishujia":{"username":"拆书家十八","city":"贵阳市"},"club":{"name":"贵阳黔灵分舵","city":"贵阳"},"prologue":"\u003cp>\u003cstrong>学习目标：恰当的目标。技能要求：行为+澄清与界定完成程度\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次现场学习后，学习者在今后两性关系中能够发现（行为）最让自己介意的事情并及时和对方沟通（澄清）从而减少心里的芥蒂，减少不满情绪的积累，以便于维持长久的亲密感（界定）。\u003c/p>\u003cp>\u003cstrong>开场分组：简单自我介绍开场，分组\u003c/strong>\u003c/p>\u003cp>【开场】不破不能立，不拆不成器！拆书帮你把知识拆成你的能力，我是贵阳第二筹备分舵的杨朵，大家可以叫我十八，此时我是一名二级拆书家，也是一名宝妈，我想成为孩子亦师亦友，引以为傲的母亲，所以终身学习必不可少，这个过程中不断的向内求，做到漂亮的活好。\u003c/p>\u003cp>【分组】今天是线上，鉴于学习的内容，我们就不用分组。\u003c/p>\u003cp>\u003cstrong>图书介绍：用场景法介绍图书。要求：事件场景-提问-影响-解决。\u003c/strong>\u003c/p>\u003cp>今天的拆页选自《终身成长》，了解这本书前我们先听一下你是否也经历过这样的事情\u003c/p>\u003cp>【事件】以前，当遇见一件事情和老公意见不合时，我就会说出我的想法，有时候可能情绪没控制好，声音比较大，而他也会说两句，但只要我声音一大，他要么选择沉默，要么就是敷衍的回答“嗯”“好”“行”，我认为他答应了就应该做到，应该做好，结果就是我们经常为这种事情吵架。\u003c/p>\u003cp>（大众化的，能引起共鸣的，让人能感同身受的，效果最佳）\u003c/p>\u003cp>【提问】你们的爱人遇到这种事情时是如何处理的，是积极的沟通？还是选择逃避？还是看似沟通了，结果还是我行我素？\u003c/p>\u003cp>（简单直接，容易引人反思，或让人诧异的问题最好）\u003c/p>\u003cp>【影响】积极沟通，了解对方的想法，就会互相体谅，达成意见一直，关系也会更亲密。而无论是逃避，还是看似假的沟通，小则心生不满，争吵不断，大到两人的感情走到尽头，分道扬镳。\u003c/p>\u003cp>（事件中体现的问题会造成的影响，提问中的问题带来的影响，也可分好、坏两部分来说）\u003c/p>\u003cp>【解决】如何做到遇到问题积极沟通，面对对方的冷漠依然对这段感情不放弃，《终身成长》这本书给出了一种方法，用改变思维来改变结果。书中给出了大量的实例说明思维转变有多么的重要，也在育儿，人际沟通，两性关系，运动等各个方面运用转变思维来获得成功的方法。\u003cbr> 今天的主题就是在两性关系中如何进行有效的沟通\u003c/p>\u003cp>（想处理好以上的问题的解决方法，然后带出拆解的书与片段内容。）\u003c/p>","ratings_count":2,"texts":[{"id":20278,"quote":"\u003cp>接下来请大家用两分钟的时间快速阅读原文的选片。\u003c/p>\u003cp>【原文】出自《终身成长》 P180—P181\u003c/p>\u003cp>夏琳的朋友告诉她，镇上新来了一个音乐家麦克斯，他跟随交响乐团来到这里演奏大提琴。第二天晚上，夏琳和朋友去看了交响乐团的演出，演出后，夏琳和朋友来到后台时，麦克斯拉着夏琳的手说：“下一次，希望我们见面的时间能长一些。”她一下就感受到了他强烈的浪漫气息，他同时被她迷人的举止和美丽的外表所吸引。他们约会的时候，这种强烈的感觉进一步升温。他们看上去非常了解对方，他们对同样的事情感兴趣——美食、分析身边的人和旅行。他们两个都在想，你为什么不早点出现呢？\u003c/p>\u003cp>然而，随着时间的推移，麦克斯变得非常情绪化。其实他一直都这么情绪化，只是一开始没有表现出来。情绪不好的时候，他喜欢一个人待着，但夏琳喜欢问他是什么让他不开心，这个做法经常会激怒他。“让我一个人待会儿。”他坚持不沟通，态度越来越强硬，而夏琳觉得自己被他关在心房之外了。\u003c/p>\u003cp>此外，他的情绪化总是不合时宜地出现。有时这对情侣正准备出门，有时他们正准备去共进一顿特殊的晚餐。要么是他不愿意去，要么夏琳就得整晚忍受他抑郁的沉默。如果她尝试着想跟他轻松地交谈，他会对她感到失\u003c/p>\u003cp>望，说：“我还以为你理解我。”\u003c/p>\u003cp>朋友看到他们如此在乎彼此，都劝他们努力去解决这个问题。但两人都悲伤地认为，如果这份感情是天注定的，那么根本不需要如此努力地去经营它。如果这段感情是天注定的，他们应该能够理解并尊重对方的需要。所以他们逐渐疏远并最终分手了。\u003c/p>\u003cp>（还有30秒，看完了请举手示意我一下，……好，时间到，没有看完的小伙伴可以跟随我对这个片段讲解再继续来看。）\u003c/p>","explains":"\u003cp>接下来我们用拆书法将这个看似故事的片段转化为自己所需要的。\u003c/p>\u003cp>【what】\u003c/p>\u003cp>原文片段告诉我们一对情侣从一见钟情到最后的不欢而散，他们始于看似互相了解，终于两人不沟通，天注定的想法。\u003c/p>\u003cp>夏琳和艾克斯为什么会分手？（提问）\u003c/p>\u003cp>学习者：没有沟通（黄不了）/缺乏沟通(阳光）\u003c/p>\u003cp>是的，因为艾克斯拒绝沟通，他想当然的认为夏琳了解他应该理解他。\u003c/p>\u003cp>【概念辨析之概念间的适用边界】\u003c/p>\u003cp>在日常生活中，我们很多人也会和艾克斯一样，为了避免出现更多这样的艾克斯，我们重点来看一下了解和理解。\u003c/p>\u003cp>了解在百度百科里解释说是对知识有一定的认识和记忆，有明白，知道的意思，\u003c/p>\u003cp>理解是指顺着条理进行详细的分析，从而了解，明白。\u003c/p>\u003cp>如：小爱知道同事的家境很贫寒，父亲在她10岁就去世了，家里还有2个弟弟。\u003c/p>\u003cp>这里就是指了解同事家里的情况。\u003c/p>\u003cp>如：小爱不参与其他人嘲笑小雨抠门，因为她知道小雨的父亲去世早，小雨要帮妈妈抚养两个弟弟。\u003c/p>\u003cp>这里就是指小爱理解小雨的处境。\u003c/p>\u003cp>相同点是都有知道，明白的意思。\u003c/p>\u003cp>不同的是了解是粗略的，知道更倾向于单一的事物，侧重知道人或事的具体情况，是外在的，直观的。如文中：她们看上去非常了解对方，他们对同样的事情感兴趣——美食、分析身边的人和旅行。\u003c/p>\u003cp>理解是范围狭窄，偏向更深层次的思想内涵，侧重知道人的追求，想法，是内在的感受，用自己的体会来感受对方。如文中夏琳体会不到艾克斯因抑郁而带来的沉默，在尝试轻松沟通时，艾克斯就会认为夏琳不理解他。有可能艾克斯只是想静静的呆会儿。\u003c/p>\u003cp>【WHY】\u003c/p>\u003cp>要理解一个人，知道他内心的感受，想法及需求，就需要沟通，因为一个树上没有完全相同的两片叶子，就连双胞胎都没有完全相同的，还不要说以前毫不相干的两个人。作者在书中第六章中也提到双方需要努力才能进行正确的沟通，需要努力才能发现并解决不同的期望和想法。\u003c/p>\u003cp>在书中，作者提出了成长型和固定型两种思维模式，固定型思维认为一切都是不可变的，如文中的艾克斯和夏琳在面对感情这块儿就是典型的固定性思维，而成长型思维就是基于你相信一切都可以通过后期的努力有所改变，如：人际关系，才艺，记忆力，运动能力等等。\u003c/p>\u003cp>（学会的好处）在两性关系中，通过双方的努力，不断的沟通（这也是成长型思维的体现）你会发现，虽然在一起十年，甚至二十年，但两人的感情不减反增，内心感激对方的存在，互相的帮助，而不是互相的埋怨与不满。\u003c/p>\u003cp>（不用的坏处）没有沟通，靠着仅有的了解，两个人终会渐行渐远，分道扬镳，就像我们看到文中的艾克斯和夏琳一样。\u003c/p>\u003cp>那么如何在两性关系中进行有效的沟通？避免两人逐渐疏远或分手的结\u003c/p>\u003cp>果。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>在书中第六章节人际关系：关于相处的思维模式，就非常契合今天这个内容，总结概括就得到第一点：发现问题。因为冰冻三尺，非一日之寒，你眼里完美无缺的爱情，婚姻，并不是一天变坏的，它是由于没有长久的维护才导致没有往更好的方向发展。是你们的需求彼此没有发现，还是发现了却担心自己无法提供，假装不知道。如在文中问题表明性格存在缺陷这一部分里，面对查理妻子频繁的外出，所以人都认为妻子有外遇时，作者说：成长性思维模式并不意味着查理必须去质问妻子，但她可以一起和她探讨她们目前出了什么问题。他可以去想一想是什么出了问题，随后在决定怎么做，如果两人之间有问题需要解决，那至少两人的关系还有挽救的机会，而不是像查理一样去逃避（在书中的185页）\u003c/p>\u003cp>第二就是审视需求，在书中作者通过泰德挽如何救了他的婚姻这个小案例中呈现出来，总结为审视需求，从审视自我出发，走出负面情绪，思考你的目的是什么，或者你的需求是什么；对方的目的是什么，或者需求是什么。还要重点考虑一下你是否忽略了对方的需求或者误解了对方的需求。（书中187-188页）\u003c/p>\u003cp>最后，主动沟通，这是通过书中——对一切意见统一这部分提炼得到的。给个沟通的方面的小建议，在这次沟通前需要向对方表明这次沟通是希望两人的关系更近一步，并不是为了指责她/他。在沟通的时先表明事实，其次是感受，最后说出你的需求。注意，在这个过程中一定要时刻保持谈话氛围的安全，不要让情绪占主导地位。（在书中182页）\u003c/p>\u003cp>【正例】\u003c/p>\u003cp>记得在21年5月份，我发现我爱人的情绪越来越低沉，也很消极，回到家一直在玩手机，不陪孩子玩，也不怎么和我说话。有一天我终于忍不住了，我特别冒火，问他最近发生了什么，他说没什么啊，挺好的。听到他这么说，气的我一句话也没说，第二天微信进行了一次吵架式的沟通。\u003c/p>\u003cp>发现问题：\u003c/p>\u003cp>我生气的是他什么都不跟我说，明明有事，却敷衍我说没什么。我希望我们之间多一些沟通。每当我大声说话时，他以为我生气了，加上受原生家庭的影响，只要对方情绪一激动，他就会选择沉默。\u003c/p>\u003cp>审视需求：\u003c/p>\u003cp>为什么在两人沟通时我特别容易情绪化，原来我想的是他应该理解我，应该和我有一样的想法，所以当听到不同想法时我就特别的愤怒，而这种感觉传达出来就是我的不耐烦和生气。\u003c/p>\u003cp>主动沟通：\u003c/p>\u003cp>当想明白这两点以后，我就选择了微信沟通。看不见对方，我又机会控制自己的情绪，他也能说出他想说的话。当天晚上我们又再次进行了沟通。\u003c/p>\u003cp>老公：我还以为你生气老火了呢\u003c/p>\u003cp>我：我为什么生气呢，我昨天晚上生气是因为你不愿意说，其实不论发生什么，或者你想什么，我都希望你能和我说一下。可能我平时声音一大，你就以为我生气了，所以我就用微信和你沟通\u003c/p>\u003cp>老公：是啊，我就害怕你生气\u003c/p>\u003cp>……\u003c/p>\u003cp>最后老公说：感谢你理解我，我把想说的话说出来就舒服了\u003c/p>\u003cp>而且我们还约定以后遇到氛围紧张，容易生气的时候，就微信沟通，不能冷战。\u003c/p>\u003cp>所以说在两性关系中，抱着解决问题的心态，带着两人关系越来越甜蜜的初心去沟通，也就是用成长型思维去沟通，亲密关系就会越来越好。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>有人会说，我想和他/她沟通，可是他/她不沟通啊，我想说的是，一个巴掌拍不响，要么是在这段感情上心死，要么是还没找到不沟通的根本原因，没有给到对方足够的安全感。当然，也不排除对方不善于表达或者根本没法表达出心中所想的。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>这个适合于两性关系中，无论是你在美妙的热恋期，还是平淡无奇的婚姻中，或者是闺蜜之间，也可以分享给你两性关系有问题的朋友。\u003c/p>","interaction":"\u003cp>\u003cstrong>催化应用：教学习者编剧本。要求：剧本要包括背景、人物动作、人物对话等等，在这个有人物有情节有发展的故事中，有角色应用刚刚学的知识成功解决了问题\u003c/strong>\u003c/p>\u003cp>【指令】\u003c/p>\u003cp>通过以上的分享，大家已经知道了在两性关系中有效的沟通方法，在脑海中过一遍，就相当于实践了一次，所以我们今天尝试做一下编剧。\u003c/p>\u003cp>在未来一周或者一个月内，你和闺蜜/伴侣因某事发生了不愉快，通过今天学习的用成长性思维沟通的三步法沟通后两人消除隔阂,甚至关系更近一步\u003c/p>\u003cp>小剧本的编写要求：\u003c/p>\u003cp>1.要设计出人物(甲方：你，乙方：闺蜜/伴侣)。\u003c/p>\u003cp>2.情节变化（包括：起因、经过、结果等）。\u003c/p>\u003cp>3.采用独白和对话形式。\u003c/p>\u003cp>4.其中的人物需使用到“两性关系中有效沟通的三步法”。\u003c/p>\u003cp>5.给大家五分钟时间，将关键内容,写在便签上,之后我们邀请一位小\u003c/p>\u003cp>伙伴来用两分钟的时间来分享一下。\u003c/p>\u003cp>特别提示:小剧本的事件必须发生在未来\u003c/p>\u003cp>大家对上面的编写要求，有什么疑问吗? 如果有，可以直接开麦说哈。\u003c/p>\u003cp>之前有小伙伴编过小剧本吗?......(学习者:没有...) \u003c/p>\u003cp>反馈: 如果没有编过，也没关系，我们一起先看一下，根据我和我爱人，改编的小剧本。包括了剧本的5要素，时间、地点、人物、场景、剧情过程。\u003c/p>\u003cp>这个示例的要点有五点。\u003c/p>\u003cp>1. 事情的时间发生在未来\u003c/p>\u003cp>2. 人物角色有两位\u003c/p>\u003cp>3. 人物之间有独白，有对话的形式\u003c/p>\u003cp>4. 在互动的过程中，应用两性关系中成长性思维有效沟通的三步法”\u003c/p>\u003cp>5. 最后还有结果\u003c/p>\u003cp>大家可以，把你编的剧本的内容，对应到这5个要素中，写在你的便签上\u003c/p>\u003cp>场景可能有：\u003c/p>\u003cp>1、对方没有及时的洗袜子\u003c/p>\u003cp>2、 衣服乱丢\u003c/p>\u003cp>3、 没有下班接你\u003c/p>\u003cp>4、 出差没有及时的和你联系\u003c/p>\u003cp>5、 因为孩子学习的事情和你吵了一架等等\u003c/p>\u003cp>（时间到，哪位来分享一下你们的故事呢，时间大约2分钟哦。）\u003c/p>\u003cp> 学习者阳光分享\u003c/p>\u003cp>【反馈】\u003c/p>\u003cp>感谢阳光分享，非常的棒，在审视需求这一步，明确了自己的目的，也知道了老婆的需求。再次感谢阳光。\u003c/p>\u003cp>【结语】\u003c/p>\u003cp>最后，我总结一下今天的拆页内容：通过一对情侣相识与看似互相了解，终结于不沟通的故事，学习了如何在两性关系中通过发现问题，申视需求，主动沟通这三步做到有效的沟通，以便于维持长久，健康亲密的两性关系。\u003c/p>\u003cp>以上就是我3-1过级的全部内容，感谢大家的聆听与陪伴，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1688883806000,"updated_at":1689907584000,"ria":true},{"id":15864,"topic":"如何了解固定型思维、如何正确有效传递成长型思维","learn_goal":"","remark":"如何了解固定型思维、如何正确有效传递成长型思维","level":"TF2-4","duration":60,"status":30,"type":0,"chaishujia":{"username":"拆书家十八","city":"贵阳市"},"club":{"name":"贵阳黔灵分舵","city":"贵阳"},"prologue":"\u003cp>【开场】不破不能立，不拆不成器！拆书帮把知识拆成你的能力！欢迎大家参加拆书帮贵阳第二筹备分舵线下拆书练级活动，我是今天的领拆人一级拆书家杨朵，大家可以叫我十八，医美设计师是我的职业，成为孩子亦师亦友，引以为傲的母亲是我终生学习的原动力，漂亮的活好是我毕生的追求。\u003c/p>\u003cp>【分组】为了方便学习过程中充分交流讨论，我们简单分个组。今天有5位书友到场，我右手边2人一组，左手边3人一组这样分开。谢谢！\u003c/p>\u003cp>\u003cstrong>目标：用FAB法介绍图书。要求：清晰辨别出F、A、B\u003c/strong>\u003c/p>\u003cp>下面我来介绍一下今天拆解这本书《终身成长》。\u003c/p>\u003cp>【F】特征，核心是“书”，用于满足好奇心。\u003c/p>\u003cp>这是一本心理学书籍，作者通过数十年对成功的研究，发现了思维模式的力量。她在书中表明，我们获得成功与否，并不是能力与天赋所决定的，更是受我们在追求目标过程中所展显的思维模式影响，本书介绍了两种思维模式：固定型和成长型，它们体现了应对成功与失败，成绩与挑战时的两种基本心态。\u003c/p>\u003cp>【A】优势，重点是“比较”，用于建立安全感。\u003c/p>\u003cp>作者卡罗尔•德韦克所通过20多年对成功者研究发现了成年长性思维的力量,和同类书籍相比这不是简单的理论和概念，他所揭示的成长性思维法则被很多具有发展眼光的父母，老师，教练，运动员和管理者运用，并在实践中得到了验证。\u003c/p>\u003cp>【B】利益，强调的是“你（学习者）”用于引发兴趣。\u003c/p>\u003cp>B1：这本书给学习者带来的好处。\u003c/p>\u003cp>怎样在达成一个目标后激情依然饱满，动力不减？怎样让孩子主动学习，面对困难不退缩，怎样让自己在人才济济的公司脱颖而出？通过本书的学习，你会了解到最根本的原因—思维方式的不同，也会更详细的知道到成长型思维方式是如何对我们的工作，孩子的教育，夫妻关系产生巨大的影响\u003c/p>\u003cp>B2：拆页片段给学习者带来的好处\u003c/p>\u003cp>通过这两个拆页的学习，你会了解到为什么面对同一个挫折，有的人一撅不正，有的人短暂的失落后依然激情满满，为什么有的孩子会因为一次考试失利而跳楼，为什么你认为孩子的能力可以通过学习提高，而你的孩子却说自己就是不行。\u003c/p>\u003cp>（ \u003cstrong>目标：设定学习目标。要求：可观察/可测量的行为或动作\u003c/strong>\u003c/p>\u003cp>在跟随我完成第一个RIA现场学习后，学习者通过通过了解固定性思维及成长性思维，学会培养自己的成长性思维。）\u003c/p>","ratings_count":3,"texts":[{"id":19942,"quote":"\u003cp>【过渡语】接下来，\u003c/p>\u003cp>下面请用2分钟的时间快速阅读这个片段。阅读完后请举手示意我。\u003c/p>\u003cp>【R阅读原文】P268-P269\u003c/p>\u003cp>下面是麦琪所说的,她梦想当一名作家:\u003c/p>\u003cp>我意识到,谈到艺术和创作时,我一直在使用固定型思维模式。我认为人的艺术细胞或创造力都是天生的,无法通过努力提高。这对我的生活造成了直接的影响，因为我一直想成为一名作家，但是一直害怕去参加写作培训班或者和别人分享我作品。这和我的思维模式直接相关，因为任何负面的评价都会让我觉得，我天生就不适合当作家。我可能不是“天生的”作家，我太害怕这种可能性了。\u003c/p>\u003cp>现在，在听过您的讲座之后，我下学期决定报名参加写作班。并且，我感觉我真正明白了是什么阻碍了我追求我感兴趣的事业，而这项事业一直是我隐藏的梦想。我真正感觉到，这个信息给了我力量。\u003c/p>\u003cp>麦琪过去的内心独白是这样的：不要去做。不要参加写作班。不要和别人分享你的作品。不值得去冒这个风险。你的梦想可能会被毁灭。保护好你的梦想。\u003c/p>\u003cp>而现在她的内心独白则变成了：去努力追求吧。让你的梦想实现。发展你的技能。追逐你的梦想。\u003c/p>\u003cp>（还有30秒，看完了请举手示意我一下，……好，时间到，没有看完的小伙伴可以跟随我对这个片段讲解再继续来看。）\u003c/p>","explains":"\u003cp>【what】这个片段通过麦琪面对自己当一名作家的梦想从不敢面对到想办法去实现的案例告诉我们，拥有成长性思维是多么的重要。\u003c/p>\u003cp>成长性思维就是基于相信我们的能力是可以通过学习和努力来获得并且提高的，在遇到挫折，不如意时，不会轻易的否定自己，不会给自己贴标签，有点像积极心态，但绝不局限于积极心态，在成功时，不会局限于现有的成绩，不会急于去证明自己，更注重于个人的成长。而相对的是固定性思维，认为能力是固定的，一成不变的，面对挑战，聚焦点不是在能力的提升，目标的实现上，更在乎他人对自己的评价。\u003c/p>\u003cp>【why】在有限的一生中，我们经常会遇到各种不如意的事情，孩子在学校表现不好请家长，工作中被领导批评，被顾客投诉，家庭里和爱人、父母因某事产生争执，因疫情被隔离…………成长型思维的人会积极面对，寻找解决的方法，固定型思维的人会表现出消极的态度，要么责怪他人，要么自我否定，情绪内耗。\u003cstrong>（通常做法）\u003c/strong>\u003c/p>\u003cp>如果长期不能觉察到你的种种反应与思维模式有关，那么你的各种能力如社交，沟通表达力，领导力，艺术细胞等等，都不能得到更大的进步，并且你的固定型思维的言语会影响孩子思维模式的发展\u003cstrong>。（坏处）\u003c/strong>\u003c/p>\u003cp>【预防异议】有的人会问，固定性思维就是消极心态吗？不，固定性思维的人同样觉得自己充满吸引力，成长性思维\u003cu>是基于相信我们的基本能力都能通过学习和努力获得并提高，\u003c/u>纵是每个人生来才能与智力，性情与才智都有所不同；那拥有成长型思维就可以像马云，董明珠，迪丽热巴等人一样获得金钱与荣誉吗？不是这样的，但至少你不会满足于目前的成绩，而且会不断的获取新的知识。\u003c/p>\u003cp>【\u003cstrong>反例】\u003c/strong>以前在才艺和记忆力，写好字这方面我一直是固定性思维，每当看到唱歌好听，跳舞好看的人，我就觉得自己没这方面的天赋，五音不全，四肢不协调，记不住歌词，听不懂旋律，在写字这方面我更离谱，我甚至一度觉得是小时候爱吃鸡爪引起的，因为大人都说我写的字像鸡爪爪的\u003cstrong>。\u003c/strong>\u003c/p>\u003cp>其实每个人都有固定型思维和成长型思维，那么怎样才能更好的培养自己的成长性思维呢（过渡语）\u003c/p>\u003cp>【how】\u003c/p>\u003cp>一、接受：拥抱自己的固定型思维，我们每个人都有两种思维模式。\u003c/p>\u003cp>二、观察：观察自己的固定型思维什么时间出现，因为什么会出现，出现的时候会对你说什么。例如：遇到比自己优秀的人，我会不由自主的贬低自己，在接受到他人批评时，我会进入固定型思维，它会对我说：你就是这么普通，资质平庸，无论怎么努力都不会很优秀等等\u003c/p>\u003cp>三、命名：给自己的固定型思维起一个名字，我的固定型思维就叫小暴君。\u003c/p>\u003cp>四、教育：已经痛苦的了解了固定型思维是怎么出现的，怎么影响我们的，那就在起步前设想一下，他会对你说什么？在失败挫折时，也是他出来的好时机，告诉他：耐心一点，虽然现在不够好，但通过努力会越来越好的。\u003c/p>\u003cp>【\u003cstrong>正例\u003c/strong>】在读了这本书后，我就明白了，人的才能是可以发展的，我只是陷入了固定型思维模式，我也有成长型思维的时候，比如在教育孩子方面（接受），在记不起要记住的东西时，在看到他人才艺表演时，我的内心就有一个声音：你记性不好，你没有音乐细胞，你太僵硬，你字就是写不好等等（观察），我给他起了名字叫小暴君（起名），现在我已经练习半年，虽然还是写的一般，但是我不会否定自己，每当小暴君来时，我都和他对话，是的，我现在的字写的一般，请耐心一点，这个需要改掉肌肉以前的记忆力，现在也在一点点变好，偶尔有一个字还是写的很好的，只是不稳定而已，继续练习，一定可以的（教育）。所以目前在练字方面我大多少时候都保持成长型思维，更不会放弃。\u003c/p>\u003cp>【意译案例】\u003c/p>\u003cp>和我一起阅读本书的一个朋友小兰，她也给我分享了她的改变。\u003c/p>\u003cp>下面是小兰的自述，她的梦想是做一名讲师：\u003c/p>\u003cp>我意识到，在有关记忆力方面，我一直都在使用固定型思维模式。谈到与记忆力有关的事情时，我都认为记忆是天生的，是遗传的，是没法改变的，而且随着年龄增加是逐渐降低的。这对我的生活造成了很大的影响，我不但很自卑，也不能去实现我的梦想—做一名讲师，我更不敢去找这方面的工作。这是受我的固定型思维影响的，因为我害怕老板说我知识积累的不够，也害怕自己在观众面前忘词，语塞，被他人嘲笑等等负面的反馈。我可能天生就是一个健忘的人，我太担心了。\u003c/p>\u003cp>现在，我读了这本书，我决定在冬季报一个有关记忆力训练的班。并且我也意识到了，真正阻碍我实现梦想的不是记忆力，而是我的思维模式。\u003c/p>\u003cp>小兰过去的内心独白是这样的：不要去，不要找这方面相关的工作，老板会认为你能力不行，同事也会嘲笑你，就这样想想就行了。\u003c/p>\u003cp>小兰现在的内心独白是这样的：去做吧，去追寻你的梦想，虽然记忆力不好，但是通过练习你会提升的。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>这个方法可以用在工作、生活、育儿等各种你感觉能力是天生的，害怕他人批评，自我否定，面对梦想不敢行动时。\u003c/p>","interaction":"\u003cp>[A1]激活经验【要求：联系到过往具体经验】\u003c/p>\u003cp>【提问设计】\u003c/p>\u003cp>那么接下来，请大家回想一下，在过去的一个月内，什么激发了你的固定性思维？他出现时对你说了什么？\u003c/p>\u003cp>比如：面对多人说话紧张时，唱歌跑调时，和孩子发生争执时，工作没做好时，看到比你优秀的人时等等\u003c/p>\u003cp>请大家想一想你类似的经历。\u003c/p>\u003cp>每人一分钟，在小组内分享或者写在便签上。4分钟之后我将邀请一位小伙伴来给大家进行分享。\u003c/p>\u003cp>那么谁来给大家分享一下呢？\u003c/p>\u003cp>【反馈设计】\u003c/p>\u003cp>谢谢小伙伴们的分享！\u003c/p>\u003cp>观察到自己的固定型思维是什么时候出现，因为什么会激发，这是一个痛苦的过程。每位小伙伴都是如此的勇敢面对真实的自我，让我们用掌声来感谢一下我们这几位分享者！（号召鼓掌）\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>1、分享者阿志：最近我们公司内部有个考试，面对这个考试我出现了固定性思维。固定性思维对我说：你已经好多年不考试了，你不如上学的时候了，你记忆力也下降了，精力也不够了，会考不过的。\u003c/p>\u003cp>2、分享者林柯：最近学习古筝，好几个导师都指出我相同的问题。面对这个问题我出现了固定性思维，他对我说：你就是练不好，无论你怎么努力，你都是这样\u003c/p>\u003cp>3、分享者燕子：最近报了一个写作训练营，里面有很多写作很厉害的大咖，加上刚开始需要进一个网站，一开始就很复杂，我就突然觉得自己什么都不会了，这时我就出现了固定性思维，他对我说：你特别的不优秀，你就是写作不行，为此我也拖了好几天的作业。\u003c/p>\u003cp>[A1+]【要求：学习者加工出以后遇到同等情况如何做】\u003c/p>\u003cp>大家通过我说的例子及刚才小组内的分享个人的案例，已经知道了成长型思维是多么的重要，也学习了如何培养自己的成长型思维，如果让你再回到刚才你回忆的事情上，你如何用接受，观察，命名，教育四步骤来培养自己的成长型思维。\u003c/p>\u003cp>（互动）……\u003c/p>\u003cp>还有吗？……\u003c/p>\u003cp>【反馈设计】\u003c/p>\u003cp>通过以上的分享我们就会发现，成长型思维模式的培养是需要经过一系列过程的，而且接受自己的固定型思维是成功培养成长型思维的第一步。（互动）\u003c/p>\u003cp>好，让我们用热烈的掌声感谢分享的小伙伴！（号召鼓掌）\u003c/p>\u003cp>【现场反馈】\u003c/p>\u003cp>燕子的分享非常完美的用运到了培养成长性思维的四步，非常的赞，希望通过今天的学习让你在写作训练营如虎添翼，学到更多的知识，有更多的收获。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>燕子：对写作训练营这个固定性思维运用刚才的四步就是：\u003c/p>\u003cp>1、接受：我就是没有那么优秀，很别人比起来就是很普通，但是为什么要和别人比呢\u003c/p>\u003cp>2、观察：看到比自己优秀的人，尤其是写作，演讲等方面，我就会变相的贬低自己，固定性思维会对我说：你就是能力平平，一般般，比够优秀。\u003c/p>\u003cp>3、命名：起名“完美小姐”\u003c/p>\u003cp>4、教育：虽然我现在看起来不是很厉害，能力也一般般，虽然我现在的努力可能看不到明显的改变，但只要我坚持去学习，随着时间的推移，一定会越来越好。\u003c/p>\u003cp>结语：【目标：承上启下。要求：呼应、总结、简短】\u003c/p>\u003cp>通过对上面内容的学习，我们了解到成长性思维模式对我们的生活方式影响有多大，以及如何培养成长型思维。那么我们拥有了成长性思维，如何有效的传递出成长性思维的言语，进而影响我们的孩子，伴侣，同事，下属。\u003c/p>\u003cp>接下来的拆页片段将带给我们有效的方法。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":19943,"quote":"\u003cp>\u003cstrong>【目标：设定学习目标。要求：可观察/可测量的行为或动作】\u003c/strong>\u003c/p>\u003cp>前后两个片段之间是递进的关系\u003c/p>\u003cp>在跟随我完成第二个RIA现场学习后，学习者通过学习如何正确有效的穿递成长性思维，作为老师，父母，领导的我们能够在日常的生活中对学生，孩子，学员传达出成长性思维语言，使她们面对挫折时能够热爱挑战，迎难而上\u003c/p>\u003cp>\u003cstrong>【目标：实用类图书、包含HOW的片段；内容不超过2页纸】\u003c/strong>\u003c/p>\u003cp>请用1分钟时间快速阅读拆页二，阅读完毕后请举手示意我：\u003c/p>\u003cp>【R阅读原文】P259-P260\u003c/p>\u003cp>但是除此之外，我们还发现了一些惊人的现象，孩子一般不会直接看到父母头脑中的思维模式，父母公开的言行反而对孩子显响更大、他们一般会学到父母的言行。不幸的是，很多父母的言行和他们头脑中的成长型思维模式并不一致，所以，是什么样的言行体现了相反的思维模式？\u003c/p>\u003cp>首先，毫无疑问的一类就是称赞孩子。父母对孩子的称赞方式塑造了孩子的思维模式。有趣的是，父母的称赞方式不一定与他们的思维模式一致。即使有些父母拥有成长型思维模式，我们依然可以看到他们会夸奖孩子的能力，而不是关注孩子的学习过程——通过称赞孩子聪明来给予孩子信心的观念有时是根深蒂同的。\u003c/p>\u003cp>其次，是父母面对孩子的错误和失败时做出的反应。一个孩子遇到挫折时，如果父母表现得焦虑、或者表现得非常关注孩子的个人能力、会更容易促使孩子形成固定型思维模式。父母可能会尝试着掩盖孩子的失败，但这样做的结果反而传递出一个信息，那就是失败是一件很严重的事。因此，即使父母拥有成长型思维模式，当孩子们遇到挫折时，他们依然会对孩子们的自信心以及士气表现出担忧。\u003c/p>\u003cp>那些对孩子的挫折表现出兴趣，并将其视为学习良机的父母才能将成长型思维模式传授给他们的孩子。这些父母认为挫折是一件值得欢迎的好事，认为这些挫折可被视为学习的良机。他们会直面和处理这些挫折，并告诉孩子下一步的学习计划.\u003c/p>\u003cp>此外，成功传授成长型思维模式还要求老师在教学过程中注重学生的理解，而不是简单地让学生死记硬背知识、规则和步骤。研究显示，当老师注重进一步的理解，并帮助学生达到这一目标的时候，学生更容易认为自己的个人能力是可以发展的。一项研究发现，如果数学老师对概念的理解进行教学，并给予学生反馈，让他们去进一步理解，并在之后让学生修改自己的作业（去体会和表明他们已经进一步理解了知识），这些老师教出的学生在数学方面会逐渐走向成长型思维模式。\u003c/p>\u003cp>（还有30秒，看完了请举手示意我一下，……好，时间到，没有看完的小伙伴可以跟随我对这个片段讲解再继续来看。）\u003c/p>","explains":"\u003cp>【what】这个片段告诉我们如何通过三个方面有效的传递成长性思维\u003c/p>\u003cp>【why】\u003c/p>\u003cp>（通常做法）在孩子考了高分时我们是如何夸赞孩子的，“你太聪明啦”“你真是个天才”“你太棒啦”“你是妈妈的骄傲”“你很有天赋”等等，虽然你拥有成长性思维，但是你表达出来的确实固定性思维的语言（智力比努力更重要），难道不是要通过赞美鼓励孩子，让孩子知道：能力可以通过后天的努力学习得来吗？\u003c/p>\u003cp>（不那么做的坏处）长时以往的固定性思维的言语鼓励，孩子为了让他在大人的眼里看起来是聪明的，他们就不愿意接受更具有挑战性的任务，或者是在学习课程更难一点，需要投入更多精力和心思才能掌握时，孩子就会从心里觉得是自己太笨了，更没有动力和勇气去下功夫提升自己。\u003c/p>\u003cp>那么如何才能有效的传递出成长性思维，让孩子们有很强的逆商呢。可以从以下三个方面去做\u003c/p>\u003cp>【how】\u003cstrong>（细化步骤）\u003c/strong>\u003c/p>\u003cp>一、有效的赞美：成功时是塑造行为的关键时候，当孩子考了高分，获得奖励时，从努力的过程去赞美他，如：妈妈看的你为了迎接这次考试，你提前3个星期都在准备了，而且有清晰明确的计划，遇到不会的题你在吃饭时也在思考，妈妈为你的努力感到骄傲。\u003c/p>\u003cp>二、有效的鼓励：当孩子遇到挫折时，最重要的是做到情感的共鸣，因为情绪的对抗是交流的最大障碍，没有了情绪的对抗，你说的他才会听到心里去。\u003c/p>\u003cp>\u003cstrong>首先\u003c/strong>，说出他此时的感受，如：你为这次比赛付出了很多时间和精力，可是没有达到你预期的结果，所以你觉得很沮丧，是吗？\u003c/p>\u003cp>\u003cstrong>其次\u003c/strong>:带着孩子做复盘。在这个过程中，你觉得那些方面做得比较好，那些还可以提升。注意在这个过程中不要做任何的评判和建议，你的任务就是引导孩子自己做复盘，你就是一个倾听者\u003c/p>\u003cp>\u003cstrong>最后\u003c/strong>：引导孩子做出学习计划。如:那对于你觉得做的不好的你想怎么做，或者需要我提供什么帮助，我都会全力支持你。\u003c/p>\u003cp>三、重视对知识的理解。\u003c/p>\u003cp>首先、鼓励孩子不仅要记住，还要理解作者这么写的意图等等。学会活学活用，而不仅仅是为了考试而学。\u003c/p>\u003cp>其次、最好能教给孩子有效的学习方法和引导理解相关的知识。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>可能有的小伙伴会说，天赋本来就很重要嘛，没有音乐天赋能做歌星吗，这一方法是建立在你相信思维模式是可以塑造的，能力是可以改变的。那还有小伙伴说，我和孩子不提学习是父慈子孝，一提学习是鸡飞狗跳，那我要提醒你哦，永远不要跳过孩子去看他后面的成绩，你要先看到孩子，再去看成绩，也就是说你需要更关注你的孩子，调整你们的亲子关系，至于如何处理好亲子关系，这是一个庞大的课题，在以后的拆书中我会有专题的分享。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>\u003cstrong>这个方法不仅适用于家庭教育，也适用于老师对学生，领导对下属，教练对学员，同事之间，朋友之间。\u003c/strong>\u003c/p>","interaction":"\u003cp>[A3]促动参与 \u003c/p>\u003cp>【场景设计】\u003c/p>\u003cp>接下来是我们的练习时间了，希望通过这个场景练习，大家能够更好的传递成长性思维，能通过自己的言行影响他人，也是一件了不起的事情。\u003c/p>\u003cp>假设你是阳光中学的一名老师，你有一名学生，他家境贫寒，家里有三个兄弟姐妹，弟弟妹妹学习成绩非常好，经常获奖，父母经常向自豪的亲朋好友说弟弟妹妹学习有多好，人有多聪明，而他很少被提起，因此他非常痛苦，他学习也很刻苦，他希望用成绩证明自己，可是考试结果都是一般般，多次下来，他就觉得是自己太笨，不够聪明，那么努力都考不好。\u003c/p>\u003cp>【行动指令】\u003c/p>\u003cp>那么你如何用今天所学到的（有效的赞美，鼓励，重视对知识的理解）帮助这个孩子，激起他的信心，让他继续努力。\u003c/p>\u003cp> 现在，请大家用8分钟时间，按照开场的分组，在小组内讨论，并且写在便签上。\u003c/p>\u003cp>随后我们邀请一个小组内的代表来阐述一下他们的内容。\u003c/p>\u003cp>开始：\u003c/p>\u003cp>（互动交流）……\u003c/p>\u003cp>时间到了，下面哪位小组代表来给我们分享一下你们的内容呢？\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>女生组分享非常有意思，两位都从不同的出发点去赞美和鼓励孩子\u003c/p>\u003cp>燕子：假如我是一个老师，我会从学习成绩的角度去激励他。\u003c/p>\u003cp> 竹子前3年都在土里扎根，随后一年会疯狂的增长，虽然你现在努力看不到明显的变化，这就好比竹子在土里扎根，你持续下去，一定会看到明显的变化（激起孩子的信心），然后带着他做复盘及计划（有效的鼓励） \u003c/p>\u003cp>林柯：我会从其他的品质方面赞美他，如：你虽然没有弟弟妹妹学习成绩看起来那么凸出，但是老师看到你很热心，有一次同学没带伞，你就送她回家，很有责任心等等，激起他的信心（有效的赞美）。\u003c/p>\u003cp>【设计反馈】\u003c/p>\u003cp>谢谢分享（邀请鼓掌）大家来鼓掌感谢我们小伙伴的分享！\u003c/p>\u003cp>希望大家以后可以多运用，也可以把这一技能传授给你身边有需要的朋友们。\u003c/p>\u003cp>【现场反馈】\u003c/p>\u003cp>两位都是非常的棒，燕子是从有效的鼓励开始，林柯通过其他品质进行有效的赞美。给与其信心，逐步帮助其建立一种信念，努力不一定会成功，但努力一定会有所改变。\u003c/p>\u003cp>[A2]催化应用【要求：包括情景或场景，学习者受启发联系到自己的具体应用场景】\u003c/p>\u003cp>【场景设计】\u003c/p>\u003cp>通过前面的演练，相信大家已经熟悉了如何更好的传递成长性思维，\u003c/p>\u003cp>现在请我们来想一下，在未来一个月内，你在家庭，工作中，经历过的他人成功或者失败失落的事情，\u003c/p>\u003cp>比如孩子学习进步得A，爱人完成了自己认为完不成的工作，同事完成了高难度的工作，或者孩子考级没过，好友考证差一分等等\u003c/p>\u003cp>【行动指令】\u003c/p>\u003cp>大家根据个人可能会遇到的事情，写出来，并且想一下你会如何用今天所学习的有效传递成长性思维的方法（有效的赞美，有效的鼓励，重视对知识的理解）解决这件事情，并将其写在便签上，稍后我们来进行分享，时间5分钟。\u003c/p>\u003cp>【小组分享】\u003c/p>\u003cp>（视现场时间而定是否要进行公开的描述）\u003c/p>\u003cp>谁愿意主动来给大家分享一下呢。\u003c/p>\u003cp>……\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>分享者林柯：最近老公敢当众讲话，也会积极的在读书会展示自己的PPT，以前他是比较沉默的，也不愿说太多的。\u003c/p>\u003cp>我会对他说：老公，看到你最近在读书会积极的发表自己的看法，也会展示自己做的PPT,而且我看到你晚上睡觉前会把今天的收获写下来，以前你都不愿意当众说话的，看到你这些变化，我真的非常开心（这个就是有效的赞美）\u003c/p>\u003cp>分享者放心：通过刚才的学习，我想到我自己最近的一个考试，由于工作耽误了考试。我刚开始就没有树立清晰的目标（有效的赞美这一点迁移到的），这个考试对我来说只是一个锦上添花的事情，所以可有可无（有效的鼓励这一点迁移到的），注重对知识的理解这一块儿，我应该不能只想着考试，要考虑到后期的应用。我回去后还会在好好的理一下思路\u003c/p>\u003cp>（放心是非会员，处于观望的状态，第一次旁听，走的时候说觉得这个场域很好，会安排时间和做好计划参加线上14天训练营，尽快加入分舵）\u003c/p>\u003cp>【反馈设计】\u003c/p>\u003cp>非常好，赞美从细节出发，鼓励前先情感共鸣。\u003c/p>\u003cp>大家掌声鼓励！再次感谢！（掌声）\u003c/p>\u003cp>【现场反馈】\u003c/p>\u003cp>非常好，林柯的赞美从细节出发，放心是迁移到了自身最近的考试上。改变是从相信可以改变开始，从现在开始，改变自己的表达方式，影响他人的思维模式\u003c/p>\u003cp>结术语【目标：强有力的结语，要求：简短，呼应】\u003c/p>\u003cp>今天我们的两个拆页的内容全部结束。\u003c/p>\u003cp> 第一个片段通过麦琪面对自己当一名作家的梦想从不敢面对到想办法去实现的案例告诉我们，拥有成长性思维是多么的重要，进而学习了如何培养成长型思维。第二个片段告诉我们如何有效的传递成长思维！这两个片段是递进的关系，可以单独使用，也可以一起用。希望通过今天的学习，大家都有所收获，即使是一句话，一个故事对你的启发，也能更好的在生活中运用到，拆书就是拆为己用，用来解决生活工作中所遇到的问题。\u003c/p>\u003cp>以上是今天的全部内容，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1684727296000,"updated_at":1685522873000,"ria":true},{"id":15722,"topic":"如何识别固定型思维、如何有效传授成长型思维模式","learn_goal":"","remark":"如何识别固定型思维、如何有效传授成长型思维模式","level":"TF2-4","duration":60,"status":29,"type":0,"chaishujia":{"username":"拆书家十八","city":"贵阳市"},"club":{"name":"贵阳黔灵分舵","city":"贵阳"},"prologue":"\u003cp>\u003cstrong>目标：两个拆页搭配，要求：有逻辑关系\u003c/strong>\u003c/p>\u003cp>今天我们的总体学习目标就是：在工作，生活中面对同一个错误，挫折，有的人迎难而上，有的人一蹶不振，埋怨他人，逃避责任，到底是什么影响了我们做出不同的反应。是思维模式的不同，思维方式决定行为，行为决定习惯，习惯影响了行为，行为又体现了思维方式。今天的学习目标就是通过两个拆页的学习，了解固定性思维及成长性思维在生活中的体现，从而在遇到挫折，不如意时能够及时区分此时是受固定性思维还是成长性思维的影响，以及如何有效的传递成长性思维。\u003c/p>\u003cp>第一个片段：通过学习固定性思维和成长性思维在日常生活中不同的表现，在遇到挫折，不如意时能够及时区此时是受固定性思维，还是成长性思维的影响。\u003c/p>\u003cp>第二个片段：通过学习如何正确有效的传递成长性思维，作为老师，父母，领导的我们能够在日常的生活中对学生，孩子，学员传达出成长性思维语言，使她们面对挫折时能够热爱挑战，迎难而上。\u003c/p>\u003cp>\u003cstrong>目标：简单开场，分组\u003c/strong>\u003c/p>\u003cp>【开场】不破不能立，不拆不成器！拆书帮把知识拆成你的能力！欢迎大家参加拆书帮贵阳第二筹备分舵线下拆书练级活动，我是今天的领拆人一级拆书家杨朵，大家可以叫我十八，医美设计师是我的职业，成为孩子亦师亦友，引以为傲的母亲是我终生学习的原动力，漂亮的活好是我毕生的追求。\u003c/p>\u003cp>【分组】为了方便学习过程中充分交流讨论，我们简单分个组。今天有5位书友到场，我右手边2人一组，左手边3人一组这样分开。谢谢！\u003c/p>\u003cp>\u003cstrong>目标：用FAB法介绍图书。要求：清晰辨别出F、A、B\u003c/strong>\u003c/p>\u003cp>下面我来介绍一下今天拆解这本书《终身成长》。\u003c/p>\u003cp>【F】特征，核心是“书”，用于满足好奇心。\u003c/p>\u003cp>这是一本心理学书籍，作者通过数十年对成功的研究，发现了思维模式的力量。她在书中表明，我们获得成功与否，并不是能力与天赋所决定的，更是受我们在追求目标过程中所展显的思维模式影响，本书介绍了两种思维模式：固定型和成长型，它们体现了应对成功与失败，成绩与挑战时的两种基本心态。\u003c/p>\u003cp>【A】优势，重点是“比较”，用于建立安全感。\u003c/p>\u003cp>作者卡罗尔•德韦克所通过20多年对成功者研究发现了成年长性思维的力量,和同类书籍相比这不是简单的理论和概念，他所揭示的成长性思维法则被很多具有发展眼光的父母，老师，教练，运动员和管理者运用，并在实践中得到了验证。\u003c/p>\u003cp>【B】利益，强调的是“你（学习者）”用于引发兴趣。\u003c/p>\u003cp>B1：这本书给学习者带来的好处。\u003c/p>\u003cp>怎样在达成一个目标后激情依然饱满，动力不减？怎样让孩子主动学习，面对困难不退缩，怎样让自己在人才济济的公司脱颖而出？通过本书的学习，你会了解到最根本的原因—思维方式的不同，也会更详细的知道到成长型思维方式是如何对我们的工作，孩子的教育，夫妻关系产生巨大的影响\u003c/p>\u003cp>B2：拆页片段给学习者带来的好处\u003c/p>\u003cp>通过这两个拆页的学习，你会了解到为什么面对同一个挫折，有的人一撅不正，有的人短暂的失落后依然激情满满，为什么有的孩子会因为一次考试失利而跳楼，为什么你认为孩子的能力可以通过学习提高，而你的孩子却说自己就是不行。\u003c/p>","ratings_count":1,"texts":[{"id":19797,"quote":"\u003cp>第一个片段;\u003c/p>\u003cp>\u003cstrong>[目标：设定学习目标。要求：可观察/可测量的行为或动作]\u003c/strong>\u003c/p>\u003cp>在跟随我完成第一个RIA现场学习后，学习者通过学习固定性思维和成长性思维在日常生活中不同的表现，能够在遇到不如意的事情时及时区分自己此时此刻是固定性思维，还是成长性思维。\u003c/p>\u003cp>【过渡语】接下来，\u003c/p>\u003cp>下面请用2分钟的时间快速阅读这个片段。阅读完后请举手示意我。\u003c/p>\u003cp>片段有些长，大家可以重点看下我标注出来的内容。\u003c/p>\u003cp>【阅读原文】P8-P9\u003c/p>\u003cp>为了帮助你更好地理解这两种思维模式是如何工作的，请想象一下，尽可能生动地去想，你是一个年轻人，经历了非常帽糕的一天：\u003c/p>\u003cp>你去上一门对你来说很重要的课，而且你非常喜欢这门课，你的教授公布了期中考试成绩，你得了C+。你非常失望，等到晚上准备回家的时候，你发现自己的车上贴了一张违章停车罚单。你感到非常泄气，打电话给最好的朋友想要倾诉。但是却没有打通。\u003c/p>\u003cp>你会怎么想？你会有什么样的感受？你会怎么做？\u003c/p>\u003cp>当我问同定型思维模式者时，他们是这样对我说的：&quot;我感到被拒绝了。&quot;“我是个失败者。”“我是个傻瓜。”“我感到自己很没用，所有人都比我优秀。&quot;&quot;我太差劲了。&quot;\u003cu>换句话说，他们会把发生的事当作一个衡量自己的能力和价值的直接的标尺，他们会这样看待自己的生活：“我的人生太可悲了。“楼上的那个人不喜欢我。”“这个世界跟我过不去。”“有人想要毁掉我。&quot;&quot;没有人爱我，所有人都恨我。&quot;&quot;生活是不公平的，所有的努力都是白费。&quot;&quot;生活太糟糕了，我太傻了。&quot;&quot;我身上没发生过什么好事。”“我是地球上最不幸的人。”\u003c/u>\u003c/p>\u003cp>可这是什么生死攸关的大事或者毁灭性的大灾难吗？还是只是一个分数、一张罚单和一通不顾心的电话？\u003c/p>\u003cp>是这些人太自卑吗，还是说他们是实实在在的悲观主义者？不，其实这些无法应对困难的人同样感到自己有价值，他们同样乐观——觉得自己聪明而有吸引力，他们和那些有着成长型思维模式的人是一样的。但他们是如何应对这些烦心事的呢？&quot;我就不应该浪费这么多时间和特力去办一件事。&quot;（换句话说，不会再让任何人来评判我。）&quot;什么都不做。&quot;&quot;待在床上。&quot;&quot;去喝酒。&quot;&quot;吃东西。&quot;&quot;找机会冲别人大喊。&quot;&quot;吃巧克力。&quot;&quot;边听音乐边郁闷。&quot;&quot;躲到壁橱里坐着。&quot;&quot;&quot;找人打一架。&quot;&quot;哭。&quot; “摔东西。&quot;&quot;还能怎么办？ &quot;\u003c/p>\u003cp>还能怎么办！你\u003cu>知道，在模拟这个情景的时候，我特意将成绩写成了C+而不是F，只把考试设定成期中考试而不是期末考试，你的车只是被贴了罚单而不是被毁了，打电话给朋友倾诉之举只是没有成功。你并没有被朋友直接拒绝。没有什么灾难性或不可逆转的事情发生。但仅仅是在这些情况的影响下\u003c/u>，\u003cu>同定型思维模式者就已经产生了这种彻底的失败感和无力感。\u003c/u>\u003c/p>\u003cp>当我把这些情况原封不动地拿给那些成长型思维模式者看后，他们是这样说的：\u003c/p>\u003cp>“我会更努力地学习，下次停车的时候我要更加小心一些，不知道我的朋友是不是今天过得不开心.&quot;\u003c/p>\u003cp>&quot;C+这个成绩告诉我，我必须在课堂上加倍付出努力，我依然有半个学期的时间来提高我的成绩。&quot;\u003c/p>\u003cp>还有很多类似的回答，我想你们已经了解他们会说些什么了。那么，他们会如何应对呢？\u003c/p>\u003cp>“我必须开始考虑，为了下一次测验，我要更努力地学习（或者换个学习方法），我会缴清罚款，下次再给朋友打电话的时候，我们再好好聊聊。”\u003c/p>\u003cp>“我会总结我在期中考试到底犯了哪些错误，下一次要做得更好。我得把我的罚款交了，打电话告诉我的朋友，那天我心情很不好。”\u003c/p>\u003cp>“下一次考试的时候我要更加努力，和我的老师交流交流，下一次停车的时候要小心一些，或者去理论一下我没有违章，还要去弄清楚我的朋友到底怎么了。”\u003c/p>\u003cp>不是说你必须拥有某种思维模式，而拥有另一种思维模式的人就会产生挫败感。谁不是这样呢？糟糕的成绩、朋友或爱人的拒绝都不是什么开心的事，没有人会喜欢这些糟糕的事情。\u003cu>只是这些有着成长型思维模式的人不会给自己贴上标签，或对自己失去信心。即使他们感到沮丧，他们也准备好了去承担这个风险，直面挑战，继续为此奋斗。\u003c/u>\u003c/p>\u003cp>（还有30秒，看完了请举手示意我一下，……好，时间到，没有看完的小伙伴可以跟随我对这个片段讲解再继续来看。）\u003c/p>","explains":"\u003cp>\u003cstrong>要求：应用意译案例，不这么做的坏处，预防异议\u003c/strong>\u003c/p>\u003cp>【why】在有限的一生中，我们经常会遇到各种不如意的事情，孩子在学校表现不好请家长，工作中被领导批评，被顾客投诉，家庭里和爱人、父母因某事产生争执，因疫情被隔离…………成长型思维的人会积极面对，寻找解决的方法，固定型思维的人会表现出消极的态度，要么责怪他人，要么自我否定，情绪内耗。\u003cstrong>（通常做法）\u003c/strong>\u003c/p>\u003cp>如果长期不能觉察到你的种种反应与思维模式有关，那么你的各种能力如社交，沟通表达力，领导力，艺术细胞等等，都不能得到更大的进步，并且你的固定型思维的言语会影响孩子思维模式的发展\u003cstrong>。（坏处）\u003c/strong>\u003c/p>\u003cp>【预防异议】有的人会问，固定性思维就是消极心态吗？不，固定性思维的人同样觉得自己充满吸引力，成长性思维\u003cu>是基于相信我们的基本能力都能通过学习和努力获得并提高，\u003c/u>纵是每个人生来才能与智力，性情与才智都有所不同；那拥有成长型思维就可以像马云，董明珠，迪丽热巴等人一样获得金钱与荣誉吗？不是这样的，但至少你不会满足于目前的成绩，而且会不断的获取新的知识。\u003c/p>\u003cp>【what】这个片段通过一个日常生活中的小事体现了固定型思维和成长型思维对我们生活的影响，进而体现成长性思维的重要性。\u003c/p>\u003cp>思维是什么，是一种信念，看不见，摸不着，却会通过平时的行为表现出来，本书的作者将其称为思维，分为成长性和固定性。成长性思维就是基于相信我们的能力是可以通过学习和努力来获得并且提高的，在遇到挫折，不如意时，不会轻易的否定自己，不会给自己贴标签，有点像积极心态，但绝不局限于积极心态，在成功时，不会局限于现有的成绩，不会急于去证明自己，更注重于个人的成长。固定性思维则相反。\u003c/p>\u003cp>【\u003cstrong>反例\u003c/strong>】我有一个同事在12月初离职了，她觉得这里已经不适合她了，起因是她在两个月前被顾客连着投诉了三次，她觉得自己很倒霉，领导也不喜欢她，在这里体现不了自己的价值，结果目前还是待业在家，找不到工作。\u003c/p>\u003cp>她在这件事情上就受到了固定性思维的影响，她觉得是自己倒霉，能力不行，领导也\u003c/p>\u003cp>不喜欢她。\u003c/p>\u003cp>其实每个人都有固定型思维和成长型思维，那么怎样才能觉察自己此时此刻是受固定型思维还是成长型思维影响呢（过渡语）\u003c/p>\u003cp>【how】\u003c/p>\u003cp>1、觉察：我此时此刻在想什么，我的感受是什么，我要做什么\u003c/p>\u003cp>2、暂停：在大脑给自己安装一个暂停键，如一个很大很尖锐的声音，或者是好玩的“缤狗”等。\u003c/p>\u003cp>3、区分：事情发生时，如果你的大脑里想的是“都怪他”“他为什么要这样做”“真实一群猪”“气死我了”“我真是笨死了，我能力有限，我不做了”等责怪他人或者自我否定的话，那此刻你是陷入了固定性思维里；如果你在想“我能从这件事中学到什么”“下次怎么做会更好”“我怎么样做才能达到我想要的”，那么此刻你就是成长性思维。如果是固定型思维，告诉自己，这没什么大不了的，让我试着用成长型思维去看待问题，我能做些什么让事情朝着我想要的方向发展。\u003c/p>\u003cp>【\u003cstrong>正例\u003c/strong>】在去年，有一段时间我在工作中遇到了瓶颈期，起因是在每次和领导沟通客户的项目方案时，她就会愤怒的说一句，不要总推特价。其实我的本意不是这样的，我觉得自己被误解，情绪也非常的低落，我什么都不想做，就这样吧，我不推了（觉察）。经过好几天的消沉，突然我大脑有一个声音告诉我，你真的要这样下去吗（暂停）。我在责怪他人，原来我在用固定型思维看待这个问题（区分）。我问自己，我的目的是什么，是充实自己，是逐步提高自己的能力，那是不是我在和领导沟通时表达的方式有问题，我是不是可以换个方式。从此，每次沟通的结果都能朝着我想要的方向发展，而且我还在和领导沟通交流中学到了我自己没有考虑到的方面。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>这个方法可以用在工作、生活、育儿等各种你感觉倒霉透顶，埋怨他人，自我否定，情绪低落的时候。\u003c/p>","interaction":"\u003cp>A1激活经验\u003c/p>\u003cp>【要求：联系到过往具体经验】\u003c/p>\u003cp>【提问设计】\u003c/p>\u003cp>那么接下来，请大家回想一下，在过去的一个月内，在工作，生活，家庭中，发生了什么事情让你觉得这都是别人的错，都怪他，或者否定自己，我能力不行，我做不到等等\u003c/p>\u003cp>比如：客户的投诉，老板因工作没达到预期效果发火，孩子在学校被叫家长，和老公因某事而责怪他等等\u003c/p>\u003cp>请大家想一想你类似的经历。\u003c/p>\u003cp>每人一分钟，在小组内分享或者写在便签上。4分钟之后我将邀请一位小伙伴来给大家进行分享。\u003c/p>\u003cp>那么谁来给大家分享一下呢？\u003c/p>\u003cp>【反馈设计】\u003c/p>\u003cp>谢谢小伙伴的分享！\u003c/p>\u003cp>在挫折时，暂时的情绪低落是正常的，重要的是有觉察情绪的认知。让我们用掌声来感谢一下小伙伴燕子！（号召鼓掌）\u003c/p>\u003cp>学习者案例记录（燕子）：开场前因儿子太吵，就告诉他如果不能保持安静，就会让爸爸带走他，结果就是孩子没有控制住，当打电话给他爸爸后，他不想离开就开始哭闹，那一刻觉得火冒三丈“你怎么这样让我丢脸”“我平时教你的都白教了”.\u003c/p>\u003cp>【A1+：要求：学习者加工出以后遇到同等情况如何做】\u003c/p>\u003cp>我想大家已经知道固定性思维和成长性思维对我们生活的影响，也通过以上的片段学会了如何及时辨别自己是受何种思维影响（觉察，暂停，区分）。\u003c/p>\u003cp>如果让你再回到刚才你回忆的事情上，你如何用觉察，暂停，区三步骤拉回自己的情绪。\u003c/p>\u003cp>（互动）……\u003c/p>\u003cp>还有吗？……\u003c/p>\u003cp>【反馈设计】\u003c/p>\u003cp>通过以上的分享我们就会发现，不同的观点会产生不同的生活方式，观点会对我们的生活方式产生重大的影响，它决定了我们是否能达到目标，是否能成为自己想成为的人，而这种观点正是思维模式带给我们的。（互动）\u003c/p>\u003cp>好，让我们用热烈的掌声感谢分享的小伙伴！（号召鼓掌）\u003c/p>\u003cp>【现场反馈】\u003c/p>\u003cp>以后再有类似的事情的话，我们就要学会使用觉察，暂停，区分这三步来及时改变自己的观点，逐步活成自己想要的样子\u003c/p>\u003cp>学习者案例记录（燕子）：\u003c/p>\u003cp>觉察：我觉得孩子哭闹让我丢脸了，我很生气，想让他马上闭嘴\u003c/p>\u003cp>暂停：转过去不要看到他的脸，深呼吸\u003c/p>\u003cp>区分：我此刻险入了固定性思维，我可以摸摸他的头，对他说：妈妈知道你想要留下来，我听到你的诉求啦。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":19798,"quote":"\u003cp>第二个RIA\u003c/p>\u003cp>\u003cstrong>目标：设定学习目标。要求：可观察/可测量的行为或动作\u003c/strong>\u003c/p>\u003cp>前后两个片段之间是递进的关系\u003c/p>\u003cp>在跟随我完成第二个RIA现场学习后，学习者通过学习如何正确有效的穿递成长性思维，作为老师，父母，领导的我们能够在日常的生活中对学生，孩子，学员传达出成长性思维语言，使她们面对挫折时能够热爱挑战，迎难而上\u003c/p>\u003cp>\u003cstrong>目标：实用类图书、包含HOW的片段；内容不超过2页纸\u003c/strong>\u003c/p>\u003cp>请用1分钟时间快速阅读拆页二，阅读完毕后请举手示意我：\u003c/p>\u003cp>【R阅读原文】P260-P261\u003c/p>\u003cp>起初，我们很惊讶地发现，这么多拥有成长型思维模式的家长没能将思维模式传授给孩子。这件事告诉我们一个道理：父母、老师和教练如果想要传递成长型思维模式，并不是头脑里有成长型思维模式就够了，而是要通过行为体现——称赞学生的方法（告诉学生、这样的努力过程可以帮助他们学到知识），在学生遭遇挫折时的反应（认为失败是学习的好机会）以及是否重视对知识的深入理解等（认为这才是学习的最终目标）。\u003c/p>\u003cp>（还有30秒，看完了请举手示意我一下，……好，时间到，没有看完的小伙伴可以跟随我对这个片段讲解再继续来看。）\u003c/p>","explains":"\u003cp>【what】这个片段告诉我们如何通过三个方面有效的传递成长性思维\u003c/p>\u003cp>【why】\u003c/p>\u003cp>（通常做法）在孩子考了高分时我们是如何夸赞孩子的，“你太聪明啦”“你真是个天才”“你太棒啦”“你是妈妈的骄傲”“你很有天赋”等等，虽然你拥有成长性思维，但是你表达出来的确实固定性思维的语言（智力比努力更重要），难道不是要通过赞美鼓励孩子，让孩子知道：能力可以通过后天的努力学习得来吗？\u003c/p>\u003cp>（不那么做的坏处）长时以往的固定性思维的言语鼓励，孩子为了让他在大人的眼里看起来是聪明的，他们就不愿意接受更具有挑战性的任务，或者是在学习课程更难一点，需要投入更多精力和心思才能掌握时，孩子就会从心里觉得是自己太笨了，更没有动力和勇气去下功夫提升自己。\u003c/p>\u003cp>那么如何才能有效的传递出成长性思维，让孩子们有很强的逆商呢。可以从以下三个方面去做\u003c/p>\u003cp>【how】\u003cstrong>（细化步骤）\u003c/strong>\u003c/p>\u003cp>一、有效的赞美：成功时是塑造行为的关键时候，当孩子考了高分，获得奖励时，从努力的过程去赞美他，如：妈妈看的你为了迎接这次考试，你提前3个星期都在准备了，而且有清晰明确的计划，遇到不会的题你在吃饭时也在思考，妈妈为你的努力感到骄傲。\u003c/p>\u003cp>二、有效的鼓励：当孩子遇到挫折时，最重要的是做到情感的共鸣，因为情绪的对抗是交流的最大障碍，没有了情绪的对抗，你说的他才会听到心里去。\u003c/p>\u003cp>\u003cstrong>首先\u003c/strong>，说出他此时的感受，如：你为这次比赛付出了很多时间和精力，可是没有达到你预期的结果，所以你觉得很沮丧，是吗？\u003c/p>\u003cp>\u003cstrong>其次\u003c/strong>:带着孩子做复盘。在这个过程中，你觉得那些方面做得比较好，那些还可以提升。注意在这个过程中不要做任何的评判和建议，你的任务就是引导孩子自己做复盘，你就是一个倾听者\u003c/p>\u003cp>\u003cstrong>最后\u003c/strong>：引导孩子做出学习计划。如:那对于你觉得做的不好的你想怎么做，或者需要我提供什么帮助，我都会全力支持你。\u003c/p>\u003cp>三、重视对知识的理解。如：孩子在背诵一首古诗时，鼓励孩子不仅要记住，还要理解作者这么写的意图等等。学会活学活用，而不仅仅是为了考试而学。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>可能有的小伙伴会说，天赋本来就很重要嘛，没有音乐天赋能做歌星吗，这一方法是建立在你相信思维模式是可以塑造的，能力是可以改变的。那还有小伙伴说，我和孩子不提学习是父慈子孝，一提学习是鸡飞狗跳，那我要提醒你哦，永远不要跳过孩子去看他后面的成绩，你要先看到孩子，再去看成绩，也就是说你需要更关注你的孩子，调整你们的亲子关系，至于如何处理好亲子关系，这是一个庞大的课题，在以后的拆书中我会有专题的分享。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>\u003cstrong>这个方法不仅适用于家庭教育，也适用于老师对学生，领导对下属，教练对学员，同事之间，朋友之间。\u003c/strong>\u003c/p>","interaction":"\u003cp>[A3]促动参与\u003c/p>\u003cp>要求：用知识点通过小组讨论形成方案，并现场分享。\u003c/p>\u003cp>【场景设计】\u003c/p>\u003cp>接下来是我们的练习时间了，希望通过这个场景练习，大家能够更好的传递成长性思维，能通过自己的言行影响他人，也是一件了不起的事情。\u003c/p>\u003cp>假设你是阳光中学的一名老师，你有一名学生，他家境贫寒，家里有三个兄弟姐妹，弟弟妹妹学习成绩非常好，经常获奖，父母经常向自豪的亲朋好友说弟弟妹妹学习有多好，人有多聪明，而他很少被提起，因此他非常痛苦，他学习也很刻苦，他希望用成绩证明自己，可是考试结果都是一般般，多次下来，他就觉得是自己太笨，不够聪明，那么努力都考不好。\u003c/p>\u003cp>那么你如何用今天所学到的（有效的赞美，鼓励，重视对知识的理解）帮助这个孩子，让他继续努力。\u003c/p>\u003cp>【小组讨论】\u003c/p>\u003cp>大家清楚练习的内容了吗？现在，请大家用8分钟时间，按照开场的分组，在小组内讨论，并且写在便签上。\u003c/p>\u003cp>随后我们邀请一个小组内的代表来阐述一下他们的内容。\u003c/p>\u003cp>开始：\u003c/p>\u003cp>（互动交流）……\u003c/p>\u003cp>时间到了，下面哪位小组代表来给我们分享一下你们的内容呢？\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>分享者杨雪：这个场景让我想起了我自己家的情况，我哥哥姐姐很努力，但是成绩一般，而我就是大人眼中别人家的孩子。如果我是老师，我会运用有效的鼓励：老师看到你平时学习很努力，也很刻苦，现在虽然没有明显的进步，但是没关系，千里之行始于足下，行动起来是最关键的，还有一个就是要注意学习的方式方法，随后老师也会分享一些好的方法给你，会帮助你的，继续努力，继续加油哦！\u003c/p>\u003cp>【设计反馈】\u003c/p>\u003cp>谢谢分享（邀请鼓掌）大家来鼓掌感谢我们小伙伴的分享！\u003c/p>\u003cp>希望大家以后可以多运用，也可以把这一技能传授给你身边有需要的朋友们。\u003c/p>\u003cp>【现场反馈】\u003c/p>\u003cp>在遇到挫折时，从情感上认同，逐步帮助其建立一种信念，努力不一定会成功，但努力一定会有所改变。\u003c/p>\u003cp>[A2]催化应用：\u003c/p>\u003cp>要求：包括情景或场景，学习者受启发联系到自己的具体应用场景\u003c/p>\u003cp>【场景设计】\u003c/p>\u003cp>通过前面的演练，相信大家已经熟悉了如何更好的传递成长性思维，\u003c/p>\u003cp>现在请我们来想一下，在近一个月内，你在家庭，工作中，经历过的他人成功或者失败失落的事情，\u003c/p>\u003cp>比如孩子学习进步得A，爱人完成了自己认为完不成的工作，同事完成了高难度的工作，或者孩子考级没过，好友考证差一分等等\u003c/p>\u003cp>【行动指令】\u003c/p>\u003cp>大家根据个人所遇到的事情，写出来，并且假如时光倒流，你会如何用今天所学习的有效传递成长性思维的方法（有效的赞美，有效的鼓励，重视对知识的理解）进行交流，请大家小组内进行讨论，并将其写在便签上，稍后我们来进行分享，时间5分钟。\u003c/p>\u003cp>【小组分享】\u003c/p>\u003cp>（视现场时间而定是否要进行公开的描述）\u003c/p>\u003cp>谁愿意主动来给大家分享一下呢。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>分享者小妖：刚才小组分享时杨雪就分享了她前段时间考公务员失利，只录取三人，而她刚好第四名，那段时间感觉抑郁了，心情非常糟糕，做什么都提不起精神。而她一个朋友也刚好经历了考试失利，但她朋友经过几天的失落就走出来了，现在的状态完全和她不同，朋友分享了一个情景疗愈法帮助她走了出来。这就是一个典型的有效的鼓励，从情感了有了认同，还分享了有效的方法。\u003c/p>\u003cp>【反馈设计】\u003c/p>\u003cp>非常好，赞美从细节出发，鼓励前先情感共鸣。\u003c/p>\u003cp>大家掌声鼓励！再次感谢！（掌声）\u003c/p>\u003cp>【现场反馈】\u003c/p>\u003cp>改变是从相信可以改变开始，从现在开始，改变自己的表达方式，影响他人的思维模式\u003c/p>\u003cp>【结语】\u003c/p>\u003cp>目标：强有力的结语，要求：简短，呼应\u003c/p>\u003cp>今天我们的两个拆页的内容全部结束。\u003c/p>\u003cp>让我们来回想一下，当我们遇到挫折，不如意时，我们会有不同的表现。\u003c/p>\u003cp>第一个片段通过一件考试失利这件事展现了成长性思维和固定性思维在生活中的体现，从而学会及时区分是受成长性思维和固定性思维影响，第二个片段告诉我们如何有效的传递成长性思维。这两个片段是递进的关系，可以单独使用，也可以一起用。希望通过今天的学习，大家都有所收获，即使是一句话，一个故事对你的启发，也能更好的在生活中运用到，拆书就是拆为己用，用来解决生活工作中所遇到的问题。\u003c/p>\u003cp>以上是今天的全部内容，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1682848170000,"updated_at":1683102087000,"ria":true},{"id":15663,"topic":"如何理解固定性思维和成长型思维，如何影响他人拥有成长型思维","learn_goal":"","remark":"如何理解固定性思维和成长型思维，如何影响他人拥有成长型思维","level":"TF2-4","duration":60,"status":19,"type":0,"chaishujia":{"username":"拆书家十八","city":"贵阳市"},"club":{"name":"贵阳黔灵分舵","city":"贵阳"},"prologue":"\u003cp>\u003cstrong>目标：两个拆页搭配，要求：有逻辑关系\u003c/strong>\u003c/p>\u003cp>今天我们的总体学习目标就是：在工作，生活中面对同一个错误，挫折，有的人迎难而上，有的人一蹶不振，埋怨他人，逃避责任，到底是什么影响了我们做出不同的反应。是思维模式的不同，思维方式决定行为，行为决定习惯，习惯影响了行为，行为又体现了思维方式。今天的学习目标就是通过两个拆页的学习，了解固定性思维及成长性思维在生活中的体现，从而在遇到挫折，不如意时能够及时区分此时是受固定性思维还是成长性思维的影响，以及如何有效的传递成长性思维。\u003c/p>\u003cp>第一个片段：通过学习固定性思维和成长性思维在日常生活中不同的表现，在遇到挫折，不如意时能够及时区此时是受固定性思维，还是成长性思维的影响。\u003c/p>\u003cp>第二个片段：通过学习如何正确有效的传递成长性思维，作为老师，父母，领导的我们能够在日常的生活中对学生，孩子，学员传达出成长性思维语言，使她们面对挫折时能够热爱挑战，迎难而上。\u003c/p>\u003cp>\u003cstrong>目标：简单开场，分组\u003c/strong>\u003c/p>\u003cp>【开场】不破不能立，不拆不成器！拆书帮把知识拆成你的能力！欢迎大家参加拆书帮贵阳第二筹备分舵线下拆书练级活动，我是今天的领拆人一级拆书家杨朵，大家可以叫我十八，医美设计师是我的职业，成为孩子亦师亦友，引以为傲的母亲是我终生学习的原动力，漂亮的活好是我毕生的追求。\u003c/p>\u003cp>【分组】为了方便学习过程中充分交流讨论，我们简单分个组。今天有5位书友到场，我右手边2人一组，左手边3人一组这样分开。谢谢！\u003c/p>\u003cp>\u003cstrong>目标：用FAB法介绍图书。要求：清晰辨别出F、A、B\u003c/strong>\u003c/p>\u003cp>下面我来介绍一下今天拆解这本书《终身成长》。\u003c/p>\u003cp>【F】特征，核心是“书”，用于满足好奇心。\u003c/p>\u003cp>这是一本心理学书籍，作者通过数十年对成功的研究，发现了思维模式的力量。她在书中表明，我们获得成功与否，并不是能力与天赋所决定的，更是受我们在追求目标过程中所展显的思维模式影响，本书介绍了两种思维模式：固定型和成长型，它们体现了应对成功与失败，成绩与挑战时的两种基本心态。\u003c/p>\u003cp>【A】优势，重点是“比较”，用于建立安全感。\u003c/p>\u003cp>作者卡罗尔•德韦克所通过20多年对成功者研究发现了成年长性思维的力量,和同类书籍相比这不是简单的理论和概念，他所揭示的成长性思维法则被很多具有发展眼光的父母，老师，教练，运动员和管理者运用，并在实践中得到了验证。\u003c/p>\u003cp>【B】利益，强调的是“你（学习者）”用于引发兴趣。\u003c/p>\u003cp>B1：这本书给学习者带来的好处。\u003c/p>\u003cp>怎样在达成一个目标后激情依然饱满，动力不减？怎样让孩子主动学习，面对困难不退缩，怎样让自己在人才济济的公司脱颖而出？通过本书的学习，你会了解到最根本的原因—思维方式的不同，也会更详细的知道到成长型思维方式是如何对我们的工作，孩子的教育，夫妻关系产生巨大的影响\u003c/p>\u003cp>B2：拆页片段给学习者带来的好处\u003c/p>\u003cp>通过这两个拆页的学习，你会了解到为什么面对同一个挫折，有的人一撅不正，有的人短暂的失落后依然激情满满，为什么有的孩子会因为一次考试失利而跳楼，为什么你认为孩子的能力可以通过学习提高，而你的孩子却说自己就是不行。\u003c/p>","ratings_count":1,"texts":[{"id":19726,"quote":"\u003cp>第一个片段;\u003c/p>\u003cp>\u003cstrong>[目标：设定学习目标。要求：可观察/可测量的行为或动作]\u003c/strong>\u003c/p>\u003cp>在跟随我完成第一个RIA现场学习后，学习者通过学习固定性思维和成长性思维在日常生活中不同的表现，能够在遇到不如意的事情时及时区分自己此时此刻是固定性思维，还是成长性思维。 \u003c/p>\u003cp>【过渡语】接下来，\u003c/p>\u003cp>下面请用2分钟的时间快速阅读这个片段。阅读完后请举手示意我。\u003c/p>\u003cp>片段有些长，大家可以重点看下我标注出来的内容。\u003c/p>\u003cp>【阅读原文】P8-P9\u003c/p>\u003cp>为了帮助你更好地理解这两种思维模式是如何工作的，请想象一下，尽可能生动地去想，你是一个年轻人，经历了非常帽糕的一天：\u003c/p>\u003cp>你去上一门对你来说很重要的课，而且你非常喜欢这门课，你的教授公布了期中考试成绩，你得了C+。你非常失望，等到晚上准备回家的时候，你发现自己的车上贴了一张违章停车罚单。你感到非常泄气，打电话给最好的朋友想要倾诉。但是却没有打通。\u003c/p>\u003cp>你会怎么想？你会有什么样的感受？你会怎么做？\u003c/p>\u003cp>当我问同定型思维模式者时，他们是这样对我说的：&quot;我感到被拒绝了。&quot;“我是个失败者。”“我是个傻瓜。”“我感到自己很没用，所有人都比我优秀。&quot;&quot;我太差劲了。&quot;\u003cu>换句话说，他们会把发生的事当作一个衡量自己的能力和价值的直接的标尺，他们会这样看待自己的生活：“我的人生太可悲了。“楼上的那个人不喜欢我。”“这个世界跟我过不去。”“有人想要毁掉我。&quot;&quot;没有人爱我，所有人都恨我。&quot;&quot;生活是不公平的，所有的努力都是白费。&quot;&quot;生活太糟糕了，我太傻了。&quot;&quot;我身上没发生过什么好事。”“我是地球上最不幸的人。”\u003c/u>\u003c/p>\u003cp>可这是什么生死攸关的大事或者毁灭性的大灾难吗？还是只是一个分数、一张罚单和一通不顾心的电话？\u003c/p>\u003cp>是这些人太自卑吗，还是说他们是实实在在的悲观主义者？不，其实这些无法应对困难的人同样感到自己有价值，他们同样乐观——觉得自己聪明而有吸引力，他们和那些有着成长型思维模式的人是一样的。但他们是如何应对这些烦心事的呢？&quot;我就不应该浪费这么多时间和特力去办一件事。&quot;（换句话说，不会再让任何人来评判我。）&quot;什么都不做。&quot;&quot;待在床上。&quot;&quot;去喝酒。&quot;&quot;吃东西。&quot;&quot;找机会冲别人大喊。&quot;&quot;吃巧克力。&quot;&quot;边听音乐边郁闷。&quot;&quot;躲到壁橱里坐着。&quot;&quot;&quot;找人打一架。&quot;&quot;哭。&quot; “摔东西。&quot;&quot;还能怎么办？ &quot;\u003c/p>\u003cp>还能怎么办！你\u003cu>知道，在模拟这个情景的时候，我特意将成绩写成了C+而不是F，只把考试设定成期中考试而不是期末考试，你的车只是被贴了罚单而不是被毁了，打电话给朋友倾诉之举只是没有成功。你并没有被朋友直接拒绝。没有什么灾难性或不可逆转的事情发生。但仅仅是在这些情况的影响下\u003c/u>，\u003cu>同定型思维模式者就已经产生了这种彻底的失败感和无力感。\u003c/u>\u003c/p>\u003cp>当我把这些情况原封不动地拿给那些成长型思维模式者看后，他们是这样说的：\u003c/p>\u003cp>“我会更努力地学习，下次停车的时候我要更加小心一些，不知道我的朋友是不是今天过得不开心.&quot;\u003c/p>\u003cp>&quot;C+这个成绩告诉我，我必须在课堂上加倍付出努力，我依然有半个学期的时间来提高我的成绩。&quot;\u003c/p>\u003cp>还有很多类似的回答，我想你们已经了解他们会说些什么了。那么，他们会如何应对呢？\u003c/p>\u003cp>“我必须开始考虑，为了下一次测验，我要更努力地学习（或者换个学习方法），我会缴清罚款，下次再给朋友打电话的时候，我们再好好聊聊。”\u003c/p>\u003cp>“我会总结我在期中考试到底犯了哪些错误，下一次要做得更好。我得把我的罚款交了，打电话告诉我的朋友，那天我心情很不好。”\u003c/p>\u003cp>“下一次考试的时候我要更加努力，和我的老师交流交流，下一次停车的时候要小心一些，或者去理论一下我没有违章，还要去弄清楚我的朋友到底怎么了。”\u003c/p>\u003cp>不是说你必须拥有某种思维模式，而拥有另一种思维模式的人就会产生挫败感。谁不是这样呢？糟糕的成绩、朋友或爱人的拒绝都不是什么开心的事，没有人会喜欢这些糟糕的事情。\u003cu>只是这些有着成长型思维模式的人不会给自己贴上标签，或对自己失去信心。即使他们感到沮丧，他们也准备好了去承担这个风险，直面挑战，继续为此奋斗。\u003c/u>\u003c/p>\u003cp>（还有30秒，看完了请举手示意我一下，……好，时间到，没有看完的小伙伴可以跟随我对这个片段讲解再继续来看。）\u003c/p>","explains":"\u003cp>\u003cstrong>要求：应用意译案例，不这么做的坏处，预防异议\u003c/strong>\u003c/p>\u003cp>【why】在有限的一生中，我们经常会遇到各种不如意的事情，孩子在学校表现不好请家长，工作中被领导批评，被顾客投诉，家庭里和爱人、父母因某事产生争执，因疫情被隔离…………成长型思维的人会积极面对，寻找解决的方法，固定型思维的人会表现出消极的态度，要么责怪他人，要么自我否定，情绪内耗。\u003cstrong>（通常做法）\u003c/strong>\u003c/p>\u003cp>如果长期不能觉察到你的种种反应与思维模式有关，那么你的各种能力如社交，沟通表达力，领导力，艺术细胞等等，都不能得到更大的进步，并且你的固定型思维的言语会影响孩子思维模式的发展\u003cstrong>。（坏处）\u003c/strong>\u003c/p>\u003cp>【预防异议】有的人会问，固定性思维就是消极心态吗？不，固定性思维的人同样觉得自己充满吸引力，成长性思维\u003cu>是基于相信我们的基本能力都能通过学习和努力获得并提高，\u003c/u>纵是每个人生来才能与智力，性情与才智都有所不同；那拥有成长型思维就可以像马云，董明珠，迪丽热巴等人一样获得金钱与荣誉吗？不是这样的，但至少你不会满足于目前的成绩，而且会不断的获取新的知识。\u003c/p>\u003cp>【what】这个片段通过一个日常生活中的小事体现了固定型思维和成长型思维对我们生活的影响，进而体现成长性思维的重要性。\u003c/p>\u003cp>思维是什么，是一种信念，看不见，摸不着，却会通过平时的行为表现出来，本书的作者将其称为思维，分为成长性和固定性。成长性思维就是基于相信我们的能力是可以通过学习和努力来获得并且提高的，在遇到挫折，不如意时，不会轻易的否定自己，不会给自己贴标签，有点像积极心态，但绝不局限于积极心态，在成功时，不会局限于现有的成绩，不会急于去证明自己，更注重于个人的成长。固定性思维则相反。\u003c/p>\u003cp>【\u003cstrong>反例\u003c/strong>】我有一个同事在12月初离职了，她觉得这里已经不适合她了，起因是她在两个月前被顾客连着投诉了三次，她觉得自己很倒霉，领导也不喜欢她，在这里体现不了自己的价值，结果目前还是待业在家，找不到工作。\u003c/p>\u003cp>她在这件事情上就受到了固定性思维的影响，她觉得是自己倒霉，能力不行，领导也\u003c/p>\u003cp>不喜欢她。\u003c/p>\u003cp>其实每个人都有固定型思维和成长型思维，那么怎样才能觉察自己此时此刻是受固定型思维还是成长型思维影响呢（过渡语）\u003c/p>\u003cp>【how】\u003c/p>\u003cp>1、觉察：我此时此刻在想什么，我的感受是什么，我要做什么\u003c/p>\u003cp>2、暂停：在大脑给自己安装一个暂停键，如一个很大很尖锐的声音，或者是好玩的“缤狗”等。\u003c/p>\u003cp>3、区分：事情发生时，如果你的大脑里想的是“都怪他”“他为什么要这样做”“真实一群猪”“气死我了”“我真是笨死了，我能力有限，我不做了”等责怪他人或者自我否定的话，那此刻你是陷入了固定性思维里；如果你在想“我能从这件事中学到什么”“下次怎么做会更好”“我怎么样做才能达到我想要的”，那么此刻你就是成长性思维。如果是固定型思维，告诉自己，这没什么大不了的，让我试着用成长型思维去看待问题，我能做些什么让事情朝着我想要的方向发展。\u003c/p>\u003cp>【\u003cstrong>正例\u003c/strong>】在去年，有一段时间我在工作中遇到了瓶颈期，起因是在每次和领导沟通客户的项目方案时，她就会愤怒的说一句，不要总推特价。其实我的本意不是这样的，我觉得自己被误解，情绪也非常的低落，我什么都不想做，就这样吧，我不推了（觉察）。经过好几天的消沉，突然我大脑有一个声音告诉我，你真的要这样下去吗（暂停）。我在责怪他人，原来我在用固定型思维看待这个问题（区分）。我问自己，我的目的是什么，是充实自己，是逐步提高自己的能力，那是不是我在和领导沟通时表达的方式有问题，我是不是可以换个方式。从此，每次沟通的结果都能朝着我想要的方向发展，而且我还在和领导沟通交流中学到了我自己没有考虑到的方面。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>这个方法可以用在工作、生活、育儿等各种你感觉倒霉透顶，埋怨他人，自我否定，情绪低落的时候。\u003c/p>","interaction":"\u003cp>A1激活经验\u003c/p>\u003cp>【要求：联系到过往具体经验】\u003c/p>\u003cp>【提问设计】\u003c/p>\u003cp>那么接下来，请大家回想一下，在过去的一个月内，在工作，生活，家庭中，发生了什么事情让你觉得这都是别人的错，都怪他，或者否定自己，我能力不行，我做不到等等\u003c/p>\u003cp>比如：客户的投诉，老板因工作没达到预期效果发火，孩子在学校被叫家长，和老公因某事而责怪他等等\u003c/p>\u003cp>请大家想一想你类似的经历。\u003c/p>\u003cp> 每人一分钟，在小组内分享或者写在便签上。4分钟之后我将邀请一位小伙伴来给大家进行分享。\u003c/p>\u003cp>那么谁来给大家分享一下呢？\u003c/p>\u003cp>【反馈设计】\u003c/p>\u003cp>谢谢小伙伴的分享！\u003c/p>\u003cp>在挫折时，暂时的情绪低落是正常的，重要的是有觉察情绪的认知。让我们用掌声来感谢一下小伙伴燕子！（号召鼓掌）\u003c/p>\u003cp>学习者案例记录（燕子）：开场前因儿子太吵，就告诉他如果不能保持安静，就会让爸爸带走他，结果就是孩子没有控制住，当打电话给他爸爸后，他不想离开就开始哭闹，那一刻觉得火冒三丈“你怎么这样让我丢脸”“我平时教你的都白教了”.\u003c/p>\u003cp>【A1+：要求：学习者加工出以后遇到同等情况如何做】\u003c/p>\u003cp>我想大家已经知道固定性思维和成长性思维对我们生活的影响，也通过以上的片段学会了如何及时辨别自己是受何种思维影响（觉察，暂停，区分）。\u003c/p>\u003cp>如果让你再回到刚才你回忆的事情上，你如何用觉察，暂停，区三步骤拉回自己的情绪。\u003c/p>\u003cp>（互动）……\u003c/p>\u003cp>还有吗？……\u003c/p>\u003cp>【反馈设计】\u003c/p>\u003cp>通过以上的分享我们就会发现，不同的观点会产生不同的生活方式，观点会对我们的生活方式产生重大的影响，它决定了我们是否能达到目标，是否能成为自己想成为的人，而这种观点正是思维模式带给我们的。（互动）\u003c/p>\u003cp>好，让我们用热烈的掌声感谢分享的小伙伴！（号召鼓掌）\u003c/p>\u003cp>【现场反馈】\u003c/p>\u003cp>以后再有类似的事情的话，我们就要学会使用觉察，暂停，区分这三步来及时改变自己的观点，逐步活成自己想要的样子\u003c/p>\u003cp>学习者案例记录（燕子）：\u003c/p>\u003cp>觉察：我觉得孩子哭闹让我丢脸了，我很生气，想让他马上闭嘴\u003c/p>\u003cp>暂停：转过去不要看到他的脸，深呼吸\u003c/p>\u003cp>区分：我此刻险入了固定性思维，我可以摸摸他的头，对他说：妈妈知道你想要留下来，我听到你的诉求啦。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":19727,"quote":"\u003cp>第二个RIA\u003c/p>\u003cp>\u003cstrong>目标：设定学习目标。要求：可观察/可测量的行为或动作\u003c/strong>\u003c/p>\u003cp>前后两个片段之间是递进的关系 \u003c/p>\u003cp>在跟随我完成第二个RIA现场学习后，学习者通过学习如何正确有效的穿递成长性思维，作为老师，父母，领导的我们能够在日常的生活中对学生，孩子，学员传达出成长性思维语言，使她们面对挫折时能够热爱挑战，迎难而上\u003c/p>\u003cp>\u003cstrong>目标：实用类图书、包含HOW的片段；内容不超过2页纸\u003c/strong>\u003c/p>\u003cp>请用1分钟时间快速阅读拆页二，阅读完毕后请举手示意我：\u003c/p>\u003cp>【R阅读原文】P260-P261\u003c/p>\u003cp>起初，我们很惊讶地发现，这么多拥有成长型思维模式的家长没能将思维模式传授给孩子。这件事告诉我们一个道理：父母、老师和教练如果想要传递成长型思维模式，并不是头脑里有成长型思维模式就够了，而是要通过行为体现——称赞学生的方法（告诉学生、这样的努力过程可以帮助他们学到知识），在学生遭遇挫折时的反应（认为失败是学习的好机会）以及是否重视对知识的深入理解等（认为这才是学习的最终目标）。\u003c/p>\u003cp>（还有30秒，看完了请举手示意我一下，……好，时间到，没有看完的小伙伴可以跟随我对这个片段讲解再继续来看。）\u003c/p>","explains":"\u003cp>【what】这个片段告诉我们如何通过三个方面有效的传递成长性思维\u003c/p>\u003cp>【why】\u003c/p>\u003cp>（通常做法）在孩子考了高分时我们是如何夸赞孩子的，“你太聪明啦”“你真是个天才”“你太棒啦”“你是妈妈的骄傲”“你很有天赋”等等，虽然你拥有成长性思维，但是你表达出来的确实固定性思维的语言（智力比努力更重要），难道不是要通过赞美鼓励孩子，让孩子知道：能力可以通过后天的努力学习得来吗？\u003c/p>\u003cp>（不那么做的坏处）长时以往的固定性思维的言语鼓励，孩子为了让他在大人的眼里看起来是聪明的，他们就不愿意接受更具有挑战性的任务，或者是在学习课程更难一点，需要投入更多精力和心思才能掌握时，孩子就会从心里觉得是自己太笨了，更没有动力和勇气去下功夫提升自己。\u003c/p>\u003cp>那么如何才能有效的传递出成长性思维，让孩子们有很强的逆商呢。可以从以下三个方面去做\u003c/p>\u003cp>【how】\u003cstrong>（细化步骤）\u003c/strong>\u003c/p>\u003cp>一、有效的赞美：成功时是塑造行为的关键时候，当孩子考了高分，获得奖励时，从努力的过程去赞美他，如：妈妈看的你为了迎接这次考试，你提前3个星期都在准备了，而且有清晰明确的计划，遇到不会的题你在吃饭时也在思考，妈妈为你的努力感到骄傲。\u003c/p>\u003cp>二、有效的鼓励：当孩子遇到挫折时，最重要的是做到情感的共鸣，因为情绪的对抗是交流的最大障碍，没有了情绪的对抗，你说的他才会听到心里去。\u003c/p>\u003cp>\u003cstrong>首先\u003c/strong>，说出他此时的感受，如：你为这次比赛付出了很多时间和精力，可是没有达到你预期的结果，所以你觉得很沮丧，是吗？ \u003c/p>\u003cp>\u003cstrong>其次\u003c/strong>:带着孩子做复盘。在这个过程中，你觉得那些方面做得比较好，那些还可以提升。注意在这个过程中不要做任何的评判和建议，你的任务就是引导孩子自己做复盘，你就是一个倾听者\u003c/p>\u003cp>\u003cstrong>最后\u003c/strong>：引导孩子做出学习计划。如:那对于你觉得做的不好的你想怎么做，或者需要我提供什么帮助，我都会全力支持你。\u003c/p>\u003cp>三、重视对知识的理解。如：孩子在背诵一首古诗时，鼓励孩子不仅要记住，还要理解作者这么写的意图等等。学会活学活用，而不仅仅是为了考试而学。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>可能有的小伙伴会说，天赋本来就很重要嘛，没有音乐天赋能做歌星吗，这一方法是建立在你相信思维模式是可以塑造的，能力是可以改变的。那还有小伙伴说，我和孩子不提学习是父慈子孝，一提学习是鸡飞狗跳，那我要提醒你哦，永远不要跳过孩子去看他后面的成绩，你要先看到孩子，再去看成绩，也就是说你需要更关注你的孩子，调整你们的亲子关系，至于如何处理好亲子关系，这是一个庞大的课题，在以后的拆书中我会有专题的分享。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>\u003cstrong>这个方法不仅适用于家庭教育，也适用于老师对学生，领导对下属，教练对学员，同事之间，朋友之间。\u003c/strong>\u003c/p>","interaction":"\u003cp>[A3]促动参与\u003c/p>\u003cp>要求：用知识点通过小组讨论形成方案，并现场分享。\u003c/p>\u003cp>【场景设计】\u003c/p>\u003cp>接下来是我们的练习时间了，希望通过这个场景练习，大家能够更好的传递成长性思维，能通过自己的言行影响他人，也是一件了不起的事情。\u003c/p>\u003cp>假设你是阳光中学的一名老师，你有一名学生，他家境贫寒，家里有三个兄弟姐妹，弟弟妹妹学习成绩非常好，经常获奖，父母经常向自豪的亲朋好友说弟弟妹妹学习有多好，人有多聪明，而他很少被提起，因此他非常痛苦，他学习也很刻苦，他希望用成绩证明自己，可是考试结果都是一般般，多次下来，他就觉得是自己太笨，不够聪明，那么努力都考不好。\u003c/p>\u003cp>那么你如何用今天所学到的（有效的赞美，鼓励，重视对知识的理解）帮助这个孩子，让他继续努力。\u003c/p>\u003cp>【小组讨论】\u003c/p>\u003cp>大家清楚练习的内容了吗？现在，请大家用8分钟时间，按照开场的分组，在小组内讨论，并且写在便签上。\u003c/p>\u003cp>随后我们邀请一个小组内的代表来阐述一下他们的内容。\u003c/p>\u003cp>开始：\u003c/p>\u003cp>（互动交流）……\u003c/p>\u003cp>时间到了，下面哪位小组代表来给我们分享一下你们的内容呢？\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>分享者杨雪：这个场景让我想起了我自己家的情况，我哥哥姐姐很努力，但是成绩一般，而我就是大人眼中别人家的孩子。如果我是老师，我会运用有效的鼓励：老师看到你平时学习很努力，也很刻苦，现在虽然没有明显的进步，但是没关系，千里之行始于足下，行动起来是最关键的，还有一个就是要注意学习的方式方法，随后老师也会分享一些好的方法给你，会帮助你的，继续努力，继续加油哦！\u003c/p>\u003cp>【设计反馈】\u003c/p>\u003cp>谢谢分享（邀请鼓掌）大家来鼓掌感谢我们小伙伴的分享！\u003c/p>\u003cp>希望大家以后可以多运用，也可以把这一技能传授给你身边有需要的朋友们。\u003c/p>\u003cp>【现场反馈】\u003c/p>\u003cp>在遇到挫折时，从情感上认同，逐步帮助其建立一种信念，努力不一定会成功，但努力一定会有所改变。\u003c/p>\u003cp>[A2]催化应用：\u003c/p>\u003cp>要求：包括情景或场景，学习者受启发联系到自己的具体应用场景\u003c/p>\u003cp>【场景设计】\u003c/p>\u003cp>通过前面的演练，相信大家已经熟悉了如何更好的传递成长性思维，\u003c/p>\u003cp>现在请我们来想一下，在近一个月内，你在家庭，工作中，经历过的他人成功或者失败失落的事情，\u003c/p>\u003cp>比如孩子学习进步得A，爱人完成了自己认为完不成的工作，同事完成了高难度的工作，或者孩子考级没过，好友考证差一分等等\u003c/p>\u003cp>【行动指令】\u003c/p>\u003cp>大家根据个人所遇到的事情，写出来，并且假如时光倒流，你会如何用今天所学习的有效传递成长性思维的方法（有效的赞美，有效的鼓励，重视对知识的理解）进行交流，请大家小组内进行讨论，并将其写在便签上，稍后我们来进行分享，时间5分钟。\u003c/p>\u003cp>【小组分享】\u003c/p>\u003cp>（视现场时间而定是否要进行公开的描述）\u003c/p>\u003cp>谁愿意主动来给大家分享一下呢。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>分享者小妖：刚才小组分享时杨雪就分享了她前段时间考公务员失利，只录取三人，而她刚好第四名，那段时间感觉抑郁了，心情非常糟糕，做什么都提不起精神。而她一个朋友也刚好经历了考试失利，但她朋友经过几天的失落就走出来了，现在的状态完全和她不同，朋友分享了一个情景疗愈法帮助她走了出来。这就是一个典型的有效的鼓励，从情感了有了认同，还分享了有效的方法。\u003c/p>\u003cp>【反馈设计】\u003c/p>\u003cp>非常好，赞美从细节出发，鼓励前先情感共鸣。\u003c/p>\u003cp>大家掌声鼓励！再次感谢！（掌声）\u003c/p>\u003cp>【现场反馈】\u003c/p>\u003cp>改变是从相信可以改变开始，从现在开始，改变自己的表达方式，影响他人的思维模式\u003c/p>\u003cp>【结语】\u003c/p>\u003cp>目标：强有力的结语，要求：简短，呼应\u003c/p>\u003cp>今天我们的两个拆页的内容全部结束。\u003c/p>\u003cp>让我们来回想一下，当我们遇到挫折，不如意时，我们会有不同的表现。\u003c/p>\u003cp>第一个片段通过一件考试失利这件事展现了成长性思维和固定性思维在生活中的体现，从而学会及时区分是受成长性思维和固定性思维影响，第二个片段告诉我们如何有效的传递成长性思维。这两个片段是递进的关系，可以单独使用，也可以一起用。希望通过今天的学习，大家都有所收获，即使是一句话，一个故事对你的启发，也能更好的在生活中运用到，拆书就是拆为己用，用来解决生活工作中所遇到的问题。\u003c/p>\u003cp>以上是今天的全部内容，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1682153766000,"updated_at":1682483076000,"ria":true},{"id":15425,"topic":"如何用成长型思维模式进行表扬","learn_goal":"","remark":"《终身成长》介绍了两种思维模式：固定型与成长型，它们体现了应对成功与失败、成绩与挑战时的两种基本心态。你认为才智和努力哪个重要，能力能否通过努力改变，决定了你是会满足于既有成果还是会积极探索新知。只有用正确的思维模式看待问题，才能更好地达成人生和职业目标。通过今日的线下分享，我们一起来学习：如何用成长型思维进行表扬！","level":"TF3-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"紫珺","city":"深圳市"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"\u003cp>各位伙伴，大家晚上好！我是拆书家周周，欢迎大家来到今天的拆书现场!\u003c/p>\u003cp>\u003cstrong>技能点：【图书介绍：学习者场景法介绍图书，包括四个步骤：事件场景-提问-影响-解决】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>事件场景\u003c/strong>：\u003c/p>\u003cp>最近我的同事小李报考了人力资源证书，考了两次都没有通过，心情非常沮丧。如果他认为是自己努力不够，就会继续努力，调整方式方法，直到考试通过，这是成长型思维。如果认为是能力不够，他就不想再继续了，因为能力不行，努力也没有用，选择放弃，这是固定型思维。\u003c/p>\u003cp>今天基于我自己要解决的问题，这里给大家分享如何用成长型思维给孩子进行表扬。最近我女儿每天都认真的写作业，仔细的检查，同时还会做课前的预习跟课后复习。还每天坚持的学习打卡。我还记得，有一次她都有点儿不舒服，但还是依然坚持把卡打完之后才去睡觉，这次数学测试考了100分，比之前进步了15分。我说到：宝贝，你真棒！真聪明！除了说这些，当时我一下子不知道怎么表扬她。\u003c/p>\u003cp>\u003cstrong>提问：想\u003c/strong>请问一下现场的伙伴，你们之前有遇到过类似的情况吗？\u003c/p>\u003cp>提问：那当你遇到孩子取得好成绩跟你分享时，你会怎么跟她沟通呢？\u003c/p>\u003cp>提问：你们沟通完之后，他们的反应是怎样的？\u003c/p>\u003cp>提问：如果你经常用：你真棒！你真聪明！来进行表扬，会产生怎样的影响？\u003c/p>\u003cp>\u003cstrong>影响\u003c/strong>：\u003c/p>\u003cp>如果我们经常这样去表扬，说：宝贝你太牛了，你太厉害了，你看你都考100分，妈妈给你点赞！\u003c/p>\u003cp>那如果孩子下次没有考到100分，他就会表现的很沮丧，很难过，他内心里面会有一种很强的挫败感。\u003c/p>\u003cp>这样的表扬让孩子形成一种认知：我就是很棒，很聪明！我要保持住，失败意味着我很愚蠢，这样的认知让他们失去学习动力和表现力，形成对自己的固定思维模式。最重要的是孩子无法知道自己到底怎么做才能做好？\u003c/p>\u003cp>\u003cstrong>解决：\u003c/strong>遇到类似的情况，我们该怎样正确的表扬呢？\u003c/p>\u003cp>今天我们要拆的这本《终身成长》，通过大量的案例介绍了两种思维模式：固定型思维和成长型思维，以及两种思维所带来的不一样的人生，我们家长学习后，不断地练习就能将固定型思维转变成成长型思维，用成长型思维表扬孩子，孩子更愿意面对困难、挑战，也能拥有积极向上的态度，不断突破自己。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>：\u003c/p>\u003cp>通过今天的学习，大家能掌握成长型思维模式来进行表扬的方法，在遇到有需要表扬来肯定的场景时，能运用成长型思维模式进行表扬。\u003c/p>\u003cp>我们今天的学习过程中有分组练习，所以我们先进行一下分组，这边两位为第一组，这边为第二组，后面两位为第三组，剩下的第四组。\u003c/p>\u003cp>\u003cstrong>技能点：【把知识改编为量表自测题】\u003c/strong>\u003c/p>\u003cp>在开始之前，我给大家设计了一个自测题，来看看大家对表扬孩子的概念处在一个什么模式里。下面请花1分钟时间根据自己的情况快速做一下。1代表完全不符合，6代表非常符合。请仔细阅读下面表格中的每一句话，根据自己的实际情况为自己打分(1代表完全不符合，6表示非常符合)，并在完成后核算一下总分。\u003c/p>\u003cp>\u003cstrong>题目评分\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【解释一下刚才量表自测题的意义】\u003c/strong>\u003c/p>\u003cp>好的，咱们一起来看看自测结果：\u003c/p>\u003cp>请问有没有小伙伴的得分在25分以上？恭喜你，在表扬孩子方面，你是一位成长型思维的家长，孩子也更愿意接受挑战。\u003c/p>\u003cp>15-25分的伙伴请举一下手，你在某些方面表扬孩子表现出成长型思维，某些方面是固定型思维。\u003c/p>\u003cp>最后，请问有没有和我一样15分以下的？那你们真是太幸运了，今天的分享就是为你们准备的。我也是有这方面的困惑，才来学习和分享这个方法。\u003c/p>\u003cp>希望今天的学习中，你们能够掌握三个步骤来学会用成长型思维表扬孩子。让孩子相信通过学习可以成长，他也收获成长型思维。\u003c/p>\u003cp>在这里给大家说明一下：\u003c/p>\u003cp>大家不要因今天的测试，或某一方面是固定型思维或成长型思维，也就认定自己是某一种思维模式，比如有人会认为学习成绩可以通过学习提升，认为性格是不变的，那么在学习方面的认知。他是成长型思维。在性格方面的认知，就是固定型思维。所以，我们每个人都同时拥有两种思维模式。成长型和固定性思维，只是表现得方面不一样而已，今天的测试也并不代表永远不变，他也可以通过学习而改变的。\u003c/p>\u003cp>请大家花1分钟时间阅读一下原文片段：阅读完的伙伴可以抬头示意一下。谢谢！\u003c/p>","ratings_count":6,"texts":[{"id":19483,"quote":"\u003cp>\u003cstrong>能点：【原书拆页R为Why或者What的内容,或原书的一个完整的案例】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>原文拆页：\u003c/strong> \u003c/p>\u003cp>原文片段P 215\u003c/p>\u003cp>父母们认为，通过表扬孩子的头脑和天赋－－他们可以给予孩子们持久的自信心－－就像送给孩子一份礼物一样，但事实上这行不通，还起了反效果。这种做法会让孩子在遇到困难，或者任何事出现问题的时候，立即对自己产生怀疑。如果父母真想送给孩子一份礼物，最好的就是教会他们热爱挑战，从错误中吸取教训，享受过程的努力的过程，不断学习，只有这样，孩子们才不会成为赞扬的奴隶。他们将拥有一种可以建立和修复自信心的终生有效的方法。\u003c/p>\u003cp>\u003cstrong>传递注重过程和成长的信息\u003c/strong>\u003c/p>\u003cp>所以，什么样的做法可以替代我们对才能和智力的赞扬呢？戴维对我那番安抚的话给了我们一些启示。我的一位学生则在这方面给了我们更多的信息：\u003c/p>\u003cp>这周末我回到家，发现我12岁的妹妹因为在学校里发生的一些事异常开心。我问他到底为什么如此兴奋，他告诉我说：＂我在社会学考试中得了102分！＂这句话她在那个周末至少重复了五遍。那时候，我决定将课上学到的内容付诸实现，我没有表扬她的智力和她获得的成绩，而是问了她一些问题，这些问题会让她回想起自己付出了多少努力学习，而且这一年中她取得了多大的进步。去年，她的成绩不断下滑，所以我认为在今年刚开始的这个时候，我有必要在此时出面，指引她走往正确的方向。\u003c/p>\u003cp>（拆页结束~）\u003c/p>","explains":"\u003cp>\u003cstrong>能点：【I讲解引导时，拆书家有进行简短互动，精准控场，还要举例子】\u003c/strong>\u003c/p>\u003cp>好的，大家都看完了拆页。\u003c/p>\u003cp>（简短互动）\u003c/p>\u003cp>\u003cstrong>What\u003c/strong>\u003c/p>\u003cp>在场的小伙伴以前有没有在表扬孩子的时候说过＂你真棒！＂＂你真聪明＂，给你点赞，你学得真快＂类似的表扬的话呢？ \u003c/p>\u003cp>回答：有！\u003c/p>\u003cp>从原文拆页片段的描述来看，原文认为我们这样做是否合理呢？\u003c/p>\u003cp>回答：不太合理！\u003c/p>\u003cp>那原文片段建议我们从哪些方面去表扬孩子呢？\u003c/p>\u003cp>\u003cstrong>＂努力过程＂和＂成长的信息＂\u003c/strong>\u003c/p>\u003cp>看来大家对原文的理解比较到位了，努力过程和成长的信息，确实是成长型思维想表达的点。\u003c/p>\u003cp>＂你真棒＂＂真聪明＂＂你学得真快＂，类似的表扬听起来像是鼓励、帮助孩子增加自信心的信息，实际上孩子从这些话里听到的信息可能是：\u003c/p>\u003cp> 如果我学得不那么快我就不聪明了，\u003c/p>\u003cp>我以后不应该尝试太难的事情，不然他们不会夸我了。\u003c/p>\u003cp>\u003cstrong>Why\u003c/strong>\u003c/p>\u003cp>孩子们都喜欢被表扬，他们尤其喜欢别人表扬自己的智力和天赋，这种称赞确实能给给他们带来特别的喜悦感，但这种感觉只能维持很短的时间，一旦遇到困难，他们的自信心就会消失，积极性也会跌到谷底，如果成功意味着他们很聪明，那么失败则意味着他们很愚蠢。这就是固定型思维模式表扬带给他们的影响。\u003c/p>\u003cp>那我们如何用成长型思维表扬孩子呢？\u003c/p>\u003cp>让孩子认为自己的能力是可以提高的，产生学习的欲望，因此会勇于迎接挑战，重视努力的过程，获得成长。以下是拆页提练出的成长型思维模式表扬孩子的步骤。\u003c/p>\u003cp>【How步骤】：\u003c/p>\u003cp>原文中：我没有表扬她的智力和她获得的成绩，而是问了她一些问题，从而可以得出我们的第一步：\u003c/p>\u003cp>\u003cstrong>第一步：了解事实或互动；\u003c/strong>\u003c/p>\u003cp>培养成长型思维最好的方法，不是看事后结果，而是在孩子完成任务的过程中与孩子互动。\u003c/p>\u003cp>如果我们没有参与到孩子的任务过程中，我们也可以通过提问、观察，了解孩子在完成任务的过程中间使用了什么有趣的策略或方法，他是怎么想到的？遇到了什么困难或挑战？发生了什么？\u003c/p>\u003cp>之前我分享的，我女儿数学考100分的场景，假如下次有类似的事情发生的话，我会用成长型思维模式来表扬她，我会这么做：\u003c/p>\u003cp>我会问：宝贝，你这次数学考了100分，你平时是怎样学习的呀？\u003c/p>\u003cp>她会说：认真写作业，做练习/预习复习打卡等。。\u003c/p>\u003cp>原文中：这些问题会让她回想起自己付出了多少努力学习，从而引导出她努力的过程进行表扬。\u003c/p>\u003cp>\u003cstrong>第二步：表扬努力的过程\u003c/strong>：\u003c/p>\u003cp>比如努力的过程，是否尝试新的策略，利用资源，用一个词概括他的卓越品质.......\u003c/p>\u003cp>我会说：＂宝贝，你每天认真的写作业，仔细的检查，同时还会做课前的预习跟课后复习。还每天坚持的学习打卡，我觉得你是一个很努力的人。＂\u003c/p>\u003cp>原文中：而且这一年中她取得了多大的进步。去年，她的成绩不断下滑。所以我得出第三步。\u003c/p>\u003cp> \u003cstrong>第三步：表扬成长：\u003c/strong>\u003c/p>\u003cp>现在和以前比，有成长的具体的细节或内容。\u003c/p>\u003cp>我会说：“宝贝，看到你的数学考了100分，比之前进步了15分，和你每天认真学习和坚持打卡是分不开的，进步很大，妈妈觉得你很有毅力。”\u003c/p>\u003cp>\u003cstrong>预防异议\u003c/strong>\u003c/p>\u003cp>可能有的家长会说：＂我夸孩子的努力，但是没有用！＂\u003c/p>\u003cp>那我也想问问您的孩子真的很努力吗？我们永远不要认为孩子并没有真正付出努力，而我们去称赞他的努力过程，就会带来积极的结果。\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>\u003c/p>\u003cp>当日常生活中，遇到孩子值得表扬的事件时，比如帮叔叔阿姨按了电梯呀，或者打了招呼，我们可以不用第一步了解事实或者互动，直接用第二步和第三步。在日常工作或者生活中，孩子/夫妻/团队同事，表现好需要进行表扬的时候，都可以使用这个方法进行表扬！\u003c/p>","interaction":"\u003cp>\u003cstrong>技能点：【A3给出一个非常具体，确定的场景，学习者可在此场景中演练或讨论或应用新学技能】\u003c/strong>\u003c/p>\u003cp>为了大家能更好的理解和掌握成长型思维进行表扬3步骤，我们一起来进行一个场景演练。请仔细听我的场景和指令：\u003c/p>\u003cp>【给出具体场景】\u003c/p>\u003cp>小明今年10岁，期末考试，英语考了98分，比她预期的分数要高，回家后她说：“真不敢相信我的英语考了98分，比去年进步了10分”，妈妈观察到她为了提升英语成绩，付出了很多努力，调整了学习方法，英语口语也提升了很多。\u003c/p>\u003cp>【现场演练】\u003c/p>\u003cp>\u003cstrong>指令\u003c/strong>：1、先请大家在小组内花3分钟讨论一下，请大家参考我刚刚的步骤和话术来进行讨论，可以边讨论边写出表扬的步骤。\u003c/p>\u003cp>2、再根据我们刚才的分组，一个人代表妈妈，一个人代表小明，妈妈用今天学习到的成长型思维表扬小明，请大家进行对话演练，待会我请一组伙伴来分享一下。\u003c/p>\u003cp>给大家5分钟，稍后我会请一组小伙伴上来和大家分享。\u003c/p>\u003cp>（大家讨论的过程中，给学习者做一些引导和互动）\u003c/p>\u003cp>好的，哪组小伙伴愿意来进行分享呢？邀请我们第三组伙伴。\u003c/p>\u003cp>【学习者分享】\u003c/p>\u003cp>记录学习者分享的内容：（分享的对话）\u003c/p>\u003cp>小明（王宇）：妈妈，你看我期末考试英语考了98分\u003c/p>\u003cp>妈妈（李霞）： 宝贝，妈妈看到你考了98分，妈妈为你感到高兴！很不错哦！\u003c/p>\u003cp>小明：我觉得我在很多方面都做了很多改进\u003c/p>\u003cp>妈妈：妈妈很好奇，在这么短的时间内，做了什么提高了成绩？\u003c/p>\u003cp>小明：我上课愿意积极举手回答问题了，自己做了一个错题本，会记录出错的原因和下次改进的方法。之前觉得英语作业好难，一些单词和词汇需要记很久才记得住，经过和妈妈一起找方法，做了单词卡片 ，容易多了，英语进步了很多。谢谢妈妈！\u003c/p>\u003cp>妈妈：妈妈觉得你通过自己的努力，在短时间内英语成绩提高了10分，觉得你很有方法！\u003c/p>\u003cp>小明：谢谢妈妈，我们去吃麦当劳。\u003c/p>\u003cp>\u003cstrong>拆书家反馈：\u003c/strong>\u003c/p>\u003cp>好的，谢谢两位伙伴的精彩分享，他们的对话中有运用到今天学习到的运用成长型思维表扬他人！第一步 有了解事实和互动，了解进步的情况，第二步表扬努力的过程，通过很多方法提升了成绩，第三部表扬成长，在短时间内成绩提升了10分。\u003c/p>\u003cp>再一次掌声送给我们的分享者。\u003c/p>\u003cp>\u003cstrong>技能点：【A2学习者可以根据指令，写出自己未来的一个具体的要做的应用，比如：某个特定任务、和人分享、事后复盘或找人陪练】\u003c/strong>\u003c/p>\u003cp>【A2催化应用】\u003c/p>\u003cp>A2：我的应用 【布置作业——找人分享】\u003c/p>\u003cp>今天的分享已经进入尾声了，但是我们的实践才刚刚开始哦！现在我给大家布置一个作业：找人分享：\u003c/p>\u003cp>今天学习用成长型思维三步骤表扬孩子这个方法后，你要分享给谁？什么时间分享？你会怎样分享？\u003c/p>\u003cp>请大家花一分钟时间将内容写在书稿空白处，我会请1-2位伙伴来分享，谢谢！\u003c/p>\u003cp>写完的伙伴举手示意一下，哪位伙伴先来分享一下？\u003c/p>\u003cp>毅哥举手了，学习完之后将分享给老婆。\u003c/p>\u003cp>毅哥：今天晚上回家后，11点给老婆分享今天学习到的方法，\u003c/p>\u003cp>毅哥：老婆，我今天学习到了一个用成长型思维模式表扬孩子的方法，我分享给你\u003c/p>\u003cp>老婆：好呀，是什么方法，和我说说\u003c/p>\u003cp>毅哥：当你孩子很努力，你想要表扬孩子的时候，可以用这个方法：\u003c/p>\u003cp>第一步了解事实和互动，他那里表现好，要表扬他哪方面。\u003c/p>\u003cp>第二步表扬努力的过程，通过哪些细节/哪些过程和付出，表扬过程。\u003c/p>\u003cp>第三步表扬成长，现在与之前比较，通过努力进步了多少。\u003c/p>\u003cp>老婆：这个方法不错，简单实用。\u003c/p>\u003cp>毅哥：是的，我们今天可以用这个方法与孩子进行一次互动。\u003c/p>\u003cp>今天大家把方法学习到了，可以用于对自己小孩的表扬。\u003c/p>\u003cp>也谢谢毅哥分享！将今日所学进行运用到实际生活中。后续有伙伴找人分享的，也可以发信息分享给我，谢谢！\u003c/p>\u003cp>\u003cstrong>结束语：\u003c/strong>\u003c/p>\u003cp>今天我分享的拆页就讲解到这里，希望今天的拆页分享对大家有所帮助。我是爱分享的拆书家周周，再次感谢大家的聆听！\u003c/p>\u003cp>拆书活动结束后，学习者毅哥进行了分享，给我发了微信，有进行分享给家人，并实际去运用。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1679758522000,"updated_at":1687358958000,"ria":true},{"id":14430,"topic":"面对挫折三步法","learn_goal":"","remark":"当孩子遇到挫折和失败时，怎样引导才能更好的帮助他们走出低迷情绪，重新找到实现目标的方法？《终身成长》一书中的成长型思维给了我们非常好的方法。","level":"TF3-1","duration":25,"status":30,"type":0,"chaishujia":{"username":"windy琴","city":"长沙市"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003cp>\u003cstrong>【开场：3分钟】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【自我介绍+分组】\u003c/strong> \u003c/p>\u003cp>大家好，我是刘琴，大家可以叫我琴子，拆解的级别是3-1。三个标签介绍自己：\u003c/p>\u003cp>①成长赋能师\u003c/p>\u003cp>②二级拆书家\u003c/p>\u003cp>③准二胎宝妈\u003c/p>\u003cp>为了更好的进行学习，现场采用两两分组的形式开展后续的讨论。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>今晚的拆书的学习目标就是：在未来当孩子或亲朋好友遇到挫折时（界定），大家能够掌握(行为）“成长型思维面对挫折三步法（澄清）”这个工具，去帮助其走出低迷情绪，找到解决问题的方法。\u003c/p>\u003cp>\u003cstrong>【场景法介绍图书】\u003c/strong>\u003c/p>\u003cp>【场景】前段时间我小孩的班级进行读绘本比赛，我崽也报名参与了，因此那段时间经常要我陪他读绘本。他在学校比赛那天，讲完了绘本，并没有获得大红花。因此晚上我下班刚进家门，我崽就跑过来抱着我的大腿说：妈妈，今天讲故事，老师只给我发了一颗糖果，但是我的好朋友不仅有糖果，还得到了大红花，我以后不想讲故事给他们听了。 我当时因为手里还提着电脑饭盒啥的，随口就说：不会呀，老师跟我说你表现很不错，还给你发了糖果呢。 但我发现我讲完之后，我儿子并没有因此而好转，反而更加的沮丧了。\u003c/p>\u003cp>【提问】大家有没有遇到过类似的情况，当小孩遇到挫折，来找你倾诉的时候，你是否也跟我一样说一句“没事，你已经做的很好了”“一点小事而已，不要在意”就过去了呢？那效果如何？ \u003c/p>\u003cp>【影响】诚然，我们的出发点是不想打击孩子信心，但发现没有：这些看似对孩子的鼓励言语，不仅没有安慰到他们，可能还会影响到他们的表达欲，更严重的可能造成小孩以后遇到事都不想跟你说。\u003c/p>\u003cp>【解决】如何才能更好的处理和应对这种情况，帮助孩子们找到更好的方法呢？《终身成长》一书中倡导的用“成长型思维看待问题”就能很好的解决这一问题。\u003c/p>\u003cp>《终身成长》是一本被认为“颠覆传统成功学观点，影响美国校园教育的创新理念”的巨著。书中介绍了两种思维模式：固定型与成长型，它们体现了应对成功与失败、成绩与挑战时的两种截然不同的心态。我今天拆解的片段也来源此书，主要讲应该如何运用成长型思维去面对挫折或失败。\u003c/p>","ratings_count":2,"texts":[{"id":18443,"quote":"\u003cp>\u003cstrong>【R】原文片段\u003c/strong> \u003cstrong>（1分钟）\u003c/strong>\u003c/p>\u003cp>接下来，请大家花1分钟的时间阅读原文内容，阅读完了可以抬头或者眼神示意我一下：\u003c/p>\u003cp>\u003cstrong>片段来源：《终身成长》P219-220\u003c/strong>\u003c/p>\u003cp>九岁的伊丽莎白第一次参加了体操运动会。她身材修长，柔韧性好，充满活力、非常适合练体操，她自己也非常热爱体操。当然，她对参加比赛有一点紧张，但是她的水平很高，并且对自己的表现很自信。她甚至已经想好要将她贏得的彩带挂在家里的哪个位置。\u003c/p>\u003cp>在第一个项目自由体操中，伊丽莎白第一个登场。尽管她表现得很不错，但在后来几个女孩出场之后，得分出现了变化，伊丽莎白输掉了比赛。在其他项目中，伊丽莎白同样表现得很好，但是依然没能贏得比赛。那天晚上比赛结束时，她一条彩带也没能得到，她感到很沮丧。\u003c/p>\u003cp>如果你是伊丽莎白的父母，你会怎么做？\u003c/p>\u003cp>1．告诉伊丽莎白，你认为她是最棒的。\u003c/p>\u003cp>2．告诉她是裁判的不公平让她丢掉了原本属于她的彩带。\u003c/p>\u003cp>3．安慰她说体操其实没那么重要。\u003c/p>\u003cp>4．告诉她她有足够的能力，下一次肯定能赢。\u003c/p>\u003cp>5．告诉她她本来就不该赢。\u003c/p>\u003cp>在当今社会中，对于如何增强孩子的自信心，存在着一种强有力的信息，这种信息的一个重要内容就是：保护孩子们免遭失败！但是这种做法或许能够暂时防止孩子们失望，但是从长远来看，却有着很大的危害。为什么这么说呢？\u003c/p>\u003cp>让我们从\u003cstrong>思维模式\u003c/strong>的角度看看对刚才五句话的五种可能的反应，倾听其中传达的信息：\u003c/p>\u003cp>第一种（你认为她是最棒的）：这种说法从根本上说并不是真心的。她并不是最好的——你知道这一点，她自己也清楚这一点，这对于她的恢复和进步一点帮助都没有。\u003c/p>\u003cp>第二种（她受到不公平待遇）：这是责备他人的做法。当事实的真相是，问题的根本在她的表现而不在裁判时，难道你希望她以后变成喜欢将自己的不足归咎于他人的人吗？\u003c/p>\u003cp>第三种（安慰她体操其实没那么重要）：这种说法会教给她，当她有什么事做不好时，贬低这些事情本身就对了。难道你真想告诉她这些吗？\u003c/p>\u003cp>第四种（她有能力）：这可能是所有信息里最危险的一个。难道是能力自动带领你走向成功的吗？如果是这样，伊丽莎白这次没能赢，为什么下一次就能赢呢？\u003c/p>\u003cp>第五种（告诉她她本来就不该贏）在这种情况下说这样的话的确有些无情。当然，你可以不用这么直白的方式表达，不过伊丽莎白具有\u003cstrong>成长型思维模式\u003c/strong>的父亲基本上就对她表达了这个意思。\u003c/p>\u003cp>下面是她父亲的原话：“伊丽莎白，\u003cstrong>我知道你的感受\u003c/strong>。你对比赛寄予了如此大的希望，而且\u003cstrong>拿出了自己最好的表现，\u003c/strong>但是依然没能贏你一定感到很失望。但是你要知道，你并\u003cstrong>没有付出100％的努力。\u003c/strong>有很多女孩\u003cstrong>练习体操的时间都比你长，\u003c/strong>而且\u003cstrong>比你更努力。\u003c/strong>如果这是你真心想要的东西，那么你就要全身心地为此付出努力。”\u003c/p>\u003cp>他同样告诉伊丽莎白，\u003cstrong>如果她只是想拿体操当个乐趣，那也没有问题。但如果她想在比赛中有所成就，那么就必须付出更多。\u003c/strong>\u003c/p>","explains":"\u003cp>\u003cstrong>【I】拆书家讲解引导（8分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【WHAT】\u003c/strong>\u003c/p>\u003cp>该片段主要通过一个案例来阐述如何通过成长型思维引导孩子走出失败或挫折带来的沮丧情绪，找到方法实现目标。那在具体讨论前，我们先了解究竟什么是成长型思维。\u003c/p>\u003cp>【备注：终身成长核心两个思维：成长型和固定型。今天由于是练级场时间关系的问题，我主要给大家分享成长型思维】《终身成长》这本书给出的定义是：成长型思维的人相信能力不是一层不变的，是可以通过后天的学习和训练获取。因此具备成长型思维的人乐于接受挑战、看重努力的过程。他们能正确看待学习、生活、工作中的成败得失。\u003c/p>\u003cp>（预防异议）有没有人听完这个概念的解释后仍然一脸懵？觉得不够清晰明了：嗯，你说的有道理，但说了等于没说，我还是不知道什么是成长型思维。那为了让大家更好的理解这个概念，更具象化一些去解读成长型思维的话：就是具有成长型思维的人，\u003cstrong>首先\u003c/strong>TA能够\u003cstrong>承认现实\u003c/strong>，也就是不逃避；\u003cstrong>其次\u003c/strong>就是能\u003cstrong>有效内归因\u003c/strong>，要对内归因，也就是不要找借口；\u003cstrong>最重要的一点\u003c/strong>就是\u003cstrong>找出问题的解决方案\u003c/strong>。三个要素缺一不可。\u003c/p>\u003cp>接下来我通过一个场景，四种不同心态的案例来帮助大家进行成长型思维概念的理解：\u003c/p>\u003cp>【场景】：作为家长，安慰小孩“期末考试数学只考了80分”的四种引导沟通情况\u003c/p>\u003cp>心态1：儿子，虽然数学只考了80分，但你的语文考了98分呀，很好了。（这种心态显然不是成长型思维的，虽然符合成长性思维的要素一：承认现实，但不符合要素二、三）\u003c/p>\u003cp>心态2：儿子，这次数学考试只考了80分，但不能完全怪你，考试前感冒了，考试没发挥好也很正常，下次好好考就行了。（这也不是成长型思维，虽然有要素一、二，但是在要素二的时候，他有归因，但并没有对内归因，更多是在找借口，逃避问题。）\u003c/p>\u003cp>心态3：儿子，这次数学只考了80分。你们数学老师把你的试卷发给我看了，发了有很多地方是你审题不认真，计算书写不细致导致的失误，这是很不应该的哦。（这也不是成长型思维，有要素一二，但是缺乏要素三）\u003c/p>\u003cp>心态4：儿子，虽然分数不能决定什么，但分数也是你对知识掌握情况的一个具体反馈。这次数学只有80分，说明你对于书本知识的掌握是不全面的，存在知识盲区，我们需要想办法攻克掉。今年寒假，我们一起把知识系统梳理一遍，把不懂的全部理解透彻。（这种心态是成长型思维，符合三大核心要素。）\u003c/p>\u003cp>相信通过这四种心态的对比，大家对成长型思维已经有一个比较清晰和具象化的理解。\u003c/p>\u003cp>\u003cstrong>【WHY】\u003c/strong>\u003c/p>\u003cp> 现在的家长都希望自己孩子具备成长型思维。尤其是当下的孩子们，他们没有经历过生活和环境的压迫，有的时候很难接受自己的不足或失败，而做出一些难以挽回的行为。因此拥有一个“胜不骄败不馁”的孩子是家长们的共同愿望。 但如何通过成长型思维去引导孩子，既讲究契机，也讲究方法。 最佳的契机之一就是在孩子遇到挫折或失败的时候。原文案例的父亲就给我们做了一个很好的示范。\u003c/p>\u003cp>\u003cstrong>【引出HOW】\u003c/strong>\u003c/p>\u003cp>从他的表达中，我们可以提炼出三个关键性动作：\u003c/p>\u003cp>\u003cstrong>第1步：安抚情绪、直面结果。\u003c/strong>这一步需要父母具备比较强的共情能力，以及直面结果的勇气。只有理解孩子，才能获得他的注意力，这样才能为后面的沟通打下基础。（我知道你的感受，输了比赛你一定很难过。）\u003c/p>\u003cp>\u003cstrong>第2步：肯定过程、分析原因。\u003c/strong>这一步很重要。肯定孩子付出的努力，表扬他的一些好的品质，孩子才有代入感。而分析原因中，要抓住他与别人的差异点是什么，这样才有说服感。（拿出了自己最好的表现；没有付出100％的努力……时间比你长，比你更努力）\u003c/p>\u003cp>\u003cstrong>第3步：提出建议、引导行动。\u003c/strong>注意，这一步非常关键的一点。你一定要带领孩子进入对问题的思考：你怎么看待这个事情的？引导他思考解决方案。在这样过程中慢慢培养TA的成长型思维。（当个乐趣，还是想在比赛中有所成就；全身心地为此付出努力）\u003c/p>\u003cp>\u003cstrong>【反例变正例】\u003c/strong>\u003c/p>\u003cp>大家还记得我开场时候说的那个案例吗？我崽参加读绘本比赛只得了一颗糖果，找我倾诉的时候，我很敷衍的回答。 如果再来一次，我会这样跟他说：\u003c/p>\u003cp>“今天读绘本比赛，你只得了一颗糖果，很不开心是吗？” \u003cstrong>这是安抚情绪、直面结果。\u003c/strong>\u003c/p>\u003cp>“为了这个比赛，每天都有练习。妈妈觉得你为了目标而努力的样子真的值得表扬哦。……你在练习绘本的半个月时间中，妈妈记得你有四次是读到一半就去玩新买的玩具了……”\u003cstrong>这是肯定过程、分析原因。\u003c/strong>\u003c/p>\u003cp>“那崽崽，读绘本比赛活动，你是觉得参加表演就行了呢？还是要取得好的成绩？” \u003cstrong>这是提出建议、引导行动。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【WHERE】\u003c/strong>\u003c/p>\u003cp>通过我们不断的探讨，我们发现这个方法不仅仅适用于亲子教育当中。还适用于成人的相处中，当你的朋友，同事，甚至家人在面对挫折所带来的不好结果时，也可以采用这个方法去引导（可能不适合你的领导）。甚至当我们自己遭遇挫折时，也同样可以使用此方法进行自我修正和调整。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A2】催化学习者应用 （7分钟）\u003c/strong>\u003c/p>\u003cp>好的，学以致用是我们拆书法的核心理念。\u003c/p>\u003cp>接下来：就是实践“面对挫折的3步法”。现编一个小剧本（大家写摘要就行了哦）。\u003c/p>\u003cp>有以下3点要求：\u003c/p>\u003cp>1. 剧本包括场景设置、人物设置，人物的动作和对话等；\u003c/p>\u003cp>2. 注意，我们设置的场景需要是未来一周或者一月内可能遇到的情况或者场景。比如说：孩子因为输了一场篮球比赛感到挫败，觉得自己不是这块料；老公在工作中表现一直不错，升职名额中没有自己就觉得是能力不行，等等都可以哦~\u003c/p>\u003cp>3. 剧本中需要运用“面对挫折引导三步法”去解决问题\u003c/p>\u003cp>第1步：安抚情绪、直面结果。\u003c/p>\u003cp>第2步：肯定过程、分析原因。\u003c/p>\u003cp>第3步：提出建议、引导行动。 \u003c/p>\u003cp>我会给到大家5分钟的时间，5分钟后会邀请一位小伙伴来讲解一下TA的剧本。\u003c/p>\u003cp>\u003cstrong>【分享者】展示：\u003c/strong>倩如分享内容\u003c/p>\u003cp>场景：老公在工作中表现一直不错，升职名额中没有自己就觉得是能力不行；\u003c/p>\u003cp>剧本设计：\u003c/p>\u003cp>1-安抚情绪、直面结果：老公，我知道你这次竞选失利，这个结果不好，(我们要认清现实)。我知道你的心里面也很难过，我能感受到。\u003c/p>\u003cp>2-肯定过程、分析原因：你为了这次竞选做了很多努力，第一工作中加班加点；第二还特意做了ppt，进行了演讲。 但通过与你日常的沟通，目前需要在带团队的能力，综合管理多项事物的能力相对欠缺，需要提升。我们不能停留在执行层面；\u003c/p>\u003cp>3-提出建议、引导行动：在这个点上面，我们可以多学一些管理型的视频类课程。先让自己具备了那项能力，再让老板和同事在这个过程中看到你有这些值得信任的能力，升职加薪都会随之而来的。\u003c/p>\u003cp>\u003cstrong>【拆书家】点评：\u003c/strong>\u003c/p>\u003cp>好的，非常感谢倩如的分享，每个步骤每个点都讲的非常好。其中有两个地方，我们在沟通的时候一定要注意：\u003c/p>\u003cp>第一就是安抚情绪使用“认清现实”这样的词，是需要斟酌的，它无法给人一种安慰感，反而有点“插一刀”的感觉哈，这里建议换一种表达词可能会更好。\u003c/p>\u003cp>第二就是在分析原因的时候，我们怎么使用“但”这样的连接措辞，这个也是要非常注意的（因为人往往会更关注“但”后面的内容）。\u003c/p>\u003cp>整体来说，今天倩如分享的三个步骤还是很全面的。\u003c/p>\u003cp>\u003cstrong> 【总结】\u003c/strong>\u003c/p>\u003cp>好的，再次感谢现场所有小伙伴们的积极参与，希望今天的拆书内容对大家有帮助。我的分享到此结束，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1666924166000,"updated_at":1668936934000,"ria":true},{"id":14076,"topic":"通往成功之路","learn_goal":"","remark":"《终身成长》作者卡罗尔·德韦克在还是一个年轻的研究员时，她在了解“人们会如何面对失败”时发现了有的人竭力回避失败，而有的人却在失败中越战越勇，面对失败，人为什么会不同呢？\n\n于是卡罗尔·德韦克展开了长达20年的实验研究，通过对各行各业中的案例研究，她提出了“成长型思维”的概念。\n\n那么什么是“成长型思维“？拥有“成长型思维“的人是如何走向成功的呢？走，我们一起走进《终身成长》拆书活动之【通往成功之路】。\n\n拆书家将通过具体案例和我们一起看他人是如何通往成功之路，同时还将邀请你我一起体验走向成功之路的秘密通道！","level":"TF2-3","duration":30,"status":30,"type":0,"chaishujia":{"username":"春儿","city":"深圳市"},"club":{"name":"深圳桃李分舵","city":"深圳"},"prologue":"\u003cp>【学习目标】\u003c/p>\u003cp>通过本次RIA学习，学习者可以在面对挫败时，能运用树立明确的目标，勇敢地自我审视，针对性地刻意练习三个步骤来直面挫折，找到解决方案。\u003c/p>\u003cp> 【自我介绍和图书介绍】\u003c/p>\u003cp>Hi，大家好，我是春儿。三个标签介绍一下自己。\u003c/p>\u003cp>1. 两个孩子的妈妈，家庭教育学习者\u003c/p>\u003cp>2. 一家日企的财务负责人\u003c/p>\u003cp>3. 一名新晋一级拆书家\u003c/p>\u003cp>今天我要分享的这本书是《终身成长》。\u003c/p>\u003cp>【F特征（用于满足好奇心）】在拆书之前我想问一下，大家日常如何定义“成功”？--是取得好成绩？是功成名就？是家庭美满？还是其他。\u003c/p>\u003cp>今天的这本书是有关思维模式的书，它介绍了一种“重新定义成功”的思维模式-“成长型思维”。那成功是什么呢？成功是不断地自我突破，自我成长。\u003c/p>\u003cp>本书作者是美国心理学家卡罗尔·德韦克。\u003c/p>\u003cp>【A优势（重点比较，建立安全感）】卡罗尔·德韦克在还是一个年轻的研究员时，她在了解“人们会如何面对失败”时发现了有的人竭力回避失败，而有的人却在失败中越战越勇，面对失败，人为什么会不同呢？\u003c/p>\u003cp>于是卡罗尔·德韦克展开了长达20年的实验研究，通过对各行各业中的案例研究，她提出了“成长型思维”的概念。2017年她本人也因此而获得了全球最大教育单项奖-“一丹奖”。\u003c/p>\u003cp>相较一些多视角介绍不同思维模式的书籍而言，本书专注于“成长”视角，用各行各业的案例来全方位呈现“成长型思维”。\u003c/p>\u003cp>本书在美国亚马逊心理畅销书在榜10年。豆瓣评分7.6分。\u003c/p>\u003cp>【B本书利益（用于引发兴趣）】看完这本书你将会了解人为什么会不同，看见【固定型思维】和【成长型思维】的碰撞，见证拥有成长型思维的人们在各行各业中直面挑战，迈向成功的。\u003c/p>\u003cp>今天我将通过具体案例和你一起看他人如何通往成功，同时还将邀请你一起演练如何通往成功！\u003c/p>\u003cp>好的，我们先花2分钟时间来一起看一下拆页原文！看完了，请示意我一下。\u003c/p>","ratings_count":1,"texts":[{"id":18094,"quote":"\u003cp>自《终身成长》（美）卡罗尔・德伟克\u003c/p>\u003cp>大家都知道，迈克尔·乔丹在高中时被校队淘汰了，现在我们会嘲笑当年踢他出校队的教练。他没有进入他想要效力的北卡罗来纳州立大学。这些人是不是太蠢了？最初可以选择他的两家NBA球队也没有签下他。多么愚蠢的错误！那是因为现在我们知道他是有史以来最棒的篮球运动员，于是认为在当初这一点应该也是显而易见的。现在，我们看着他的时候，看到的是了不起的篮球巨星迈克尔·乔丹，但在当初，他只是普通的小球员迈克尔·乔丹。\u003c/p>\u003cp>被高中校队淘汰后，乔丹非常郁闷。他的母亲说：“我对他说，让他回学校好好训练。”他真的按照母亲说的做了。他每天早上六点就离开家，在上课前抽空练习。在北卡罗来纳大学的时候，他不断弥补自己的弱点——他的防守动作、控球能力和投篮。他的教练对他远超他人的努力深感惊讶。一次，在球队输掉季后赛最后一场比赛后，乔丹不断地练习了好几个小时的投篮。他是在为下一年的比赛做准备。即使他后来功成名就——让自己成为别人眼中的运动奇才，他的艰苦训练仍然是出了名的。公牛队之前的助理教练约翰·巴赫（John Bach）就说他是“一个不断想提高自己天赋的天才”。\u003c/p>\u003cp>对乔丹来说，成功源于人的头脑。“坚韧的意志和决心比某些身体上的优势更强有力。我经常这么说，我也是一直这样认为的。”但是其他人并不这么认为。他们看到乔丹时，只能看到他完美的身体素质带领他走向成功。\u003c/p>","explains":"\u003cp>【意译案例】\u003c/p>\u003cp>好的，大家都看完拆页原文了。\u003c/p>\u003cp>原文中介绍的美国著名篮球选手乔丹的经历，接下来我和大家分享的是我们国内的一名著名运动员的经历，大家猜猜是谁呢？对，我要分享的是叱咤乒坛的著名乒乓球运动员-邓亚萍的经历。\u003c/p>\u003cp>邓亚萍在9岁那年被河南省队退回，原因是教练认为邓亚萍身高太矮，没有培养价值，于是让他父亲把邓亚萍领回了家。\u003c/p>\u003cp>但是，邓亚萍没有因为被他人否定而放弃乒乓球。在河南省省队时邓亚萍其实已经是一个非常努力，练习最刻苦的队员了。在被退回后，她更严格要求自己，想尽办法找出自己的不足，卯足劲和自己较劲。她意识到自己的身高是拦路虎，因为腿短她比他人需要更多的跑动，多跑动自然会比他人更慢，那么想要跟上对手的节奏甚至超越对手的速度，只有提升跑动的速度。\u003c/p>\u003cp>于是，年仅9岁的邓亚萍穿上沙包衣，腿上绑上沙袋，用着铁拍子，除了睡觉就是训练，没日没夜。\u003c/p>\u003cp>在13岁那年，邓亚萍在成人组拿到了全国冠军，在16岁取得了世界冠军。\u003c/p>\u003cp>邓亚萍在写给她儿子的信中说道：“能跟自己较劲，就不要甩锅给人生。专注于自己，才能成为一个伟大的运动员。”\u003c/p>\u003cp>【不这么做的坏处】\u003c/p>\u003cp>当人们被否定时，很多人会马上发起防御机制归因于外部因素（比如，是那个教练看不惯我。。。），或者以自我否定来逃避问题（比如，我确实先天素质不够，不适合继续下去。。。）。\u003c/p>\u003cp>【细化步骤】\u003c/p>\u003cp>但是，案例中的乔丹和邓亚萍没有因为被否定而放弃，是什么在推动他们走向成功的呢？\u003c/p>\u003cp>\u003cstrong>\u003cu>1.树立明确的目标（知道自己要什么）\u003c/u>\u003c/strong>\u003c/p>\u003cp>无论是乔丹还是邓亚萍，能够引领他们一直往前看是因为他们内心都有十分明确的目标--战胜自我，战胜他人，成为一名伟大的运动员。\u003c/p>\u003cp>乔丹也曾经说过“无论是在练习中还是在真正的比赛中，我都是为了胜利而战斗。没有什么能阻止我以及我对胜利的渴望。”\u003c/p>\u003cp>明确的目标如同灯塔，指引着他们一路坚韧向前，乘风破浪，最终到达终点。\u003c/p>\u003cp>\u003cu>所以，给自己树立一个明确的目标非常重要。\u003c/u>\u003c/p>\u003cp>\u003cstrong>\u003cu>2.勇敢地自我审视（知道自己缺乏什么）\u003c/u>\u003c/strong>\u003c/p>\u003cp>无论是乔丹意识到防守动作、控球能力和投篮是自己的弱点，还是邓亚萍正视自己身高矮这个先天不足，他们都能勇敢地正视自己的不足。\u003c/p>\u003cp>这听起来很简单但其实并不容易，因为这是反人性的。基于天性，人们总会高估自己而低估他人，人们通常能在“高估自己”中感受到成就感并获得更多的信心和力量，而“低估自己”则往往带给自己沮丧，所以，人们总是不那么待见自己的不足和缺点。\u003c/p>\u003cp>能够勇敢自我审视的人通常具有强大的反思能力，基于这个能力，他能够客观地去看待自己的得失成败。\u003c/p>\u003cp>\u003cu>所以，能够勇敢地看见自己的不足是走向成功的必要因素。\u003c/u>\u003c/p>\u003cp>\u003cstrong>\u003cu>3.针对性地刻意练习（知道自己该做什么）\u003c/u>\u003c/strong>\u003c/p>\u003cp>无论是乔丹刻意练习防守动作、控球能力和投篮，还是邓亚萍苦练步法，他们都采用了有针对性的刻意练习。\u003c/p>\u003cp>刻意练习是一种有目的的，有意识的，努力冲出自我舒适区，长期且重复进行练习，并在练习中不断获得反馈的练习方法。\u003c/p>\u003cp>刻意练习是一个非常系统的科学练习方法，不是三言两语就可以让学习者get到这项技能，那我们今天学习的目标是\u003cu>知道在通往成功的路上有刻意练习这样一个方法\u003c/u>。有一本书名为《刻意练习》书籍，找机会来拆这本书吧。\u003c/p>","interaction":"\u003cp>【A3 促动参与】\u003c/p>\u003cp>好的，接下来进入第三个环节拆为己用。我们要用今天学习的三个步骤：\u003c/p>\u003cp>1. 树立明确的目标（知道自己要什么）\u003c/p>\u003cp>2. 勇敢地自我审视（知道自己缺乏什么）\u003c/p>\u003cp>3. 针对性地刻意练习（知道自己该做什么）\u003c/p>\u003cp>来帮助一位拆书帮的小伙伴走出困境，找到出路。\u003c/p>\u003cp>【场景设计】\u003c/p>\u003cp>小王是一个某个拆书帮分舵的学习者，她因为被《这样读书就够了》的拆书法所吸引，从而走入了拆书帮。但随着拆书路上不断喜提的“大侠请重新来过”，小王开始纠结这个拆书还要进行下去吗？小王来找她的闺蜜小林倾诉。\u003c/p>\u003cp>小林是一个具有成长性思维的人，她运用自我成长的三步法来帮小王拨开迷雾，找到出路。\u003c/p>\u003cp>（预案）不知道今天在座的有没有还没有踏上拆书征途的小伙伴？如果有，为了便于这位小伙伴参与拆为己用的练习，我稍微介绍一下什么是拆书。我刚才行为就是一个拆书的行为，其中包括\u003c/p>\u003cp>■Who: 这个活动里至少有学习者，拆书家，观察家3个角色，我就是本次的拆书家，你是其中的学习者，乌冬是本次的观察家。\u003c/p>\u003cp>■How：\u003c/p>\u003cp>◎拆书家：通过1.带领学习者共读拆页 2.为学习者解读拆页 3.带领学习者运用拆页的知识。\u003c/p>\u003cp>同时这也是拆书家通过打怪升级成为特定级别的拆书家的练武场。\u003c/p>\u003cp>◎学习者：在拆书活动获得新知，并在拆书家的带领下理解新知，并尝试将新知内化\u003c/p>\u003cp>◎观察家：基于拆书帮的《拆书家成长手册》中的技能点评估拆书家是否达到了特定级别拆书家的要求。\u003c/p>\u003cp>好的，回到我们这次练习上，在这个场景设计中的小王就是一名在打怪升级中受挫的拆书家。\u003c/p>\u003cp>【小组讨论】\u003c/p>\u003cp>接下来我们进行小组讨论。先来分配一下角色。我们选择一位小伙伴来扮演闺蜜小林，选择一位小伙伴扮演小王。\u003c/p>\u003cp>其他小伙伴也可以跟着小林的引导，一起来思考自己的拆书之路。可以把自己的经历参考以下模块打到公屏上，以促进相互学习和思维碰撞！\u003c/p>\u003cp>好的，给大家7分钟时间演练。各位小王也可以把自过程参照以下模板打到公屏上。\u003c/p>\u003cp>■\u003cstrong>\u003cu>树立明确的目标（知道自己要什么）\u003c/u>\u003c/strong>\u003c/p>\u003cp>我知道自己参加拆书帮拆书是为了获得-------------，并坚信通过自己的努力一定会如愿以偿！\u003c/p>\u003cp>■\u003cstrong>\u003cu>勇敢地自我审视（知道自己缺乏什么）\u003c/u>\u003c/strong>\u003c/p>\u003cp>在拆书路上我喜提“大侠请重新来过”是因为我在---------------地方做的还不够好。\u003c/p>\u003cp>■\u003cstrong>\u003cu>针对性地刻意练习（知道自己该做什么）\u003c/u>\u003c/strong>\u003c/p>\u003cp>在我做的不够好的地方，我可以通过做-----------------，让自己进一步提升。\u003c/p>\u003cp>是的，我将那么去做！\u003c/p>\u003cp>【角色扮演】\u003c/p>\u003cp>好的，7分钟后，我会邀请小王扮演者和小林扮演者上来给我们展示他们的演练成果。\u003c/p>\u003cp>【学习者案例记录：角色扮演】\u003c/p>\u003cp>小王：林哥，我现在拆2-1，反复提交了很多次都被退回。明明觉得很简单，但却总过不了。\u003c/p>\u003cp>小林：那你是为什么要参加拆书的呢？过了获得三级拆书家？还是其他什么？\u003c/p>\u003cp>小王：我觉得拆书比起自己读书更能记住知识点，能提到演讲能力，还想早点成为三级拆书家。\u003c/p>\u003cp>小林：首先你需要一个明确的目标，比如更加巩固知识，提高演讲能力等\u003c/p>\u003cp>小王：是的。\u003c/p>\u003cp>小林：有个明确的目标，那么在你遇到“请大侠重新来过”时，你不会心情不好，而是把它当作一个反馈，然后去提升。\u003c/p>\u003cp>小王：嗯，是的。\u003c/p>\u003cp>小林：那目前你觉得哪一块问题最多啊？\u003c/p>\u003cp>小王：感觉A1和A2吧。A1总是找不到更符合原文的案例，A2是需要未来设立一个目标，我总感觉回忆一下过去，曾经遇到什么类似的事情，现在学了后怎么去做。但总感觉好像又不是。。。\u003c/p>\u003cp>小林：梳理一下，A1是找不到契合的案例，A2是设计动作指令的问题，是吗？\u003c/p>\u003cp>小王：是啊\u003c/p>\u003cp>小林：嗯，现在你走到第二步了。第一步，首先树立了一个目标，提高演讲能力，巩固知识。第二步，勇敢审视了自己的不足，一个是A1如何原文练习实际案例，A2就是指令不清晰。\u003c/p>\u003cp>小王：是的。\u003c/p>\u003cp>小林：那怎样进行刻意练习呢？\u003c/p>\u003cp>小王：可以练。假如未来某个时候遇到类似事情，就可以描述一个场景，并用原文里的方法去解决，明确时间。。。这样积累素材。\u003c/p>\u003cp>小林：我觉得你已经知道怎么去做了。帮你梳理一下就是，第一，你的目标是过完三级，会有更好的演讲能力，更好的知识储备。第二，在勇敢自我审视中，你觉得问题点是A1缺乏契合的案例，A2没能发出清晰的指令。第三，针对这个问题，你需要针对性练习，就是提升更加具象化和场景化去描述的能力，今后在生活和工作中在这方面下下功夫。\u003c/p>\u003cp>小王：好的，这下清晰多了，谢谢林哥！\u003c/p>\u003cp>拆书家：好的，非常感谢两位！刚才的角色分配也非常合适，小林的扮演者易伯伯在技能点上的把握非常清晰和精准，给安宁扮演的小王给出了非常具体的指导，我在旁也受益良多。那我们的小王如果自己的困惑已经获得了一个解决方案的话，可以请你自己来陈述一下解决方案吗？\u003c/p>\u003cp>【学习者案例记录：陈述解决方案】\u003c/p>\u003cp>小王：可以。在拆2级过级中，感觉提交了一个预备表，自己感觉还挺不错，但是总会被打回来，自己也比较受挫。\u003c/p>\u003cp>经过今天的学习，知道首先要树立一个明确的目标，也就是自己想要什么？我参加拆书是为了获得一个演讲能力，那样在分享知识时可以学习者更好的体验。其次，在自我审视，也就是发现自己缺乏什么？第一，从我的生活经验工作经验中找不出跟原文契合的案例。第二，A2的指令不够清晰。那以后，我要多记录，积累素材。我要经常参加拆书活动，以学习者身份观察拆书家，他们是如何联系自己生活的。然后，跟他们讨教经验，如何更好地把自己的生活经验和原文案例联系起来。多看看人家在发布指令时是如何引导学习者的。多观察，多学习，用心讨教经验。这是我今晚学习的一个总结。\u003c/p>\u003cp>好的，非常感谢安宁。\u003c/p>\u003cp>也感谢各位的参与和贡献，愿我们都拥有成长型思维！拆书路上一路同行，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1661566596000,"updated_at":1661788239000,"ria":true},{"id":13099,"topic":"两种思维之下的不同生活","learn_goal":"","remark":"两种思维之下的不同生活","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"如心","city":""},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"\u003cp>1、 【自我介绍】\u003c/p>\u003cp>大家好，我是如心，70后，在一家企业做技术工程师。我喜欢拆书，拆书让我有了阅读的习惯，同时也提高了自己的认识思维能力 ；也喜欢做小视频，有兴趣的小伙伴可以链接我一起学习哦。\u003c/p>\u003cp>2、【什么是拆书】\u003c/p>\u003cp>刚才我说喜欢拆书，那什么是拆书呢？\u003c/p>\u003cp>“拆书”是一种面向成人的学习方法、强调以学习者为中心，把学到的知识关联学习者的经验，规划具体的运用到工作或者生活中。\u003c/p>\u003cp>拆书法分为个人学习的拆书法和组织学习的拆书法。\u003c/p>\u003cp>个人学习拆书法是用便签法进行读书。\u003c/p>\u003cp>组织学习拆书法是一位拆书家把书中的内容加工一场现场学习，引导和促进一群人把知识拆为己用。\u003c/p>\u003cp>3、【什么是拆书帮】\u003c/p>\u003cp>什么是拆书帮呢？拆书帮是拆书法学习爱好者社群，它在全国各地有拆书帮分舵，分舵的使命是帮助更多学习爱好者成长为拆书家。\u003c/p>","ratings_count":1,"texts":[{"id":17078,"quote":"\u003cp>《终身成长》\u003c/p>\u003cp>R:\u003c/p>\u003cp>两种思维之下的不同生活\u003c/p>\u003cp>你的车只是被贴了罚单而不是被毁了，打电话给朋友倾诉之举只是没有成功，你并没有被朋友直接拒绝。没有什么灾难性或不可逆转的事情发生，但仅仅是在这些情况的影响下，固定型思维模式者就已经产生了这种彻底的失败感和无力感。\u003c/p>\u003cp>当我把这些情况原封不动地拿给那些成长型思维模式者看后，他们是这样说的：\u003c/p>\u003cp>“我会更努力地学习，下次停车的时候我要更加小心一些，不知道我的朋友是不是今天过得不开心。”\u003c/p>\u003cp>“C+这个成绩告诉我，我必须在课堂上加倍付出努力，我依然有半个学期的时间来提高我的成绩。”\u003c/p>\u003cp>还有很多类似的回答，我想你们已经了解他们会说些什么了。那么，他们会如何应对呢？\u003c/p>\u003cp>“我必须开始考虑，为了下一次测验，我要更努力地学习（或者换个学习方法），我会缴清罚款，下次再给朋友打电话的时候，我们再好好聊聊。”\u003c/p>\u003cp>“我会总结我在期中考试到底犯了哪些错误，下一次要做得更好。我得把我的罚款交了，打电话告诉我的朋友，那天我心情很不好。”\u003c/p>\u003cp>“下一次考试的时候我要更加努力，和我的老师交流交流，下一次停车的时候要小心一些，或者去理论一下我没有违章，还要去弄清楚我的朋友到底怎么了。”\u003c/p>\u003cp>不是说你必须拥有某种思维模式，而拥有另一种思维模式的人就会产生挫败感。谁不是这样呢？糟糕的成绩、朋友或爱人的拒绝都不是什么开心的事，没有人会喜欢这些糟糕的事情。只是这些有着成长型思维模式的人不会给自己贴上标签，或对自己失去信心。即使他们感到沮丧，他们也准备好了去承担这个风险，直面挑战，继续为此奋斗。\u003c/p>","explains":"\u003cp>不知道大家有没有过这样的经历。\u003c/p>\u003cp>为了参加了一场考试，你准备了很长时间，你满怀信心能够考好，但是成绩出来后，发现成绩比预料中的低了很多。\u003c/p>\u003cp>早上到办公室，你和同事打招呼，他当时正在看邮件，没有回应你。\u003c/p>\u003cp>当我们面对类似的事情时，大家会怎么处理呢？\u003c/p>\u003cp>固定型思维模式认为“准备了这么久的考试没考好，我太失败了”，“嗯，同事没有回应我，应该是我哪里做错了，或者同事在生我的气”。\u003c/p>\u003cp>成长型思维模式认为“我这次没考好，一定是哪里出问题，我要努力，下次考个好成绩”，“同事没有回应我，他是在认真看邮件，真是太专注了”。\u003c/p>\u003cp>刚才说到固定型思维模式和成长型思维模式，这两种思维模式有什么不同呢？\u003c/p>\u003cp>固定型思维模式认为人的能力是固定的，当他遇到挫折，会陷入负面情绪，然后给自己贴上“失败者”标签，产生失败和无力感，然后放弃努力。\u003c/p>\u003cp>成长型思维模式认为人的能力是可以提升的，当他遇到挫折时会认为挫折只是暂时的，会从挫折中总结经验，然后继续努力，一直保持向上的激情。\u003c/p>\u003cp>拆页告诉我们，用成长型思维模式三步，可以解决面对挫折产生的无力感和失败感。\u003c/p>\u003cp>1、 接纳情绪，不贴标签。\u003c/p>\u003cp>每个人遇到挫折时难免会不开心，我们要做的就是接纳自己的情绪，告诉自己不开心是正常的。重要的是不给自己贴负面标签，比如“我无能”，“我就知道我不行”等。\u003c/p>\u003cp>2、 分析原因，总结经验。\u003c/p>\u003cp>把事情的起因、经过、结果先理一遍，梳理出影响结果的事情，分析失败的原因，然后总结经验，以后避免类似错误。\u003c/p>\u003cp>3、 规划行动，继续努力。\u003c/p>\u003cp>根据分析的原因和总结的经验，重新调整行动，继续努力。当然，在努力过程中如果遇到挫折，我们可以重新启动刚才的三个步骤。\u003c/p>","interaction":"\u003cp>讲到这里，我想起在很多年前发生在我身上的一件事。\u003c/p>\u003cp>我们单位每年会请一个TTT培训讲师为有潜力的员工进行培训，发展参训的员工为企业内训师。\u003c/p>\u003cp>有一年我有幸成为参加培训中的一员，经过三天的培训，培训师让每人设计一门课程，一周后进行试讲，培训师在试讲现场进行指导后进行第二轮试讲，然后进行内训师级别认定。\u003c/p>\u003cp>那次参加培训的员工，大部分来自销售部门，看着他们在台上侃侃而谈的样子，心想人家做销售那么会讲，像我这样天天不讲话的人，怎么能比得过人家呢？越想越紧张，轮到我上台时，把想讲的话全忘了，最后只好照着PPT读了一遍。\u003c/p>\u003cp>培训讲师在现场给了我很多意见，鼓励我参加第二轮试讲，我总觉得自己怎么也不可能比得过销售部门啊，后来没参加第二轮试讲，当然也没有成为单位的内训师。\u003c/p>\u003cp>后来我反思自己失败的原因，大概有以下几条：\u003c/p>\u003cp>1、 给自己贴了标签。认为自己不是讲课的料，不可能讲好课。\u003c/p>\u003cp>2、 受紧张情绪困扰。一直想压住紧张情绪，结果越想越紧张。\u003c/p>\u003cp>3、 没有反思过真正的问题。一直认为自己不适合讲课，没想过要努力改变自己。\u003c/p>\u003cp>【A2便签】\u003c/p>\u003cp>刚才讲的是我失败的一个经验。接下来，我在应用方面，给自己定的目标是在3月底前，应用拆页中介绍的成长型思维3步法，完成1-2的升级。\u003c/p>\u003cp>第一不给自己贴负面标签，虽然年龄大了，但是只要肯努力，一定可以的。\u003c/p>\u003cp>中间如果出现面情绪，比如着急、担心等等，告诉自己这都是正常的，调整好心态。\u003c/p>\u003cp>第二是不断总结经验。\u003c/p>\u003cp>升级需要准备的事情有很多，准备拆页、找师父改稿子，背诵稿子、联系过级等，准备过程中不断总结经验，详细记录自己是怎么做的，哪里准备得不好，哪个经验可以复制等等\u003c/p>\u003cp>第三是规划行动。\u003c/p>\u003cp>在3月10号前，定下来逐字稿的终稿，在3月20号之前把稿子背会，怎么背呢？\u003c/p>\u003cp>①多听:把逐字稿录成音频多听。\u003c/p>\u003cp>②多读:把逐字稿打印下来空闲时多读\u003c/p>\u003cp>③多练:对着镜子反复练习，给别人讲。\u003c/p>\u003cp>最后联系分舵进行线上升级。\u003c/p>\u003cp>好了，以上就是我A2的分享。\u003c/p>\u003cp> 今天的分享就就要结束了，我是来自喜乐分舵的如心，感谢大家的陪伴，谢谢。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1646219169000,"updated_at":1646275417000,"ria":true},{"id":13079,"topic":"用成长型思维改善关系","learn_goal":"","remark":"拆书主题：用成长型思维改善关系\n书籍名称：《终身成长》\n个人介绍：一个TF2-4拆了九次才过的，依旧要笨（奔）向三级的拆书老油条\n挑战等级：TF3-1\n拆书时长：15-20\n学习者收获：改变思维改善关系\n结缘拆书：由《这样读书就够了》结缘拆书帮，结缘优秀的拆书家，结缘更好的自己！","level":"TF3-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"陈松波","city":"重庆市"},"club":{"name":"重庆山城分舵","city":"重庆市"},"prologue":"\u003cp>\u003cstrong>自我介绍+场景图书介绍法+目标（2分钟）\u003c/strong>\u003c/p>\u003cp>大家好！我是陈松波，我今天要拆的是TF3-1 \u003c/p>\u003cp>\u003cstrong>事件场景：\u003c/strong>首先，我想邀请大家想想你有没有遇到过这样的一个场景——\u003c/p>\u003cp>有一天，老婆下班回家，给我讲了一个很长，很详细的故事，但是整个故事都没有重点，我觉得无聊透了，但我还是努力不表现出来。但她最终还是被她发现了。\u003c/p>\u003cp>她就是说我，对她漠不关心，一点也不在乎她，她每天都主动与我分享工作中遇到开心的不开心的事，而我还表现得不耐烦且我从来都不给她说我工作上的事。然后就是开始与我争吵，那段时间我们经常这样。\u003c/p>\u003cp>\u003cstrong>提问：\u003c/strong>不知道大家在夫妻关系、情侣关系或其它的亲密关系中遇到过类似责备突然来袭的情况呢？你当时是怎么处理的呢？效果如何呢？\u003c/p>\u003cp>\u003cstrong>影响：\u003c/strong>其实类似这样的问题，如果不能很好的解决的话，短期来看会影响彼此的心情，长期如此的话，则很有可能会严重响彼此的亲密关系，甚至引发更大的关系危机。\u003c/p>\u003cp>\u003cstrong>解决：\u003c/strong>那这个问题到底应该怎么解决呢？那我今天要给大家分享的这本书《终身成长》就给出了解决方法。它的作者是斯坦福大学心理学家——卡罗尔德韦克，她在本书中指出在亲密关系中固定型思维者的责备总是来得又快又猛，而要解决这一问题的的方法就是运用成长型思维改善关系。\u003c/p>\u003cp>\u003cstrong>学习目标：\u003c/strong>\u003c/p>\u003cp>在跟我完成本次RIA现场学习后，在与他人关系的出现问题的时候，能够按成长型的思维改善关系三步法去【澄清】改善【行为】与他人关系中出现的问题【界定】。\u003c/p>","ratings_count":1,"texts":[{"id":17056,"quote":"\u003cp>接下来我们就是一起来看看这两种思维到底有什么不一样的，请大家花2分钟的时间阅读片段\u003c/p>\u003cp>\u003cstrong>R阅读原拆页（2分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>问题表明性格存在缺陷\u003c/strong>\u003c/p>\u003cp>固定型思维模式者的第二个问题，就是认为问题意味着根深蒂的缺陷。但是，就好比任何伟大的成就不可能不经历挫折一样，所有良好的两性关系也不可能避免冲突和问题。\u003c/p>\u003cp>固定型思维模式者在谈到冲突时会选择责备，有时他们会责备自已，但大部分时候他们选择责备对方。而且他们会将责备的矛头指向对方的个人特质——认为这是性格的缺陷。\u003c/p>\u003cp>但是还没完。当人们将问题的源头指向伴侣的个性并加以责备时，这种举动会让他们感觉愤怒并厌恶自己的伴侣。\u003c/p>\u003cp>而且问题将进一步升级: 既然问题是固定的个人特质引起的，那么这一事实代表这个问题无法被解决。\u003c/p>\u003cp>所以，一旦固定型思维模式者发现了伴侣某些方面的缺点，他们就会看不起对方，并对整个恋爱关系感到不满。(相反，成长型思维模式者会看到伴侣身上的不完美，但依然认为他们的恋爱关系是良好的。)\u003c/p>\u003cp>有的时候，固定型思维模式者对伴侣和两人关系中的问题视而不见，这样他们就可以不去面对和解决。\u003c/p>\u003cp>每个人都认为伊冯娜可能有外遇。她经常接到神秘的电话，经常在接孩子时迟到，“和女友们一起出去玩”的次数变多了，好像老是心不在焉的。她的丈夫查理说,伊冯娜只是在经历一个特殊的阶段“所有女人都会经历这种阶段,”查理坚持说，“这 并不代表她有在外面有了别的男人。”\u003c/p>\u003cp>查理的好朋友催他去查一查事情的真相。但是查理认为，如果他面对了现实——如果结局是不好的—— 那么他的世界就会崩塌。从固定型思维模式者的思考方式来看，他必须面对几个现实中的一个，要么他爱的女人是个坏女人，要么他自己是一个坏人，导致妻子离他远去，要么他们的关系是糟糕且无法挽回的。\u003c/p>\u003cp>他一个选择都不能承受。他意识不到，这个问题其实可以被解决，伊冯娜只是在向他传递信息，她非常渴望他能知道:不要不拿我当一回事，我需要更多的关注。\u003c/p>\u003cp>成长型思维模式并不意味着查理必须去质问妻子，但是他可以与她探讨他们目前的情况。他可以去想一想是什么出了问题，或许可以针对问题去咨询顾问，在仔细考虑后再决定接下来该怎么做。如果两个人之间有问题需要解决，那么至少两个人的关系还有挽救的机会。\u003c/p>","explains":"\u003cp>\u003cstrong>分享I便签（4分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>WHAT:\u003c/strong> （强化讲解概念）\u003c/p>\u003cp>这个片段介绍了固定型思维与成长型思维在面对两人关系出现问题时，所采取的不同年应对措施。\u003c/p>\u003cp>我们一起来看看下面这几句话，看看他们哪些是固定型思维，哪些是成长型思维。\u003c/p>\u003cp>1、 如果我们的感情是天注定的，那么一切问题都会自然地得到解决\u003c/p>\u003cp>2、 两个人即使有天雷勾动地火的感觉，但健康长久的关系依旧需要双方的努力\u003c/p>\u003cp>3、 她就是一个坏女人，所以才会离开我和孩子。\u003c/p>\u003cp>4、 我们关系已经出了问题，我能做些什么来改善呢？\u003c/p>\u003cp>以上四句话，哪些能体现成长型思维？哪些体现了固定型思维？对的，1、3是固定型思维的表现，2、4是成长型思维的表现。\u003c/p>\u003cp>固定型思维模式者在谈到冲突时会选择责备，而且他们会将责备的矛头指向对方的个人特质——认为这是性格的缺陷，是不可改变的；\u003c/p>\u003cp>成长型思维模式者在遇到冲突时，则会相办法与对方探讨目前的情况，以及怎么去解决，认为冲突是可以解决的，关系是可以改善的；\u003c/p>\u003cp>通过这样的对比，我们会发现固定型思维与成长型思维的区别表现在：是否相信亲密的关系可以通过努力得以改善。\u003c/p>\u003cp>拥有固定型思维的人在面对问题出现时，常常无选择逃避或责备，把原因归咎于性格缺陷，认为无法改变。拥有成长型思维的人在面对与他人关系出现问题时，会选择面对现状，并努力分析原因，寻求改变方法。\u003c/p>\u003cp>我们从成长型思维与固定型思维对比的要点，可以归纳出成长型思维改善关系三个步骤\u003c/p>\u003cp>\u003cstrong>HOW：\u003c/strong> \u003c/p>\u003cp>\u003cstrong>第一步\u003c/strong> \u003cstrong>察觉现状\u003c/strong>\u003c/p>\u003cp>固定型思维的人对关系中出现的问题往往视而不见，这样他们就不用去面对和解决问题。可这不仅不会让问题消逝反而会让问题越来越严重。\u003c/p>\u003cp>所以成长型思维改善关系的第一步就是察觉现状，察觉自己在面对现状的态度，是在逃避吗？是在责备吗？并承认关系中出现的问题。\u003c/p>\u003cp>\u003cstrong>第二步 分析原因\u003c/strong>\u003c/p>\u003cp>既然我们已经承认现在的关系中出现了问题，那么我们接下来就要去分析下，这些问题是怎么产生的？以及我们为什么会逃避或是责备他人？\u003c/p>\u003cp>\u003cstrong>第三步 寻求改善\u003c/strong>\u003c/p>\u003cp>固定型思维的人认为如果两个人适合在一起，一切问题都会自然而然的解决掉，不需要自己付出努力去改变什么。而这种良好的关系不需要努力维系的想法，常常让他们的关系走向破裂。\u003c/p>\u003cp>而成长型思维的人在发现问题，经过分享后找到了原因，接下来他们会通过各种途径寻求改进的方法，并努力的去改善彼此间的关系\u003c/p>\u003cp>所以成长型思维改变关系的第三步就是寻求方法，努力改善。\u003c/p>\u003cp>\u003cstrong>WHEN：\u003c/strong>\u003c/p>\u003cp>这个方法可以用改善两性关系，亲子关系等亲密关系或其他你在乎并愿意改进的关系当中。\u003c/p>\u003cp>\u003cstrong>案例：\u003c/strong>\u003c/p>\u003cp>我老婆有一天下班回家后，给我讲了一个很长，很详细的故事，但是整个故事都没有重点，我觉得无聊透了，但我还是努力不表现出来。但她最终还是被她发现了。\u003c/p>\u003cp>她就是说我，对她漠不关心，一点也不在乎她，她每天都主动与我分享工作中遇到开心的不开心的事，而我还表现得不耐烦且我从来都不给她说我工作上的事。然后就是开始与我争吵，那段时间我们经常这样。\u003c/p>\u003cp>在这个例子中，我和我老婆都掉入了固定型思维模式中，一开始自己就在逃避自己觉得无聊的情况，并期待这无聊的情况会很快过去。我老婆可能认为我表现出的不耐烦就是为因我对她关心，并责备我。我们都陷入了固定型思维中，我在逃避，我老婆在责备。都并未寻找方法，努力改善。\u003c/p>\u003cp>好，我接下来看看运用成长型思维改善关系三步法，我们应该怎么做\u003c/p>\u003cp>第一步，察觉现状。这个故事让自己感到无聊这一个问题确实存在，我好像在逃避这种无聊的状态\u003c/p>\u003cp>第二，分析原因。为什么老婆要给我讲这么长一个故事呢？他想给我表达什么？是不是想让我知道更多的细节呢？ 为什么老婆讲一个长一点的故事自己就会觉得无聊呢？\u003c/p>\u003cp>第三步，寻求改善。找到原因后就是尝试着做出一些改变了。比如跟对方说，亲爱的，你给我讲这么多是想让我知道整个事情的经过吗？你讲了这么多的细节，我不明白你的重点是什么？你可不可以直接告诉我为什么这事这么让你兴奋？等等\u003c/p>\u003cp>相信经过这样的三步，我们能更好处理这个问题，改善彼此的关系。\u003c/p>","interaction":"\u003cp>\u003cstrong>分 组：\u003c/strong>\u003c/p>\u003cp>接下来我们会有分组学习和讨论，所以我们先来进行一个简单的分组。\u003c/p>\u003cp>\u003cstrong>A2催化学习者应用（7分钟）\u003c/strong>\u003c/p>\u003cp>好了，我例子讲完了，接下来我们要在现场来运用一下这个方法。具体怎么运用呢？《这样读书就够了》中介绍了一个重要的关于学习的研究结果：在大脑中过一次，等于实际应用了一次。\u003c/p>\u003cp>所以，接下来请每个人都想一想在未来一周或一个月内你可能会运用到成长型思维改善关系三步法的场景。\u003c/p>\u003cp>一听到改变关系，你第一个想到的是谁？是你丈夫？妻子？爸妈？或者是其他人。想想你们可能会发生什么事情影响你们的关系，这件事情发生了，你打算怎么做，你会和他说些什么？\u003c/p>\u003cp>\u003cstrong>请大家编一个小故事（剧本），写出整个事件的起因，经过，结果以及双方的对话。在这个故事中要体现成长型思维改善关系的三步法。\u003c/strong>\u003c/p>\u003cp>请大家把这个小故事（剧本）写在我给大家的卡卡片上，时间是5分钟，5分钟后我会请小伙伴来给我们分享他的故事（剧本）。\u003c/p>\u003cp>学习者案例：\u003c/p>\u003cp>小故事（剧本）\u003c/p>\u003cp>时间：本周末\u003c/p>\u003cp>地点：客厅 厨房\u003c/p>\u003cp>人物：ZZ，弟弟，爸爸，妈妈\u003c/p>\u003cp>事件：（含起因经过结果）\u003c/p>\u003cp>起因：\u003c/p>\u003cp>之前爸爸、弟弟、我在客户看电视或玩耍，妈妈一个人在厨房做饭，经常抱怨我们三个不去给她帮忙做饭。经常抱怨我们，我之前就觉得做个饭嘛，哪里需要那么多人帮忙嘛。学过这个方法后啦，我打算在本周日去尝试运用：\u003c/p>\u003cp>本周日爸爸，弟弟，我在客厅看电视；妈妈在厨房做饭。我意识到不进去帮忙妈妈待会又会不开心了。于是，我就走进厨房，说：\u003c/p>\u003cp>“妈妈，我来帮你做饭，有什么需要我帮忙的吗？”\u003c/p>\u003cp>“出去，出去，谁要你帮忙”妈妈\u003c/p>\u003cp>我说“好，那我把饭碗洗了拿出去吧”，一会儿，我又进去对妈妈说“妈妈有你真幸福，辛苦了妈妈，我爱你！”\u003c/p>\u003cp>“油嘴滑舌的，个人出去，厨房本来都小，转都转不开了”妈妈故作镇静的说。\u003c/p>\u003cp>于是，我又拿着筷子出去了。\u003c/p>\u003cp>一会儿，我看妈妈菜炒好了，我就主动进去端菜并说：“妈，好香的菜啊！口水都要流出来了”\u003c/p>\u003cp>妈妈开心的笑了下，说“香就多吃点”\u003c/p>\u003cp>菜端上桌后，我们一家人开开心心的吃了起来\u003c/p>\u003cp>…………\u003c/p>\u003cp>感谢ZZ的分享，从ZZ的分享中我们可以看到整个事件的起因，经过及结果，非常的棒，同在这个小剧本中我们也看到了ZZ运用改善关系三步法的运用，首先是察觉现状，即不去帮妈妈，妈妈可能会不开心，并分析原因，且做出了一些改善的办法，最终一家人开开心心的吃饭，非常温馨的画面，再次感觉ZZ的分享\u003c/p>\u003cp>\u003cstrong>结束语：\u003c/strong>\u003c/p>\u003cp>今天，我给大家分享了固定型思维和成长型思维，希望大家了解决定我们成功与否的不是能力与天赋，而是我们的思维方式！\u003c/p>\u003cp>\u003cstrong>好，我的分享到此结束，谢谢大家！\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1645868318000,"updated_at":1647146063000,"ria":true},{"id":12143,"topic":"如何识别固定型思维，并引导转变","learn_goal":"","remark":"终身成长","level":"TF3-2","duration":25,"status":0,"type":0,"chaishujia":{"username":"曾燕","city":"贵阳市"},"club":{"name":"贵阳黔灵分舵","city":"贵阳"},"prologue":"\u003cp>【拆解图书】《终身成长》\u003c/p>\u003cp>【拆解主题】如何识别固定型思维，并引导转变\u003c/p>\u003cp>【拆解级别】TF3-2\u003c/p>\u003cp>\u003cstrong>自我介绍\u003c/strong>\u003c/p>\u003cp>各位伙伴们晚上好！我是拆书家曾燕。\u003c/p>\u003cp>我的三个标签：全职宝妈，读书爱好者以及未来的三级拆书家。\u003c/p>\u003cp>图书介绍（2分钟）\u003c/p>\u003cp>\u003cstrong>技能要求【学习者场景介绍法中，能够清晰辨别出聚焦于图书和学习主题的事件、提问、影响和解决4个步骤。】（2分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【事件】\u003c/strong>不知道大家有没有过这样的经历，你参加培训、考试或者活动，本来就是抱着学习心态去的，活动过程中却要求当众表达或是现场要求总结，你开始表现焦虑，害怕回答错误，甚至在上台演讲时口干舌燥、大脑空白，身体颤抖。当其他伙伴都在认真完成或者开始练习时，只有你关心最终的成绩是否合格，能否通过这场考试或培训。\u003c/p>\u003cp>\u003cstrong>【提问】\u003c/strong>像不像上学时被老师抽查回答问题\u003cstrong>？\u003c/strong>如果回答错误，你会在心里想什么？是不是也曾害怕被老师发现，其实自己并不聪明？一年一度的高考已经结束了，过去你想过它是未来决定自己一生的关键因素吗？甚至觉得人的一生命运从一开始就被注定了？\u003c/p>\u003cp>\u003cstrong>【影响】\u003c/strong>这样的思维模式极大可能让人们陷入自卑的怪圈，会怀疑自己，否定自己，给自己贴上各种标签，甚至失去信心、希望，因此积聚大量负能量，认为自己无论做什么事情都会做不好，努力是没有用的。\u003c/p>\u003cp>\u003cstrong>【解决】\u003c/strong>我命由我不由天，《终身成长》就是帮助我们度过非常时期的秘籍，详细的讲解了固定型思维对我们带来的影响和伤害，当我们受挫、失败、失去信心时，有意识的察觉自己的固定型思维，学习消化和转变，从本质上相信自己，相信创造，勇于迎接挑战，开启成功的人生，实现终身成长。\u003c/p>\u003cp>\u003cstrong>技能要求【学习目标中包含学习者要完成的具体内容和完成程度，现场学习设计清晰体现了该学习目标。】\u003c/strong>\u003c/p>\u003cp>学习目标：在跟随我完成本次RIA现场学习者能够清晰的辨认（行为）自己的固定型思维，为什么会出现这样的想法，找到原因（界定），学会接纳它，重新认识自己的思维能力，有意识的引导思维的转变。\u003c/p>\u003cp>\u003cstrong>技能要求【A1环节的量表题清晰设置了多个选项，学习者通过自测可以了解在某一种情况下自己的表现】（2分钟）\u003c/strong>\u003c/p>\u003cp>正式拆书之前，先请大家用1分钟做一个小测试。\u003c/p>\u003cp>【量表自测题\u003cstrong>】\u003c/strong>这个评估能帮你了解自己的内心是否存在固定型思维能力，这样的思维能力对你自己生活影响程度。\u003c/p>\u003cp>仔细阅读下列表格中的每句话，利用自己的判断，圈出自己对每个问题的得分。\u003c/p>\u003cp>1～5，1表示完全不符合，5表示完全符合，请大家直观做出回应。\u003c/p>\u003cp>【I】解释自测题\u003c/p>\u003cp>好，看到大家都做完了，大家可以合计一下自己得多少分。\u003c/p>\u003cp>有没有得分在30分以上的小伙伴，请举手？\u003c/p>\u003cp>说明你长时间处于固定型思维模式，经常自我怀疑和否定，害怕失败，不喜欢挑战，比较安于现状；\u003c/p>\u003cp>得分在10-30之间的举下手，你们偶尔会处于固定型思维模式中，在生活中有一定的影响，可以接受突破，但很有可能后劲不足。\u003c/p>\u003cp>那么，剩下没举手的小伙伴，得分在10分以下，恭喜大家处于固定型思维模式的时间比较少，喜欢挑战，并且时刻以相信自己为前提\u003c/p>","ratings_count":0,"texts":[{"id":16051,"quote":"\u003cp>\u003cstrong>技能要求【原书拆页R为why或者what的内容，或原书一个完整的案例】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>《终身成长》P6、7（2分钟）\u003c/strong>\u003c/p>\u003cp>相信自己的才能是一成不变的，也就是固定型思维模式，会使你急于一遍遍地证明自己的能力。如果你只拥有一般内水平的智力和品德，以及普通的个性，那么，你最好证明你自己能够在这些方面达到正常水平，不能让自己在这些基本特征方面看上去或者给人感觉不足。\u003c/p>\u003cp>我们当中有些人从很小的时候就被训练成这种思维模式。我小时候就非常关注自己是不是聪明，但真正将这种固定型思维模式印入我大脑的，是我六年级的老师威尔斯女士。和阿尔弗雷德.比奈不一样，威尔斯女士认为，智商决定了人们的一切。我们按照智商从高到低安排在教室里的座位，只有智商最高的同学才能举旗、拍黑板擦或者给校长写报告。她除了每天用她那种找判的态度让我们感到紧张之外，还建立了一种思维模式，在这种思维模式中，全班同学都有一个强烈的目标，就是要让自己显得聪明而不是愚蠢。在每次考试或者在课堂上被她叫起来回答问题时，我们整个人都可以说是处在成败的紧要关头，谁还会在乎和享受学习的内容呢？\u003c/p>\u003cp>我见过的太多人都抱有这种要证实自己的强烈目标，在课堂上，在工作中，甚至在他们的个人关系中。每种时刻都需要他们对自己的智力、个性以及特征进行证明。每一个时刻，他们都在接受评估：我会成功还是失败？我看上去是聪明还是愚蠢？我是会被接受还是被拒绝？我看上去像是个成功者还是失败者？\u003c/p>","explains":"\u003cp>\u003cstrong>技能要求【I环节拆书家有进行简短互动，并能精确控场】(5分钟)\u003c/strong>\u003c/p>\u003cp>大部分小伙伴都已经看完了，在讲解之前，我们一起回顾一下，在这个片段里面提到的关键概念？\u003c/p>\u003cp>学习者互动：成功、失败，努力、固定型思维\u003c/p>\u003cp>过去自己当学生的时候，有没有遇到过案例里的老师？当时是怎么想的？\u003c/p>\u003cp>学习者互动：\u003c/p>\u003cp>why：如果我告诉你“明天的你会比今天更优秀，”你还会介怀失败吗？有一个重要的道理，决定成长的第一步是你是否相信努力。比起智商和情商，思维模式的差异才是人与人不同的根本原因。\u003c/p>\u003cp>现在，我想问大家，现在的你，更关心别人眼里你是否聪明，还是怎么才能变得更聪明？你想变得完美了再参加比赛，还是想在比赛中变得完美”\u003c/p>\u003cp>学习者互动：想要先完成再完美\u003c/p>\u003cp>其实这些问题，我相信大家在日常生活中是有思考过的，但是为什么没有改变或者进步呢？究竟是什么原因阻碍了大家呢？今天我们就来了解一下，固定型思维对我们的影响。\u003c/p>\u003cp>what：固定型思维模式认为，人的智商是天生的，后天再怎么努力也不会改变。他们倾向于回避失败与挑战，考虑的问题是我是个什么样人，认定人的基本能力不能通过后天的努力去培养。更看重的是自己曾经的天赋如何，而去选择不相信自己可以成为更好的人。\u003c/p>\u003cp>长期处于这样的思维模式中，会严重导致我们的自信心不足，让我们没有勇气和信心去改变自己以及当下的生活状态，安于现状，反复陷入想害怕失败的怪圈。那么，让我们一起来学习如何转变自己的思维模式，可分为五步：\u003c/p>\u003cp>how：1.观察：通常会在什么情况下出现固定型思维？它出现的频率以及场合。是遇到失败？被批评时或是任务的截止日期等。\u003c/p>\u003cp>2.分析：当发现了固定型思维模式时，它是如何让我们思考、感受的，具体的原因是什么？背后的需求是什么？\u003c/p>\u003cp>3.接纳：拥抱自己的固定型思维，面对这个事实，我们每个人都会有一部分固定型思维模式。\u003c/p>\u003cp>4.引导：先停下来，找到自己内心的需求，是积极主动，还是消极被动？有意识的引导自己的想法由“消极”往“积极”去转变；\u003c/p>\u003cp>5.行动：当思维发生变化，需要做的就是立即行动，用行动改变自己，刻意训练。\u003c/p>\u003cp>【例子】这个地方，我想用自己的例子来向大家说明，5月份的时候，我参加了一场培训演讲的课程，当时去的主要目的，就是希望自己能学习到思维逻辑，并且练习表达，我们那个课程是要求上台演讲的，结果准备上台的时候，就开始手心冒汗，上了台，特别紧张，怕讲不好，最后就开始语无论次，想表达的也没有表达清楚，台下的我特别自责，为什么我就是没做好。\u003c/p>\u003cp>一直以来，我都是极度害怕当众表达的，每次在台下都能侃侃而谈，真有机会上台时却退缩了，无论在台下练习多久，始终不敢举手上台，因为害怕，怕自己说错了，怕被别人看出我的不聪明。\u003c/p>\u003cp>学习到这本书，当我害怕想逃避时，我都会刻意引导自己用到这个方法，\u003c/p>\u003cp>第一步先观察这种害怕的情绪，是不是让自己处于固定型思维模式下思考；\u003c/p>\u003cp>第二步，分析它，为什么会有害怕和退缩的行为，这样的思维方式让我内心更平静，它的确是在保护我的自尊心不受伤害；\u003c/p>\u003cp>第三，接纳这样的自己，无论是遇到什么情况，害怕和退缩都只是我的个人情绪问题，有这样的思维并不代表我不好，我不行，这只是出于自我保护的一种举动。第四，认识到这个问题，我便会有意识的引导自己，别害怕，如果错了，失败了，就重新学习，大不了重头来过；\u003c/p>\u003cp>第五，行动起来，即使还是会害怕，想要逃避，只要我敢于举手，表达自己，就是我转变思维的开始。\u003c/p>\u003cp>where：这个方法可以帮助很多人，当我们遇到困难、逆境想退缩、逃避时，害怕自己失败时，想改变自己的，都可以尝试。也适用于运用到企业、教育、体育、人际沟通、家庭中推广，希望我们每一个人都好，更积极、勇敢的生活，相信自己，做一个可以掌控自己人生的人。\u003c/p>","interaction":"\u003cp>\u003cstrong>技能要求【A3环节，给出了一个非常具体、确定的场景，学习者可在此场景中演练或讨论或应用新学技能】【使用A3技能点的环节指令清晰，学习者可以根据拆书家设定的案例场景，应用知识点进行小组讨论并形成一个解决方案，或是应用知识点进行组内角色扮演。】（10分钟）\u003c/strong>\u003c/p>\u003cp>那么，分享了这么多，是适候该练习一下，落实到行动上才是最重要的。\u003c/p>\u003cp>检验一下大家是否理解如何转变固定型思维的五个步骤。\u003c/p>\u003cp>【分组】接下来，我们先进行分组，从我的左手边，两个一组。\u003c/p>\u003cp>在我们设计的场景中，领导安排小A参加了有关其他部门的培训，虽然是去凑数的，但是听得很认真，就在培训即将结束时，却被领导安排做会后总结，这时候小A内心非常纠结，不敢接受这个挑战，领导很认可A的能力，并且看出了他的顾虑，，想要帮助小A走出目前思维的逆境。\u003c/p>\u003cp>要求：两人，一人扮演领导，一人扮演小A，领导如何运用引导思维转变五步法，帮助小A转变思维，接受挑战。小组内讨论五分钟，然后我们将邀请一组小伙伴来为我们分享。\u003c/p>\u003cp>\u003cstrong>学习者案例\u003c/strong>：\u003c/p>\u003cp>\u003cstrong>技能要求【A2环节指令清晰，学习者可以根据指令，写出自己未来的一个具体的要做的应用（比如：某个特定任务、和人分享、事后复盘或找人陪练】（4分钟）\u003c/strong>\u003c/p>\u003cp>我们都要相信，成功往往是一时的，而成长是一辈子的。为了让大家记得更牢，给大家布置个小任务：今天回去，就找身边的小伙伴分享学习内容。想想你会找谁分享呢？在什么时间，什么地方？你会分享哪部分内容呢？或者是事后复盘今日之所学内容，有哪些要点，还有没有更好的建议，怎样运用到自己的案例当中？学以致用。还可以接朋友一起来练习，想象一下遇到了什么问题，让朋友一起帮助你转变自己的思维，小伙伴们会选择哪一种作业来完成，大家可以思考或者讨论2分钟，待会我们提前请小伙伴分享一下他的作业。\u003c/p>\u003cp>\u003cstrong>学习者案例：\u003c/strong>\u003c/p>\u003cp>结束语：现在，该由你来决定是否该做出改变了，学会观察、分析、接纳、引导、行动引导思维转变五步法。改变也许艰难，却能够让你成为掌握自己未来方向的人。最后，感谢大家的积极参与。\u003c/p>\u003cp>\u003cstrong>技能要求【总时长没有少于20分钟，没有超过25分钟。】\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1629014859000,"updated_at":1629014859000,"ria":true},{"id":12024,"topic":"如何用成长型思维表扬孩子。","learn_goal":"","remark":"孩子们都喜欢被表扬，他们尤其喜欢别人表扬自己的智力和天赋，这种称赞确实能给给他们带来特别的喜悦感，但这种感觉只能维持很短的时间，一旦遇到困难，他们的自信心就会消失，积极性也会跌到谷底，如果成功意味着他们很聪明，那么失败则意味着他们很愚蠢。这就是固定器思维模式表扬带给他们的影响。\n \n那如何用成长型思维表扬孩子？","level":"TF3-2","duration":23,"status":30,"type":0,"chaishujia":{"username":"毛群","city":"珠海市"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003cp>书籍: 《终身成长》\u003c/p>\u003cp>开场：【自我介绍】\u003c/p>\u003cp>大家好，我叫毛群，是今天的3-2拆书家，来自岳阳，有两个女儿的拆书爱好者。\u003c/p>\u003cp>我的拆页大概耗时25分钟左右，主题是：如何用成长型思维表扬孩子\u003c/p>\u003cp>场景：邻居夸女儿很能干，帮我干活时，我总是谦虚地说：＂哪里，哪里呀，已经半个月没搞卫生了，实在看不下去了＂\u003c/p>\u003cp>女儿参加的校合唱团，为了准备六一节目，连续几天一上午都在排练，回来向我诉说的时候，我只是说：＂哦，你们真棒！＂我一时不知道怎么表扬她？\u003c/p>\u003cp>女儿上了绘画课回来，把画拿到我面前炫耀，我说：＂画得真好看，＂\u003c/p>\u003cp>提问：不知道大家有没有和我类似的经历，在孩子向我们寻求肯定欣赏时。要么不敢表扬孩子，要么表扬＂你真棒＂＂你真聪明＂＂给你点赞＂，这样的表扬会让孩子体验到什么呢，对他们有什么影响呢？\u003c/p>\u003cp>影响：\u003c/p>\u003cp>这样的表扬让孩子形成一种认知：我就是很棒，很聪明！我要保持住，失败意味着我很愚蠢，这样的认知让他们失去学习动力和表现力，形成对自己的固定思维模式。最重要的是孩子无法知道自己到底怎么做才能做好？\u003c/p>\u003cp>解决：遇到类似的情况，怎么办呢？\u003c/p>\u003cp>今天我们要拆的这本《终身成长》，通过大量的案例介绍了两种思维模式：固定型思维和成长型思维，以及两种思维所带来的不一样的人生，我们家长学习后，不断地练习就能将固定型思维转变成成长型思维，用成长型思维表扬孩子，孩子更愿意面对困难、挑战，也能拥有积极向上的态度，不断突破自己。\u003c/p>\u003cp>【学习目标】\u003c/p>\u003cp>通过今天的学习，大家现场能完成一次用成长型思维模式表扬孩子的剧本，下次遇到有需要表扬来肯定孩子的场景，能想到或运用成长型思维模式表扬孩子。看到自己努力的过程，指引她走向正确的方向。\u003c/p>\u003ch1>A1：【反思过去】在开始之前，我给大家设计了一个自测题，来看看大家对表扬孩子的概念处在一个什么模式里。下面请花1分钟时间根据自己的情况快速做一下。1代表完全不符合，6代表非常符合。请仔细阅读下面表格中的每一句话，根据自己的实际情况为自己打分(1代表完全不符合，6表示非常符合)。\u003c/h1>\u003cp>【自测表解释】\u003c/p>\u003cp>好，我看大家都已经测完了。\u003c/p>\u003cp>请问有没有小伙伴的得分在25分以上？恭喜你，在表扬孩子方面，你是一位成长型思维的家长，孩子也更愿意接受挑战。\u003c/p>\u003cp>12-25分的伙伴请举一下手，你在某些方面表扬孩子表现出成长型思维，某些方面是固定型思维。\u003c/p>\u003cp>最后，请问有没有12分以下的？那你们真是太幸运了，今天的分享就是为你量身打造的，\u003c/p>\u003cp>希望今天的学习中，你们能够掌握三个步骤来学会用成长型思维表扬孩子。让孩子相信通过学习可以成长，他也收获成长型思维。\u003c/p>\u003cp>在这里给大家解释一下：\u003c/p>\u003cp>大家不要因今天的测试，或某一方面是固定型思维或成长型思维，也就认定自己是某一种思维模式，比如有人会认为学习成绩可以通过学习提升，认为性格是不变的，那么在学习方面的认知。他是成长型思维。在性格方面的认知，就是固定型思维。所以，我们每个人都同时拥有两种思维模式。成长型和固定性思维，只是表现得方面不一样而已，今天的测试也并不代表永远不变，他也可以通过学习而改变的。\u003c/p>","ratings_count":1,"texts":[{"id":15987,"quote":"\u003cp>下面给大家1分钟的时间阅读手中的原文片段，阅读的时候可以圈出你认为的关键词。\u003c/p>\u003cp>原文片段P 215\u003c/p>\u003cp>父母们认为，通过表扬孩子的头脑和天赋－－他们可以给予孩子们持久的自信心－－就像送给孩子一份礼物一样，但事实上这行不通，还起了反效果。这种做法会让孩子在遇到困难，或者任何事出现问题的时候，立即对自己产生怀疑。如果父母真想送给孩子一份礼物，最好的就是教会他们热爱挑战，从错误中吸取教训，享受过程的努力的过程，不断学习，只有这样，孩子们才不会成为赞扬的奴隶。他们将拥有一种可以建立和修复自信心的终生有效的方法。\u003c/p>\u003cp>\u003cstrong>传递注重过程和成长的信息\u003c/strong>\u003c/p>\u003cp>所以，什么样的做法可以替代我们对才能和智力的赞扬呢？戴维对我那番安抚的话给了我们一些启示。我的一位学生则在这方面给了我们更多的信息：\u003c/p>\u003cp>这周末我回到家，发现我12岁的妹妹因为在学校里发生的一些事异常开心。我问他到底为什么如此兴奋，他告诉我说：＂我在社会学考试中得了102分！＂这句话她在那个周末至少重复了五遍。那时候，我决定将课上学到的内容付诸实现，我没有表扬她的智力和她获得的成绩，而是问了她一些问题，这些问题会让她回想起自己付出了多少努力学习，而且这一年中她取得了多大的进步。去年，她的成绩不断下滑，所以我认为在今年刚开始的这个时候，我有必要在此时出面，指引她走往正确的方向。\u003c/p>","explains":"\u003cp>What\u003c/p>\u003cp>我们在场的小伙伴，以前有没有在表扬孩子的时候说过＂你真棒！＂＂你真聪明＂给你点赞，你学得真快＂类似的表扬的话呢？\u003c/p>\u003cp>有，\u003c/p>\u003cp>从原文拆页片段的描述来看，原文认为我们这样做是否合理呢？\u003c/p>\u003cp>不合理\u003c/p>\u003cp>那原文片段建议我们从哪些方面去表扬孩子呢？\u003c/p>\u003cp>\u003cstrong>＂努力过程＂和＂成长的信息＂\u003c/strong>\u003c/p>\u003cp>大家对原文的理解确实很到位，努力过程和成长的信息，确实是成长型思维想表达的点。\u003c/p>\u003cp>＂你真棒＂＂真聪明＂＂你学得真快＂\u003c/p>\u003cp>类似的表扬听起来像是鼓励、帮助孩子增加自信心的信息，实际上孩子从这些话里听到的信息可能是：\u003c/p>\u003cp>如果我学得不那么快我就不聪明了，\u003c/p>\u003cp>我以后不应该尝试太难的事情，不然他们不会夸我了。\u003c/p>\u003cp>我最好不要努力学习。不然他们会觉得我其实没那么聪明。\u003c/p>\u003cp>Why\u003c/p>\u003cp>是的，孩子们都喜欢被表扬，他们尤其喜欢别人表扬自己的智力和天赋，这种称赞确实能给给他们带来特别的喜悦感，但这种感觉只能维持很短的时间，一旦遇到困难，他们的自信心就会消失，积极性也会跌到谷底，如果成功意味着他们很聪明，那么失败则意味着他们很愚蠢。这就是固定器思维模式表扬带给他们的影响。\u003c/p>\u003cp>那如何用成长型思维表扬孩子？\u003c/p>\u003cp>让孩子认为自己的能力是可以提高的。产生学习的欲望，因此会勇于迎接挑战，重视努力的过程，获得成长？以下是我提练出的成长型思维模式表扬孩子的步骤。\u003c/p>\u003cp>How：\u003c/p>\u003cp>第一步：了解事实或互动，\u003c/p>\u003cp>培养成长型思维最好的方法，不是在事后表扬，而是在孩子完成任务的过程中与孩子互动。\u003c/p>\u003cp>如果我们没有参与到孩子的任务过程中，我们也可以通过提问、观察，了解孩子在完成任务的过程中间使用了什么有趣的策略或方法，他是怎么想到的？遇到了什么困难或挑战？发生了什么？\u003c/p>\u003cp>来说说，开篇我女儿参加的校合唱团准备六一活动的故事，假如下次有类似的事情发生的话，我会用成长型思维模式来表扬孩子，我会这么做：\u003c/p>\u003cp>我会问孩子发生了什么事情要练习一上午？\u003c/p>\u003cp>他说老师让我们一个节点地唱好，高声部唱好了，低声部又唱得不好。唱着唱着就过了吃中午饭的时间了，老师又说还有一点点唱好了，就可以下课了，结果我们都饿得受不了。\u003c/p>\u003cp>那当你饿得受不了的时候，你还愿意配合老师练习吗？他说有点愿意，也有点不愿意，我问为什么呢？\u003c/p>\u003cp>他说：＂我喜欢唱歌，我觉得我们唱得很好听。不愿意就是肚子饿了。\u003c/p>\u003cp>第二步：表扬努力过程信息：\u003c/p>\u003cp>比如努力的过程，是否尝试新的策略，利用资源，用一个词概括他的卓越品质.......\u003c/p>\u003cp>我会说：＂小钰，当你说你肚子饿了还在认真的唱歌时，而且还唱了一上午。我感受到你很热爱唱歌，你是一个很有毅力的人。＂\u003c/p>\u003cp>第三步：表扬成长信息：\u003c/p>\u003cp>现在和以前比，有成长的具体的细节或内容。\u003c/p>\u003cp>我会说：“听到你唱的合唱团的歌越来越好听了！你们合唱的视频给人一种美和力量感，让人很感动。”\u003c/p>\u003cp>预防异议\u003c/p>\u003cp>可能有的家长会说：＂我夸孩子的努力，但是没有用？＂\u003c/p>\u003cp>那我也想问问您的孩子真的很努力吗？我们永远不要认为孩子并没有真正付出努力，而我们去称赞他的努力过程，就会带来积极的结果。\u003c/p>\u003cp>当日常生活中，遇到孩子值得表扬的事件时，比如帮叔叔阿姨按了电梯呀，或者打了招呼。我们可以不用第一步了解事实或者互动。直接用第二步和第三步。\u003c/p>","interaction":"\u003ch1>\u003cstrong>A3：场景演练\u003c/strong> 为了加深大家对知识的印象，下面马上进入一个真枪实弹的场景演练。请仔细听我的场景和指令：\u003c/h1>\u003cp>【给出具体场景】\u003c/p>\u003cp>小钰今年10岁，期末考试，数学考了95分，比他预期的分数要高，回家后他说：“真不敢相信我的数学考了95分，比去年进步了5分”，妈妈观察到：他今年对数学的兴趣程度越来越高了，上课愿意积极举手回答问题了，自己做了一个错题本，会记录出错的原因和下次改进的方法。曾经觉得数独作业好难，一个数独作业2 个小时都做不出来，经过她和妈妈一起找规律，找到一个规律之后，她自己找到了其它的规律，现在4分钟就能做一个数独作业。比妈妈快多了。数独作业培养了一些数学思维。\u003c/p>\u003cp>【给出清晰指令】\u003c/p>\u003cp>下面给大家5分钟的时间，一个人代表妈妈，一个人代表小钰，妈妈用今天学习到的成长型思维表扬小钰，请大家设计出来的整个过程填写在表格中，写完后小组内先分享，待会我请一组伙伴来分享一下。\u003c/p>\u003cp>【现场演练】\u003c/p>\u003cp>第一步：了解事实或互动，\u003c/p>\u003cp>培养成长型思维最好的方法，不是在事后表扬，而是在孩子完成任务的过程中与孩子互动。\u003c/p>\u003cp>如果我们没有参与到孩子的任务过程中，我们也可以通过提问、观察，了解孩子在完成任务的过程中间使用了什么有趣的策略或方法，他是怎么想到的？遇到了什么困难或挑战？发生了什么？\u003c/p>\u003cp>妈妈（陈兴）：小钰，这次期末考试真的考了95吗？\u003c/p>\u003cp>小钰：是的，很得意的表情\u003c/p>\u003cp>妈妈（陈兴）：太棒了，考这么好。今年为什么考95分呢？\u003c/p>\u003cp>小钰：因为今年有兴趣了，我还做了一个错题本，会记录出错的原因和下次改进的方法。上课也愿意积极回答问题。\u003c/p>\u003cp>第二步：表扬努力过程信息：\u003c/p>\u003cp>妈妈：\u003c/p>\u003cp>妈妈（陈兴）：妈妈觉得你之前一个数独作业2 个小时都做不出来，现在4分钟就能做一个数独作业。说明你花了很多心思来做作业。\u003c/p>\u003cp>通过数独作业的进步，你对数学的兴趣程序也高了。还有一些很实际的努力的动作。比如：上课愿意积极举手回答问题了，自己做了一个错题本，会记录出错的原因和下次改进的方法，说明你努力的方向和方法越来越对了。\u003c/p>\u003cp>小钰：嗯，是的。\u003c/p>\u003cp>第三步：表扬成长信息：\u003c/p>\u003cp>妈妈（陈兴）：妈妈不是一定要打100分，今年95分比去年高了5分就是成长。因为你努力了。\u003c/p>\u003cp>谢谢陈兴和潇潇的演练，非常精彩，特别是表扬过程，非常细致，很有鼓励、激励孩子更愿意挑战的感觉。 \u003c/p>\u003ch1>\u003cstrong>A2：我的应用\u003c/strong> 【布置作业——特定任务】\u003c/h1>\u003cp>今天的分享基本上进入尾声了，但是我们的实践才刚刚开始！因为级别对时间限制的原因，就给大家布置一个家庭作业去实践吧：现在还是周四的晚上，那就有请大家在明天或周末，用成长型思维三步骤表扬孩子，完成一次实际的运用。\u003c/p>\u003cp>知识有用，是因为知识有被运用。我们今天的学习有没有用，就看大家有没有实际去运用，完成的伙伴请拍照发给我，或语言发给我。我送一个小小的惊喜给你。\u003c/p>\u003cp>李林分享：\u003c/p>\u003cp>李林：我们家孩子暑假在学习游泳，以前他游泳的时候，我在旁边等她学完了，带她回家，学习了之后，我放下手机，她学习的时候，我在旁边观察。看看她有哪些进步？有哪些动作做得比较好，然后回家的路上就会和孩子一起讨论。\u003c/p>\u003cp>第一步：了解事实或互动，\u003c/p>\u003cp>李林（妈妈）：我看你在游泳时，教练老说要你放松，你是怎么做到放松的呀？\u003c/p>\u003cp>孩子：我刚开始想象自己是一条鱼，不管用，老是害怕沉下去。就是想像自己是一片树叶，想像自己很轻。就好一点了。\u003c/p>\u003cp>李林（妈妈）：天啦！效果这么好，你是怎么想到的呀？是有一个小朋友告诉我的呀。\u003c/p>\u003cp>孩子： 是有一个小朋友告诉我的呀。\u003c/p>\u003cp>李林（妈妈）：你把你的想法告诉他了？\u003c/p>\u003cp>孩子：嗯，\u003c/p>\u003cp>第二步：表扬努力过程信息：\u003c/p>\u003cp>李林（妈妈）：妈妈看到你把遇到的困难和同伴一起分享，学习他的好的经验。你是一个愿意向他人学习的人。遇到困难时，还愿意坚持，说是你很有毅力。\u003c/p>\u003cp>孩子：嗯，很开心。\u003c/p>\u003cp>第三步：表扬成长信息：\u003c/p>\u003cp>李林（妈妈）：你今天游泳时间比昨天多游了10分钟，踢水的动作每一天都有进步。\u003c/p>\u003cp>【结语】\u003c/p>\u003cp>好了，希望今天的分享对大家有所帮助，再次感谢。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1627914593000,"updated_at":1629424030000,"ria":true},{"id":11943,"topic":"成长型思维","learn_goal":"","remark":"面对同一个问题，不同的人会有不同的选择。不同的选择造就不一样的人生！我们不禁要问：为什么同一个问题有不同的选择呢？","level":"TF3-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"毛群","city":"珠海市"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003cp>开场：\u003c/p>\u003cp>【自我介绍】\u003c/p>\u003cp>大家好，我叫毛群，是今天的3-1拆书家，\u003c/p>\u003cp>来自岳阳，有两个女儿的拆书爱好者。\u003c/p>\u003cp>我的拆页大概耗时20分钟左右，主题是：成长型思维模式\u003c/p>\u003cp>场景：最近呀，当我面对拆书稿修改了几次也不合格时，我的内在会有个声音对自己说：＂我对知识的领悟和吸收能力是有限的，我不擅长在拆书这方面的学习能力培养。＂\u003c/p>\u003cp>＂如果我成为了三级拆书家，不能去讲好一场拆书课？或者变现？这样努力不是白费时间吗？＂大家猜想得到，我这样的思维模式，肯定是想放弃拆书了。\u003c/p>\u003cp>提问：不知道在场的小伙伴有没有和我类似的体验呢？比如当你的工作或生活中某到了挑战，你也尝试过努力，当暂时突破不了时，你可能会怀疑自己在这方面的能力是不是不适合？害怕努力之后还是要面对失败？你会怎么思考呢？\u003c/p>\u003cp>影响：\u003c/p>\u003cp>思维决定行为，当我们把问题归结于能力不变，努力也没用，行为上消极懈怠，以致于升学失败、职场表现平平，甚至被淘汰....本质上是固定型思维的问题。\u003c/p>\u003cp>解决：\u003c/p>\u003cp>面对类似的问题和场景，我们有什么合适的方法呢？有的，\u003c/p>\u003cp>今天我们要拆的这本《终身成长》，通过大量的案例介绍了两种思维模式：固定型思维和成长型思维，以及两种思维所带来的不一样的人生，学习后就能将固定型思维转变成成长型思维，面对困难、挑战时，能不断突破自己。\u003c/p>","ratings_count":1,"texts":[{"id":15895,"quote":"\u003cp>下面请大家花1.5分钟的时间来阅读原文，阅读后请抬头示意我一下。\u003c/p>\u003cp>阅读原文，《终身成长》  P6\u003c/p>\u003cp>请想象一下，尽可能生动地去想，你是一个年轻人，经历了非常糟糕的一天：\u003c/p>\u003cp>你去上一门对你来说很重要的课，而且你非常喜欢这门课。你的教授公布了期中考试成绩，你得了C+。你非常失望，等到晚上准备回家的时候，你发现自己的车上贴了一张违章停车罚单。你感到非常泄气，打电话给最好的朋友想要倾诉，但是却没有打通。\u003c/p>\u003cp>你会怎么想？你会有什么样的感受？你会怎么做？当我问固定型思维模式者时，他们是这样对我说的：“我感到被拒绝了。”“我是个失败者。”“我是个傻瓜。”“我感到自己很没用而且愚蠢——所有人都比我优秀。”“我太差劲了。”换句话说，他们会把发生的事当作一个衡量自己的能力和价值的直接的标尺。\u003c/p>\u003cp>他们会这样看待自己的生活：“我的人生太可悲了。”“我没有人生。”“楼上的那个人不喜欢我。”“这个世界跟我过不去。”“有人想要毁掉我。”“没有人爱我，所有人都恨我。”“生活是不公平的，所有的努力都是白费。”“生活太糟糕了，我太傻了。”“我身上没发生过什么好事。”“我是地球上最不幸的人。”\u003c/p>\u003cp>他们是如何应对这些烦心事的呢？“我就不应该浪费这么多时间和精力去办一件事。”（换句话说，不会再让任何人来评判我。）“什么都不做。”“吃东西。”“找机会冲别人大吼。”“边听音乐边郁闷。”“躲到壁橱里坐着。”“找人打一架。”“哭。”“摔东西。”\u003c/p>\u003cp>“还能怎么办？”还能怎么办！你知道，在模拟这个情景的时候，我特意将成绩写成了C+而不是F，只把考试设定成期中考试而不是期末考试，你的车只是被贴了罚单而不是被毁了，打电话给朋友倾诉之举只是没有成功，你并没有被朋友直接拒绝。没有什么灾难性或不可逆转的事情发生，但仅仅是在这些情况的影响下，固定型思维模式者就已经产生了这种彻底的失败感和无力感。\u003c/p>\u003cp>当我把这些情况原封不动地拿给那些成长型思维模式者看后，他们是这样说的：\u003c/p>\u003cp>“我会更努力地学习，下次停车的时候我要更加小心一些，不知道我的朋友是不是今天过得不开心。”\u003c/p>\u003cp>“C+这个成绩告诉我，我必须在课堂上加倍付出努力，我依然有半个学期的时间来提高我的成绩。”\u003c/p>\u003cp>那么，他们会如何应对呢？\u003c/p>\u003cp>“我必须开始考虑，为了下一次测验，我要更努力地学习（或者换个学习方法），我会缴清罚款，下次再给朋友打电话的时候，我们再好好聊聊。”\u003c/p>\u003cp>“我会总结我在期中考试到底犯了哪些错误，下一次要做的更好。”\u003c/p>\u003cp>“下一次停车的时候，我要小心一些。”\u003c/p>\u003cp>不是说你必须拥有某种思维模式，而拥有另一种思维模式的人就会产生挫败感。谁不是这样呢？糟糕的成绩、朋友或爱人的拒绝都不是什么开心的事，没有人会喜欢这些糟糕的事情。只是这些有着成长型思维的人不会给自己贴上标签，或对自己失去信心。即使他们感到沮丧，他们也准备好了去承担风险，直面挑战，继续为此奋斗。\u003c/p>","explains":"\u003cp>【学习目标1】\u003c/p>\u003cp>好的，我看到大家都已阅读完毕，我们来开启今天的拆书之旅。\u003c/p>\u003cp>通过今天的学习，大家能够分辨出自己在处理某些事情上的思维模式是成长型思维，还是固定性思维？当未来觉察到固定思维模式在影响自己或他人时，能想到或运用激发成长型思维模式的三步曲，获得成长。\u003c/p>\u003cp>I：【why】\u003c/p>\u003cp>最近我在看《觉醒年代》，突然感悟到：人与人之间本质的差别，是思维模式的不同。思维模式在影响着我们面对同样的问题时，做不同的选择和行动。\u003c/p>\u003cp>【What】\u003c/p>\u003cp>在这本书里，作者向我们表示：我们每个人都同时拥有两种思维模式固定型思维模式和成长型思维模式，每个人因个体差异不一样，会在不同的领域展现出不同的思维模式。\u003c/p>\u003cp>书中给的定义：固定型思维模式认为自己的能力是一成不变。拥有成长型思维模式时，我们相信智力、能力是可以提高的，就会产生学习的欲望，因此会勇于迎接挑战、重视努力过程、从批评中、他人的成功中学习，获得成就或成长。\u003c/p>\u003cp>今天我们通过一些案例来深入了解什么是成长型思维模式。\u003c/p>\u003cp>第一个案例：刚才关于我拆书的案例，我认为自己在拆书方面的能力天生就欠缺，努力也没有用。\u003c/p>\u003cp>大家觉得这是不是成长型思维模式？\u003c/p>\u003cp>对，不是的，这是典型的固定思维模式，我认为能力是天赋，是已经注定的，不变的。如果有天赋的话，就不需要更多的努力就会写好拆书稿。不可否认天赋确实会有影响，但相比思维模式的影响小多了，甚至可以忽略不计。\u003c/p>\u003cp>所以区分成长型思维和固定型思维的关键点之一是：是否“相信”能力是可以提高的。\u003c/p>\u003cp>第二个案例：女儿学了几年的钢琴，作为孩子的家长非常尽职尽责的督促孩子的练习。几年下来，一直夸孩子：“你真棒，你只要努力练习，妈妈相信你一定可以成为音乐家的。”孩子的能力几乎没有进步。\u003c/p>\u003cp>请问这是成长型思维模式吗？对，不是的，还是固定思维模式，这位家长相信能力是可以通过练习提高，他用了夸奖孩子的方法，但是孩子的能力没有提高。如果是成长型思维的家长就会通过改变策略及具体的行为，让能力得到成长。用到的方法可能就不只是夸奖孩子。\u003c/p>\u003cp>所以区分成长型思维和固定型思维的关键点之二是：有没有通过改变策略，来获得能力的成长。\u003c/p>\u003cp>案例三：还是这位学琴的孩子，当她在学习的过程遇到挑战或挫败了，想放弃的时候。这位家长像这是孩子突破对自己认知的一个机会，而且，除了欣赏孩子，肯定孩子之外，不断地改变策略，比如：从孩子的兴趣点，找合适的老师，营造一些孩子喜欢的学习氛围和表演机会等等。\u003c/p>\u003cp>这位家长是成长型思维模式吗？对，确实是成长型思维模式。他不仅“相信能力是可以提高”的，他也一直和孩子一起不断的改变策略和“提高”能力。\u003c/p>\u003cp>所以，拥有成长型思维模式时，能够持续努力精进，它最后的结果一定是指向成长的。\u003c/p>\u003cp>也正是因为这一点，越来越多的人希望具有成长型思维，但是思维模式的转变不是靠一个小花招就能改变的，他是一个比较长期的过程，并需要不断的激发对成长型思维的认知，刻意练习并面对，增加我们使用成长型思维模式思考的机会，自然会减少固定型思维模式思考。那我们如何激发成长型思维模式呢？\u003c/p>\u003cp>【How】\u003c/p>\u003cp>关于开篇，我讲的我个人关于拆书的案例。当我学习了成长型思维模式之后。下次又遇到修改好多次都达不到技能点的要求时。我会这么做：\u003c/p>\u003cp>第一步：觉察，觉察此刻内在的想感受是？我们对能力的判断是？我们的思维模式是？\u003c/p>\u003cp>我会觉察到自己有些挫败，认为自己天生不具备拆书需要的能力，如果努力的话，也会需要比别人更长的时间，甚至还不会有成绩。我判断我处在固定型思维模式里。\u003c/p>\u003cp>第二步：接纳，接纳我们的固定思维，用语言描述我们的接纳，并把他当成一次成长的机会。\u003c/p>\u003cp>我对自己说：＂我只足暂时现在不会，但不代表我永远不会，不会，意味着是提升这方面能力的一次机会。\u003c/p>\u003cp>第三步：改变策略，拓展能力，\u003c/p>\u003cp>为了达到拓展能力的目标，我们可以从两方面去思考改变策略的方向。\u003c/p>\u003cp>1. 盘点资源：有什么资源可以帮助到我们拓展能力？\u003c/p>\u003cp>2. 行为层面：我要改变什么行为拓展能力呢？\u003c/p>\u003cp>我会怎么做呢？\u003c/p>\u003cp>1.盘点资源：我会向优秀的拆书家、师父请教，去官网找资源，看看别人是怎么写的。\u003c/p>\u003cp>2.行为层面：自己每周写1-2篇自己的收获，做得好的地方。把自己感兴趣的片段，用拆书的方法写一写，生活中去运用。\u003c/p>\u003cp>以上就是我个人的一个案例。\u003c/p>\u003cp> 以上我称之为激发成长型思维三步曲。\u003c/p>\u003cp>预防异议\u003c/p>\u003cp>也请大家注意：成长型思维模式相信能力是可以培养的，但它并不能告诉你你能改变多少或者需要多长时间才能改变，并不意味着每一件可以被改变的事都应该被改变。我们需要接受自己的一些不完美之处，特别是那些并不会给我们自己或别人带来危害的。\u003c/p>","interaction":"\u003cp>A2\u003c/p>\u003cp>我们拆书帮提倡：＂大脑中过一遍，等于实际应用一遍。＂接下来是大家应用的环节，请各位用激发成长型思维三步曲，编写一个剧本。\u003c/p>\u003cp>试想未来的一周或一个月里，你的孩子、家人或者是朋友，遇到困难，他们习惯性的想中途放弃或否定自己，你会如何使用激发成长型思维三步曲与他沟通呢？\u003c/p>\u003cp>剧本中要有故事的背景、人物和情节变化（起因，经过，结果）和双方的对话、动作等。给大家的时间是5分钟，5分钟之后，请一位伙伴分享。\u003c/p>\u003cp>谢谢探探的分享\u003c/p>\u003cp>今天，我们通过现场拆解，了解了成长型思维模式和固定型思维模式的区别还有如何用成长型思维模式思考。OK，以上就是我要拆解的全部内容，感谢大家的聆听。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1626710087000,"updated_at":1627540035000,"ria":true},{"id":11320,"topic":"培养成长型思维","learn_goal":"","remark":"培养成长型思维，成为人生赢家","level":"TF3-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"DorisPGY","city":"深圳市"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"\u003cp>大家好，我是今天的拆书家Doris。今天带拆的这本书是《终身成长》。先给大家分享一个真实的故事。\u003c/p>\u003cp>【事件场景】\u003c/p>\u003cp>故事的主角是小A，小A是一名HR，毕业4、5年来，她总是觉得自己不擅长表达，所以一直负责员工的薪酬福利的工作，每次老板希望小A做一些培训或开会讲话的事情，小A总是非常抗拒说，我不太擅长表达，要不还是让小B来吧，就这样小A一直默默的低头做事，没有得到任何的晋升机会。\u003c/p>\u003cp>【提问】\u003c/p>\u003cp>在座的小伙伴，有没有遇到过类似的经历呢？（有小伙伴点头）面对自己不擅长的工作，你是勇敢的接下挑战？还是直接拒绝机会呢？（有小伙伴说：不做没有把握的事情）。\u003c/p>\u003cp>【影响】\u003c/p>\u003cp>如果我们遇到不擅长的事情就逃避，那我们会失去什么呢？（有人说：失去晋升或成长的机会）那我们就会错失很多成长的机会，就像前面的小A，虽然自己份内的工作做的也不错，但一直没有晋升机会，曾经的她甚至因为没有获得所谓的“想要的成长”而焦虑，纠结要不要换一个工作。\u003c/p>\u003cp>【解决】\u003c/p>\u003cp>我们常说：一个人的气质里藏着他的经历，其实一个人的思维里也藏着他的未来。今天带拆的这本《终身成长》，书中通过大量的案例介绍了两种思维模式：固定型思维和成长型思维，以及两种思维所带来的不一样的人生，通过今天的分享，希望大家在面对失败和挑战的时候，采用成长型思维模式的“三步曲”，获得终身成长，成为人生赢家。\u003c/p>","ratings_count":1,"texts":[{"id":15245,"quote":"\u003cp>\u003cstrong>请大家花2分钟的时间，看一下拆页，看完的小伙伴抬头示意我一下。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cu>终身成长：培养自己的成长型思维模式\u003c/u>\u003c/strong>\u003c/p>\u003cp>请想象一下，尽可能生动地去想，你是一个年轻人，经历了非常糟糕的一天：\u003c/p>\u003cp>你去上一门对你来说很重要的课，而且你非常喜欢这门课。你的教授公布了期中考试成绩，你得了C+。你非常失望，等到晚上准备回家的时候，你发现自己的车上贴了一张违章停车罚单。你感到非常泄气，打电话给最好的朋友想要倾诉，但是却没有打通。\u003c/p>\u003cp>你会怎么想？你会有什么样的感受？你会怎么做？当我问固定型思维模式者时，他们是这样对我说的：“我感到被拒绝了。”“我是个失败者。”“我是个傻瓜。”“我感到自己很没用而且愚蠢——所有人都比我优秀。”“我太差劲了。”换句话说，他们会把发生的事当作一个衡量自己的能力和价值的直接的标尺。\u003c/p>\u003cp>他们会这样看待自己的生活：“我的人生太可悲了。”“我没有人生。”“楼上的那个人不喜欢我。”“这个世界跟我过不去。”“有人想要毁掉我。”“没有人爱我，所有人都恨我。”“生活是不公平的，所有的努力都是白费。”“生活太糟糕了，我太傻了。”“我身上没发生过什么好事。”“我是地球上最不幸的人。”\u003c/p>\u003cp>他们是如何应对这些烦心事的呢？“我就不应该浪费这么多时间和精力去办一件事。”（换句话说，不会再让任何人来评判我。）“什么都不做。”“吃东西。”“找机会冲别人大吼。”“边听音乐边郁闷。”“躲到壁橱里坐着。”“找人打一架。”“哭。”“摔东西。”\u003c/p>\u003cp>“还能怎么办？”还能怎么办！你知道，在模拟这个情景的时候，我特意将成绩写成了C+而不是F，只把考试设定成期中考试而不是期末考试，你的车只是被贴了罚单而不是被毁了，打电话给朋友倾诉之举只是没有成功，你并没有被朋友直接拒绝。没有什么灾难性或不可逆转的事情发生，但仅仅是在这些情况的影响下，固定型思维模式者就已经产生了这种彻底的失败感和无力感。\u003c/p>\u003cp>当我把这些情况原封不动地拿给那些成长型思维模式者看后，他们是这样说的：\u003c/p>\u003cp>“我会更努力地学习，下次停车的时候我要更加小心一些，不知道我的朋友是不是今天过得不开心。”\u003c/p>\u003cp>“C+这个成绩告诉我，我必须在课堂上加倍付出努力，我依然有半个学期的时间来提高我的成绩。”\u003c/p>\u003cp>那么，他们会如何应对呢？\u003c/p>\u003cp>“我必须开始考虑，为了下一次测验，我要更努力地学习（或者换个学习方法），我会缴清罚款，下次再给朋友打电话的时候，我们再好好聊聊。”\u003c/p>\u003cp>“我会总结我在期中考试到底犯了哪些错误，下一次要做的更好。”\u003c/p>\u003cp>“下一次停车的时候，我要小心一些。”\u003c/p>\u003cp>不是说你必须拥有某种思维模式，而拥有另一种思维模式的人就会产生挫败感。谁不是这样呢？糟糕的成绩、朋友或爱人的拒绝都不是什么开心的事，没有人会喜欢这些糟糕的事情。只是这些有着成长型思维的人不会给自己贴上标签，或对自己失去信心。即使他们感到沮丧，他们也准备好了去承担风险，直面挑战，继续为此奋斗。\u003c/p>","explains":"\u003cp>好的，我看到大部分小伙伴已经读完了。\u003c/p>\u003cp>【概念讲解】\u003c/p>\u003cp>拆页中描述了“糟糕的一天”，大家应该也会经常遇到这样不太顺利的一天吧？这段描述里，大家有特别注意到哪些关键词吗？（有人说：成长型思维，有人说：贴标签）是的，今天我们要讲解的核心概念就是“成长型思维”。什么是成长型思维呢？成长型思维认为：人的能力是可以通过努力培养的。他们不怕失败和挑战，专注于成长的过程，看重的是：我该做什么和怎么做，而不是“我能不能，我行不行”。下面我们通过几个场景，看一下什么是“成长型思维”。\u003c/p>\u003cp>1. 我的一个大学女同学前几天找抱怨说：我最近注册会计师考试，考了2门都挂了，我真的是太不擅长考试了。这是成长型思维吗？显然不是，因为2门考试挂了，她就给自己贴上了标签，觉得自己不擅长考试，成长型思维的人会接纳自己没有考好的这个事实，不去放大事件本身，也不会否定自己。就想拆页中所说：“不会给自己贴上标签，或对自己失去信心”。所以说成长型思维第一步就是接纳事实，不给自己贴标签。\u003c/p>\u003cp>2. 我们拆书家经常遇到的一个情况是：在线下分舵拆了几次，好不容易过了，上传到总舵，又被总舵的评审挂掉了，就像我这次的3-1，收到“再来一次”的结果后，我是有点沮丧的，但我是这样给自己做心理建设的：没事的，3-1本身就比较难，我才拆了2次，有问题很正常，而且大家给了我这么多的反馈，我下次肯定可以做的更好。我这是不是成长型思维？是的，我有沮丧的情绪，但是我更多的是鼓励自己，就像拆页中讲的“我会总结我在期中考试到底犯了哪些错误，下一次要做的更好”。成长型思维认为自己暂时没有做好，下次会更好。\u003c/p>\u003cp>3. 大家有没有过在地下停车场停车，但一直找不到车的情况呢？有一次我和我朋友花了半个小时才找到他的车，他当时就抱怨说：什么烂停车场，连个查询系统都没有，我反而说下次下车的时候，我们拍下位置和号码，所以我每次和他出去我都会特别记录一下停车的位置。请问我们谁是成长型思维的人？是的，我是那个成长型思维的人，就像拆页所讲“下一次停车的时候，我要小心一些。”想着发现自己的问题，选择下一次做出改变。\u003c/p>\u003cp>通过以上场景，我们已经知道了成长型思维的特点：不给自己贴标签，愿意肯定自己，并做出改变，那具体怎么做才能培养自己的成长型思维呢？我把它归结为三个步骤：\u003c/p>\u003cp>【清晰的How】\u003c/p>\u003cp>1. 接纳事实，但不否定自己：我们做不好一件事情，不要习惯性给自己贴标签或自我攻击，告诉自己我只是暂时没有做好这件事而已。\u003c/p>\u003cp>2. 多鼓励自己：遇到困难的时候，有负面情绪真的很正常，多鼓励自己，其实我这里做的不错，下次我那里可以做的更好，我就是做的不好，才需要不断努力。\u003c/p>\u003cp>3. 发现问题，选择改变：遇到困难，更多的是找到问题出在哪里，想一下哪里可以做的更好一点。\u003c/p>\u003cp>以上就是培养成长型思维的三步骤。\u003c/p>\u003cp>【转为正例】\u003c/p>\u003cp>大家还记得我开头提到的小A吗？其实那就是我自己，2020年前的我总是觉得自己不擅长表达，总是拒绝表达的机会，2020年因为这本书，我有了成长型思维的观念。2020年下半年，当我老板发现我Excel很不错，可以替代外部讲师给员工做培训，我就接下了这个工作，其实我第一期做的不太好，有点沮丧，但是呢，我转念一想：\u003c/p>\u003cp>首先，接纳自己不擅长表达的事实：过去几年的职场经验，我没有过多表现自己的机会，所以我的表达能力有所欠缺。\u003c/p>\u003cp>其次，多鼓励自己：我告诉自己：暂时的一次表现不好没什么，我会做的越来越好。\u003c/p>\u003cp>最后，发现问题，选择改变：第一次上课的时候，我发现没有更多的实操，大家还是不会做，我就迅速的调整内容，很快大家都跟上进度。\u003c/p>\u003cp>也正是因为这样的分享，我在公司树立了自己的IP，获得了疫情期间额外的升职加薪。以上就是因为成长型思维而让自己职场有转机的一个小故事。\u003c/p>\u003cp>【适用边界】 \u003c/p>\u003cp>那什么时候可以运用成长型思维呢？当我们面对困难，不知所措的时候；当我们面对失败，情绪沮丧的时候；当我们不擅长做某件事，一直不敢做的时候，都可以用成长型思维改变事情的发生。当然你可以用这样的方法指导别人，比如：下属不愿意上台演讲，你可以用成长型思维引导他增加公开讲话的机会等等。\u003c/p>","interaction":"\u003cp>那大家想一下，有没有类似的场景可以运用今天学到的成长型思维呢？（比如遇到困难特别想放弃的时候，又或者是遇到不擅长的事情特别想退缩的时候）。在大脑中过一遍，等于实际应用了一遍。\u003c/p>\u003cp>请接下来大家编写一个小故事，背景可以是未来1个月你的朋友或家人可能遇到挫折，他们习惯性的想中途放弃或否定自己，你打算运用成长型思维的三步骤来引导他们战胜困难，请大家花5分钟的时间来编写一下这个小故事，包含人物、情节变化（包括：起因、经过、结果）和简单的对话，5分钟后，我请一个小伙伴起来分享一下自己的对话，好吗？\u003c/p>\u003cp>\u003cstrong>&lt;学习者案例记录&gt;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>分享者：李广源\u003c/strong>\u003c/p>\u003cp>\u003cstrong>时间：周末，地点：家里沙发上，人物：我和老婆，起因：早晨去公司停车，很难找到车位，比较影响早晨的心情\u003c/strong>\u003c/p>\u003cp>\u003cstrong>老婆：我现在已经尽量早起去抢位置，有时候也不吃早饭，还是没有办法找到停车位。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>李广源：这个资源是我们没有办法改变的，也不能换工作。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>老婆：我已经尽最大努力了，还是让我很恼火。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>李广源：其实我也理解你，关键的现实是停车资源有限的问题（接纳事实），不是我们自己的错误，我不想你因为停车影响一天的心情（鼓励自己），那我们就想着改变作息习惯，早起，或者不想开车那就打车（做出改变）。\u003c/strong>\u003c/p>\u003cp>以上就是我今天的分享，希望大家在学了今天的拆页后，在心里种下这样的种子：我们的思维方式里真的藏着我们的未来。很多时候，我们总是掉进习惯性的思维陷阱里，跳不出来。但如果大脑里装着“成长型思维”，改变对待自己的态度，人生会大不相同。谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1618134910000,"updated_at":1618284326000,"ria":true},{"id":11164,"topic":"培养成长型思维","learn_goal":"","remark":"曾几何时，我是一个固定型思维的“胆小女孩”，开会不敢坐在前面，总怕被叫到发言，一直觉得自己不擅长沟通，喜欢给自己贴标签等等，突然有一天我听到了这本书《终身成长》，我被警醒：我完全可以“向前一步”，我可以通过努力让自己变得更好，所以现在的我愿意尝试曾经的不可能，因为我逐渐刻意练习我的“成长型思维”，更加专注于如何把事情做的更好。","level":"TF3-1","duration":20,"status":29,"type":0,"chaishujia":{"username":"DorisPGY","city":"深圳市"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"\u003cp>\u003cstrong>【技能点：学习目标】学习目标包含了学习者要完成行为的具体内容和完成程度，现场学习设计清晰，体现了该学习目标。\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次拆页后，在面对未知或挑战的时候，识别固定型思维，尝试刻意运用成长型思维的三步骤，制定出行动步骤或行动建议。\u003c/p>\u003cp>\u003cstrong>【技能点：场景介绍法】能够清晰辨别出聚焦于图书和学习主题的事件、提问、影响和解决4个步骤。\u003c/strong>\u003c/p>\u003cp>大家好，我是今天的拆书家Doris。今天带拆的这本书是《终身成长》。先给大家分享一个真实的案例。\u003c/p>\u003cp>【事件场景】\u003c/p>\u003cp>小A是一名HR，毕业4、5年来，她总是觉得自己不擅长沟通和表达，所以一直负责员工的薪酬福利的工作，每次老板希望小A做一些培训或开会讲话的事情，小A总是推辞说，我不太会讲话，要不还是让小B来吧，就这样小A一直在部门里默默的低头做事，几乎没有晋升机会。\u003c/p>\u003cp>【提问】\u003c/p>\u003cp>在座的小伙伴，有没有遇到过类似的经历呢？（有小伙伴点头）在面对自己不擅长的工作，你是勇敢的接下挑战？还是直接拒绝机会呢？\u003c/p>\u003cp>【影响】\u003c/p>\u003cp>如果我们总是逃避困难或挑战，那我们就会错失很多成长的机会，就像前面的小A，虽然自己的工作做的也不错，但一直没有晋升机会，曾经的她甚至因为没有获得想要的成长而焦虑，纠结要不要换一个工作。\u003c/p>\u003cp>【解决】\u003c/p>\u003cp>我们常说：一个人的气质里藏着他的经历，其实一个人的思维里也藏着他的未来。今天带拆的这本《终身成长》，书中通过大量的案例介绍了两种思维模式：固定型思维和成长型思维，以及两种思维所带来的不一样的人生，通过今天的分享，希望大家在面对失败和挑战的时候，采用成长型思维模式的“三步曲”，获得终身成长，成为人生赢家。\u003c/p>","ratings_count":1,"texts":[{"id":15080,"quote":"\u003cp>\u003cstrong>\u003cu>终身成长：培养自己的成长型思维模式\u003c/u>\u003c/strong>\u003c/p>\u003cp>请想象一下，尽可能生动地去想，你是一个年轻人，经历了非常糟糕的一天：\u003c/p>\u003cp>你去上一门对你来说很重要的课，而且你非常喜欢这门课。你的教授公布了期中考试成绩，你得了C+。你非常失望，等到晚上准备回家的时候，你发现自己的车上贴了一张违章停车罚单。你感到非常泄气，打电话给最好的朋友想要倾诉，但是却没有打通。\u003c/p>\u003cp>你会怎么想？你会有什么样的感受？你会怎么做？当我问固定型思维模式者时，他们是这样对我说的：“我感到被拒绝了。”“我是个失败者。”“我是个傻瓜。”“我感到自己很没用而且愚蠢——所有人都比我优秀。”“我太差劲了。”换句话说，他们会把发生的事当作一个衡量自己的能力和价值的直接的标尺。\u003c/p>\u003cp>他们会这样看待自己的生活：“我的人生太可悲了。”“我没有人生。”“楼上的那个人不喜欢我。”“这个世界跟我过不去。”“有人想要毁掉我。”“没有人爱我，所有人都恨我。”“生活是不公平的，所有的努力都是白费。”“生活太糟糕了，我太傻了。”“我身上没发生过什么好事。”“我是地球上最不幸的人。”\u003c/p>\u003cp>他们是如何应对这些烦心事的呢？“我就不应该浪费这么多时间和精力去办一件事。”（换句话说，不会再让任何人来评判我。）“什么都不做。”“吃东西。”“找机会冲别人大吼。”“边听音乐边郁闷。”“躲到壁橱里坐着。”“找人打一架。”“哭。”“摔东西。”\u003c/p>\u003cp>“还能怎么办？”还能怎么办！你知道，在模拟这个情景的时候，我特意将成绩写成了C+而不是F，只把考试设定成期中考试而不是期末考试，你的车只是被贴了罚单而不是被毁了，打电话给朋友倾诉之举只是没有成功，你并没有被朋友直接拒绝。没有什么灾难性或不可逆转的事情发生，但仅仅是在这些情况的影响下，固定型思维模式者就已经产生了这种彻底的失败感和无力感。\u003c/p>\u003cp>当我把这些情况原封不动地拿给那些成长型思维模式者看后，他们是这样说的：\u003c/p>\u003cp>“我会更努力地学习，下次停车的时候我要更加小心一些，不知道我的朋友是不是今天过得不开心。”\u003c/p>\u003cp>“C+这个成绩告诉我，我必须在课堂上加倍付出努力，我依然有半个学期的时间来提高我的成绩。”\u003c/p>\u003cp>那么，他们会如何应对呢？\u003c/p>\u003cp>“我必须开始考虑，为了下一次测验，我要更努力地学习（或者换个学习方法），我会缴清罚款，下次再给朋友打电话的时候，我们再好好聊聊。”\u003c/p>\u003cp>“我会总结我在期中考试到底犯了哪些错误，下一次要做的更好。”\u003c/p>","explains":"\u003cp>\u003cstrong>目标：拆书家给出清晰的具体行动建议或具体步骤（举出案例，通过概念与匹配例子之间对比，引出知识点逻辑、步骤等；或主动给出貌似相近或相反的概念，并辨析混淆概念之间的细微差异，让学习者清晰知识点的适用边界。\u003c/strong>\u003c/p>\u003cp>好的，我看到大部分小伙伴已经阅读完了。\u003c/p>\u003cp>【概念讲解】\u003c/p>\u003cp>拆页中描述了“糟糕的一天”，大家应该也会经常遇到这样不太顺利的一天吧？这段描述里，大家有特别注意到哪几个关键词吗？（学习者回答：固定型思维、成长型思维、贴标签）是的，今天我们要讲解的核心概念就是“成长型思维”。成长型思维指的是什么呢？成长型思维认为：人的能力可以通过努力培养的。他们不怕失败和挑战，专注于成长的过程，看重的是：我该做什么和怎么做。固定型思维认为，人的能力是一成不变的。他们喜欢回避失败与挑战，更看重：我是一个什么样的人；下面我们一起回顾一下书中的内容，对比一下“成长型思维”和“固定型思维”的区别。\u003c/p>\u003cp>1. 面对糟糕的一天，书中的固定型思维的人是怎么看待自己的呢？他是不是说“我是个失败者”，“我太差劲了”，他们习惯性的给自己贴标签，因为所发生的糟糕的事情来否定自己，成长型思维的人会接纳事实，认为我只是暂时没有做好这件事而已，不去否定自己。2. 因为这样糟糕的一天，固定型思维的人这样看待自己的生活：这个世界跟我过不去，生活太糟糕了，他们更多的是抱怨，而成长型思维的人认为，C+这个成绩告诉我，我必须在课堂上加倍付出努力。也会有不好的情绪，但是他们更多的是鼓励自己。\u003c/p>\u003cp>3. 固定型思维的人，应对烦心事的方式是：什么都不做，哭，找机会冲别人大吼。他们没有做出实质性的改变，只是逃避问题。成长型思维的人则想着下次停车的时候要更加小心一些，我要更努力地学习（或者换个学习方法），他们想着发现问题，并选择下一次做出改变。\u003c/p>\u003cp>【概念对比图】\u003c/p>\u003cp>通过对比，我们已经知道了成长型思维的特点：不给自己贴标签，愿意肯定自己，并做出改变，那具体怎么做才能培养自己的成长型思维呢？我把它归结为三个步骤：\u003c/p>\u003cp>【清晰的How】\u003c/p>\u003cp>1. 接纳事实，但不否定自己：如果我们做错了事情，不要习惯性给自己贴标签或自我攻击，告诉自己我只是暂时没有做好这件事而已。\u003c/p>\u003cp>2. 多鼓励自己：遇到困难或受挫的时候，有负面情绪真的很正常，但不要过分抱怨，多告诉自己下次可以做的更好。\u003c/p>\u003cp>3. 发现问题，选择改变：遇到问题更多的是反思自己，找到问题出在哪里，想一下哪里可以做的更好一点。\u003c/p>\u003cp>以上就是培养成长型思维的三步骤。\u003c/p>\u003cp>【转为正例】\u003c/p>\u003cp>大家还记得我开头提到的小A吗？其实那就是我自己，2020年前的我总是觉得自己不擅长沟通和表达，每次老板让我在大家面前讲话的时候，我都非常勉强，2020年因为这本书，我心里开始有了成长型思维的概念。2020年下半年，当我老板发现我Excel很不错，可以替代外部讲师，给员工做内训师的时候，我接下了这个工作，其实我第一期做的不太好，有点沮丧，但我转念一想：\u003c/p>\u003cp>首先，接纳自己不擅长表达的事实：过去几年的职场经验，我没有过多表现自己的机会，所以我的表达能力有所欠缺，但我认为我并不差，我可以抓住这次机会锻炼自己。\u003c/p>\u003cp>其次，多鼓励自己：我告诉自己反正以后还会给同事培训，一次表现不好没什么，我相信自己会做的一次比一次好。\u003c/p>\u003cp>最后，发现问题，选择改变：第一次上课的时候，我发现大家只听我怎么讲，没有更多的实操，还是不会做，我做出了一下调整：一是给大家更多的时间课上练习，二是下一节课前，再让大家练习上一节课的内容，很快大家都跟上进度。\u003c/p>\u003cp>也正是因为这样的分享，在2期分享后，我在公司树立了自己的IP，还获得了疫情期间额外的升职加薪。以上就是发生在我身上的一个小故事。\u003c/p>\u003cp>【适用边界】 \u003c/p>\u003cp>那什么时候可以运用成长型思维呢？当我们面对困难，不知所措的时候；当我们面对失败，情绪沮丧的时候；当我们不擅长做某件事，一直不敢做的时候，都可以尝试用成长型思维的模式改变事情的发生。当然你可以用这样的方法指导别人，比如：下属不擅长上台演讲，你希望他主持下个月的供应商大会，你可以引导他接下这个挑战；你朋友精心准备了一个年终汇报PPT，老板却提出了各种问题，他很失落，你可以帮他积极的看待这个事情等等。\u003c/p>","interaction":"\u003cp>\u003cstrong>【技能点：规划应用】指令清晰，学习者可以根据指令，设计出一个包含人物角色、有起因经过结果、有对话的故事。\u003c/strong>\u003c/p>\u003cp>那大家想一下，有没有类似的场景可以运用今天学到的成长型思维呢？给大家30秒的时间想一下，在大脑中过一遍，等于实际应用了一遍。\u003c/p>\u003cp>请接下来大家编写一个小故事，背景可以是未来1个月你的同事或家人可能遇到挫折，他们习惯性的固定型思维，不知道怎么办，你打算运用成长型思维的三步骤来引导他们战胜困难，请大家花5分钟的时间来编写一下这个小故事，包含人物、情节变化（包括：起因、经过、结果）和对话，一定要有对话，5分钟后，我将请一个小伙伴起来分享一下自己的对话，好吗？\u003c/p>\u003cp>\u003cstrong>&lt;学习者案例&gt;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>分享者：学痕\u003c/strong>\u003c/p>\u003cp>时间：下周的一个晚上\u003c/p>\u003cp>地点：在家里\u003c/p>\u003cp>任务：雪痕和表弟\u003c/p>\u003cp>起因：表弟总是觉得自己坚持不了做好一件事，比如跑步\u003c/p>\u003cp>对话：\u003c/p>\u003cp>表弟: 哎，我总是无法坚持做一件事，像跑步，我总是半途而废。\u003c/p>\u003cp>雪痕: 我认为你不能这样看，他本来是一件小事，其实没有那么严重，你喜欢给自己贴标签，是不对的。\u003c/p>\u003cp>表弟: 那我该怎么做呢？\u003c/p>\u003cp>雪痕: 首先，你只是1天没有跑步，但你之前已经坚持了7天，你把这件事放大了，可以试着就事论事，你就是短暂性的没有坚持而已，不要扩大为永久性。其次，我觉得你应该多看到自己之前的坚持，除了这一点，你已经写20多个代码案例，写的很好了，你只是在某一方面做的不好而已，相应的你可以针对自己的不足采取相应的对策，做出改变，而不是给自己扣帽子。\u003c/p>\u003cp>谢谢雪痕的分享，讲的非常深入和细致。\u003c/p>\u003cp>以上就是我今天的分享，希望大家在学习了今天的拆页后，在心里种下这样的种子：我们的思维方式里真的藏着我们的未来。很多时候，我们就是一念之转，因为大脑里装着“成长型思维”，可能都会让自己的心态和行为有很大的转变。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1615814351000,"updated_at":1617532797000,"ria":true},{"id":10374,"topic":"孩子受挫时，如何抓住时机培养成长型思维？","learn_goal":"","remark":"你可能会认为，父母一旦拥有了更偏向于成长型的思维模式，这种思维模式就会自动传递给孩子，但是这只是我们一厢情愿的想法。成长型父母，如果没有在合适的时机，通过合适的言行去影响孩子，很可能就教出了固定型思维的孩子。\n\n那么，如何才能培养成长型思维的孩子呢？这个周四我们一起来学习讨论吧！","level":"TF3-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"付盈盈","city":"武汉"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"\u003cp>为了便于今天的学习和讨论，我们先来分一下组。\u003c/p>\u003cp>各位小伙伴儿大家好，我是今天的拆书家付盈盈。今天我要拆解的片段选自《终身成长》这本书。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>通过今天的学习，我们能够在孩子遭遇挫折时，使用（行为）以成长型思维来面对挫折的3步骤（澄清），引导孩子走出低落情绪，调整策略去重新实现目标（界定）。\u003c/p>\u003cp>\u003cstrong>【图书介绍】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>事件场景：\u003c/strong>最近我女儿换了新的英语老师，这位新老师对学生们自我介绍的要求跟以前就不太一样：以前是……。现在多了两句话：我来自K80，我的老师是sephi.我女儿可能也没有一下子记住，过后也没有练习。上周第二次上课的时候，她就按照原来的方式去介绍，班上有孩子起哄：这也太简单了，太短了。老师也提示他还有2句，但是她完全忘记了，在老师的启发下也没有说出那2句。我女儿就整堂课情绪不太好。下课后，她就跟我说妈妈，我不想跟他们一起上课了。我当时注意力在我自己的事情上，随口就说：哎呀，多大点事啊，妈妈觉得你也做的很好啊。然后，我女儿就跟我说：妈妈，可是就只有我的自我介绍是短短的！她本来只是有点沮丧，听了我说的话，还开始有点烦躁了。\u003c/p>\u003cp>\u003cstrong>提问：\u003c/strong>大家有没有这样的经历，你的孩子或者是看到别人的孩子遭遇了一些挫折，情绪非常低落，父母告诉他们“哎呀，这多大点事啊，你已经很棒了。”说完以后才发现还不如不说呢。有这种经历吗？\u003c/p>\u003cp>\u003cstrong>影响：\u003c/strong>我们或多或少都遇到过类似的情况，这种处理方式，看起来好像也是鼓励，但是不仅没有安慰到他们，而且对他们的处境也没有任何帮助。甚至还对你们的关系和他的情绪起到了反作用。\u003c/p>\u003cp>\u003cstrong>解决：\u003c/strong>怎么破呢？《终身成长》这本书可以帮到你。这本书通过对“成长型思维”和“固定型思维”2种思维模式的对比呈现，改变我们的认知，即相信我们的能力是可以发展的。认知的改变，不仅能够让我们调整自己的思维模式，也能够影响到身边的人，比如今天的学习片段，我们可以在孩子受挫时，帮助他们用成长型思维，把失败当作成长的机会，来帮助他们重新实现目标。\u003c/p>","ratings_count":1,"texts":[{"id":14222,"quote":"\u003cp>在第一个项目自由体操中,伊丽莎白第一个登场。尽管她表现得很不错,但在后来几个女孩出场之后,得分出现了变化,伊丽莎白输掉了比赛。在其他项目中,伊丽莎白同样表现得很好,但是依然没能赢得比赛。那天晚上比赛结束时,她一条彩带也没能得到,她感到很沮丧。\u003c/p>\u003cp>如果你是伊丽莎白的父母,你会怎么做?\u003c/p>\u003cp>1、告诉伊丽莎白,你认为她是最棒的。\u003c/p>\u003cp>2、告诉她是裁判的不公平让她丢掉了原本属于她的彩带。\u003c/p>\u003cp>3、安慰她说体操其实没那么重要。\u003c/p>\u003cp>4、告诉她她有足够的能力,下一次肯定能赢。\u003c/p>\u003cp>5、告诉她她本来就不该赢。\u003c/p>\u003cp>在当今社会中,对于如何增强孩子的自信心,存在着一种强有力的信息,这种信息的一个重要内容就是:保护孩子们免遭失败!但是这种做法或许能够暂时防止孩子们失望,但是从长远来看,却有着很大的危害。为什么这么说呢?\u003c/p>\u003cp>让我们从思维模式的角度看看对刚才五句话的五种可能的反应.倾听其中传达的信息:\u003c/p>\u003cp>第一种(你认为她是最棒的):这种说法从根本上说并不是真心的。她并不是最好的--你知道这一点,她自己也清楚这一点,这对于她的恢复和进步一点帮助都没有。\u003c/p>\u003cp>第二种(她受到不公平待遇):这是责备他人的做法。当事实的真相是,问题的根本在她的表现而不在裁判时,难道你希望她以后变成喜欢将自己的不足归咎于他人的人吗?\u003c/p>\u003cp>第三种(安慰她体操其实没那么重要):这种说法会教给她,当她有什么事做不好时,贬低这些事情本身就对了。难道你真想告诉她这些吗?\u003c/p>\u003cp>第四种(她有能力):这可能是所有信息里最危险的一个。难道是能力自动带领你走向成功的吗?如果是这样,伊丽莎白这次没能赢为什么下一次就能赢呢?\u003c/p>\u003cp>第五种(告诉她她本来就不该赢):在这种情况下说这样的话的确有些无情。当然,你可以不用这么直白的方式表达,不过伊丽莎白具有成长型思维模式的父亲基本上就对她表达了这个意思。\u003c/p>\u003cp>下面是她父亲的原话:&quot;伊丽莎白,我知道你的感受。你对比赛寄予了如此大的希望,而且拿出了自己最好的表现,但是依然没能赢,你一定感到很失望。但是你要知道,你并没有付出100%的努力。有很多女孩练习体操的时间都比你长,而且比你更努力。如果这是你真心想要的东西,那么你就要全身心地为此付出努力。\u003c/p>","explains":"\u003cp>\u003cstrong>【what概念辨析】\u003c/strong>\u003c/p>\u003cp>在讨论教孩子用成长型思维来面对挫折之前，我们先来看看什么是成长型思维模式。成长型思维模式即相信能力是可以发展的，这是底层信念。拥有成长型思维模式的人勇于迎接挑战、重视努力过程、积极采取行动。\u003c/p>\u003cp>有人说，这不就是积极思维嘛。成长型思维的人确实很多时候体现出积极的特质，比如拥抱变化，采取行动。但是它的核心是对能力的态度，是相对于固定型思维而言的。而积极思维是相对于消极思维而言的，强调我们看待事情的方式。一个积极思维的人在遭遇挫折的时候，不会被失败打垮，但是他也是很有可能认为我这方面的能力是没办法改变的。\u003c/p>\u003cp> 我们来看几个例子，来加深对概念的理解。\u003c/p>\u003cp>\u003cstrong>例子1\u003c/strong>：我月考数学只考了60分，没关系啊，我数学不行，但是我语文还是挺好的。这是成长型思维还是积极思维？（积极思维）\u003c/p>\u003cp>\u003cstrong>例子2\u003c/strong>：我月考数学只考了60分，我确实这几个章节的知识点掌握的不好，我需要花点时间去把那些知识点弄明白。这是成长型思维还是积极思维？（成长型思维）\u003c/p>\u003cp>\u003cstrong>例子3\u003c/strong>：我月考数学只考了60分，考试的时候我正好身体不舒服状态不好，而且刚好考察的内容是我掌握的不太好的部分，考60分是个偶然啦，不代表我数学不行。这是成长型思维还是积极思维？（积极思维）\u003c/p>\u003cp>\u003cstrong>例子4\u003c/strong>：我月考数学只考了60分，虽然我很难过，但是这确实是对我前段时间学习成果的检验，我需要去找找原因，把没掌握的知识补起来。这是成长型思维还是积极思维？（成长型思维）\u003c/p>\u003cp>通过刚才的几个例子，我们知道了成长型思维区别于其他概念最重要的一点就是，它认为能力是可以发展的，拥有这种思维的人，能够持续努力精进，所以它最后的结果一定是指向成长的。\u003c/p>\u003cp>也就是因为这一点，越来越多的家长，希望培养出具有成长型思维的孩子，“胜不骄败不馁”是需要背后的思维模式来支撑的。但是思维模式这个东西，没办法直接从我们的脑子到孩子的脑子，需要我们在日常生活中潜移默化地影响，而孩子遇到挫折的时候就是一个非常好的培养成长型思维模式的契机。那么如何在孩子遭遇挫折的时候，培养他的成长型思维呢？\u003c/p>\u003cp>\u003cstrong>【引出How】\u003c/strong>\u003c/p>\u003cp>在原文中，作者给出了具有一个成长型思维的父亲的示范。\u003c/p>\u003cp>我们可以从中总结出4个关键步骤： \u003c/p>\u003cp>\u003cstrong>第一步，安抚情绪：\u003c/strong>共情＋直面现实\u003cstrong>。\u003c/strong>（原文我知道你的感受，输了比赛你一定很失望）对孩子的情绪和处境表示理解，但是要面对现实。共情其实不直接体现成长型思维，但是学过沟通的都懂，为了保障后面的效果，这个餐前甜点不能少。\u003c/p>\u003cp>\u003cstrong>第二步，肯定努力：\u003c/strong>根据事实，肯定孩子在过程中值得发扬的行为、品质。（原文中：你拿出了自己最好的表现）这里的努力，并不是仅仅是指付出了汗水，同时也包括在过程中的尝试新策略，听取他人意见等等有利于目标实现的行为。如果实在找不到，可以省略这一步，但是不能说瞎话。\u003c/p>\u003cp>\u003cstrong>第三步，引导行动：\u003c/strong>（有很多女孩练习体操的时间都比你长，如果这是你真心想要的东西，拿你就要全身心地为此付出努力）仅仅有高目标高标准是不够的，我们要和孩子一起找到改进的方法，并且尽可能在她成长的过程中给予建设性的反馈。\u003c/p>\u003cp>\u003cstrong>【举例】\u003c/strong>比如说，在前面我讲到我女儿的例子，后来我发现随口的“你已经很棒了”没有用，然后我就跟她说：\u003c/p>\u003cp>（第一步，安抚情绪）你是不是觉得自己刚刚课堂表现不好，所以说不想跟Amy他们一起上课啦？ \u003c/p>\u003cp>（第二步，肯定努力）她点了点头，然后我接着说：你刚刚虽然自我介绍不完整，但还是积极参与后面的互动，挺好的。\u003c/p>\u003cp>（第三步，引导行动）我说那我们多练习几次就好啦，Amy他们课后复习了，所以就可以很流畅地自我介绍。我们也来练习吧。\u003c/p>\u003cp>然后我就带她一起念了10遍，她自己又练习了几次，现在自我介绍又信心满满了。\u003c/p>\u003cp>\u003cstrong>【where】\u003c/strong>但是也要注意，成长型思维强调个人持续的努力，但是现实生活中孩子遭遇挫折，确实有很多种原因的，比如裁判不公平、身体状况、目标设置不合理等等。那我们可能需要其他的方法来消除外界因素对孩子的影响。以上面对挫折的3步骤，不仅仅适用于家长教育孩子，只要在当时的情境中，我们暂时扮演老师、教练的角色，都是适用的。比如老师教育学生、上级培养下属。甚至在你自己遭遇挫折时，也可以运用这种方法自我对话。\u003c/p>","interaction":"\u003cp>OK，为了实践我们刚刚学习的“面对挫折的3步骤”，我们来现场编一个小剧本。剧本的背景可能是未来你会遇到的一个场景，比如孩子考试考差了，下属工作失误了等。给大家5分钟的时间，稍后我会请一组小伙伴来表演一下。\u003c/p>\u003cp>【学习者案例】\u003c/p>\u003cp>【点评回应】 感谢小雪的分享，从小雪的分享中我们听到了对孩子努力的肯定，行为的引导，虽然没有演示具体如何安抚，但已经有这个意识，知道要去做，我们活动结束后可以将这部分再进行细化。很好！\u003c/p>\u003cp>\u003cstrong>结语\u003c/strong>\u003c/p>\u003cp>通过今天的学习，我们学习了在孩子遭遇挫折时，如何运用成长抗挫3步骤（安抚情绪，肯定努力，采取行动）找到方法，持续付出努力去实现目标。每一次挫折，都是孩子成长的机会，不仅仅是对孩子，对我们所有人都是一样。决定我们成长的第一步，不是我们是否努力，而是我们是否相信努力！\u003c/p>\u003cp>OK，以上就是我要拆解的全部内容，感谢大家的陪伴！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1599143669000,"updated_at":1600135842000,"ria":true},{"id":9730,"topic":"夸孩子聪明，难道错了吗？","learn_goal":"学习者通过学习后，可以在孩子教育过程中，应用成长思维方式教育","remark":"","level":"TF3-3","duration":30,"status":29,"type":0,"chaishujia":{"username":"吴佳音","city":"厦门"},"club":{"name":"厦门鹭岛抚琴分舵","city":"厦门"},"prologue":"大家好，我叫佳音，用三个标签来介绍自己。\r\n专业——心理学：曾经主修的学业。\r\n职业——培训师：现在的谋生之道。\r\n副业——拆书家：未来的成长之路。 \r\n【介绍图书】\r\n【事件】先说说本次的主题：夸孩子聪明，我错了吗？\r\n问：大家觉得这种夸奖是对还是错呢？\r\n答：对/错/不一定。\r\n以前，我们的教育模式多是“棍棒底下出孝子”，近些年，又开始风行“鼓励教育”，鼓励教育告诉我们，要多去发现孩子的闪光点，多去夸奖孩子，帮助孩子建立自信并且保护它，这一观点目前也为很多父母和老师所接受。\r\n比如，当孩子听了几遍儿歌后就能背下来时，会夸孩子“你学得真快！”；当孩子画出一副超出你预期的图画时，会夸孩子“你太有天赋了！”；当孩子成绩优异时，会夸孩子“你都没怎么看书就考这么高的分，你简直就是个小天才！”……\r\n【提问】大家觉得孩子除了接收到鼓励，还可能接收到哪些信息呢？\r\n【影响】可能是“我生来就很聪明”、“我从小就很有天赋，根本不需要什么努力。”、“妈妈喜欢聪明的我”、“聪明能够让我妈妈喜欢我，为了让妈妈一直喜欢我，我不能表现出不聪明。”…… \r\n如果孩子们接收到的是这些信息，他们为了维护自己的聪明，就不敢犯错，不敢去挑战更有难度的任务，他们甚至会通过撒谎来显示自己的天赋和能力。而这些将大大限制了他们发展和进步的空间。\r\n其实，不仅仅是夸奖，批评也一样，你传达的跟孩子接收到的可能并不对等。那么如何才能给予诚实而有建设性的建议，并且能够让孩子能准确接收到呢？\r\n【解决（1）】答案就在《终身成长》这本书中。\r\n 在介绍这本书前，先做一个问卷调查。\r\n【A1】请大家仔细阅读表格中描述的每一句话，并与自己平时的做法进行对照，然后给自己打分，1分代表完全不符合，6分代表完全符合。\r\n请不要犹豫,看懂题意后马上做答并计分。\r\n1、生活和工作中，我总是勇于尝试新鲜事物应用于工作与生活中。\r\n2、我总是愿意付出时间与精力学习来提升自身技能。\r\n3、面对困难时，我相信可以通过付出努力，以期获得更好的结果。\r\n4、面对压力和挫折时，我会尝试寻找不同的解决方式，以期有更好的结果。\r\n5、面对失败，我会寻找存在的差距提升自身技能，期许提高下次获得成功的几率。\r\n6、面对成功，我总是会保持谦卑，避免沾沾自喜。\r\n【I】大家可以计算下，你们所获得的分值。\r\n若分值是26（含）以上，说明你经常使用成长型思维模式处理问题。\r\n若分值是14—26，说明你具备成长型思维模式，但有时候会使用固定型思维模式处理问题。\r\n若分值是14（含）以下，说明你经常使用固定型思维模式处理问题。\r\n 什么是固定型思维模式和成长型思维模式？这就是《终身成长》这本书中提出的两个概念。图例中详细的解析了成长型思维认同的是智力是可以提升的，也就是说可以通过后天的努力和学习提高智力。所以成长型思维的人更愿意接受调整，甚至能从失败或批评中获得学习的机会。书中不仅详细解析什么是成长型思维模式，并通过案例分析具体的使用方法。\r\n【解决（2）】今天我们将通过两个片段，更深入的了解什么是成长型思维、如何使用成长型思维处理困境、如何帮助孩子形成成长型思维。\r\n 第一个片段是一个案例，面对同一个困境，固定型和成长型思维模式分别采取了不同的应对方式。接下来，请大家利用4分钟的时间进行阅读，阅读的过程中，也可以对照图例（固定型思维模式和成长型思维模式对比图）一并阅读。","ratings_count":1,"texts":[{"id":13572,"quote":"\u003cp>困境1：假设你报考了一所研究生院。你在志愿上只填了这一家学院，因为这是你唯一心仪的选择。你对录取充满自信，因为很多人都认为你在这个领域的研究工作独具创见，令人兴奋。但是，你的申请被拒绝了。\u003c/p>\u003cp>固定型思维模式的反应：一开始你告诉自己，竞争太激烈了，所以被拒绝不能反映你的真实水平。也许有太多条件优秀的申请者，研究生院无法全部接受。然后，你脑海深处那个声音开始说话了。那声音说，你是在骗自己，为自己找借口。它对你说，招生委员会认为你的研究工作不尽如人意。过了一阵，你对自己说，这可能是真的。你的工作也许真的平庸乏味，不值一提。他们发现了这一点。毕竟他们都是专家。对方已经做出了裁决一一你配不上这所学院。\u003c/p>\u003cp>在一番努力之后，你又说服自己相信了一开始的结论。这个结论也很合理，而且对你更有利。你感觉好一点了。在固定型思维模式下（在大多数认知疗法中也一样），事情到这一步就结束了。你重新找到了自尊，所以不用再多想了。\u003c/p>\u003cp>但在成长型思维模式下，这只是一个开始：你之前只是在自说自话现在要开始学习和自我提高了。\u003c/p>\u003cp>成长型思维模式的解決办法：考虑好你的目标，然后想想你要怎么做才能实现它。你能采取哪些措施让自己获得成功？你能收集到什么信息？也许下次你该多申请几个学校。也许与此同时，你应该去广泛收集信息，让你的申请书更具竞争性：他们希望招收什么样的学生？他们最看重哪些经验？在进行下一次申请前，你要多积累这方面的经验。\u003c/p>\u003cp>这是一个真实的故事，我知道那位被拒绝的学生采取了哪些措施。她听取了一些有力的成长型思维模式的建议。几天后，她给那所学校打了一个电话。她找到了相关负责人，并把自己的情况告诉了他。她说：“我不想质疑您的決定。我只是想问一下，如果下次我想再申请这所学校，我该怎么改进自己的申请书。如果您能在这方面给我一些反馈和建议，我将感激不尽。”\u003c/p>\u003cp>没人能对这种期望获得有益反馈的真诚请求嗤之以鼻。几天后，那位负责人给她回了电话。学校同意接受她的申请了。原来，当时拒绝她其实也只是一念之差。在重新考虑过她的申请后，他们決定可以多招收一名学生。他们对她的主动性颇为欣赏，这也为她加了分。\u003c/p>\u003cp>为从失败的经验中吸取教训，在未来有所进步，她主动去寻找相关信息。在这个案例中，她其实并不需要完善自己的申请书。她终于能在新的研究生项目中澘心学习了。\u003c/p>","explains":"\u003cp>【学习目标】在跟随我完成本次的RIA现场学习后，学习者能够在面对困境或失败的情况下，通过使用成长型思维模式（澄清）的方式，进行分析困境或所遇到的失败事件（界定），拟定下一步行动并实施（行为）\u003c/p>\u003cp>【互动】\u003c/p>\u003cp>拆书家：这个片段中举了一个例子，当去申请研究生院被拒绝时，两种不同思维模式的反应截然不同。遇到阻碍或挫折时，固定型思维模式的人更倾向于自我保护或者放弃，而成长型思维模式的人，则会坚持不懈。那请问大家，固定型思维模式的反应是什么样的呢？\u003c/p>\u003cp>学习者：被拒绝不能反映你的真实水平/有太多条件优秀的申请者\u003c/p>\u003cp>拆书家：除了这些肯定自己的想法外，还有其他的反应吗？\u003c/p>\u003cp>学习者：不尽如人意/平庸乏味/你配不上这所学院。\u003c/p>\u003cp>拆书家：有肯定也有否定，但最终的结论是什么呢？\u003c/p>\u003cp>学习者：否定自己，给失败找原因，上不了这所学院了。错过“我”是学院的损失。\u003c/p>\u003cp>拆书家：是的，固定型思维模式的人更倾向于自我保护，所以虽然说服自己的过程中，有肯定有否定，甚至还会有些反复，但是最后还是倾向于肯定自己的想法——我很优秀，拒绝我是你们的损失。然后呢？就没有然后了，到此为止，放弃了。\u003c/p>\u003cp>而在拥有成长型思维模式的人，会觉得这才只是一个开始。在本书《终身成长》中，一直强调拥有成长型思维模式的人相信头脑和天赋只是基本条件，而能力是可以通过专注和努力来发展提升的，在这个片断中，我们可以看到拥有成长型思维的人的反应很积极，在遇到院校申请失败的时候，不会立刻陷入到失败中，而是会从失败的经验中吸取教训，主动去做点什么，并相信自己可以通过再次努力而获得成功。\u003c/p>\u003cp>那么面对困境时，到底怎么才算什么用成长型思维面对呢？是不是会通过失败的经验吸取教训就可以呢？\u003c/p>\u003cp>为了大家更好地理解成长型思维，我举几个例子，大家看一看是不是成长型思维呢？\u003c/p>\u003cp>【概念讲解】\u003c/p>\u003cp>拆书家：比如，年初做工作计划，你提交给老大，结果你的计划被老大批得一无是处，你很无语，认为“我这份计划非常完美，只是他不懂欣赏。”，下次改好一点再提交给他，大家觉得算具备了成长型思维？\u003c/p>\u003cp>不是，因为这里并没有正视失败的情形，这样子的行为会陷入到找借口的境地之中，无助于自己的成长，具备成长型思维的人，首先应该要有勇气接受失败并正视问题。\u003c/p>\u003cp>如果你认为“老大说得有到理，我做得不好，他提的修改意见该怎么改就怎么改吧，以他为主。”，这种想法视乎正视问题并愿意改变，这是具备成长型思维了吗？\u003c/p>\u003cp>不是，因为你并没有明确目标，目标不是别人给你的，而是自己给自己的。只有明确自己的目标后，才能发现自己的思路是否有偏差。如果有偏差就该及时调整。如果确实有待商榷，则应继续求证，并最终确定方向。具备成长型思维的人，不仅要有勇气接受并正视问题，而且要有自己明确的目标。\u003c/p>\u003cp>如果你认为“老大的格局确实比我高，考虑得比我全面，我的确不足，我能参考他的意见，我之后改改完善一下，争取下一回提交给他的时候，能通过并获得他的认可“，这里有接受失败并正视问题，且有明确的目标，但这是具备成长型思维了吗？\u003c/p>\u003cp>还不是，因为虽正视问题，有确认目标，但是进一步执行的行动或者是可实施的计划是没有的，或者是说是不清晰的，大家回忆一下刚刚阅读的片断中，拥有成长型思维的小伙伴，是不是在面对被院校拒绝后，他之后做了哪些行动呢？\u003c/p>\u003cp>学员：他听取了一些建议，并在第二天打了电话给院校，主动寻向校方问了下次如何才能被院校录取的标准是什么的问题。\u003c/p>\u003cp>拆书家：是的，拥有成长型思维的人，不能仅仅停留在思维层面，正视问题、吸引教训，相信自己未来会变得更好，最主要的是要付诸行动，行动步骤很多的时候，甚至还需要制定相应的行动计划。\u003c/p>\u003cp>那么到底什么样的才是用成长型思维模式处理困境呢？\u003c/p>\u003cp>【HOW】总结一下，\u003c/p>\u003cp>一是接受并正视问题： 要接受自己的想法，无论这些想法是正面还是负面的，是积极的还是消极的。接受是处理问题的开始。因为只有不逃避，才能正视问题，并积极解决问题。\u003c/p>\u003cp>二是明确目标： 明确目标不仅仅是要明确自己希望获得的成果，而且是不与价值观相悖的，要清楚自己真正想要的是什么，这样的目标才能成为你今后坚持不懈地执行计划的关键。记住：目标一定是你自己的目标，而非他人给你制定或下达的目标。\u003c/p>\u003cp>三是拟定下一步行动并实施：可以是立刻可以实施的行动，也可以是制定一个具体的可实施的行动计划，并坚持不懈地实行它。\u003c/p>\u003cp>【异议预防】为了达成目标，更好的拟定下一步行动并实施，你还需要收集相关的信息，寻找相应的措施，何时何地如何执行。越细致越具体，这会你的成功率更高。\u003c/p>\u003cp>为了更好的帮助大家理解，我举个例子：\u003cbr>\u003c/p>\u003cp>最近我的大娃所在学校在推双语教学，我的小孩之前没有有意让她接受这一块，结果老师反馈她在学校里很排斥抗拒，我有些后悔没有早点让小朋友早点接触英语，我打算让她开始接触英语启蒙，时间会有点晚。但是问题已经存在，我想我后悔也没用，对待这个问题，我清楚我必须先接受事实，相信这并不能代表小朋友未来就不会英语学习。\u003c/p>\u003cp>当然我的目标也很明确，就是想通过英语启蒙给大娃培养英语语感、逐步熟悉英语，未来学习英语打好基础，同时这个过程也顺便给老二做胎教。\u003c/p>\u003cp>接下来我并不是停留在只有想法的阶段，我就在一张纸上列了可以有助于做这件事的清单，也搜集一些信息资料，接着立刻能做的事情就是在老师告诉我这个情况之后的一周内，就先选择了一些适合小朋友看的双语动画片《爱冒险的朵啦》和绘本，通过动画片吸引孩子的注意力，引发她的兴趣，同时结合一些简单的英文绘本与孩子做亲子共读，当我做了这些事情后，动画片和绘本果然有效果，我家的小朋友现在可以就一些简单的物品跟英文建立起联系，嘴里时不时的蹦出一些从动画片中学来的英文句子，而且还表现更多兴趣。这就是我运用成长型思维来解决我在亲子教育的问题，希望能对大家理解成长型思维有所帮助。\u003c/p>\u003cp>【异议预防】有的小伙伴可能会问，如果不使用成长型思维，继续保持现状可以吗？短时间看似乎问题不大，但如果是长时间维持现状呢？其实这就变成了逃避，陷入不敢面对的情况，甚至时间长了以后，问题不进则退，有可能会变得恶化，这种结果是否还是你能承受的呢？如果这个问题可能会持续存在，甚至影响越来越大时，我们就应该防微杜渐，尽早使用成长型思维模式来面对处理。\u003c/p>","interaction":"\u003cp>【A2催化学习者应用】\u003c/p>\u003cp>以上就是我对这个拆页的讲解，拆书帮的学习，讲究拆为已用。\u003c/p>\u003cp>现在请大家设想下是否有过这样的场景，如在公司干的累死累活，却不如写PPT的；在家里任劳任怨，管娃的吃喝拉撒管教育，却不如偶尔溜娃的那位……\u003c/p>\u003cp>当这些情况一而再，再而三的出现，你可能就没有动力继续努力工作，也可能就越来越没耐心应对孩子和家人……这些都是我们不希望看到的结果，因为一旦你失去耐心，失去动力……问题就会越来越严重，陷入到恶性循环中。或者其它类似困境的场景呢？\u003c/p>\u003cp>今天，我们就来预演下，请大家分成2个小组讨论，编一个剧本故事，故事有主角，有起因经过，甚至有对话，内容有体现我们刚刚今日所学，大概几百字即可。将摘要写在一张纸上，时间五分钟。五分钟后我们将一位伙伴站起来讲讲他们的剧本。\u003c/p>\u003cp>【学习者——曹志文分享：升职晋升后的困境】\u003c/p>\u003cp>近期职位晋升，但&quot;我&quot;却遇到了一个困境，而且这个困境应该是今后晋升都会面临的问题。公司有个流行的说法是：你总是会升职到一个你不胜任的岗位。我原本的岗位是比较基层的，一般只需要完成领导交付的事情就可以了。但晋升后，领导希望我不仅可以带好团队，而且可以很好的完成今年甚至是明年的业务。\u003c/p>\u003cp>之前的职位并不需要我思考太多，同时也不需要进行多方沟通。所以我的接触面不够广，视野也不够开阔，这些都是我的短板。\u003c/p>\u003cp>【接受并正视问题】\u003c/p>\u003cp>我告诉自己： 我需要对自己的短板，进行针对的改进和提升。比如拓宽接触面、开阔视野等。\u003c/p>\u003cp>【明确目标】\u003c/p>\u003cp>我： 我觉得我可以从几个方面去着手，最终达到提升自我的目的，可以胜任公司的新职位安排\u003c/p>\u003cp>比如：\u003c/p>\u003cp>1、多与公司/部门同职位的人员接触，多了解他们的目前工作中的痛点和短板，这也将是我今后工作中需要攻克的内容。\u003c/p>\u003cp>2、多参加一些会议或研讨，了解行业趋势，从而开阔自己的视野。\u003c/p>\u003cp>3、此外，我目前的想法可能会不够全面，我需要向资深的同事和领导多学习，虚心求教。他们可能会分享一些经验，比如如何快速获取优质资讯等。\u003c/p>\u003cp>【制定计划】\u003c/p>\u003cp>我：我可以马上与上司和前辈请教，他们眼中的新职业位最佳人选应该是一种什么样的状态，有什么要求才能做好呢？\u003c/p>\u003cp>非常感谢志文的分享，在这个故事中，中志文分享困境是故事的主角升职后的工作内容较之前有很大区别，甚至是以前工作中所没有接触过的。而且目前面临的这个困境，可能会在未来存在一段较长的时间，甚至今后如果有职位的变动，也将再次面临这个困境。\u003c/p>\u003cp>志文非常理性的分析了“我”目前存在的问题和短板，也明确了自己的目标，并制定了相应的计划。通过各种渠道进行信息收集、获取有效资源等，改进现状，进而处理困境。\u003c/p>\u003cp>相信大家通过志文的案例分享，能够更好的理解如何通过使用成长型思维模式接受、明确目标、拟定下一步行动并实施的方法，更理性的分析并处理困境。\u003c/p>\u003cp>作为长辈/父母，我们需要使用成长型思维处理我们面临的困境。同时，我们也希望孩子也能拥有成长型思维，以便能更好的应对未来的各种挑战。\u003c/p>\u003cp>【互动】\u003c/p>\u003cp>拆书家问：是不是有成长型思维模式的父母就能教会孩子或者更准确的说是就能够潜移默化的影响孩子，让他们从小就具备成长型思维呢？\u003c/p>\u003cp>学习者答：不一定。\u003c/p>\u003cp>拆书家问：为什么呢？\u003c/p>\u003cp>学习者答：自己学会和教别人学会是两码事。\u003c/p>\u003cp>不可否认自己学会了才有可能教会孩子，但想要教会或潜移默化的影响孩子，这是需要方法的。日常生活中，亲子互动的场景非常多，今天时间关系，我们先聚焦在孩子面对失败向你寻求帮助时，我们应如何引导。接下来跟大家分享的是一个案例，当9岁小姑娘面对失败时，她的父亲如何引导她使用成长型思维处理困境的。接下来是阅读时间，请阅读完的伙伴举手示意我一下。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}},{"id":13573,"quote":"\u003cp>对孩子成功的不当称赞所带来的问题，应该是我们面临的问题中最容易对付的。失败似乎是一个更棘手的问题。孩子们在遭遇失败时，已经够沮丧和痛苦了。让我们再回到这个问题上，这一次让我们说说在孩子面临失败时，父母所传达给孩子们的信息。\u003c/p>\u003cp>九岁的伊丽莎白第一次参加了体操运动会。她身材修长，柔韧性好，充满活力、非常适合练体操，她自己也非常热爱体操。当然，她对参加比赛有一点紧张，但是她的水平很高，并且对自己的表现很自信。她甚至已经想好要将她贏得的彩带挂在家里的哪个位置。\u003c/p>\u003cp>在第一个项目自由体操中，伊丽莎白第一个登场。尽管她表现得很不错，但在后来几个女孩出场之后，得分出现了变化，伊丽莎白输掉了比赛。在其他项目中，伊丽莎白同样表现得很好，但是依然没能贏得比赛。那天晚上比赛结束时，她一条彩带也没能得到，她感到很沮丧。\u003c/p>\u003cp>如果你是伊丽莎白的父母，你会怎么做？\u003c/p>\u003cp>1．告诉伊丽莎白，你认为她是最棒的。\u003c/p>\u003cp>2．告诉她是裁判的不公平让她丢掉了原本属于她的彩带。\u003c/p>\u003cp>3．安慰她说体操其实没那么重要。\u003c/p>\u003cp>4．告诉她她有足够的能力，下一次肯定能赢。\u003c/p>\u003cp>5．告诉她她本来就不该赢。\u003c/p>\u003cp>在当今社会中，对于如何增强孩子的自信心，存在着一种强有力的信息，这种信息的一个重要内容就是：保护孩子们免遭失败！但是这种做法或许能够暂时防止孩子们失望，但是从长远来看，却有着很大的危害。为什么这么说呢？\u003c/p>\u003cp>让我们从思维模式的角度看看对刚才五句话的五种可能的反应，倾听其中传达的信息：\u003c/p>\u003cp>第一种（你认为她是最棒的）：这种说法从根本上说并不是真心的。她并不是最好的——你知道这一点，她自己也清楚这一点，这对于她的恢复和进步一点帮助都没有。\u003c/p>\u003cp>第二种（她受到不公平待遇）：这是责备他人的做法。当事实的真相是，问题的根本在她的表现而不在裁判时，难道你希望她以后变成喜欢将自己的不足归咎于他人的人吗？\u003c/p>\u003cp>第三种（安慰她体操其实没那么重要）：这种说法会教给她，当她有什么事做不好时，贬低这些事情本身就对了。难道你真想告诉她这些吗？\u003c/p>\u003cp>第四种（她有能力）：这可能是所有信息里最危险的一个。难道是能力自动带领你走向成功的吗？如果是这样，伊丽莎白这次没能赢，为什么下一次就能赢呢？\u003c/p>\u003cp>第五种（告诉她她本来就不该贏）在这种情况下说这样的话的确有些无情。当然，你可以不用这么直白的方式表达，不过伊丽莎白具有成长型思维模式的父亲基本上就对她表达了这个意思。\u003c/p>\u003cp>下面是她父亲的原话：“伊丽莎白，我知道你的感受。你对比赛寄予了如此大的希望，而且拿出了自己最好的表现，但是依然没能贏你一定感到很失望。但是你要知道，你并没有付出100％的努力。有很多女孩练习体操的时间都比你长，而且比你更努力。如果这是你真心想要的东西，那么你就要全身心地为此付出努力。”\u003c/p>\u003cp>他同样告诉伊丽莎白，如果她只是想拿体操当个乐趣，那也没有问题。但如果她想在比赛中有所成就，那么就必须付出更多。\u003c/p>\u003cp>伊丽莎白记住了父亲的话，她花了更多时间来反复练习和完善自己的全套动作，尤其是比较薄弱的部分。在下一次比赛中，全地区有80名女孩参加了角逐。伊丽莎白赢得了5个个人项目的彩带，并夺得这次比赛综合项目的总冠军，捧回家一个巨大的奖杯。到现在，她的房间里挂满了各种获奖证明，几乎覆盖了整个墙面。\u003c/p>\u003cp>其实，她的父亲不仅告诉了她真相，也同样教给她从失败中学习的方法，告诉她为了未来的成功需要付出全部努力。伊丽莎白感到失望时，她的父亲很同情她，但他没有给她虚伪的鼓励，因为那只会让她在未来感到更加失望。\u003c/p>\u003cp>我与很多教练交谈的时候，他们都会问我：“那些可塑之才都怎么了？这样的运动员都哪去了？”很多教练抱怨说，当他们给予运动员纠正性的反馈时，这些运动员都会抱怨自己的自信心受到了打击。有时这些运动员还会打电话回家向父母抱怨。他们似乎只希望教练告诉他们，自己多么有天赋，其他的什么也别说。\u003c/p>\u003cp>这些教练说，在过去，一场联赛或少儿足球赛结束后，父母们会在回家的路上与孩子们回顾和分析球赛，给他们提供一些有帮助的建议。而现在在回家路上，如果孩子们当天表现不好或者所在的球队输了，父母们会责怪教练和裁判。他们不愿意责怪孩子，怕伤害孩子的自信心。\u003c/p>\u003cp>但是从上面伊丽莎白的例子中可以看出，孩子们需要诚实而有建设性的反馈。如果孩子们被“保护”起来，他们将无法从失败中很好地学习。他们会认为建议、指导和反馈是消极而具有破坏性的。回避建设性的批评并不会帮助孩子们建立自信，反而会危害他们的未来。\u003c/p>","explains":"\u003cp>【学习目标】在跟随我完成本次的RIA现场学习后，当孩子遭遇失败向学习者寻求帮助的时候，学习者能够通过说感受、讲事实、提建议的方式（澄清），提出（行动）诚肯而有建设性（界定）的反馈（行为）。\u003c/p>\u003cp>这个片段在后半段主要讲述了一个9岁的小女孩遭遇失败时，她的父亲是如何使用成长型思维处理的。在文中有提出了一个问题“如果你是伊丽莎白的父母，你会怎么做？”，同时，给出了五种回复的方式，并一一进行分析。前四种的处理方式归结起来就是：自我催眠、推卸责任，但这些并无法真正帮助到孩子。只是打着“保护孩子自信心”的旗帜，阻碍着孩子的成长，只有第五种才是使用成长型思维的处理方式。\u003c/p>\u003cp>有个成语叫忠言逆耳，要如何让这“忠言”听着更“顺耳”，如何让伊丽莎白愿意接受，甚至是乐意接受呢？他的父亲做了一个很好的表率，不仅使用了成长型思维帮女儿处理问题，而且做了一个诚实而有建设性的反馈。\u003c/p>\u003cp>【HOW】从这个片断中的“父亲”与孩子的对话过程中，我提炼出以下三步骤，可以在当孩子遭遇失败向你寻求帮助时，我们做为父母可以运用这个步骤向孩子做出诚肯而有建设性的反馈。\u003c/p>\u003cp>一是说感受：比如“我知道你的感受”、“你对比赛给予了如此大的希望”……，通过说感受让孩子感受到，大人能理解他，达到共情的目的。\u003c/p>\u003cp>二是讲事实：比如“你并没有付出100%的努力”、“有很多女孩练习体操的时间都比你长，而且比你更努力。”，说事实，是避免双方都陷入评判的地步，使大家能基于事实来进行沟通交流。\u003c/p>\u003cp>三是提建议：比如他提了两个建议，一是“如果只是想拿体操当个乐趣，那也没有问题。”；二是“如果这是你真心想要的东西，那么你就要全身心地为此付出努力。”、“如果她想在比赛中有所成就，那么就必须付出更多。”\u003c/p>\u003cp>当然这三者的顺序并不是固定的，可能是感受与事实在前，建议在后；也可能是先给建议，再说明感受和事实。\u003c/p>\u003cp>【举例说明】\u003c/p>\u003cp>我女儿从去年开始就很迷恋拼拼图，一开始是9块的，接着是16、32、48。从一开始拼木质的，到现在拼纸质的。从最早要选择她感兴趣的图案，到现在拼色块的。从以前的二维到现在尝试三维的，她对拼图一直保持着极高的热情。\u003c/p>\u003cp>对于她这个年龄层而言，拼图实际上是一个失败率非常高的游戏，要求观察细节选出正确的拼图，放置到正确的位置，放置的方向和角度要正确，很容易不小心碰到或者不小心把已经拼好的拼图弄坏了，只要有一块拼错，后面就会跟着一直错。\u003c/p>\u003cp>她玩游戏一般都是我陪着她拼，最开始9块都不会拼的时候，一不对，就开始在那发脾气，扔拼图。我现在就会抱抱她，“你很生气，没拼对是吧。”、“就差一点点是吗？”、“没对准是吗？”……【说感受】\u003c/p>\u003cp>等她的情绪慢慢停下来了，我会陪着她把拼图捡起来，“你很生气是吧，没把拼图们送回家是吗？”、“你现在拼的这张图比之前多花了些30分钟，还没弄好，是吗？….【说事实】\u003c/p>\u003cp>接着我会试着引导她：你可以尝试先做简单的部分，不一定停在难住你的部分。你也可以尝试一下多转个方向、另外换个位置试试看……甚至我会问她，是否需要妈妈帮忙。而我的帮忙一般是动口不动手。【给建议】\u003c/p>\u003cp>现在不仅在拼拼图上，而且在搭积木、黏黏土……她情绪发泄的时间不长，而且当安抚完后，她会愿意再次去尝试，甚至自己会在那念叨着“太高了”、“太少了”……她开始有一个冷静后的自我分析的过程。虽然有时候她还是会有情绪失控的时候，但我看到的是失败后她仍旧勇于去尝试，也会尝试去分析，当然她现在也发现了自己的局限性，她开始会主动寻求帮助。\u003c/p>\u003cp>无论在这个过程中，她面对怎样的失败和挫折，她都能保持着非常高的热情。\u003c/p>\u003cp>【适用边界】这个方法不仅面对失败时可以给予孩子诚肯而有建设性的反馈。当面对成功时，也同样适用用这个步骤，引导孩子从成功中学习到经验。\u003c/p>","interaction":"\u003cp>【A3促动参与】\u003c/p>\u003cp>【提出并明确问题】\u003c/p>\u003cp>拆书家：刚才分享的是当孩子遭遇失败寻求帮助时，通过说感受、讲事实、提建议三步骤做出诚实而有建设性的反馈。\u003c/p>\u003cp>当孩子遇到失败时，你能否感受到她的情绪以及是否能准确表达出她的情绪感受呢？你是否能获得信息且能保持客观的立场进行讲述孩子失败的事实呢？你是否能换位思考后给予中肯的建议呢？当孩子遭遇失败向你寻求帮助时，大家可能会在哪个环节中卡壳？或者会遗漏掉哪个环节？\u003c/p>\u003cp>学习者：说感受这个步骤。\u003c/p>\u003cp>拆书家：为什么是说感受呢？\u003c/p>\u003cp>学习者：因为需要先获得孩子的认同，才能获得信息了解事实并提出建议；我们通常需要先处理情绪再处理问题，如果有情绪可能就无法客观的处理，但说感受这件事我感觉似乎很难让小孩子理解。\u003c/p>\u003cp>拆书家：有没有具体的场景呢？哪个小伙伴能举例说说呢？分享一个具体的例子。\u003c/p>\u003cp>学习者曹志文：我有两个小孩，大的今年7岁，小的今年4岁，我感觉是不是因为两个小孩的问题，容易造成照顾不平衡，我发现我最小的小孩很容易发脾气，经过我的观察是因为她哥哥经常在我们大人不注意的时候，去逗她，有时候故意拿她的玩具，有时候碰她的小妹。经过一段的观察后，我发现了老大的这个问题，我就尝试教育他，问他怎么老是去干扰妹妹呢？老大撅着嘴回复我说：“我也不知道”。我们大人感觉他会不会是因为觉得妹妹的出现，导致他得到的照顾减少了，有一些嫉妒的感受。就跟他说， 你是不是嫉妒妹妹经常得到爸爸妈妈的关爱呢？他就不说话了。感觉他并不是理解什么是“嫉妒”这种感受。\u003c/p>\u003cp>拆书家：你是指你向你的老大说“嫉妒”感受这个词，你的老大似乎不是很认同？或者是说不理解？是吗？\u003c/p>\u003cp>学习者：是的\u003c/p>\u003cp>【互动】\u003c/p>\u003cp>拆书家：好的，感谢你分享的例子，大家觉得这个有没有代表性？能否理解“说感受”这个步骤在操作的过程中难以做到位，并不容易得到孩子的认可呢？\u003c/p>\u003cp>学习者：可以的\u003c/p>\u003cp>【讨论问题的本质】\u003c/p>\u003cp>拆书家：那我们就基于这个场景来深入探讨一下问题，大家觉得向孩子用“说感受”做到位，得不到孩子的认可其本质的原因是什么？请大家分成2组，在小组内进行讨论，给大家5分钟的时间，待会我会请伙伴们分享一下：\u003c/p>\u003cp>（5分钟后）\u003c/p>\u003cp>拆书家：好的，我们讨论先告一段落，我看到大家讨论都很积极，我们请组员代表出来分享一下你们的讨论成果\u003c/p>\u003cp>【学员分享】\u003c/p>\u003cp>学习者：我们觉得向孩子用“说感受”难以做到位，得不到孩子的认可其本质原因有这些：\u003c/p>\u003cp>1、父母平常不好意思或不知道如何说感受：就是羞于说感受，不好意思将感受说出来，或者说平时就是很少做这种表述，导致不知道如何表达。\u003c/p>\u003cp>2、较少让孩子理解什么是感受，这就造成父母说的感受，孩子不一定听得懂\u003c/p>\u003cp>3、说感受太麻烦，太费时：说感受经常需要反复的说，需要极大的耐性。而棍棒教育更简单直接，成效似乎更显著。这样子容易造成孩子不相信父母是在对他们说感受。\u003c/p>\u003cp>4、说感受时总是会“先入为主”，不够客观：受到固定思维的影响，大人会一直用原有的观点看孩子，正所谓“你以为的只是你以为的”。可能会存在针对不同的事实，却说出相同或相似的感受。\u003c/p>\u003cp>5、因为不了解行为背后的原因，所以无法准确说感受：有时候孩子都不知道做这个行为的具体原因，大人需要抽茧剥丝才能窥探到行为背后的原因和更深层的感受。\u003c/p>\u003cp>拆书家：大家都很棒，一下子提了很多因素，那这些因素中，哪一个比较关键呢？或者是说，可不可以总结一下最本质的原因是什么？给个提示：是出在孩子身上，还是父母身上呢？\u003c/p>\u003cp>学习者：父母让孩子体验“感受”、教育与践行不足\u003c/p>\u003cp>拆书家：大家认可吗？认可的伙伴，请举手!\u003c/p>\u003cp>（经过现场统计）\u003c/p>\u003cp>【明确问题】\u003c/p>\u003cp>拆书家：看来大家都很认可这个原因，的确，大多数孩子从小的时候，可以看做一张白纸，他对世界的认知，是有依赖父母及家庭环境，包括感受、情绪等等，如果父母没有创造这样子的氛围，突然间让孩子感受到大人跟他说你现在是处于什么样的情绪，跟他谈感受还是比较难的。\u003c/p>\u003cp>【引导分组讨论解决方案】\u003c/p>\u003cp>拆书家：\u003c/p>\u003cp>接下来，请小组讨论如何对父母对孩子“感受”的体验、教育和践行不足这个关键问题，有哪些方法和建议可以改善解决？讨论时间8分钟。\u003c/p>\u003cp>最后我们将请伙伴上来分享他们的成果。\u003c/p>\u003cp>【学员分享——讲解成果】\u003c/p>\u003cp>学习者：\u003c/p>\u003cp>1、可以通过情绪管理类的绘本，让孩子多了解和掌握各种不同的情绪，这样才能准确表达自己的情绪，同时也可以更准确的理解别人的表述。讲绘本的过程，也会让家长更了解孩子的理解程度。沟通过程中，选择孩子能理解的词语进行表述。\u003c/p>\u003cp>2、当出现孩子出现某些情绪时，可以利用相应的情境耐心向孩子解释。如当孩子因为输棋而出现嫉妒的情绪时，就可以耐心跟孩子解释你的情绪有生气、嫉妒，而且是因为嫉妒导致生气。这样就能帮助孩子认识和理解更多的情绪。只有先了解并理解情绪，才能进行准确表达。只有一次次的表达得当，才能让孩子理解自己的感受。\u003c/p>\u003cp>3、家长要做好情绪的自我觉察，主动察觉到自己的情绪变化，从而进行自我调控，不随便发脾气，也不先入为主给孩子批判。这个自我察觉并不容易，需要日常的刻意练习。当然，也可以让孩子来做这个监督者，比如可以与孩子约定好，让孩子来提醒大人控制好情绪，双方先订立好规则。\u003c/p>\u003cp>【总结——拆书家反馈】\u003c/p>\u003cp>非常感谢大家的分享，我总结一下刚刚大家的方法主要是这几步：\u003c/p>\u003cp>一、借助绘本，让孩子认识各种情绪的感受\u003c/p>\u003cp>二、帮助孩子发现和理解自己的情绪感受\u003c/p>\u003cp>三、家长主动要察觉和控制自己情绪，做好情绪管理，不随意发脾气、不先入为主给孩子批判。\u003c/p>\u003cp>这几点步骤，还是有一定的适用边界，个人认为还是比较适合低幼阶段的小朋友，建议越早实施越好，相信在结合运用今天所学得成长型思维思考方式，小朋友在成长的路上，会得到爸爸妈妈有力的指导。 现在我给大家留一个家庭作业，希望大家回去可以践行，学有所有。\u003c/p>\u003cp>【A2】布置任务——事后复盘\u003c/p>\u003cp>问：请问下大家，近期是否有遇到孩子/晚辈面对失败时，你需要给出反馈的情况？\u003c/p>\u003cp>答：有/没有\u003c/p>\u003cp>今天的课程结束后，希望大家能认真做个复盘，总结下这个反馈是否对孩子有所帮助，是否有体现出成长型思维模式。同时，规划下未来将如何使用成长型思维去提出反馈。\u003c/p>\u003cp>【学习者-徐雪艳案例】\u003c/p>\u003cp>&nbsp;我儿子今年6岁，在他5岁的时候我就希望他去学钢琴。他试了两次，都是哭着走出教室，我不忍心，就没逼他继续学。今年他6岁了，我又骗他去试一试，他去了5次后，又说不去了。他说“太难了”、“他不会”……我听了很生气，他怎么这么容易就放弃。但是我知道冲他发脾气没有什么用，甚至会有反效果。这次我是用这样折方式跟他沟通的\u003c/p>\u003cp>我首先是肯定他，跟他说你已经很棒了。我问了其他小朋友的爸爸妈妈，其他小朋友都是上一节课后，要练习好几次才能记住，你没有练习都能记住。如果你再练习一下，肯定更棒，就不会觉得难了。要不你再去上一次课，然后练习五次，再去上一次课，看看有没有变简单？他后来同意再去试试，目前来说学习的效果还不错。\u003c/p>\u003cp>复盘：我觉得我所给予的反馈算是有建设性的，但诚肯不诚肯可能有点水分哈。我自认为我儿子是有固定思维的，而我的反馈具备了一定的成长型思维。我希望他明白，很多事情一开始不会，经过学习会从不会变成会，而且每个人都是这样的。这应该是一种更刻意去培养他成长型思维的反馈方式，以后也打算继续朝这个方向去做。\u003c/p>\u003cp>不过，我觉得我在“说感受”的方面还可以做得更好些，当他遇到挫折时，有一些负面的情绪是正常的，接受并引导他舒缓情绪也很重要。\u003c/p>\u003cp>【学习者-曹志文案例】\u003c/p>\u003cp>背景；我的孩子上小学一年级，前两天上课忘带笔记本，为了记录老师布置的作业，和同桌要了一张纸记录；在记录完后去上厕所期间，他的同桌私下收回了那张记录纸，等他回来被同桌告知，要把纸收回不想给他了。最后布置的作业被擦，他也来不及抄录；只能放学后和其他小朋友询问。这件事给他造成了很大困惑不知道如何处理。\u003c/p>\u003cp>我选择跟孩子聊这个事：\u003c/p>\u003cp>一说感受：这件事给你造成了很大困惑对不对？心里也是不舒服对不对。事后还给你造成了很多麻烦。你想知道怎么处理这种事吗？\u003c/p>\u003cp>二讲事实：孩子这是一个物权问题，首先你的同桌把纸给了你，那就成为了你的东西，他已无权收回，你要清楚这点。\u003c/p>\u003cp>孩子说：要纸的时候我说的是给，同桌收回的时候说借，不想借我了。\u003c/p>\u003cp>我说：无论是给还是借，你同桌都物权在未经过你同意前，私下收回。\u003c/p>\u003cp>（在这个过程中，给孩子模糊的是非观中，建立一个判断对错的标准。有了这个标准，孩子相信自己是对的，不再困惑）\u003c/p>\u003cp>三提建议：既然你同桌做错了，还给你造成了困扰。这件事情你不能默默的接受，要站出来处理。这么处理呢？能跟他打吗？\u003c/p>\u003cp>孩子：不能。\u003c/p>\u003cp>我说：很好，不能打。这时候就要靠说了。下次在遇到这种事，你得跟他说\u003c/p>\u003cp>一、说事实：这纸不论你是送给我还是借给我，都不能私自收回，要经过我的同意\u003c/p>\u003cp>二、说影响：你这么私下拿走，已经给我造成很大的麻烦，我把作业都记录在上面了\u003c/p>\u003cp>三、提建议：如果我们还是好朋友，请把纸还我，或者让我抄一份。如果你还是不还的话我就只能找老师帮忙解决了\u003c/p>\u003cp>&nbsp; &nbsp; 在处理这件事情最好公开处理，有小朋友围观最好哈，能获得更多人支持。\u003c/p>\u003cp>【结尾】\u003c/p>\u003cp>今天分享到了尾声，我们一共分享了两个片段，第一个片段帮助我们理解什么是成长型思维及如何运用成长型思维分析问题、面对处理困境。当我们认识理解了什么是成长型思维后，才有利于在教育孩子时也运用到成长型思维帮助孩子成长。\u003c/p>\u003cp>第二个片段主要讲，当孩子遭遇失败向你寻求帮助的时候，父母如何向孩子做出诚肯而有建设性的反馈，引导孩子形成成长型思维。\u003c/p>\u003cp>孩子是父母的一面镜子，希望作为父母/长辈的我们能以身作则，也希望在潜移默化中，孩子/晚辈也能慢慢形成成长型思维。\u003c/p>\u003cp>希望今天的分享对大家今后的工作和生活有所帮助，感谢大家今天的参与，我是拆书家佳音。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1582874811000,"updated_at":1582874811000,"ria":true},{"id":9504,"topic":"发现你的思维模式","learn_goal":"介绍固定型思维模式和成长型思维模式的差异和对人的不同影响","remark":"《终身成长——重新定义成功的思维模式》是斯坦福大学心理学家卡罗尔•德韦克的著作。德韦克通过对成功的数十年研究之后，发现了固定型与成长型两种思维模式对人们的影响。只有用正确的思维模式看待问题，才能更好地达成人生和职业目标。\r\n\r\n该书在亚马逊心理类畅销榜坐镇10年，累计印刷180万册。世界首富比尔•盖茨非常喜欢这本书，他说仅仅对成长性思维模式进行一番深入了解，就能使自己的思想和生活彻底改变。修订版的腰封背面是帮主赵周老师对这本书的推荐，这本书也是拆书学院的授权拆书课之一。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"卷毛小蓝","city":"上海市"},"club":{"name":"上海申活分舵","city":"上海市"},"prologue":"大家好，我是卷毛小蓝，是一个新手拆书家。用三个标签来介绍一下我自己，第一个是人才测评，我的本职工作是人才测评，例如性格测评、智商测评等等，感兴趣的朋友我们可以多交流。第二个标签是码字小能手，从博客时代写到了公众号时代；为了达到全年52篇的目标，距离2020年到来还有十几天时间，我得每天写一篇公众号来度过最后这个月。第三个标签是诸葛钢铁，大家最近如果有追剧的话，可能会追一部叫庆余年的片子，里面范思辙的扮演者郭麒麟，他在演电视剧之前是相声演员，当然现在也还是；他在相声中塑造了一个女朋友的人物形象，叫诸葛钢铁，一个温婉动人的女子，所以粉丝就管自己叫诸葛钢铁了，我就是其中一个。","ratings_count":1,"texts":[{"id":13321,"quote":null,"explains":"\u003cp>\u003cstrong>拆书和拆书帮介绍\u003c/strong>\u003cbr>\u003c/p>\u003cp>今天是我的1-1过级拆。拆书是一种读书方法，也是一种学习方法。它的核心思想就是拆为己用，从自己出发，学习要以自己为主。读什么书，读书里的哪些部分，都要从自己的需求出发。重要的不是记住多少知识点，而是自己的理解、消化和应用。RIA拆书法包含三个阶段，第一步读原文；第二步用自己的话来阐述原文的观点，才能变成自己的理解，思考它在什么场合适用，什么场合不适用，这样才能消化吸收；第三步要联系自己，一个是联系自己过往的经验，找到一个和原文情况类似的例子，可以是成功的，也可以是失败的，思考成功和失败的地方；另外一个联系是联系自己的未来和计划，自己打算怎么用起来。\u003c/p>\u003cp>拆书可以自己一个人拆，写三张便签，一张是对原文的理解，一张联系自己的例子，一张写自己的行动计划。也可以像今天一样来到拆书帮线下的活动，分享给其他人听。拆书帮是一个学习社群，聚集了很多爱学习、关注自己成长的小伙伴，定期组织拆书活动，在这里一起学习，进行思想碰撞。大家在这里可以参与拆书活动，也可以像我一样开始升级打怪，成为一个拆书家。\u003c/p>\u003cp>\u003cstrong>书籍介绍\u003c/strong>\u003c/p>\u003cp>今天我分享的拆页来自《终身成长》这本书（展示书籍），副标题是重新定义成功的思维模式，作者是斯坦福大学心理学家卡罗尔•德韦克。该书在亚马逊心理类畅销榜呆了10年，累计印刷180万册。世界首富比尔•盖茨也非常喜欢这本书。这本书和拆书帮也很有缘分，修订版的腰封背面是帮主赵周老师对这本书的推荐，这本书也是拆书学院的授权拆书课之一。她对成功这个主题做了数十年的研究，她发现人们的成功不仅仅和天赋、能力有关，更和自身的思维模式有关。正是思维模式不同，导致了人们在达成目标方面存在差异。下面请大家阅读一下原文拆页，读完就抬头示意我。\u003c/p>\u003cp>\u003cstrong>I内容讲解\u003c/strong>\u003c/p>\u003cp>【what】拆页里面提到了成长型思维和固定型思维，两种思维最大的差别是固定型思维认为人的能力是不可改变的，我天生就是这么强，努力是没有用的；而成长型思维相信人是可以改变的，通过努力和学习可以提升我自己。从这里开始，不同思维模式的人就会有不一样的思考和行动。就像拆页中提到的，我被研究生院拒绝了，我面对失败的时候，固定思维相信人的能力不能改变，一种想法是我能力不行，我就完了，我没希望了；另外一种想法是觉得这件事情都是别人的错，我的能力一点没有问题；不管如何，对于这件事情我无能为力，不可以改变了，不能解决了。把问题推给别人，找外界的借口，固然可以让自己好受点，但对于想达成的目标会越来越远。\u003c/p>\u003cp>而成长思维觉得自己还是有机会的，虽然我现在不行，但未来我是可以的，还能做些什么改变现状，于是她选择打那个电话，接下来她更有可能找到自己努力的方向，多做些什么，为自己的成功做出准备。\u003c/p>\u003cp>【why】为什么不同思维会导致这么大的差异呢？其实人还是想让自己舒服的，如果相信一个事情是不能变得，我的能力是固定的，那最好我天生就这么厉害。所有让我觉得自己不够厉害的事情我就少去做，那就不会伤害到我。但如果我是一个成长性思维的人，我没有这种心理负担，我觉得明天的我会比今天的我更好，我不用担心今天的我失败了就完蛋了，我可以不断的去尝试，因为我知道自己更好的一面在那边。这样的话就可以看到面对失败的时候，两种思维一个愿意接受，一个不愿意承认，面对负面反馈的时候，一个愿意主动寻求反馈，一个不愿意去寻求反馈，以及包括面对挑战也是类似的。\u003c/p>\u003cp>然后我们在现实生活中，人并不是一出生就很强，婴儿就处于无敌模式。都是通过学习、尝试，从不熟练、失败中成长，积累经验教训的过程。但如果我们一开始就觉得自己很强，不能做一些挑战暴露自己弱点的话，这对我们的成长就是不利的。\u003c/p>\u003cp>【where／not】成长思维并不是说只要相信可以改变，就一定要去改变。要不要改变，取决于自己想要成为什么样的人，目标是什么。如果我目标在那里，我就去改变，完全不需要因为外界的压力去改变。同样的，成长型思维思维也不意味着相信改变可以发生就容易改变，事物发展有自然规律，有的事情容易改变，有的改变就比较花时间。\u003c/p>\u003cp>【how】当我们遭遇拆页中提到的失败或者挫折时，我们应该用什么样的成长型思维去面对它呢？首先不要着急给自己贴负面标签，说自己就是不适合，也不要着急给自己找借口，说都是别人的错，和我没关系，同样的不要着急给这件事情打叉号，这事情没价值，或者彻底没戏了。第二，要回想一下自己的目标是什么，我为什么要做这件事情，它是不是真的重要，值得自己继续努力。如果是的话，第三，为了达到这个目标，自己可以做一些什么进行改变，自己什么时候去做这个行动。如果成长型思维在面对挫折的时候，如果按照这样的步骤，可能会把我们从对自己的埋怨中拉出来。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1激活经验\u003c/strong>\u003c/p>\u003cp>说说自己的例子，看这本书的时候，一边看一边扎心，我觉得自己身上有很多固定型思维。我工作中的一部分是要做培训讲师给学员上课，得到的评价是个非常有亲和力的讲师，但控场能力不够，不能很好抓住学员的注意力。有一次课程评价很差，但搞笑的是，我感觉是自己讲那门课讲的最好的一次。拿到这个课程评价内心很难过，当时的想法就是我付出这么多了也不过得到这样的评价。可能我就是个性比较随和，不喜欢影响别人，不适合做培训，以后还是少培训一些吧，也省的听别人批评我培训做的不好，我烦死了。也给自己找过借口，这帮学员就是那种只愿意听老师填鸭灌输的，只想听正确答案，不喜欢思考，不喜欢自己讨论问题，不适合我这种启发式的、教练式的教学模式。这么想就更让我不喜欢培训这件事了。后面有同事协调我去培训，只要能回避我就回避了，或者抱着很大地心理负担去做培训。\u003c/p>\u003cp>今年下半年有一次旁听别人的培训，是个年长的培训师。当时想，如果我50岁年纪大了，是不是就会比较有影响力，更容易做个讲师了呢。同时在喜欢郭麒麟之后，看过他2016年到今年的相声表演，即使是像他这么有天赋的人，也是慢慢变得更好的，也是有一个成长的过程的。也进而反思培训对自己到底意味着什么？是不是想要去做好的一件事。我发现自己很喜欢分享，愿意把自己看到的好东西给大家分享，以前培训的时候学员也给过我很棒的互动和反馈，自己也很享受，如果因为一次负面评价和控场技巧就放弃了，也太可惜了。这件事情既然对我重要，那我就可以去试试看，提升我的控场技巧。\u003c/p>\u003cp>\u003cstrong>A2行动计划\u003c/strong>\u003c/p>\u003cp>我的计划是什么呢？在培训这件事情上，我以后肯定还是会遇到负面反馈的，我肯定还是会自怨自艾，但我可以提醒自己说，哎，你现在是不是固定思维了？不要着急给自己下结论呀，我还能做什么改变？\u003c/p>\u003cp>具体落到行动上，从这个月开始，每个月至少讲一次培训。如果公司没有培训需要我讲，我就在拆书帮、优势学习等社群里面讲，给自己练习的机会，提升自己的培训能力。这样就是让成长型思维，帮助在我想要改变的目标上提升自己。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1576727974000,"updated_at":1576727974000},{"id":9493,"topic":"通过制定“可实施计划”提升行动力  ","learn_goal":"通过制定可实施计划提升行动力","remark":"面对失败时，你是否曾经怀疑自己的能力？面对较难的挑战时，你是否担心被证实智力、能力较差，而选择放弃？生活中我们的压力往往来源于以上的思维方式，《终身成长》里推崇大家使用“成长型思维”看问题，让我们面对失败、挑战时，相信能通过自己的努力，不断提升。","level":"TF2-3","duration":20,"status":30,"type":0,"chaishujia":{"username":"灵君","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"\u003cp>大家好，我是灵君，灵活的灵、君子的君。先简单的介绍下自己：我的一个标签视觉记录2018年12月第一次尝试视觉记录，接着在这个方面不断精进，给课程做视觉记录也开启了自己的手绘日更。对手绘、视觉感兴趣的伙伴可以随时链接。\u003cbr>\u003c/p>\u003cp>\u003cstrong>&nbsp;[分组]&nbsp;\u003c/strong>\u003c/p>\u003cp>接我介绍分享完毕，接下来今天会有讨论环节，让大家充分结合自己的经验分享，那么先给大家分好小组。按照作为顺序2人一组，请大家找到你的伙伴确认下眼神。\u003c/p>\u003cp>\u003cstrong>&nbsp;[学习目标]&nbsp;\u003c/strong>\u003c/p>\u003cp>今天，在大家跟随我一起学习完本片段后，当你在工作或生活中想要解决某个问题时（比如学习某个知识、完成某项考试等），可以使用“可实行计划”三步法，来设计方案，提升自己的行动力。&nbsp;\u003c/p>\u003cp>\u003cstrong>【图书介绍】\u003c/strong>\u003c/p>\u003cp>在开始学习之前，先给大家介绍下《终身成长》这本书\u003c/p>\u003cp>F：《终身成长》是由资深心理学家卡罗尔 德韦克撰写的，主要讲解了“成长型思维”模式相对于智商、能力，更容易让人发挥潜能获得成功。\u003c/p>\u003cp>A：本书蝉联美国亚马逊心理类畅销榜10年，累计印刷180万册。相对于其他成长类图书，《终身成长》内容来源于作者数十年的研究，有大量实验数据支持。并且作者不仅全方位展示了“成长型思维”的优势，还提供了切实可行的方法论，帮助人们建立 “成长型思维”。\u003c/p>\u003cp>B1：面对失败时，你是否曾经怀疑自己的能力？面对较难的挑战时，你是否担心被证实智力、能力较差，而选择放弃？生活中我们的压力往往来源于以上的思维方式，《终身成长》里推崇大家使用“成长型思维”看问题，让我们面对失败、挑战时，相信能通过自己的努力，不断提升。\u003c/p>\u003cp>Ｂ2：拥有“成长型思维”的人会从失败中总结经验，重新设立目标，制定切实可行的计划来帮自己走出困境。今天的拆页作者就告诉大家，如何制定“可实行计划”，来解决问题。\u003c/p>","ratings_count":1,"texts":[{"id":13308,"quote":"\u003cp>\u003cstrong>【阅读原书拆页R】\u003c/strong>\u003c/p>\u003cp>请大家先阅读手中拆页。阅读完毕抬头示意一下。\u003c/p>\u003cp>\u003cstrong>可实行的计划与不可实行的计划\u003c/strong>\u003c/p>\u003cp>这位申请者最关键的反应就是给学校打电话收集更多信息，这并不容易。人们每天都计划着去做一些困难的事，但他们往往不会真的将其付诸行动。他们会想“我明天再做吧＂，并发誓第二天一定要完成任务。但彼得・戈尔维策( Peter Gollwitzer)及其同事们的研究却显示，誓言，甚至是强烈的誓言，往往是没有一点用的。明天之后还有明天。\u003c/p>\u003cp>有效的做法是制定一个清晰具体的计划:“明天，在我休息的时候我要喝杯茶，关上办公室的门，给学校打电话。”或者换个例子:“周三早上，我起床刷牙后，要马上坐在书桌前开始写报告。”或者是:“今天晚上，吃过晚饭洗完碗后，我要和我的妻子在客厅坐下，和她谈话。我会对她说:‘亲爱的，我想和你说点事，我想这会让我们更幸福。’”\u003c/p>\u003cp>想想你要去做的某件事，去学习的某些知识，或是要面对的某个问题。\u003cstrong>先明确目标，然后制定一个具体的计划。你要在何时实行计划?你将在哪里实行计划?你准备怎样实行计划?要考虑到具体的细节。\u003c/strong>\u003c/p>\u003cp>这些具体的、可以设想的计划涉及\u003cstrong>你做事的时间、地点和方式。这会让你保持高效的行动力，当然会提高成功的概率。\u003c/strong>\u003c/p>\u003cp>所以，不仅要制定一个成长型思维模式计划，更要设想具体细节设想你要如何实行它。\u003c/p>","explains":"\u003cp>\u003cstrong>【拆书家讲解引导I】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>Why\u003c/strong>好的，大部分伙伴已经阅读完毕，没有读完也没有关系，我们一同学习。面对问题大家经常会想要解决，很多时候目标也制定了，也开启行动了，可就是没办法坚持。导致你行动力较差的原因很多，其中有一个方法能提升我们的行动力——制定目标和规划时，足够具体、切实可行。 \u003c/p>\u003cp>\u003cstrong>What\u003c/strong>《终身成长》中提出了一个方法“可实行的计划”三步法：1、明确目标2、制定具体计划3、实施计划。通过这三步能帮助我们将问题详细分解，提升计划完成率。\u003c/p>\u003cp>\u003cstrong>How\u003c/strong>\u003cstrong>（细化原文步骤）\u003c/strong>那么这个三步法具体如何操作呢？\u003c/p>\u003cp>\u003cstrong>1\u003c/strong>\u003cstrong>、明确目标：\u003c/strong>不清晰目标时就去实践，往往会坚持不下去。就算咬牙坚持，也容易出现做完了发现完全不符合预期，浪费时间。在开始行动前，可以从以下两点明确目标：\u003c/p>\u003cp>\u003cstrong>①\u003c/strong>\u003cstrong>我的目标是什么？\u003c/strong>（what）\u003c/p>\u003cp>在什么时间，完成什么结果（量化目标）\u003c/p>\u003cp>\u003cstrong>②\u003c/strong>\u003cstrong>为什么我要实现这个目标？\u003c/strong>（why）\u003c/p>\u003cp>能清楚回答为什么实现，就会清晰的认知到目标对自己的意义，也为制定计划打好基础。\u003c/p>\u003cp>\u003cstrong>2\u003c/strong>\u003cstrong>、制定具体计划：\u003c/strong>目标清晰后，我们需要匹配具体的计划，可以从以下几个方面让行动计划更具体、切实可行。\u003c/p>\u003cp>\u003cstrong>①\u003c/strong>\u003cstrong>（when）开启行动的时间\u003c/strong>：比如文中举例的：明天我在休息时，周三早上，我在起床刷牙后；\u003c/p>\u003cp>\u003cstrong>②\u003c/strong>\u003cstrong>（where）明确行动地点\u003c/strong>：比如书桌前、客厅里。明确的地点会减少我们大脑思考行动的时间，有利于行动的及时开展。\u003c/p>\u003cp>\u003cstrong>③\u003c/strong>\u003cstrong>（how）明确行动步骤\u003c/strong>：比如：我会对她说:‘亲爱的，我想和你说点事，我想这会让我们更幸福。具体的行动步骤会让减少我们的压力感，促进行动。\u003c/p>\u003cp>\u003cstrong>④\u003c/strong>\u003cstrong>（who或其他）完善细节\u003c/strong>：行动计划细节越完善，越容易提升行动力。比如设计计划时，提前罗列需要配合的人，可以帮助我们提早做好沟通准备。\u003c/p>\u003cp>\u003cstrong>3\u003c/strong>\u003cstrong>、实施计划：\u003c/strong>在完成前两步后，就可以在预计的时间内督促自己完成行动即可。如果目标足够明确、计划足够具体，相信实施并不会太难。如果想要更好的促进自己完成，也\u003cstrong>可以增加奖励机制。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>where\u003c/strong>“可实行计划”三步法可以在较复杂的问题中使用，可以帮我们清晰目标、制定具体规划，最终解决。但对于需要即刻做出选择的简单问题，比如：“午饭到底选择外卖还是出去吃”，就可以不使用该方法了。\u003c/p>\u003cp>\u003cstrong>举例\u003c/strong>\u003c/p>\u003cp>以我学习视觉为例，今年1月开始接触视觉，慢慢跟着老师临摹学习，但总很难突破自己呈现模式单一、过于细致的问题。9月时想要突破，我使用了“可实施计划”三步法，帮助我迅速解决问题：\u003c/p>\u003cp>\u003cstrong>1\u003c/strong>\u003cstrong>、明确目标：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>a\u003c/strong>\u003cstrong>：我的目标是什么？（what）\u003c/strong>\u003c/p>\u003cp>在1个月内，学习视觉笔记的呈现方式，在视觉记录现场做1次差异化呈现\u003c/p>\u003cp>\u003cstrong>b\u003c/strong>\u003cstrong>：为什么我要实现这个目标？（why）\u003c/strong>\u003c/p>\u003cp>只有学习并尝试不同风格，才能让视觉记录水平尽快提升，也方便匹配不同客户需求\u003c/p>\u003cp>\u003cstrong>2\u003c/strong>\u003cstrong>、制定具体计划：\u003c/strong>\u003c/p>\u003cp>目标清晰后，我就开启了学习计划制定：\u003c/p>\u003cp>\u003cstrong>a\u003c/strong>\u003cstrong>：（when）开启行动的时间：\u003c/strong>9月14-15日学习线下两天课程并完成认证；9月15日-10月15日，完成每日1幅视觉作品练习。\u003c/p>\u003cp>\u003cstrong>b\u003c/strong>\u003cstrong>：（where）明确行动地点：\u003c/strong>每日早餐后在书房完成\u003c/p>\u003cp>\u003cstrong>c\u003c/strong>\u003cstrong>：（how）明确行动步骤：\u003c/strong>我规定了自己写完每日500字心得（读书、电影等等）后绘制文字内容\u003c/p>\u003cp>\u003cstrong>d\u003c/strong>\u003cstrong>：（who或其他）完善细节：\u003c/strong>要求自己将文字和手绘上传到头条账号、微博。\u003c/p>\u003cp>\u003cstrong>3\u003c/strong>\u003cstrong>、实施计划：\u003c/strong>\u003c/p>\u003cp>在完成前两步后，我就开启了认证课程，并在上面认识了厉害的前辈，交流学习。后来每天开启码字+配图，并且在头条和微博上发布，不断收到反馈，促进我坚持下去。\u003c/p>\u003cp>10月下旬为一位老师绘制视觉记录，得到认可。通过1个月的努力，再去完成视觉记录时明显在呈现模式上有了突破。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3促动学习者现场演练】\u003c/strong>\u003c/p>\u003cp>我们刚刚一起学习了如何使用“可实施计划”三步法，来帮助我们设定计划，提升行动力，那我们一起来练习下如何使用。\u003c/p>\u003cp>场景设计\u003c/p>\u003cp>Alice今年要准备在职研究生考试，还有2个月了，但因为每天上班比较忙，一下班就想休息，周末也因为放松总耽误复习，她想要解决这个问题，向学霸lily咨询。\u003c/p>\u003cp>小组讨论\u003c/p>\u003cp>面对苦恼的Alice，lily怎样使用今天学些的“可实施计划三步法”，来帮助Alice梳理行动计划，促进她在最后冲刺的2个月安心复习呢？\u003c/p>\u003cp>下面就请大家在小组内演练，一会我会请一组伙伴上台分享。\u003c/p>\u003cp>\u003cstrong>分享者内容：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>Alice\u003c/strong>\u003cstrong>：\u003c/strong>还有2个月就要参加研究生考试了，但明显感觉时间不够用，每天上班比较忙，一下班就想休息，Lily你有什么好的办法吗？\u003c/p>\u003cp>\u003cstrong>Lily\u003c/strong>\u003cstrong>：\u003c/strong>好的，Alice我想先问2个问题：“你为什么想要考取研究生呢？”“”你想要考这个学校需要多少分？（\u003cstrong>1、明确目标：\u003c/strong> \u003cstrong>①\u003c/strong>\u003cstrong>我的目标是什么？\u003c/strong>（what）\u003cstrong>②\u003c/strong>\u003cstrong>为什么我要实现这个目标？\u003c/strong>（why））\u003c/p>\u003cp>\u003cstrong>Alice:\u003c/strong>现在工作很累，我想要通过学历提升，可以为将来换工作、提升收入做准备。我的目标就是能在2个月后按照以往该学校的录取分数顺利通过考试，现在要解决时间不够用的问题。\u003c/p>\u003cp>\u003cstrong>Lily\u003c/strong>\u003cstrong>：\u003c/strong>好的，你的目标已经很明确了，目前来看是需要匹配合理计划，我的建议是：\u003c/p>\u003cp>可以利用下班后的时间集中学，或是利用碎片时间（\u003cstrong>2、制定具体计划：\u003c/strong>\u003cstrong>①\u003c/strong>\u003cstrong>（when）开启行动的时间\u003c/strong>）；\u003c/p>\u003cp>下班后如果在家里学习，需要找一个安静的角落，周围没有事情影响，提升注意力（\u003cstrong>2、制定具体计划：\u003c/strong>\u003cstrong>②\u003c/strong>\u003cstrong>（where）明确行动地点\u003c/strong>）；\u003c/p>\u003cp>针对每门课，需要思考一周7天，每天集中复习哪一门，在进入学习区域后，立即打开该门课程资料开启学习（\u003cstrong>2、制定具体计划：\u003c/strong>\u003cstrong>③\u003c/strong>\u003cstrong>（how）明确行动步骤\u003c/strong>）；\u003c/p>\u003cp>可以通过一些小细节来提升行动力，比如买一些好看的本子当错题本，让自己心情愉悦（\u003cstrong>2、制定具体计划：\u003c/strong>\u003cstrong>④\u003c/strong>\u003cstrong>（who或其他）完善细节\u003c/strong>）；\u003c/p>\u003cp>有了以上的准备，就需要开始实施计划了，可以设立一些奖励措施，比如完成一张卷子吃一顿大餐，用这样的方式提升幸福感，坚持完成2个月复习。（\u003cstrong>3、实施计划\u003c/strong>）\u003c/p>\u003cp>\u003cstrong>Alice\u003c/strong>\u003cstrong>：\u003c/strong>你的建议很全面哇，也的确是马上可以操作的，我回家就按照上面的内容梳理一下2个月的计划，尽快开启最后冲刺。\u003c/p>\u003cp>\u003cstrong>【总结】\u003c/strong>\u003c/p>\u003cp>好的，通过今天的学习和演练，以后在遇到问题需要解决时，希望大家可以使用“可实施计划”三步法，理清自己的目标，制定出具体的计划，开启坚定不移的行动。相信我们解决问题的能力一定会迅速提升！这就是今天的分享，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1576588568000,"updated_at":1576588826000,"ria":true},{"id":9294,"topic":"终身成长：培养成长型思维模式","learn_goal":"大家再做事时，不再沿用固定型思维模式，而是采用成长型思维模式","remark":"你想拥有满满的正能力，摆脱爱抱怨的困境吗？\r\n你想改变，逃出重重阻力，迈开前进的步伐吗？\r\n你想转变思维，获得终身成长，成为人生赢家吗？\r\n \r\n推荐《终身成长》这本书，它颠覆传统成功学的观点，坐镇美国亚马逊心理畅销书10年，经比尔·盖茨、樊登、赵周老师等众名人的鼎力推荐，是心理学领域不得不读的一本好书。\r\n \r\n11月18日，福田场，欢迎你的到来，我们一起探讨：如何借助成长型思维模式，突破改变的重重阻力，获得终身成长，成为人生赢家。","level":"TF3-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"alisa33","city":"深圳市"},"club":{"name":"深圳智行分舵","city":"深圳"},"prologue":"\u003cp>&nbsp; &nbsp;大家好，我是alisa，很高兴今天跟大家再次相聚，我也非常感谢大家的到来，陪我们3个拆书家一同拆书成长。接下来分享的是关于成长型思维模式的话题。\u003c/p>\u003cp>为今天拆书特意准备的三个标签：\u003c/p>\u003cp>1、从固定型在向成长型思维模式转变的路上，来自于本书收益；\u003c/p>\u003cp>2、从小被表扬的那个“别人家的孩子”，而自己却很清楚，实际，真没那么好，主要存在认识和思维上的差异；\u003c/p>\u003cp>3、喜欢分享，今天带拆3-2。沟通，习惯类主题，165天觉察日记，443天每天1万步，希望今天的分享能给你启发。\u003c/p>\u003cp>\u003cstrong>为便于\u003c/strong>\u003cstrong>接下来\u003c/strong>\u003cstrong>的学习，我们先分下组：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>具体分组指令在\u003c/strong>\u003cstrong>A3环节。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【事件场景】：\u003c/strong>\u003c/p>\u003cp>先给大家描述几个工作或生活中的场景：\u003c/p>\u003cp>场景1：还是得相信星座，我跟我老公或者老婆两人就是星座不合，当初我还不信，这不，两人天天干架，这辈子呀，幸福是没指望了。\u003c/p>\u003cp>场景2：部门聚会，同事喊你唱歌，你每次都是再三推脱“我不行，不会唱歌，天生五音不全”；\u003c/p>\u003cp>场景3：每次公司有挑战性的项目，你总是躲的最远的那个，生怕不小心砸到你，搞得头破血流；\u003c/p>\u003cp>\u003cstrong>【提问互动】\u003c/strong>\u003c/p>\u003cp>在坐的小伙伴，你曾有过类似的经历没？你是如何处理的呢？是固步自封，拒绝改变，还是换个思维看问题，想办法去解决呢？\u003c/p>\u003cp>\u003cstrong>【影响】：\u003c/strong>\u003c/p>\u003cp>思维模式影响一个人的婚姻、家庭和事业，甚至整个人生状态。固定型思维严重的人，他们悲观，充满负能量，往往学习不努力，工作不积极，生活没激情，他们听天由命，害怕失败，恐惧挑战，最终停止不前。\u003c/p>\u003cp>\u003cstrong>【解决】：\u003c/strong>\u003c/p>\u003cp>今天带拆的书是：《终身成长》。作者告诉我们，成功，并不是由能力和天赋决定的，更受思维模式的影响。书中介绍了两种思维模式：固定型和成长型，体现我们应对成功与失败时的两种基本心态，帮我们找到恐惧、失败的原因，突破阻碍，获得成长。\u003c/p>\u003cp>通过今天的分享，希望大家在面对失败与挑战时，采用成长型思维模式的“成长四步曲”来应对，获得终身成长，成为人生的赢家。\u003c/p>\u003cp>\u003cstrong>学习目标：\u003c/strong>\u003c/p>\u003cp>通过今天的分享，希望大家能够辨识出成长型和固定型思维模式，在面对失败与挑战时，采用成长型思维模式的“成长四步曲”来应对，突破阻碍，勇往直前。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A1】激活经验\u003c/strong>\u003cstrong>&nbsp;自测题\u003c/strong>\u003c/p>\u003cp>到这，你是不是好奇自己的思维模式到底如何呢？正好，给大家准备了测试题，在拆页第一部分。\u003c/p>\u003cp>用第一感觉回答，不需要深度思考，1分代表完全不符合，6分代表非常符合。\u003c/p>\u003cp>做完加下总分。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>1、我的能力和智慧是可以通过后天的努力改变的。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2、面对失败，我不逃避，接纳自己。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3、我每次都能有意识的调整自己做事的思维模式。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4、我总能从失败中分析原因，把它看作一次学习的过程。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>5、遇到困难，我总会想尽办法去解决。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cstrong>上述各项得分合计：\u003c/strong>\u003cstrong>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>I\u003c/strong>\u003cstrong>】\u003c/strong>\u003cstrong>解释自测题\u003c/strong>\u003c/p>\u003cp>好，大家都做完了：\u003c/p>\u003cp>得分在24分以上的小伙伴请举手？\u003cstrong>互动\u003c/strong>\u003cstrong>放下\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者：迪迪\u003c/strong>\u003cstrong>&nbsp;阿丁2人举手\u003c/strong>\u003c/p>\u003cp>说明你具有高水平的成长型思维模式，不怕失败，喜欢挑战；\u003c/p>\u003cp>12—24分之间的呢？\u003cstrong>放下\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者：大部分伙伴举手\u003c/strong>\u003c/p>\u003cp>你具有一定水平的成长型思维模式，可以借助一些方法和工具，通过练习，不断向成长型思维模式去转变；\u003c/p>\u003cp>12分以下的有吗？\u003cstrong>没有，恭喜大家\u003c/strong>\u003c/p>\u003cp>要留意了，你爱抱怨，常被固定型思维模式包围。\u003c/p>\u003cp>辛运的是，研究发现，很多人仅仅知道两种思维模式的存在就获得很大的启发。\u003c/p>\u003cp>得分越高，说明你的成长型思维模式水平越高。\u003c/p>\u003cp>有兴趣的小伙伴，分享后可以再次测评，看是否有进步。\u003c/p>","ratings_count":2,"texts":[{"id":13074,"quote":"\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>好，了解了思维模式的现状，那么，我们又该如何改善呢？\u003c/p>\u003cp>接下来，请大家快速浏览拆页，读完后抬头示意我下，时间1分钟。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>拆书主题\u003c/strong>\u003cstrong>】\u003c/strong>\u003cstrong>：\u003c/strong>\u003cstrong>培养\u003c/strong>\u003cstrong>成长型思维模式\u003c/strong>\u003c/p>\u003cp>困境2：压力太大了。你迫切渴望上场比赛，但每次他们让你上场，想看看你的本事，你却因为过于紧张而无法集中精神。你以前在压力下总能保持冷静，但这是职业联赛。现在你眼里只有向你冲来的那些大个子——体重加起来足有一吨的大个子们想要把你撞飞。这些大个子的动作快得超乎你的想象。你感觉被包围了，而且孤立无援。\u003c/p>\u003cp>成长型思维模式的解决办法：在成长型思维模式下，\u003cstrong>你告诉自己\u003c/strong>\u003cstrong>，\u003c/strong>进入职业联赛代表着一个巨大的进步，需要进行很多调整和学习。有很多事你不可能一下子了解，现在你最好开始努力了解它们。\u003c/p>\u003cp>你试着去花更多时间和经验丰富的四分卫相处，向他们取经，和他们一起观看比赛录像。\u003cstrong>你不再隐瞒自己的不安全感，而是告诉他们这与大学联赛相比有多么不同。\u003c/strong>他们则会向你坦白，他们当年的感觉和你一模一样。实际上，他们还会给你讲述自己当年受辱的故事。\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp;你问他们当年是如何克服起步阶段的困难的，\u003c/strong>他们会传授给你精神和身体上的技巧。当你开始感觉更能融入球队时，你会意识到你是这个集体的一部分。这个集体想要帮助你成长，而不是评判或者轻视你。你不再担忧球队为你的才能付出了过高的代价，你开始用高度努力的工作和团队精神来回报球队为你付的钱了。\u003c/p>\u003cp>以上，拆页片段结束。\u003c/p>","explains":"\u003cp>好，看大家都读完了拆页。\u003c/p>\u003cp>\u003cstrong>【WHY/WHAT】：\u003c/strong>\u003c/p>\u003cp>其实，我们出生时，都是具有很高水平的成长型思维模式的。\u003c/p>\u003cp>回想婴儿时，跌倒了，我们会立刻站起来；说错话了，也不会觉得脸红。为什么？因为，那是婴儿在\u003cstrong>学习走路\u003c/strong>，\u003cstrong>学习说话\u003c/strong>\u003cstrong>，没错，在学习\u003c/strong>。后来，我们长大了，反而是怕这怕那，停滞不前了。\u003c/p>\u003cp>请问中间到底发生了什么变化？\u003cstrong>互动\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者：害怕跌倒\u003c/strong>\u003c/p>\u003cp>因为我们转变了思维模式：由成长型变成了固定型。\u003c/p>\u003cp>试想，如果家长总夸孩子聪明，一开始孩子也信了，可是等他真正遇到困难，发现自己的水平并不比别人厉害，就会认为家长一直在骗他，觉得自己反倒是个笨孩子，于是就变得畏畏缩缩，怕这怕那。\u003c/p>\u003cp>那么，怎么理解固定型和成长型，两种思维模式呢？\u003c/p>\u003cp>固定型思维模式认为，人的智商是天生的，后天再怎么努力也不会改变。他们倾向于回避失败与挑战，更看中自己的身份标签：是个什么人；\u003c/p>\u003cp>相反的，成长型思维模式认为，人的基本能力可以通过努力培养。不管你的天赋如何，相信通过练习，都是可以改变提高的。他们不怕失败和挑战，更专注于成长的过程，考虑的是：下一步该做什么事。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>简单的\u003c/strong>\u003cstrong>互动提问】：\u003c/strong>\u003c/p>\u003cp>现在我们回到拆页，一起看一下。\u003c/p>\u003cp>请问大家，拆页给我们介绍的思维模式叫什么呢？想想我们今天的主题？\u003cstrong>互动\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>\u003cstrong>成长型思维模式\u003c/strong>\u003cstrong>&nbsp;&nbsp;点头回应\u003c/strong>\u003c/p>\u003cp>对，在面对压力、挑战时，成长型思维模式的人是如何应对的呢？\u003c/p>\u003cp>是选择接纳自己，转变思维？还是逃避呢？\u003cstrong>互动\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者：接纳自己\u003c/strong>\u003c/p>\u003cp>是的，他们接纳自己的现状，转变思维。拆页提到，他们认识到跟职业联赛存在的巨大差距，有很多需要学习和调整的地方，需要努力去了解，等等。\u003c/p>\u003cp>其次，成长型思维模式的人还做了那些动作呢？有没有分析原因？\u003cstrong>互动\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者：有\u003c/strong>\u003cstrong>的\u003c/strong>\u003cstrong>。\u003c/strong>\u003c/p>\u003cp>他们分析使自己紧张、没有安全感、不敢上场的原因，说出自己的真实感受，弄明白触发固定型思维模式的根源。\u003c/p>\u003cp>最后，找到原因后，他们做的最重要的动作，是什么呢？想要改变，就得（行动）？\u003cstrong>互动\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>\u003cstrong>立即行动\u003c/strong>\u003cstrong>。\u003c/strong>\u003c/p>\u003cp>对，立即行动，想办法解决，他们向其他四分卫的伙伴请教，如何克服起步阶段的困难，不断尝试，最终融入组织。\u003c/p>\u003cp>\u003cstrong>【行动步骤】：\u003c/strong>\u003c/p>\u003cp>通过上述分析，我们归纳出培养成长型思维模式的核心步骤，便于大家记忆，我给起名为：“成长四步曲”：\u003c/p>\u003cp>\u003cstrong>第一步：接纳\u003c/strong>\u003cstrong>自我\u003c/strong>。世界本无完人，我们要勇敢接纳眼前的自己。比如，考试不及格，就告诉自己，只是“暂时没有通过，并不代表永远通不过，下次需要更加努力”。\u003cstrong>记住4个字“暂时没有”\u003c/strong>；\u003c/p>\u003cp>\u003cstrong>第二步：\u003c/strong>\u003cstrong>转变\u003c/strong>\u003cstrong>思维\u003c/strong>\u003cstrong>。\u003c/strong>做事前先停下来，留意自己内心的想法，是积极主动，还是消极被动？有意识将想法由“消极”往“积极”去转变，即由固定型向成长型思维模式转变；\u003c/p>\u003cp>\u003cstrong>第三步：分析原因\u003c/strong>。分析是哪些原因和想法导致自己停滞不前的，\u003cstrong>询问当时的感受是什么？\u003c/strong>是紧张、压力，还是焦虑？\u003c/p>\u003cp>\u003cstrong>第四步：\u003c/strong>\u003cstrong>立即\u003c/strong>\u003cstrong>行动。\u003c/strong>找到了触发问题的根源，就采取措施\u003cstrong>，立即\u003c/strong>\u003cstrong>行动\u003c/strong>\u003cstrong>，\u003c/strong>去改变它。老话说的好，“只要思想不滑坡，办法总比困难多”，可以去请教，借助工具，像《刻意练习》就很不错哦。\u003c/p>\u003cp>\u003cstrong>【正面例子】：\u003c/strong>举个例子：\u003c/p>\u003cp>我是很抗拒在公众场合发言的，简单几句话，每次就要忐忑好久，采用“成长四步曲”，我尝试着改变：\u003c/p>\u003cp>第一步，接纳自我：每次发言前，我对自己说，“这次说不好就说不好了，出丑也只是暂时的，为了以后说的更好”；\u003c/p>\u003cp>第二步，转变思维：每次我会停下来，留意内心的想法，刻意从“固定型思维”：“我不行”，“错了太丢人”往“成长型思维”：“错就错呗，谁也不认识谁”，“我得多练习，才可能下次更好”去转变；\u003c/p>\u003cp>第三步，分析原因：想想为什么我每次会紧张，是因为我缺乏公正演讲的技能，太在乎别人的看法和评价了，我担心出错、出丑，把自己包裹的严严实实，害怕表现；\u003c/p>\u003cp>第四步，立即行动：找到根源后，我看了心理学，行为科学，公众演讲等相关书籍，做了像拆书帮升级打怪的刻意练习，现在跟1-1时的变化就是我成长型思维模式转变的有力佐证。\u003c/p>\u003cp>\u003cstrong>【适用边界】：\u003c/strong>\u003c/p>\u003cp>“成长四步曲”适用范围很广，面对失败和挑战，在教育，体育、企业管理、人际沟通等都可以尝试。\u003c/p>\u003cp>当然，违反道德、法律法规层面的不建议。\u003c/p>","interaction":"\u003cp>\u003cstrong>13分钟开始\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A3】促动参与\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）：\u003c/strong>\u003c/p>\u003cp>好，分享了这么多，接下来进入学以致用的环节，我们设计一个小剧场，运用“成长四步曲”，进行角色演练。\u003c/p>\u003cp>\u003cstrong>【场景设计】\u003c/strong>\u003cstrong>：\u003c/strong>\u003c/p>\u003cp>话说某一天下班回家，老婆拉着老公说：今天我们领导找我，想把一个非常重要的项目给我做。这个项目是我们公司明年的重要战略之一，我以前从没做过这么大的项目，还是个新领域，我现在好纠结，要不要接呢？万一被我搞砸了怎么办？\u003c/p>\u003cp>【\u003cstrong>小组讨论，角色扮演\u003c/strong>】\u003c/p>\u003cp>\u003cstrong>现场分组，右手边\u003c/strong>\u003cstrong>3人，中间3人，左边2人一组\u003c/strong>\u003c/p>\u003cp>\u003cstrong>现场事故：一小伙伴凳子坏了 停顿了一段时间\u003c/strong>\u003c/p>\u003cp>要求：老公尝试用“成长四步曲”的方法帮助老婆成长。\u003c/p>\u003cp>一人扮演老婆，一人扮演老公，组内先讨论1分钟，再角色演练3分钟，最后请一组小伙伴分享。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>老\u003c/strong>\u003cstrong>婆\u003c/strong>\u003cstrong>的扮演者\u003c/strong>\u003cstrong>：\u003c/strong>\u003cstrong>学习者（娜娜）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>老公\u003c/strong>\u003cstrong>的扮演者\u003c/strong>\u003cstrong>：\u003c/strong>\u003cstrong>学习者（徐进）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>老婆：\u003c/strong>好烦呐，今天不想做饭，你做吧。\u003c/p>\u003cp>\u003cstrong>老公：\u003c/strong>可以啊。是什么让你觉得这么烦呢？\u003cstrong>（聆听，引导）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>老婆：\u003c/strong>今天领导说我优秀，想给我一个项目。可我觉得这个项目太大了，以前我没相关经验，好纠结，感觉有个好大的坑。（第一步，\u003cstrong>接纳自己）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>老公：\u003c/strong>你是觉得根本达不成，还是努力后可以克服呢？\u003c/p>\u003cp>\u003cstrong>老婆：\u003c/strong>我觉得我可以做到。不过要花很多时间，新的项目领域，还会有一些未知的困难，所以会让我感觉很害怕。\u003cstrong>（第一步，接纳自己）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>老公：\u003c/strong>你觉得做成这个项目会给你带来哪些成长或者改变呢？\u003c/p>\u003cp>\u003cstrong>老婆：\u003c/strong>提升项目经验，改变目前尴尬的职场局面，更实际的就是升职加薪，走上人生巅峰。\u003cstrong>（第二步，转变思维）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>老公：\u003c/strong>那是那些原因导致你不想接这个项目呢？\u003c/p>\u003cp>\u003cstrong>老婆：\u003c/strong>这是新项目，需要跟一个新的团队配合，比较担心新成员间的配合度。另外，确实是缺乏相关的经验，可能会考虑不周全，所以会犹豫。\u003cstrong>（第三步，分享原因）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>老公：\u003c/strong>那你有哪些办法可以解决吗？\u003c/p>\u003cp>\u003cstrong>老婆：\u003c/strong>提前跟新团队成员磨合沟通，预测项目可能会发生的一些风险，做好项目计划和预案。如果担心跟成员不熟悉的话，我就可以多请大家聚餐，下班后多交流，出去活动，加强感情沟通，提升默契度。\u003cstrong>（第四步，立即行动）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>老公：嗯，\u003c/strong>你这个想法非常好，我支持。\u003c/p>\u003cp>\u003cstrong>老婆：\u003c/strong>越说越觉得好，我现在就给老板打电话去。\u003cstrong>（第四步，立即行动）\u003c/strong>\u003cstrong>退场\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家点评\u003c/strong>\u003cstrong>：\u003c/strong>感谢娜娜和徐进小伙伴的分享。运用今天的“成长四步曲”，首先，“老婆”意识到自己的差距，第二步，“老公”巧妙的引导“老婆”转变思维，做不好如何，做好了升职加薪等；第三步，引导“老婆”分析原因，第三步“老婆”采取措施，如请客吃饭等，立即行动，给老板打电话。\u003c/p>\u003cp>“老公”巧妙的运用了“成长四步曲”帮助老婆改变思维，积极主动的接下这个挑战性项目。非常精彩。\u003c/p>\u003cp>\u003cstrong>【A\u003c/strong>\u003cstrong>2\u003c/strong>\u003cstrong>】催化应用\u003c/strong>\u003cstrong>&nbsp;&nbsp;\u003c/strong>\u003cstrong>布置特定任务\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>特定任务的\u003c/strong>\u003cstrong>A2：\u003c/strong>\u003cstrong>找人分享\u003c/strong>\u003cstrong>】\u003c/strong>\u003c/p>\u003cp>通过刚才的演练，进一步加深了对“成长四步曲”的理解。\u003c/p>\u003cp>俗话说的好，教是最好的学。为了让大家学得更好，给大家布置个小作业：回去一周内，找身边的小伙伴分享今天学到的内容。想想你会找谁分享呢？在什么时间，什么地方？你会分享哪部分内容呢？\u003c/p>\u003cp>请大家思考1分钟，写到拆页上，待会请小伙伴分享他的作业。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者案例记录：（现场分享）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>人物：\u003c/strong>\u003cstrong>学习者\u003c/strong>婷婷和她同学\u003c/p>\u003cp>\u003cstrong>时间：\u003c/strong>本周六下午\u003c/p>\u003cp>\u003cstrong>地点：\u003c/strong>在家里视频\u003c/p>\u003cp>\u003cstrong>分享要点\u003c/strong>\u003cstrong>：\u003c/strong>转变思维（固定型向成长型思维模式转变），&nbsp;想办法解决，少抱怨\u003c/p>\u003cp>同学刚工作，压力大，现在国外出差，一再说没人带她，项目时间非常紧，自己刚毕业又不懂。\u003c/p>\u003cp>给同学分享说，这是目前的现状，我们改变不了，要学着接受，可以分析原因，想办法找人帮助自己，看能否找人给到支持，可以是公司的同事，可以是师兄，师姐等。帮助同学转变思维，缓解压力，从负面情绪中走出来，换个角度和思维去思考，帮同学度过现阶段艰难的一段时光。\u003c/p>\u003cp>\u003cstrong>拆书家点评：\u003c/strong>感谢婷婷同学，希望回去后及时给你同学分享，尽快帮助到她走出困境。\u003c/p>\u003cp>\u003cstrong>结束语：\u003c/strong>\u003c/p>\u003cp>今天给大家分享了思维模式的话题，总结出培养成长型思维模式的“成长四步曲”，即：\u003c/p>\u003cp>1、接纳自我；2、转变思维；3、分析原因；4、立即行动。&nbsp;\u003c/p>\u003cp>最后，借用书中我最喜欢的一句话结束今天的分享：“你的能力恰如思维模式，只要想变，就能改变。”\u003c/p>\u003cp>愿今天的分享，你我都能有所成长。\u003c/p>\u003cp>好，我是Alisa，感谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1574153966000,"updated_at":1574765584000,"ria":true},{"id":8654,"topic":"夸孩子聪明，难道我错了吗？","learn_goal":"学习者通过学习后，可以在孩子教育过程中，应用成长思维方式教育","remark":"","level":"TF3-3","duration":60,"status":29,"type":0,"chaishujia":{"username":"吴佳音","city":"厦门"},"club":{"name":"厦门鹭岛抚琴分舵","city":"厦门"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 大家好，我叫佳音，用三个标签来介绍自己。\r\n专业——心理学：曾经主修的学业。\r\n职业——培训师：现在的谋生之道。\r\n副业——拆书家：未来的成长之路。&nbsp;\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;【介绍图书】\u003cbr>【事件】先说说本次的主题：夸孩子聪明，我错了吗？\r\n问：大家觉得这种夸奖是对还是错呢？\r\n答：对/错/不一定。\r\n以前，我们的教育模式多是“棍棒底下出孝子”，近些年，又开始风行“鼓励教育”，鼓励教育告诉我们，要多去发现孩子的闪光点，多去夸奖孩子，帮助孩子建立自信并且保护它，这一观点目前也为很多父母和老师所接受。\r\n比如，当孩子听了几遍儿歌后就能背下来时，会夸孩子“你学得真快！”；当孩子画出一副超出你预期的图画时，会夸孩子“你太有天赋了！”；当孩子成绩优异时，会夸孩子“你都没怎么看书就考这么高的分，你简直就是个小天才！”……\u003cbr>【提问】大家觉得孩子除了接收到鼓励，还可能接收到哪些信息呢？\u003cbr>【影响】可能是“我生来就很聪明”、“我从小就很有天赋，根本不需要什么努力。”、“妈妈喜欢聪明的我”、“聪明能够让我妈妈喜欢我，为了让妈妈一直喜欢我，我不能表现出不聪明。”…… \r\n如果孩子们接收到的是这些信息，他们为了维护自己的聪明，就不敢犯错，不敢去挑战更有难度的任务，他们甚至会通过撒谎来显示自己的天赋和能力。而这些将大大限制了他们发展和进步的空间。\r\n其实，不仅仅是夸奖，批评也一样，你传达的跟孩子接收到的可能并不对等。那么如何才能给予诚实而有建设性的建议，并且能够让孩子能准确接收到呢？\u003cbr>【解决（1）】答案就在《终身成长》这本书中。\u003cbr>&nbsp;在介绍这本书前，先做一个问卷调查。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>&nbsp; &nbsp; 【A1】请大家仔细阅读表格中描述的每一句话，并与自己平时的做法进行对照，然后给自己打分，1分代表完全不符合，6分代表完全符合。\u003c/p>\u003cp>请不要犹豫,看懂题意后马上做答并计分。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>问题\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>1\u003c/strong>\u003c/p>\u003cp>\u003cstrong>完全\u003c/strong>\u003c/p>\u003cp>\u003cstrong>不符合\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>2\u003c/strong>\u003c/p>\u003cp>\u003cstrong>不符合\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>3\u003c/strong>\u003c/p>\u003cp>\u003cstrong>略不\u003c/strong>\u003c/p>\u003cp>\u003cstrong>符合\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>4\u003c/strong>\u003c/p>\u003cp>\u003cstrong>略微\u003c/strong>\u003c/p>\u003cp>\u003cstrong>符合\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>5\u003c/strong>\u003c/p>\u003cp>\u003cstrong>符合\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>6\u003c/strong>\u003c/p>\u003cp>\u003cstrong>完全\u003c/strong>\u003c/p>\u003cp>\u003cstrong>符合\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>1、我总是勇于尝试新鲜事物应用于工作与生活中。\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>2\u003c/strong>\u003cstrong>.\u003c/strong>\u003cstrong>我总是愿意付出时间与精力学习来提升自身技能。\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>3、面对困难时，我愿意付出努力，以期获得更好的结果。\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>4、面对挫折时，我总是会尝试寻找不同的解决方式，以期有更好的结果。\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>5、面对失败，我总是会寻找存在的差距，提升自身技能，期许提高下次获得成功的几率。\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>6、面对成功，我总是会寻找存在的偶然因素，并努力转化为自身技能，期许下次的再次成功。\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>【I】大家可以计算下，你们所获得的分值。\u003c/p>\u003cp>若分值是26（含）以上，说明你经常使用成长型思维模式处理问题。\u003c/p>\u003cp>若分值是14—26，说明你具备成长型思维模式，但有时候会使用固定型思维模式处理问题。\u003c/p>\u003cp>若分值是14（含）以下，说明你经常使用固定型思维模式处理问题。\u003c/p>\u003cp>&nbsp; &nbsp; 什么是固定型思维模式和成长型思维模式？这就是《终身成长》这本书中提出的两个概念。图例中详细的解析了成长型思维认同的是智力是可以提升的，也就是说可以通过后天的努力和学习提高智力。所以成长型思维的人更愿意接受调整，甚至能从失败或批评中获得学习的机会。书中不仅详细解析什么是成长型思维模式，并通过案例分析具体的使用方法。\u003c/p>\u003cp>【解决（2）】今天我们将通过两个片段，更深入的了解什么是成长型思维、如何使用成长型思维处理困境、如何帮助孩子形成成长型思维。\u003c/p>\u003cp>&nbsp; &nbsp; 第一个片段是一个案例，面对同一个困境，固定型和成长型思维模式分别采取了不同的应对方式。接下来，请大家利用4分钟的时间进行阅读，阅读的过程中，也可以对照图例（固定型思维模式和成长型思维模式对比图）一并阅读。\u003c/p>","ratings_count":1,"texts":[{"id":12339,"quote":"\u003cp>这是一些思维模式练习，请与我一同面对一系列困境。在每个例子里，你会先看到固定型思维模式的反应，然后体验成长型思维模式的解決办法。\u003c/p>\u003cp>困境1：假设你报考了一所研究生院。你在志愿上只填了这一家学院，因为这是你唯一心仪的选择。你对录取充满自信，因为很多人都认为你在这个领域的研究工作独具创见，令人兴奋。但是，你的申请被拒绝了。\u003c/p>\u003cp>固定型思维模式的反应：一开始你告诉自己，竞争太激烈了，所以被拒绝不能反映你的真实水平。也许有太多条件优秀的申请者，研究生院无法全部接受。然后，你脑海深处那个声音开始说话了。那声音说，你是在骗自己，为自己找借口。它对你说，招生委员会认为你的研究工作不尽如人意。过了一阵，你对自己说，这可能是真的。你的工作也许真的平庸乏味，不值一提。他们发现了这一点。毕竟他们都是专家。对方已经做出了裁决一一你配不上这所学院。\u003c/p>\u003cp>在一番努力之后，你又说服自己相信了一开始的结论。这个结论也很合理，而且对你更有利。你感觉好一点了。在固定型思维模式下（在大多数认知疗法中也一样），事情到这一步就结束了。你重新找到了自尊，所以不用再多想了。但在成长型思维模式下，这只是一个开始：你之前只是在自说自话现在要开始学习和自我提高了。\u003c/p>\u003cp>成长型思维模式的解決办法：考虑好你的目标，然后想想你要怎么做才能实现它。你能采取哪些措施让自己获得成功？你能收集到什么信息？也许下次你该多申请几个学校。也许与此同时，你应该去广泛收集信息，让你的申请书更具竞争性：他们希望招收什么样的学生？他们最看重哪些经验？在进行下一次申请前，你要多积累这方面的经验。\u003c/p>\u003cp>这是一个真实的故事，我知道那位被拒绝的学生采取了哪些措施。她听取了一些有力的成长型思维模式的建议。几天后，她给那所学校打了一个电话。她找到了相关负责人，并把自己的情况告诉了他。她说：“我不想质疑您的決定。我只是想问一下，如果下次我想再申请这所学校，我该怎么改进自己的申请书。如果您能在这方面给我一些反馈和建议，我将感激不尽。”\u003c/p>\u003cp>没人能对这种期望获得有益反馈的真诚请求嗤之以鼻。几天后，那位负责人给她回了电话。学校同意接受她的申请了。原来，当时拒绝她其实也只是一念之差。在重新考虑过她的申请后，他们決定可以多招收一名学生。他们对她的主动性颇为欣赏，这也为她加了分。\u003c/p>\u003cp>为从失败的经验中吸取教训，在未来有所进步，她主动去寻找相关信息。在这个案例中，她其实并不需要完善自己的申请书。她终于能在新的研究生项目中澘心学习了。\u003c/p>\u003cp>可实行的计划与不可实行的计划\u003c/p>\u003cp>这位申请者最关键的反应就是给学校打电话收集更多信息，这并不容易。人们每天都计划着去做一些困难的事，但他们往往不会真的将其付诸行动。他们会想“我明天再做吧”，并发誓第二天一定要完成任务。但彼得・戈尔维策（&nbsp;Peter Gollwitzer）及其同事们的研究却显示，誓言，甚至是强烈的誓言，往往是没有一点用的。明天之后还有明天。\u003c/p>\u003cp>有效的做法是制定一个清晰具体的计划：“明天在我体息的时候，我要喝杯茶，关上办公室的门给学校打电话。”或者換个例子：“周三早上，我起床刷牙后，要马上坐在书桌前开始写报告。”或者是：“今天晚上，吃过晚饭洗完碗后，我要和我的妻子在客厅坐下，和她谈话。我会对她说：‘亲爱的，我想和你说点事，我想这会让我们更幸福。’”\u003c/p>\u003cp>想想你要去做的某件事，去学习的某些知识，或是要面对的某个问题。先明确目标，然后制定一个具体的计划。你要在何时实行计划？你将在哪里实行计划？你准备怎样实行计划？要考虑到具体的细节。\u003c/p>\u003cp>这些具体的、可以设想的计划涉及你做事的时间地点和方式。这会让你保持高效的行动力，当然会提高成功的概率。\u003c/p>\u003cp>所以，不仅要制定一个成长型思维模式计划，更要设想具体细节，设想你要如何实行它。\u003c/p>\u003cp>…………\u003c/p>\u003cp>最关键的一点就是制定一个具体的、成长型导向的计划，并坚持不解地实行它。\u003c/p>","explains":"\u003cp>【学习目标】在跟随我完成本次的RIA现场学习后，学习者能够在面对困境或失败的情况下，通过使用成长型思维模式（澄清）的方式，进行分析困境或所遇到的失败事件（界定），制定出改善计划（行为）\u003c/p>\u003cp>片段中举了一个例子，当申请被拒绝时，不同思维模式的反应截然不同。遇到阻碍或挫折时，固定型思维模式的人更倾向于自我保护或者放弃，而成长型思维模式的人，则会坚持不懈。\u003c/p>\u003cp>【互动】\u003c/p>\u003cp>问：片段中举了一个例子，当申请被拒绝时，不同思维模式的反应截然不同。固定型思维模式的反应是什么样的呢？\u003c/p>\u003cp>答：被拒绝不能反映你的真实水平/有太多条件优秀的申请者\u003c/p>\u003cp>问：除了这些肯定自己的想法外，还有其他的反应吗？\u003c/p>\u003cp>答：不尽如人意/平庸乏味/你配不上这所学院。\u003c/p>\u003cp>问：有肯定也有否定，但最终的结论是什么呢？\u003c/p>\u003cp>答：被拒绝不能反映你的真实水平/有太多条件优秀的申请者……\u003c/p>\u003cp>总结：固定型思维模式的人更倾向于自我保护，所以虽然说服自己的过程中，有肯定有否定，甚至还会有些反复，但是最后还是倾向于肯定自己的想法——我很优秀，拒绝我是你们的损失。然后呢？就没有然后了，到此为止，放弃了。\u003c/p>\u003cp>【概念讲解】而在成长型思维模式下，这才只是一个开始。因为成长型思维模式相信头脑和天赋只是基本条件，而能力是可以通过专注和努力来发展提升的。\u003c/p>\u003cp>比如，年初做工作计划，结果你的计划被老大批得一无是处，但你仍认为“这份计划非常完美，只是他不懂欣赏。”这是具备了成长型思维？不是，因为他并没有正视失败的结局。\u003cstrong>具备成长型思维的人，首先应该要有勇气接受并正视问题。\u003c/strong>\u003c/p>\u003cp>如果你认为“老大觉得工作计划该怎么改就怎么改吧，反正他说了算。”，这就是接受事实并愿意改变，这是具备成长型思维了吗？不是，因为他并没有明确目标，目标不是别人给你的，而是自己给自己的。只有明确自己的目标后，才能发现自己的思路是否有偏差。如果有偏差就该及时调整。如果确实有待商榷，则应继续求证，并最终确定方向。\u003cstrong>具备成长型思维的人，不仅要有勇气接受并正视问题，而且要有明确的目标。\u003c/strong>\u003c/p>\u003cp>如果你认为“老大的格局确实比我高，考虑得比我全面，我赶紧改改。不过，有个环节，我觉得等会还是要再重述下自己的观点。”这是接受并正视问题，且有明确的目标，这是具备成长型思维了吗？不是，因为他的计划不够具体，比如“重述观点”说明已经有过一次不成功的经验了，重述的成功率并不高，属于原地长联。需要更充分的数据、资讯等信息，对观点进行重构，以增加成功率。\u003c/p>\u003cp>那么到底什么样的才是使用成长型思维模式处理问题呢？当工作计划被驳回时，如果你认为“老大的格局确实比我高，考虑得比我全面。我之前做的不完善甚至忽略的部分需要再收集详尽的数据和资讯，才能真正完善这份计划。另外，有个环节，我还是需要将资料再整理下，重构下我的观点，再去跟老大沟通下。今天整理下需要的资料，需要其他同事支持的也要先沟通，争取明天汇总下资讯，便于后天更新完工作计划。”这才是使用成长型思维模式处理问题的过程。\u003cstrong>具备成长型思维的人，不仅要有勇气接受并正视问题，而且要有明确的目标，还需要有细致可执行、具有成长型导向的计划进行实施。\u003c/strong>\u003c/p>\u003cp>【HOW】总结一下，如何使用成长型思维模式处理困境呢？\u003c/p>\u003cp>一是接受并正视问题\u003c/p>\u003cp>接受自己的想法，无论这些想法是正面还是负面的，是积极的还是消极的。接受是处理问题的开始。因为只有不逃避，才能正视问题，并积极解决问题。\u003c/p>\u003cp>二是明确目标\u003c/p>\u003cp>明确目标不仅仅是要明确自己希望获得的成果，而且是不与价值观相悖的，这样的目标才能成为你今后坚持不懈地执行计划的关键。所以目标一定是你自己的目标，而非他人给你制定或下达的目标。\u003c/p>\u003cp>三是制定一个具体的、成长型导向的计划，并坚持不懈地实行它。\u003c/p>\u003cp>为了达成目标，你需要收集相关的信息，寻找相应的措施，何时何地如何执行。越细致越具体，将会让成功率更高。\u003c/p>\u003cp>举例：\u003c/p>\u003cp>我是在4岁的时候开始做英语启蒙的，时间有点晚。但问题已经存在，后悔也没用，我必须先接受事实。当然我的目标也很明确，给老大做英语启蒙，同时也顺便给老二做胎教。接下来就是计划，当了解越来越多的信息后，这个年龄开始做启蒙可以与阅读做结合的。所以我选择的是儿歌和书籍的结合。即儿歌吸引孩子的注意力，引发她的兴趣。同时结合儿歌对应的书籍做亲子共读。\u003c/p>\u003cp>【异议预防】如果不使用成长型思维，继续保持现状可以吗？短时间看似乎问题不大，但如果是长时间维持现状呢？甚至时间长了以后，问题更严重了，是否还是你能承受的呢？如果这个问题可能会持续存在，甚至影响越来越大时，就应该防微杜渐，使用成长型思维模式处理困境。\u003c/p>","interaction":"\u003cp>【A2催化学习者应用】\u003c/p>\u003cp>【拆书家提问设计】\u003c/p>\u003cp>以上就是我对这个拆页的讲解。\u003c/p>\u003cp>请大家设想下是否有过这样的经历，如在公司干的累死累活，却不如写PPT的；在家里任劳任怨，管娃的吃喝拉撒管教育，却不如偶尔溜娃的那位……\u003c/p>\u003cp>当这些情况一而再，再而三的出现，你可能就没有动力继续努力工作，也可能就越来越没耐心应对孩子和家人……这些都是我们不希望看到的结果，因为一旦你失去耐心，失去动力……问题就会越来越严重，陷入到恶性循环中。\u003c/p>\u003cp>你是否也有遇到过类似的一些困境呢？是否希望能有所改变呢？但是知道和做到总是有一道鸿沟，为了让大家在今后能更好的运用今天所学到的方法，使用成长型思维模式处理困境。\u003c/p>\u003cp>今天，我们就来预演下，就像是学生时代的一些重要考试，如中考、高考等。在正式考试前，会有各种模拟考，就是为了让考生能在正式考试中发挥出正常的水准。\u003c/p>\u003cp>接下来我们每个人将做一个分组演练，分为两组进行讨论。讨论完后各编一段小故事，故事有主角，有起因经过，甚至有对话，内容有体现我们刚刚今日所学，大概几百字即可。将摘要写在一张纸上，时间五分钟。五分钟后我们将一位伙伴站起来讲讲故事。\u003c/p>\u003cp>【学习者——曹志文分享：升职晋升后的困境】\u003c/p>\u003cp>近期职位晋升，但&quot;我&quot;却遇到了一个困境，而且这个困境应该是今后晋升都会面临的问题。公司有个流行的说法是：你总是会升职到一个你不胜任的岗位。我原本的岗位是比较基层的，一般只需要完成领导交付的事情就可以了。但晋升后，领导希望我不仅可以带好团队，而且可以很好的完成今年甚至是明年的业务。\u003c/p>\u003cp>之前的职位并不需要我思考太多，同时也不需要进行多方沟通。所以我的接触面不够广，视野也不够开阔，这些都是我的短板。\u003c/p>\u003cp>【接受并正视问题】\u003c/p>\u003cp>我需要对自己的短板，进行针对的改进和提升。比如拓宽接触面、开阔视野等。\u003c/p>\u003cp>【明确目标】\u003c/p>\u003cp>我觉得我可以从几个方面去着手，\u003c/p>\u003cp>1、多与公司/部门同职位的人员接触，多了解他们的目前工作中的痛点和短板，这也将是我今后工作中需要攻克的内容。\u003c/p>\u003cp>2、多参加一些会议或研讨，了解行业趋势，从而开阔自己的视野。\u003c/p>\u003cp>3、此外，我目前的想法可能会不够全面，我需要向资深的同事和领导多学习，虚心求教。他们可能会分享一些经验，比如如何快速获取优质资讯等。\u003c/p>\u003cp>【制定计划】\u003c/p>\u003cp>非常感谢志文的分享，在这个故事中，中志文分享困境是故事的主角升职后的工作内容较之前有很大区别，甚至是以前工作中所没有接触过的。而且目前面临的这个困境，可能会在未来存在一段较长的时间，甚至今后如果有职位的变动，也将再次面临这个困境。\u003c/p>\u003cp>志文非常理性的分析了“我”目前存在的问题和短板，也明确了自己的目标，并制定了相应的计划。通过各种渠道进行信息收集、获取有效资源等，改进现状，进而处理困境。\u003c/p>\u003cp>相信大家通过志文的案例分享，能够更好的理解如何通过使用成长型思维模式接受、明确目标、制定计划的方法，更理性的分析并处理困境。\u003c/p>\u003cp>作为长辈/父母，我们需要使用成长型思维处理我们面临的困境。同时，我们也希望孩子也能拥有成长型思维，以便能更好的应对未来的各种挑战。\u003c/p>\u003cp>问：是不是有成长型思维模式的父母就能教会孩子或者更准确的说是就能够潜移默化的影响孩子，让他们从小就具备成长型思维呢？\u003c/p>\u003cp>答：不一定。\u003c/p>\u003cp>问：为什么呢？\u003c/p>\u003cp>答：自己学会和教别人学会是两码事。\u003c/p>\u003cp>不可否认自己学会了才有可能教会孩子，但想要教会或潜移默化的影响孩子，这是需要方法的。日常生活中，亲子互动的场景非常多，今天时间关系，我们先聚焦在孩子面对失败向你寻求帮助时，我们应如何引导。接下来跟大家分享的是一个案例，当9岁小姑娘面对失败时，她的父亲如何引导她使用成长型思维处理困境的。接下来是阅读时间，请阅读完的伙伴举手示意我一下。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}},{"id":12340,"quote":"\u003cp>对孩子成功的不当称赞所带来的问题，应该是我们面临的问题中最容易对付的。失败似乎是一个更棘手的问题。孩子们在遭遇失败时，已经够沮丧和痛苦了。让我们再回到这个问题上，这一次让我们说说在孩子面临失败时，父母所传达给孩子们的信息。\u003c/p>\u003cp>九岁的伊丽莎白第一次参加了体操运动会。她身材修长，柔韧性好，充满活力、非常适合练体操，她自己也非常热爱体操。当然，她对参加比赛有一点紧张，但是她的水平很高，并且对自己的表现很自信。她甚至已经想好要将她贏得的彩带挂在家里的哪个位置。\u003c/p>\u003cp>在第一个项目自由体操中，伊丽莎白第一个登场。尽管她表现得很不错，但在后来几个女孩出场之后，得分出现了变化，伊丽莎白输掉了比赛。在其他项目中，伊丽莎白同样表现得很好，但是依然没能贏得比赛。那天晚上比赛结束时，她一条彩带也没能得到，她感到很沮丧。\u003c/p>\u003cp>如果你是伊丽莎白的父母，你会怎么做？\u003c/p>\u003cp>1．告诉伊丽莎白，你认为她是最棒的。\u003c/p>\u003cp>2．告诉她是裁判的不公平让她丢掉了原本属于她的彩带。\u003c/p>\u003cp>3．安慰她说体操其实没那么重要。\u003c/p>\u003cp>4．告诉她她有足够的能力，下一次肯定能赢。\u003c/p>\u003cp>5．告诉她她本来就不该赢。\u003c/p>\u003cp>在当今社会中，对于如何增强孩子的自信心，存在着一种强有力的信息，这种信息的一个重要内容就是：保护孩子们免遭失败！但是这种做法或许能够暂时防止孩子们失望，但是从长远来看，却有着很大的危害。为什么这么说呢？\u003c/p>\u003cp>让我们从思维模式的角度看看对刚才五句话的五种可能的反应，倾听其中传达的信息：\u003c/p>\u003cp>第一种（你认为她是最棒的）：这种说法从根本上说并不是真心的。她并不是最好的——你知道这一点，她自己也清楚这一点，这对于她的恢复和进步一点帮助都没有。\u003c/p>\u003cp>第二种（她受到不公平待遇）：这是责备他人的做法。当事实的真相是，问题的根本在她的表现而不在裁判时，难道你希望她以后变成喜欢将自己的不足归咎于他人的人吗？\u003c/p>\u003cp>第三种（安慰她体操其实没那么重要）：这种说法会教给她，当她有什么事做不好时，贬低这些事情本身就对了。难道你真想告诉她这些吗？\u003c/p>\u003cp>第四种（她有能力）：这可能是所有信息里最危险的一个。难道是能力自动带领你走向成功的吗？如果是这样，伊丽莎白这次没能赢，为什么下一次就能赢呢？\u003c/p>\u003cp>第五种（告诉她她本来就不该贏）在这种情况下说这样的话的确有些无情。当然，你可以不用这么直白的方式表达，不过伊丽莎白具有成长型思维模式的父亲基本上就对她表达了这个意思。\u003c/p>\u003cp>下面是她父亲的原话：“伊丽莎白，我知道你的感受。你对比赛寄予了如此大的希望，而且拿出了自己最好的表现，但是依然没能贏你一定感到很失望。但是你要知道，你并没有付出100％的努力。有很多女孩练习体操的时间都比你长，而且比你更努力。如果这是你真\u003c/p>\u003cp>心想要的东西，那么你就要全身心地为此付出努力。”\u003c/p>\u003cp>他同样告诉伊丽莎白，如果她只是想拿体操当个乐趣，那也没有问题。但如果她想在比赛中有所成就，那么就必须付出更多。\u003c/p>\u003cp>伊丽莎白记住了父亲的话，她花了更多时间来反复练习和完善自己的全套动作，尤其是比较薄弱的部分。在下一次比赛中，全地区有80名女孩参加了角逐。伊丽莎白赢得了5个个人项目的彩带，并夺得这次比赛综合项目的总冠军，捧回家一个巨大的奖杯。到现在，她的房间里挂满了各种获奖证明，几乎覆盖了整个墙面。\u003c/p>\u003cp>其实，她的父亲不仅告诉了她真相，也同样教给她从失败中学习的方法，告诉她为了未来的成功需要付出全部努力。伊丽莎白感到失望时，她的父亲很同情她，但他没有给她虚伪的鼓励，因为那只会让她在未来感到更加失望。\u003c/p>\u003cp>我与很多教练交谈的时候，他们都会问我：“那些可塑之才都怎么了？这样的运动员都哪去了？”很多教练抱怨说，当他们给予运动员纠正性的反馈时，这些运动员都会抱怨自己的自信心受到了打击。有时这些运动员还会打电话回家向父母抱怨。他们似乎只希望教练告诉他们，自己多么有天赋，其他的什么也别说。\u003c/p>\u003cp>这些教练说，在过去，一场联赛或少儿足球赛结束后，父母们会在回家的路上与孩子们回顾和分析球赛，给他们提供一些有帮助的建议。而现在在回家路上，如果孩子们当天表现不好或者所在的球队输了，父母们会责怪教练和裁判。他们不愿意责怪孩子，怕伤害孩子的\u003c/p>\u003cp>自信心。\u003c/p>\u003cp>但是从上面伊丽莎白的例子中可以看出，孩子们需要诚实而有建设性的反馈。如果孩子们被“保护”起来，他们将无法从失败中很好地学习。他们会认为建议、指导和反馈是消极而具有破坏性的。回避建设性的批评并不会帮助孩子们建立自信，反而会危害他们的未来。\u003c/p>","explains":"\u003cp>【学习目标】在跟随我完成本次的RIA现场学习后，当他人遭遇失败向学习者寻求帮助的时候，学习者能够通过说感受、讲事实、提建议的方式（澄清），提出（行动）诚肯而有建设性（界定）的反馈（行为）。\u003c/p>\u003cp>这个片段中讲述了一个9岁的小女孩遭遇失败时，她的父亲是如何使用成长型思维处理的。在文中有提出了一个问题“如果你是伊丽莎白的父母，你会怎么做？”，同时，给出了五种回复的方式，并一一进行分析。前四种的处理方式归结起来就是：自我催眠、推卸责任，但这些并无法真正帮助到孩子。只是打着“保护孩子自信心”的旗帜，阻碍着孩子的成长，只有第五种才是使用成长型思维的处理方式。\u003c/p>\u003cp>有个成语叫忠言逆耳，要如何让这“忠言”听着更“顺耳”，如何让伊丽莎白愿意接受，甚至是乐意接受呢？他的父亲做了一个很好的表率，不仅使用了成长型思维帮女儿处理问题，而且做了一个诚实而有建设性的反馈。\u003c/p>\u003cp>【HOW】当孩子遭遇失败向你寻求帮助时，如何做出诚肯而有建设性的反馈呢？可归结为以下三步骤。\u003c/p>\u003cp>一是说感受。比如“我知道你的感受”、“你对比赛给予了如此大的希望”……\u003c/p>\u003cp>二是讲事实。比如“你并没有付出100%的努力”、“有很多女孩练习体操的时间都比你长，而且比你更努力。”\u003c/p>\u003cp>三是提建议。比如他提了两个建议，一是“如果只是想拿体操当个乐趣，那也没有问题。”；二是“如果这是你真心想要的东西，那么你就要全身心地为此付出努力。”、“如果她想在比赛中有所成就，那么就必须付出更多。”\u003c/p>\u003cp>当然这三者的顺序并不是固定的，可能是感受与事实在前，建议在后；也可能是先给建议，再说明感受和事实。\u003c/p>\u003cp>我女儿从去年开始就很迷恋拼拼图，一开始是9块的，接着是16、32、48。从一开始拼木质的，到现在拼纸质的。从最早要选择她感兴趣的图案，到现在拼色块的。从以前的二维到现在尝试三维的，她对拼图一直保持着极高的热情。\u003c/p>\u003cp>对于她这个年龄层而言，拼图实际上是一个失败率非常高的游戏，要求观察细节选出正确的拼图，放置到正确的位置，放置的方向和角度要正确，很容易不小心碰到或者不小心把已经拼好的拼图弄坏了，只要有一块拼错，后面就会跟着一直错。\u003c/p>\u003cp>她玩游戏一般都是我陪着她拼，最开始9块都不会拼的时候，一不对，就开始在那发脾气，扔拼图。我一般会抱抱她，“你很生气，没拼对是吧。”、“就差一点点是吗？”、“没对准是吗？”……\u003c/p>\u003cp>等她的情绪慢慢停下来了，我会陪着她把拼图捡起来，“你很生气是吧，没把拼图们送回家是吗？”、“你是不是觉得很可惜，就差那么一点点”……\u003c/p>\u003cp>当她再次遇到问题的时候，我会先试着引导她：转个方向、再转一次、换个位置、换块拼图……甚至我会问她，是否需要妈妈帮忙。而我的帮忙一般是动口不动手。\u003c/p>\u003cp>现在不仅在拼拼图上，而且在搭积木、黏黏土……她情绪发泄的时间不长，而且当安抚完后，她会愿意再次去尝试，甚至自己会在那念叨着“太高了”、“太少了”……她开始有一个冷静后的自我分析的过程。虽然有时候她还是会有情绪失控的时候，但我看到的是失败后她仍旧勇于去尝试，也会尝试去分析，当然她现在也发现了自己的局限性，她开始会主动寻求帮助。\u003c/p>\u003cp>无论在这个过程中，她面对怎样的失败和挫折，她都能保持着非常高的热情。\u003c/p>\u003cp>【适用边界】这个方法不仅面对失败时可以给予孩子诚肯而有建设性的反馈。当面对成功时，也同样适用，也会让他们从中学习到经验。\u003c/p>","interaction":"\u003cp>【A3促动参与】\u003c/p>\u003cp>【提出并明确问题】\u003c/p>\u003cp>问：刚才分享的是当孩子遭遇失败寻求帮助时，通过说感受、讲事实、提建议三步骤做出诚实而有建设性的反馈。\u003c/p>\u003cp>当孩子遇到失败时，你能否感受到她的情绪以及是否能准确表达出她的情绪感受呢？你是否能获得信息且能保持客观的立场进行讲述孩子失败的事实呢？你是否能换位思考后给予中肯的建议呢？当孩子遭遇失败向你寻求帮助时，你会在哪个环节中卡壳？或者会遗漏掉哪个环节？\u003c/p>\u003cp>答：说感受\u003c/p>\u003cp>问：为什么是说感受呢？\u003c/p>\u003cp>答：因为需要先获得孩子的认同，才能获得信息了解事实并提出建议；因为需要先处理情绪再处理问题，有情绪可能就无法客观的处理问题……\u003c/p>\u003cp>问：大家是否都认同当孩子遇到失败时，感受到她的情绪并且能准确表达出她的情绪感受是非常重要的，是吗？\u003c/p>\u003cp>答：是的。\u003c/p>\u003cp>【引导分组讨论问题本质】\u003c/p>\u003cp>接下来是分组讨论，既然大家都觉得感受很重要，那么哪些因素会影响到我们无法将“说感受”做到位？为什么无法获得孩子的认同？为什么感知不够准确？为什么情绪的表达不够清晰呢？……3分钟讨论结束后，将请伙伴按顺序来分享。\u003c/p>\u003cp>【学员分享】\u003c/p>\u003cp>1、不好意思或不知道如何说感受：就是羞于说感受，不好意思将感受说出来，或者说平时就是很少做这种表述，导致不知道如何表达。\u003c/p>\u003cp>2、说感受太麻烦，太费时：说感受经常需要反复的说，需要极大的耐性。而棍棒教育更简单直接，成效似乎更显著。\u003c/p>\u003cp>3、说感受时总是会“先入为主”，不够客观：受到固定思维的影响，大人会一直用原有的观点看孩子，正所谓“你以为的只是你以为的”。可能会存在针对不同的事实，却说出相同或相似的感受。\u003c/p>\u003cp>4、因为不了解行为背后的原因，所以无法准确说感受：有时候孩子都不知道做这个行为的具体原因，大人需要抽茧剥丝才能窥探到行为背后的原因和更深层的感受。\u003c/p>\u003cp>【总结】非常感谢大家的分享，特别是第四点，这应该也是为什么大家都很认同“说感受”是非常重要的。准确的说出感受是讲事实和提建议的基础，否则提再多的建议都是无效的。\u003c/p>\u003cp>【引导分组讨论解决方案】\u003c/p>\u003cp>接下来针对这四个影响因素进行讨论，如何将这些影响因素的影响程度降到最低呢？有什么方法和建议吗？接下来是分组讨论的时间，讨论的时间是5分钟，最后我们将请伙伴上来分享他们的成果。\u003c/p>\u003cp>再重申下，因为时间关系，各组可以选择仅针对某一影响因素进行讨论并提供多种方法，也可以每个影响因素均提供一个方法。\u003c/p>\u003cp>【学员分享——讲解成果】\u003c/p>\u003cp>1、不好意思或不知道如何说感受\u003c/p>\u003cp>A、通过情绪管理类的绘本，让孩子多了解和掌握各种不同的情绪，这样才能准确表达自己的情绪，同时也可以更准确的理解别人的表述。讲绘本的过程，也会让家长更了解孩子的理解程度。沟通过程中，选择孩子能理解的词语进行表述。\u003c/p>\u003cp>B、当出现孩子出现某些情绪时，可以利用相应的情境耐心向孩子解释。如当孩子因为输棋而出现嫉妒的情绪时，就可以耐心跟孩子解释你的情绪有生气、嫉妒，而且是因为嫉妒导致生气。这样就能帮助孩子认识和理解更多的情绪。\u003c/p>\u003cp>只有先了解并理解情绪，才能进行准确表达。只有一次次的表达得当，才能鼓励多说感受。\u003c/p>\u003cp>2、说感受太麻烦，太费时：短平快的方式会大行其道往往是大人的情绪管理不到位，导致无法耐心的说感受。当情绪激动时，很难进行耐心、诚恳的有效沟通。\u003c/p>\u003cp>但是情绪要管理好需要先主动察觉到自己的情绪变化，才能进行自我调控。这个自我察觉并不容易，需要日常的刻意练习。当然，也可以让孩子来做这个监督者，比如可以与孩子约定好，让孩子来提醒大人控制好情绪，但需要双方先订立好规则。\u003c/p>\u003cp>3、说感受时总是会“先入为主”，不够客观：“先入为主”往往是固定思维导致的，总是用老眼光看人。我们需要把孩子当做独立的个体对待，尊重孩子。而只有充分的尊重，才能倾听到孩子的心声。\u003c/p>\u003cp>4、因为不了解行为背后的原因，所以无法准确说感受：这种情况有很多，因为孩子自己都不知道为什么，所以家长可能也很难一次就判断准确。可以多渠道（比如一些经典书目等）了解孩子的心理发展规律。其次是需要多观察孩子的行为，关注细节。最后，可以结合二者做出一些初步的判断和假设，并找机会尝试与孩子进行沟通交流，从而了解孩子行为背后可能的原因。比如刚才分享的那个哥哥欺负妹妹的案例中，可初步判断哥哥的行为背后的原因可能是因逗妹妹哭很好玩，也可能是想要获得大人的关注。那么就可以找机会进行试探性的沟通，了解哥哥的真实感受。\u003c/p>\u003cp>【总结——拆书家反馈】\u003c/p>\u003cp>非常感谢大家的分享，1、通过绘本，并利用日常的情境耐心向解释各种情绪，让孩子理解情绪并说出感受。2、家长主动察觉情绪，做好情绪管理，避免使用短平快的处理方式。3、充分的尊重孩子，并倾听孩子的心声，避免出现因固定思维导致的感受偏差。4、多渠道了解孩子的发展规律，多观察孩子行为的细节，并尝试了解行为背后的原因，以便能准确的说出感受。\u003c/p>\u003cp>【A2】布置任务——事后复盘\u003c/p>\u003cp>问：请问下大家，近期是否有遇到孩子/晚辈面对失败时，你需要给出反馈的情况？\u003c/p>\u003cp>答：有/没有\u003c/p>\u003cp>今天的课程结束后，希望大家能认真做个复盘，总结下这个反馈是否诚实而有建设性，是否有体现出成长型思维模式。同时，规划下未来将如何使用成长型思维去提出反馈。\u003c/p>\u003cp>【学习者-徐雪艳案例】\u003c/p>\u003cp>&nbsp;我儿子今年6岁，在他5岁的时候我就希望他去学钢琴。他试了两次，都是哭着走出教室，我不忍心，就没逼他继续学。今年他6岁了，我又骗他去试一试，他去了5次后，又说不去了。他说“太难了”、“他不会”……我听了很生气，他怎么这么容易就放弃。但是我知道冲他发脾气没有什么用，甚至会有反效果。这次我是用这样折方式跟他沟通的\u003c/p>\u003cp>我首先是肯定他，跟他说你已经很棒了。我问了其他小朋友的爸爸妈妈，其他小朋友都是上一节课后，要练习好几次才能记住，你没有练习都能记住。如果你再练习一下，肯定更棒，就不会觉得难了。要不你再去上一次课，然后练习五次，再去上一次课，看看有没有变简单？他后来同意再去试试，目前来说学习的效果还不错。\u003c/p>\u003cp>复盘：我觉得我所给予的反馈算是有建设性的，但诚肯不诚肯可能有点水分哈。我自认为我儿子是有固定思维的，而我的反馈具备了一定的成长型思维。我希望他明白，很多事情一开始不会，经过学习会从不会变成会，而且每个人都是这样的。这应该是一种更刻意去培养他成长型思维的反馈方式，以后也打算继续朝这个方向去做。\u003c/p>\u003cp>不过，我觉得我在“说感受”的方面还可以做得更好些，当他遇到挫折时，有一些负面的情绪是正常的，接受并引导他舒缓情绪也很重要。\u003c/p>\u003cp>【学习者-曹志文案例】\u003c/p>\u003cp>背景；我的孩子上小学一年级，前两天上课忘带笔记本，为了记录老师布置的作业，和同桌要了一张纸记录；在记录完后去上厕所期间，他的同桌私下收回了那张记录纸，等他回来被同桌告知，要把纸收回不想给他了。最后布置的作业被擦，他也来不及抄录；只能放学后和其他小朋友询问。这件事给他造成了很大困惑不知道如何处理。\u003c/p>\u003cp>我选择跟孩子聊这个事：\u003c/p>\u003cp>一说感受：这件事给你造成了很大困惑对不对？心里也是不舒服对不对。事后还给你造成了很多麻烦。你想知道怎么处理这种事吗？\u003c/p>\u003cp>二讲事实：孩子这是一个物权问题，首先你的同桌把纸给了你，那就成为了你的东西，他已无权收回，你要清楚这点。\u003c/p>\u003cp>孩子说：要纸的时候我说的是给，同桌收回的时候说借，不想借我了。\u003c/p>\u003cp>我说：无论是给还是借，你同桌都物权在未经过你同意前，私下收回。\u003c/p>\u003cp>（在这个过程中，给孩子模糊的是非观中，建立一个判断对错的标准。有了这个标准，孩子相信自己是对的，不再困惑）\u003c/p>\u003cp>三提建议：既然你同桌做错了，还给你造成了困扰。这件事情你不能默默的接受，要站出来处理。这么处理呢？能跟他打吗？\u003c/p>\u003cp>孩子：不能。\u003c/p>\u003cp>我说：很好，不能打。这时候就要靠说了。下次在遇到这种事，你得跟他说\u003c/p>\u003cp>一、说事实：这纸不论你是送给我还是借给我，都不能私自收回，要经过我的同意\u003c/p>\u003cp>二、说影响：你这么私下拿走，已经给我造成很大的麻烦，我把作业都记录在上面了\u003c/p>\u003cp>三、提建议：如果我们还是好朋友，请把纸还我，或者让我抄一份。如果你还是不还的话我就只能找老师帮忙解决了\u003c/p>\u003cp>&nbsp; &nbsp; 在处理这件事情最好公开处理，有小朋友围观最好哈，能获得更多人支持。\u003c/p>\u003cp>【结尾】\u003c/p>\u003cp>今天分享了两个片段，第一个片段中分享的是在面对困境或失败的情况下，通过使用成长型思维模式更理性的分析并处理困境。\u003c/p>\u003cp>第二个片段：当孩子遭遇失败向你寻求帮助的时候，如何做出诚肯而有建设性的反馈，引导孩子形成成长型思维。\u003c/p>\u003cp>孩子是父母的一面镜子，希望作为父母/长辈的我们能以身作则，也希望在潜移默化中，孩子/晚辈也能慢慢形成成长型思维。\u003c/p>\u003cp>希望今天的分享对大家今后的工作和生活有所帮助，感谢大家今天的参与，我是拆书家佳音。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1566057444000,"updated_at":1570086885000,"ria":true},{"id":8491,"topic":" 如何打破固定思维","learn_goal":"学会识别固定型思维，用四步法将固定型思维转变为成长型思维","remark":"在瞬息万变的时代，唯有终身成长才能不被出局。人的能力是可以培养的还是一成不变的？人生中的挫败对你意味着什么？努力有什么意义？人的思维模式可以改变么？来听原来的原讲解不同思维模式下的人生，学会如何打破固定型思维，让自己终身成长。","level":"TF3-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"原来的原","city":"北京市"},"club":{"name":"北京城市之光分舵","city":"北京市"},"prologue":"我是原来的原，我的三个标签是：加班狗，理科男，拆书家（二级）。\r\n为了便于讨论，咱们先分一下组。按4人一组，分为4组吧。从左到右，每桌为一组。大家对分组都清楚了吧。好的。那我们继续。\r\n今天我选的拆页来自《终身成长》，比尔·盖茨撰文推荐，累计印量180万册，是超级畅销书。【事件场景】我们的成长过程中总会面临各种各样的挑战，学生时代有考试，找工作的时候有面试，工作当中还有大大小小的考验。面对挑战，我们努力过，也放弃过。面对失败，我们坚持过也逃避过。【提问】一年一度的高考刚刚结束，你相信一考定终生么？各位上学时喜欢做难题么？题目做错了你是什么感受？对于那些学霸，你认为他们是天赋异禀还是努力过人？【影响】对以上问题的不同答案，源自不同的思维模式。思维模式会渗透到一个人的婚姻、事业、家庭，甚至整个人生状态。不同的思维模式导致不同的想法和行为，会将你领上一条完全不同的人生道路。【解决】这本《终身成长》深入浅出地讲解了固定型思维和成长型思维两种不同的思维模式，以及如何把前者转化为后者，把负能量变成正能量，勇于迎接挑战，开启成功的人生，实现终身成长。【设定学习目标】我们今天的学习目标，就是要学会如何识别固定型思维，用四步法将固定型思维转变为成长型思维。","ratings_count":1,"texts":[{"id":12144,"quote":"\u003cp>请想象一下，尽可能生动地去想，你是一个年轻人，经历了非常糟糕的一天：\u003c/p>\u003cp>\u003cstrong>你去上一门对你来说很重要的课，而且你非常喜欢这门课。你的教授公布了期中考试成绩，你得了C+。你非常失望，等到晚上准备回家的时候，你发现自己的车上贴了一张违章停车罚单。你感到非常泄气，打电话给最好的朋友想要倾诉，但是却没有打通。\u003c/strong>\u003c/p>\u003cp>你会怎么想？你会有什么样的感受？你会怎么做？当我问\u003cstrong>固定型思维模式者\u003c/strong>时，他们是这样对我说的：“我感到被拒绝了。”“我是个失败者。”“我是个傻瓜。”“我感到自己很没用而且愚蠢——所有人都比我优秀。”“我太差劲了。”换句话说，他们会把发生的事当作一个衡量自己的能力和价值的直接的标尺。\u003c/p>\u003cp>他们会这样看待自己的生活：“我的人生太可悲了。”“我没有人生。”“楼上的那个人不喜欢我。”“这个世界跟我过不去。”“有人想要毁掉我。”“没有人爱我，所有人都恨我。”“生活是不公平的，所有的努力都是白费。”“生活太糟糕了，我太傻了。”“我身上没发生过什么好事。”“我是地球上最不幸的人。”\u003c/p>\u003cp>他们是如何应对这些烦心事的呢？“我就不应该浪费这么多时间和精力去办一件事。”（换句话说，不会再让任何人来评判我。）“什么都不做。”“吃东西。”“找机会冲别人大吼。”“边听音乐边郁闷。”“躲到壁橱里坐着。”“找人打一架。”“哭。”“摔东西。”\u003c/p>\u003cp>“还能怎么办？”还能怎么办！你知道，在模拟这个情景的时候，我特意将成绩写成了C+而不是F，只把考试设定成期中考试而不是期末考试，你的车只是被贴了罚单而不是被毁了，打电话给朋友倾诉之举只是没有成功，你并没有被朋友直接拒绝。没有什么灾难性或不可逆转的事情发生，但仅仅是在这些情况的影响下，固定型思维模式者就已经产生了这种彻底的失败感和无力感。\u003c/p>\u003cp>当我把这些情况原封不动地拿给那些\u003cstrong>成长型思维模式者\u003c/strong>看后，他们是这样说的：“我会更努力地学习，下次停车的时候我要更加小心一些，不知道我的朋友是不是今天过得不开心。”那么，他们会如何应对呢？“我必须开始考虑，为了下一次测验，我要更努力地学习（或者换个学习方法），我会缴清罚款，下次再给朋友打电话的时候，我们再好好聊聊。”\u003c/p>","explains":"\u003cp>【逻辑概念】这个片段，通过“倒霉的一天”，展示了对待同样的事情“固定型思维模式”和“成长型思维模式”典型想法和行为。固定型思维相信自己的才能是一成不变的，拒绝失败，认为努力无用。而成长型思维认为能力是可以通过努力来培养的，喜欢挑战，认为失败是学习的好机会。两种思维的根本差异，在于相信能力是固定的还是可培养的，并由此衍生出对失败、努力等一系列态度和行为。\u003c/p>\u003cp>【对比举例】我女儿前一段刚刚结束期末考试，成绩退步很大，万幸的是她的闺蜜小胡同学退步也很大。一天她俩在讨论这次考试失利的事儿，我刚好路过。我女儿：1、爸，你和我妈当年学习是不是也不怎么样啊？咱家遗传基因不行，我不是学习的料。——这是哪种思维模式？是固定型思维，认为能力是天生的。2、她接着问，我这么努力学习了，成绩不进步反而下降了，我再也不想学习了。——这是哪种思维模式？是固定型思维，认为努力没用，能力是固定的。这时候小胡同学说：这次没考好，正好暴露了我的薄弱环节，我找到差距，努力练习，下次成绩应该能有进步。——这是哪种思维模式？成长型思维模式，认为能力通过努力是可以提高的。\u003c/p>\u003cp>【适用边界】当我们逃避挑战，害怕失败，觉得努力无用的时候，就要反思是否陷入了固定型思维，争取把它转化为成长型思维。\u003c/p>\u003cp>【给出步骤】那么如何把固定型思维转变为成长型思维，实现终身成长呢？共需4步：1、接受：勇敢面对，拥抱自己的固定型思维模式；2、观察：弄清楚是什么引发了你的固定思维模式？是失败？批评？压力？3、命名：给自己的固定型思维模式人格取个名字；4、教育：和你的固定型思维人格交交心，鼓励他一起踏上通往成长型思维模式的旅程。\u003c/p>\u003cp>【例子】我在大学的时候，有一次参加小品表演被观众嘘下台去了，深受打击1从此认为自己没有这方面的天赋，拒绝参加任何公开的表演，直到我使用了上面的4步。1、接受。受了这么大刺激，有这种想法很正常。2、观察。原因是害怕观众的批评，避免再次失败。3、命名。小X，代表未知。4、教育。我说“小X，我知道你是想保护我，怕我再次受到伤害，但我不想做个胆小鬼，还想试试，咱们可以从熟人、小范围开始练习，比如：家人、朋友之间讲个小笑话。”小X说“好吧”，于是慢慢地，我成长了，都可以像今天这样公开拆书了。\u003c/p>\u003cp>【关键难点】这4步中，我个人觉得最难的是接受，需要长期坚持的是教育。\u003c/p>","interaction":"\u003cp>【教学习者编剧本】以上是我对这个片段的理解。接下来我们做一个现场演练。请大家两两一组讨论，完成一个小剧本，要求通过对话将固定型思维转化为成长型思维。场景可以是新工作的挑战压力巨大，学习英语、钢琴等努力效果不佳想要放弃，搞砸了一场重要的项目、演讲，考试失败了，马上要到截止日期而拖延症爆发等等。对话时，一个人扮演固定型思维，另一个人扮演成长型思维，后者指导前者发生转变，做出积极的行动。时间五分钟。五分钟后，我们请一组代表和大家分享他们的剧本。\u003c/p>\u003cp>【A2】\u003c/p>\u003cp>小何：我是小何，我代表固定型思维。我准备了半年的职称考试，天天晚上12点才睡，结果还是没有考过。这说明两个原因：一考试太难了，二年龄太大了。我觉得这辈子都通不过职称考试了，干脆放弃算了。\u003cbr>\u003c/p>\u003cp>紫藤：你有这种想法是非常正常的。考试没有通过，你认为自己的能力是固定的，没有办法得到提升，在给自己找借口，这属于固定型思维。我分析了一下，你有这种想法的原因可能是你害怕面对下一次考试的失败。你感到自己的能力不足。其实能力是可以通过努力提升的。我是紫藤，代表成长型思维，来帮你走出固定型思维的陷阱。我理解你的担心，但人都是需要成长的。面对职称考试，是有一些方法可以实施的。你可以按章节，把题目、知识点分类。集中精力解决80%的分值，其余20%有余力的时候再去攻克，这样可以保证拿到80%的分数，就比较容易通过考试啦。当然这个过程是循序渐进的，你也可以通过步骤的拆解、时间的充分利用，得到能力的提升，你的问题就好解决了。你愿意尝试一下么？\u003c/p>\u003cp>小何：我觉得你说的特别的有道理，我决定改变下自己的学习方式，迎接下一次考试。\u003cbr>\u003cbr>【总结】感谢两位小伙伴的分享。今天我们一起学会了如何识别固定型思维，以及如何通过四个步骤将它转变为成长型思维。希望大家今后能够有意识地运用今天所学，让自己终身成长。谢谢！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1564059832000,"updated_at":1564059832000,"ria":true},{"id":8481,"topic":"如何打破固定型思维，让自己终身成长","learn_goal":"如何用四步法将固定型思维转变为成长型思维","remark":"在瞬息万变的时代，唯有终身成长才能不被出局。\r\n\r\n人的能力是可以培养的还是一成不变的？\r\n\r\n人生中的挫败对你意味着什么？\r\n\r\n努力有什么意义？\r\n\r\n人的思维模式可以改变么？\r\n\r\n来听原来的原讲解如何用四步法将固定型思维转变为成长型思维，让自己终身成长。","level":"TF3-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"原来的原","city":"北京市"},"club":{"name":"北京城市之光分舵","city":"北京市"},"prologue":"我是原来的原，我的三个标签是：加班狗，理科男，拆书家（二级）。\r\n为了便于讨论，咱们先分一下组。按3人一组，分为4组吧。从。。。到。。。为一组。大家对分组都清楚了吧。好的。那我们继续。\r\n今天我选的拆页来自《终身成长》，比尔·盖茨撰文推荐，累计印量180万册，是超级畅销书。【事件场景】我们的成长过程中总会面临各种各样的挑战，学生时代有考试，找工作的时候有面试，工作当中还有大大小小的考验。面对挑战，我们努力过，也放弃过。面对失败，我们坚持过也逃避过。【提问】一年一度的高考刚刚结束，你相信一考定终生么？各位上学时喜欢做难题么？题目做错了你是什么感受？对于那些学霸，你认为他们是天赋异禀还是努力过人？【影响】对以上问题的不同答案，源自不同的思维模式。思维模式会渗透到一个人的婚姻、事业、家庭，甚至整个人生状态。不同的思维模式导致不同的想法和行为，会将你领上一条完全不同的人生道路。【解决】这本《终身成长》深入浅出地讲解了固定型思维和成长型思维两种不同的思维模式，以及如何把前者转化为后者，把负能量变成正能量，勇于迎接挑战，开启成功的人生，实现终身成长。【设定学习目标】我们今天的学习目标，就是要学会如何识别固定型思维，用四步法将固定型思维转变为成长型思维。","ratings_count":0,"texts":[{"id":12135,"quote":"\u003cp>请想象一下，尽可能生动地去想，你是一个年轻人，经历了非常糟糕的一天：\u003c/p>\u003cp>\u003cstrong>你去上一门对你来说很重要的课，而且你非常喜欢这门课。你的教授公布了期中考试成绩，你得了C+。你非常失望，等到晚上准备回家的时候，你发现自己的车上贴了一张违章停车罚单。你感到非常泄气，打电话给最好的朋友想要倾诉，但是却没有打通。\u003c/strong>\u003c/p>\u003cp>你会怎么想？你会有什么样的感受？你会怎么做？当我问\u003cstrong>固定型思维模式者\u003c/strong>时，他们是这样对我说的：“我感到被拒绝了。”“我是个失败者。”“我是个傻瓜。”“我感到自己很没用而且愚蠢——所有人都比我优秀。”“我太差劲了。”换句话说，他们会把发生的事当作一个衡量自己的能力和价值的直接的标尺。\u003c/p>\u003cp>他们会这样看待自己的生活：“我的人生太可悲了。”“我没有人生。”“楼上的那个人不喜欢我。”“这个世界跟我过不去。”“有人想要毁掉我。”“没有人爱我，所有人都恨我。”“生活是不公平的，所有的努力都是白费。”“生活太糟糕了，我太傻了。”“我身上没发生过什么好事。”“我是地球上最不幸的人。”\u003c/p>\u003cp>他们是如何应对这些烦心事的呢？“我就不应该浪费这么多时间和精力去办一件事。”（换句话说，不会再让任何人来评判我。）“什么都不做。”“吃东西。”“找机会冲别人大吼。”“边听音乐边郁闷。”“躲到壁橱里坐着。”“找人打一架。”“哭。”“摔东西。”\u003c/p>\u003cp>“还能怎么办？”还能怎么办！你知道，在模拟这个情景的时候，我特意将成绩写成了C+而不是F，只把考试设定成期中考试而不是期末考试，你的车只是被贴了罚单而不是被毁了，打电话给朋友倾诉之举只是没有成功，你并没有被朋友直接拒绝。没有什么灾难性或不可逆转的事情发生，但仅仅是在这些情况的影响下，固定型思维模式者就已经产生了这种彻底的失败感和无力感。\u003c/p>\u003cp>当我把这些情况原封不动地拿给那些\u003cstrong>成长型思维模式者\u003c/strong>看后，他们是这样说的：“我会更努力地学习，下次停车的时候我要更加小心一些，不知道我的朋友是不是今天过得不开心。”那么，他们会如何应对呢？“我必须开始考虑，为了下一次测验，我要更努力地学习（或者换个学习方法），我会缴清罚款，下次再给朋友打电话的时候，我们再好好聊聊。”\u003c/p>","explains":"\u003cp>【逻辑概念】这个片段，通过“倒霉的一天”，展示了对待同样的事情“固定型思维模式”和“成长型思维模式”典型想法和行为。固定型思维相信自己的才能是一成不变的，拒绝失败，认为努力无用。而成长型思维认为能力是可以通过努力来培养的，喜欢挑战，认为失败是学习的好机会。两种思维的根本差异，在于相信能力是固定的还是可培养的，并由此衍生出对失败、努力等一系列态度和行为。【对比举例】我女儿前一段刚刚结束期中考试，成绩退步很大，万幸的是她的闺蜜小胡同学退步也很大。一天她俩在讨论这次考试失利的事儿，我刚好路过。我女儿：1、爸，你和我妈当年学习是不是也不怎么样啊？咱家遗传基因不行，我不是学习的料。——这是哪种思维模式？是固定型思维，认为能力是天生的。2、她接着问，我这么努力学习了，成绩不进步反而下降了，我再也不想学习了。——这是哪种思维模式？是固定型思维，认为努力没用，能力是固定的。这时候小胡同学说：这次没考好，正好暴露了我的薄弱环节，我找到差距，努力练习，下次成绩应该能有进步。——这是哪种思维模式？成长型思维模式，认为能力通过努力是可以提高的。【适用边界】当我们逃避挑战，害怕失败，觉得努力无用的时候，就要反思是否陷入了固定型思维，争取把它转化为成长型思维。【给出步骤】那么如何把固定型思维转变为成长型思维，实现终身成长呢？共需4步：1、接受：勇敢面对，拥抱自己的固定型思维模式；2、观察：弄清楚是什么引发了你的固定思维模式？是失败？批评？压力？3、命名：给自己的固定型思维模式人格取个名字；4、教育：和你的固定型思维人格交交心，鼓励他一起踏上通往成长型思维模式的旅程。【例子】我在大学的时候，有一次参加小品表演被观众嘘下台去了，深受打击1从此认为自己没有这方面的天赋，拒绝参加任何公开的表演，直到我使用了上面的4步。1、接受。受了这么大刺激，有这种想法很正常。2、观察。原因是害怕观众的批评，避免再次失败。3、命名。小X，代表未知。4、教育。“小X，我知道你是想保护我，怕我再次受到伤害，但我不想做个胆小鬼，还想试试，咱们可以从熟人、小范围开始练习，比如：家人、朋友之间讲个小笑话。”慢慢地，我成长了，都可以像今天这样公开拆书了。【关键难点】这4步中，我个人觉得最难的是接受，需要长期坚持的是教育。\u003c/p>","interaction":"\u003cp>【教学习者编剧本】以上是我对这个片段的理解。接下来我们做一个现场演练。请大家两两一组讨论，完成一个小剧本，要求通过对话将固定型思维转化为成长型思维。场景可以是新工作的挑战压力巨大，学习英语、钢琴等努力效果不佳想要放弃，搞砸了一场重要的项目、演讲，考试失败了，马上要到截止日期而拖延症爆发等等。对话时，一个人扮演固定型思维，另一个人扮演成长型思维，后者指导前者发生转变，做出积极的行动。时间五分钟。五分钟后，我们请一组代表和大家分享他们的剧本。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1563945579000,"updated_at":1563945579000,"ria":true},{"id":8480,"topic":"如何打破固定型思维","learn_goal":"用四步法将固定型思维转变为成长型思维","remark":"在瞬息万变的时代，唯有终身成长才能不被出局。\r\n\r\n人的能力是可以培养的还是一成不变的？\r\n\r\n人生中的挫败对你意味着什么？\r\n\r\n努力有什么意义？\r\n\r\n人的思维模式可以改变么？\r\n\r\n来听原来的原讲解如何用四步法将固定型思维转变为成长型思维，让自己终身成长。","level":"TF3-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"原来的原","city":"北京市"},"club":{"name":"北京城市之光分舵","city":"北京市"},"prologue":"我是原来的原，我的三个标签是：加班狗，理科男，拆书家（二级）。\r\n为了便于讨论，咱们先分一下组。按3人一组，分为4组吧。从。。。到。。。为一组。大家对分组都清楚了吧。好的。那我们继续。\r\n今天我选的拆页来自《终身成长》，比尔·盖茨撰文推荐，累计印量180万册，是超级畅销书。【事件场景】我们的成长过程中总会面临各种各样的挑战，学生时代有考试，找工作的时候有面试，工作当中还有大大小小的考验。面对挑战，我们努力过，也放弃过。面对失败，我们坚持过也逃避过。【提问】一年一度的高考刚刚结束，你相信一考定终生么？各位上学时喜欢做难题么？题目做错了你是什么感受？对于那些学霸，你认为他们是天赋异禀还是努力过人？【影响】对以上问题的不同答案，源自不同的思维模式。思维模式会渗透到一个人的婚姻、事业、家庭，甚至整个人生状态。不同的思维模式导致不同的想法和行为，会将你领上一条完全不同的人生道路。【解决】这本《终身成长》深入浅出地讲解了固定型思维和成长型思维两种不同的思维模式，以及如何把前者转化为后者，把负能量变成正能量，勇于迎接挑战，开启成功的人生，实现终身成长。【设定学习目标】我们今天的学习目标，就是要学会如何识别固定型思维，用四步法将固定型思维转变为成长型思维。","ratings_count":0,"texts":[{"id":12134,"quote":"\u003cp>请想象一下，尽可能生动地去想，你是一个年轻人，经历了非常糟糕的一天：\u003c/p>\u003cp>\u003cstrong>你去上一门对你来说很重要的课，而且你非常喜欢这门课。你的教授公布了期中考试成绩，你得了C+。你非常失望，等到晚上准备回家的时候，你发现自己的车上贴了一张违章停车罚单。你感到非常泄气，打电话给最好的朋友想要倾诉，但是却没有打通。\u003c/strong>\u003c/p>\u003cp>你会怎么想？你会有什么样的感受？你会怎么做？当我问\u003cstrong>固定型思维模式者\u003c/strong>时，他们是这样对我说的：“我感到被拒绝了。”“我是个失败者。”“我是个傻瓜。”“我感到自己很没用而且愚蠢——所有人都比我优秀。”“我太差劲了。”换句话说，他们会把发生的事当作一个衡量自己的能力和价值的直接的标尺。\u003c/p>\u003cp>他们会这样看待自己的生活：“我的人生太可悲了。”“我没有人生。”“楼上的那个人不喜欢我。”“这个世界跟我过不去。”“有人想要毁掉我。”“没有人爱我，所有人都恨我。”“生活是不公平的，所有的努力都是白费。”“生活太糟糕了，我太傻了。”“我身上没发生过什么好事。”“我是地球上最不幸的人。”\u003c/p>\u003cp>他们是如何应对这些烦心事的呢？“我就不应该浪费这么多时间和精力去办一件事。”（换句话说，不会再让任何人来评判我。）“什么都不做。”“吃东西。”“找机会冲别人大吼。”“边听音乐边郁闷。”“躲到壁橱里坐着。”“找人打一架。”“哭。”“摔东西。”\u003c/p>\u003cp>“还能怎么办？”还能怎么办！你知道，在模拟这个情景的时候，我特意将成绩写成了C+而不是F，只把考试设定成期中考试而不是期末考试，你的车只是被贴了罚单而不是被毁了，打电话给朋友倾诉之举只是没有成功，你并没有被朋友直接拒绝。没有什么灾难性或不可逆转的事情发生，但仅仅是在这些情况的影响下，固定型思维模式者就已经产生了这种彻底的失败感和无力感。\u003c/p>\u003cp>当我把这些情况原封不动地拿给那些\u003cstrong>成长型思维模式者\u003c/strong>看后，他们是这样说的：“我会更努力地学习，下次停车的时候我要更加小心一些，不知道我的朋友是不是今天过得不开心。”那么，他们会如何应对呢？“我必须开始考虑，为了下一次测验，我要更努力地学习（或者换个学习方法），我会缴清罚款，下次再给朋友打电话的时候，我们再好好聊聊。”\u003c/p>","explains":"\u003cp>【逻辑概念】这个片段，通过“倒霉的一天”，展示了对待同样的事情“固定型思维模式”和“成长型思维模式”典型想法和行为。固定型思维相信自己的才能是一成不变的，拒绝失败，认为努力无用。而成长型思维认为能力是可以通过努力来培养的，喜欢挑战，认为失败是学习的好机会。两种思维的根本差异，在于相信能力是固定的还是可培养的，并由此衍生出对失败、努力等一系列态度和行为。【对比举例】我女儿前一段刚刚结束期中考试，成绩退步很大，万幸的是她的闺蜜小胡同学退步也很大。一天她俩在讨论这次考试失利的事儿，我刚好路过。我女儿：1、爸，你和我妈当年学习是不是也不怎么样啊？咱家遗传基因不行，我不是学习的料。——这是哪种思维模式？是固定型思维，认为能力是天生的。2、她接着问，我这么努力学习了，成绩不进步反而下降了，我再也不想学习了。——这是哪种思维模式？是固定型思维，认为努力没用，能力是固定的。这时候小胡同学说：这次没考好，正好暴露了我的薄弱环节，我找到差距，努力练习，下次成绩应该能有进步。——这是哪种思维模式？成长型思维模式，认为能力通过努力是可以提高的。【适用边界】当我们逃避挑战，害怕失败，觉得努力无用的时候，就要反思是否陷入了固定型思维，争取把它转化为成长型思维。【给出步骤】那么如何把固定型思维转变为成长型思维，实现终身成长呢？共需4步：1、接受：勇敢面对，拥抱自己的固定型思维模式；2、观察：弄清楚是什么引发了你的固定思维模式？是失败？批评？压力？3、命名：给自己的固定型思维模式人格取个名字；4、教育：和你的固定型思维人格交交心，鼓励他一起踏上通往成长型思维模式的旅程。【例子】我在大学的时候，有一次参加小品表演被观众嘘下台去了，深受打击1从此认为自己没有这方面的天赋，拒绝参加任何公开的表演，直到我使用了上面的4步。1、接受。受了这么大刺激，有这种想法很正常。2、观察。原因是害怕观众的批评，避免再次失败。3、命名。小X，代表未知。4、教育。“小X，我知道你是想保护我，怕我再次受到伤害，但我不想做个胆小鬼，还想试试，咱们可以从熟人、小范围开始练习，比如：家人、朋友之间讲个小笑话。”慢慢地，我成长了，都可以像今天这样公开拆书了。【关键难点】这4步中，我个人觉得最难的是接受，需要长期坚持的是教育。\u003c/p>","interaction":"\u003cp>【教学习者编剧本】以上是我对这个片段的理解。接下来我们做一个现场演练。请大家两两一组讨论，完成一个小剧本，要求通过对话将固定型思维转化为成长型思维。场景可以是新工作的挑战压力巨大，学习英语、钢琴等努力效果不佳想要放弃，搞砸了一场重要的项目、演讲，考试失败了，马上要到截止日期而拖延症爆发等等。对话时，一个人扮演固定型思维，另一个人扮演成长型思维，后者指导前者发生转变，做出积极的行动。时间五分钟。五分钟后，我们请一组代表和大家分享他们的剧本。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1563945485000,"updated_at":1563945485000,"ria":true},{"id":7753,"topic":"用成长型思维改善关系","learn_goal":"用成长型思维改善关系","remark":"","level":"TF3-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"陈松波","city":"重庆市"},"club":{"name":"重庆山城分舵","city":"重庆市"},"prologue":"\u003cp>\u003cstrong>自我介绍\u003c/strong>\u003cstrong>+\u003c/strong>\u003cstrong>场景图书介绍法\u003c/strong>\u003cstrong>+\u003c/strong>\u003cstrong>目标（\u003c/strong>\u003cstrong>2\u003c/strong>\u003cstrong>分钟）\u003c/strong>\u003c/p>\u003cp>大家好！我是陈松波，我今天要拆的是TF3-1 \u003c/p>\u003cp>\u003cstrong>事件场景：\u003c/strong>首先，我想邀请大家想想你有没有遇到过这样的一个场景——\u003c/p>\u003cp>有一天，伴侣下班回家，给我讲了一个很长，很详细的故事，但是整个故事都没有重点，我觉得无聊透了，但我还是努力不表现出来。但她最终还是被她发现了。\u003c/p>\u003cp>她就是说我，对她漠不关心，一点也不在乎她，她每天都主动与我分享工作中遇到开心的不开心的事，而我还表现得不耐烦且我从来都不给她说我工作上的事。然后就是开始与我争吵，那段时间我们经常这样。\u003c/p>\u003cp>\u003cstrong>提问：\u003c/strong>不知道大家在夫妻关系、情侣关系或其它的亲密关系中遇到过类似的情况呢？你们当时是怎么处理的呢？效果如何呢？\u003c/p>\u003cp>\u003cstrong>影响：\u003c/strong>其实类似这样的问题，如果不能很好的解决的话，很有可能会严重响彼此的亲密关系，甚至引发更大的关系危机。\u003c/p>\u003cp>\u003cstrong>解决：\u003c/strong>那这个问题到底应该怎么解决呢？那我今天要给大家分享的这本书《终身成长》就给出了解决方法。它的作者是斯坦福大学心理学家——卡罗尔德韦克，她在本书中指出在亲密关系中固定型思维者的责备总是来得又快又猛，而要解决这一问题的的方法就是运用成长型思维改善关系。\u003c/p>\u003cp>\u003cstrong>学习目标\u003c/strong>\u003cstrong>：\u003c/strong>\u003c/p>\u003cp>在跟我完成本次RIA现场学习后，大家能区分固定型思维和成长型思维，在与他人关系的出现问题的时候，能够运用成长型的思维改善关系三步法去改善关系。\u003c/p>\u003cp>接下来我们就是一起来看看这两种思维到底有什么不一样的，请大家花2分钟的时间阅读片段\u003c/p>","ratings_count":0,"texts":[{"id":11258,"quote":"\u003cp>\u003cstrong>R\u003c/strong>\u003cstrong>阅读原拆页（\u003c/strong>\u003cstrong>2\u003c/strong>\u003cstrong>分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>问题表明性格存在缺陷\u003c/strong>\u003c/p>\u003cp>固定型思维模式者的第二个问题，就是认为问题意味着根深蒂的缺陷。但是，就好比任何伟大的成就不可能不经历挫折一样，所有良好的两性关系也不可能避免冲突和问题。\u003c/p>\u003cp>固定型思维模式者在谈到冲突时会选择责备，有时他们会责备自已，但大部分时候他们选择责备对方。而且他们会将责备的矛头指向对方的个人特质——认为这是性格的缺陷。\u003c/p>\u003cp>但是还没完。当人们将问题的源头指向伴侣的个性并加以责备时，这种举动会让他们感觉愤怒并厌恶自己的伴侣。\u003c/p>\u003cp>而且问题将进一步升级: 既然问题是固定的个人特质引起的，那么这一事实代表这个问题无法被解决。\u003c/p>\u003cp>所以，一旦固定型思维模式者发现了伴侣某些方面的缺点，他们就会看不起对方，并对整个恋爱关系感到不满。(相反，成长型思维模式者会看到伴侣身上的不完美，但依然认为他们的恋爱关系是良好的。)\u003c/p>\u003cp>有的时候，固定型思维模式者对伴侣和两人关系中的问题视而不见，这样他们就可以不去面对和解决。\u003c/p>\u003cp>每个人都认为伊冯娜可能有外遇。她经常接到神秘的电话，经常在接孩子时迟到，“和女友们一起出去玩”的次数变多了，好像老是心不在焉的。她的丈夫查理说,伊冯娜只是在经历一个特殊的阶段“所有女人都会经历这种阶段,”查理坚持说，“这 并不代表她有在外面有了别的男人。”\u003c/p>\u003cp>查理的好朋友催他去查一查事情的真相。但是查理认为，如果他面对了现实——如果结局是不好的—— 那么他的世界就会崩塌。从固定型思维模式者的思考方式来看，他必须面对几个现实中的一个，要么他爱的女人是个坏女人，要么他自己是一个坏人，导致妻子离他远去，要么他们的关系是糟糕且无法挽回的。\u003c/p>\u003cp>他一个选择都不能承受。他意识不到，这个问题其实可以被解决，伊冯娜只是在向他传递信息，她非常渴望他能知道:不要不拿我当一回事，我需要更多的关注。\u003c/p>\u003cp>成长型思维模式并不意味着查理必须去质问妻子，但是他可以与她探讨他们目前的情况。他可以去想一想是什么出了问题，或许可以针对问题去咨询顾问，在仔细考虑后再决定接下来该怎么做。如果两个人之间有问题需要解决，那么至少两个人的关系还有挽救的机会。\u003c/p>","explains":"\u003cp>\u003cstrong>分享\u003c/strong>\u003cstrong>I\u003c/strong>\u003cstrong>便签（\u003c/strong>\u003cstrong>4\u003c/strong>\u003cstrong>分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>WHAT:\u003c/strong> （强化讲解概念）\u003c/p>\u003cp>这个片段介绍了固定型思维与成长型思维在面对两人关系出现问题时，所采取的不同年应对措施。到底什么叫成长型思维呢？我们一起来看看下面这几句话，看看他们哪些是固定型思维，哪些是成长型思维。\u003c/p>\u003cp>1、&nbsp; 如果我们的感情是天注定的，那么一切问题都会自然地得到解决\u003c/p>\u003cp>2、&nbsp; 两个人即使有天雷勾动地火的感觉，但健康长久的关系依旧需要双方的努力\u003c/p>\u003cp>3、&nbsp; 她就是一个坏女人，所以才会离开我和孩子。\u003c/p>\u003cp>4、&nbsp; 我们关系已经出了问题，我能做些什么来改善呢？\u003c/p>\u003cp>以上四句话，哪些能体现成长型思维？哪些体现了固定型思维？对的，1、3是固定型思维的表现，2、4是成长型思维的表现。通过这样的对比，我们会发现固定型思维与成长型思维的区别表现在：是否相信亲密的关系可以通过努力得以改善。\u003c/p>\u003cp>拥有成长型思维的人在面对与他人关系出现问题时，会选择面对现状，并努力分析原因，寻求改变方法。而拥有固定型思维的人在面对问题出现时，常常无选择逃避或责备。\u003c/p>\u003cp>\u003cstrong>HOW\u003c/strong>\u003cstrong>：\u003c/strong> \u003c/p>\u003cp>我们从成长型思维与固定型思维对比的要点，可以归纳出成长型思维改善关系三个步骤\u003c/p>\u003cp>\u003cstrong>第一步\u003c/strong>\u003cstrong> \u003c/strong>\u003cstrong>直面现状\u003c/strong>\u003c/p>\u003cp>固定型思维的人对关系中出现的问题往往视而不见，这样他们就不用去面对和解决问题。可这不仅不会让问题消逝反而会让问题越来越严重。\u003c/p>\u003cp>所以成长型思维改善关系的第一步就是直面现状，察觉自己在面对现状的态度，是在逃避吗？是在责备吗？并承认关系中出现的问题。\u003c/p>\u003cp>\u003cstrong>第二步\u003c/strong>\u003cstrong> \u003c/strong>\u003cstrong>分析原因\u003c/strong>\u003c/p>\u003cp>既然我们已经承认现在的关系中出现了问题，那么我们接下来就要去分析下，这些问题是怎么产生的？以及我们为什么会逃避或是责备他人？\u003c/p>\u003cp>\u003cstrong>第三步\u003c/strong>\u003cstrong> \u003c/strong>\u003cstrong>寻求改善\u003c/strong>\u003c/p>\u003cp>固定型思维的人认为如果两个人适合在一起，一切问题都会自然而然的解决掉，不需要自己付出努力去改变什么。而这种良好的关系不需要努力维系的想法，常常让他们的关系走向破裂。\u003c/p>\u003cp>而成长型思维的人在发现问题，经过分享后找到了原因，接下来他们会通过各种途径寻求改进的方法，并努力的去改善彼此间的关系\u003c/p>\u003cp>所以成长型思维改变关系的第三步就是寻求方法，努力改善。\u003c/p>\u003cp>\u003cstrong>WHEN\u003c/strong>\u003cstrong>：\u003c/strong>\u003c/p>\u003cp>这个方法可以用改善两性关系，亲子关系等亲密关系或其他你在乎并愿意改进的关系当中。\u003c/p>\u003cp>\u003cstrong>案例：\u003c/strong>\u003c/p>\u003cp>我老婆有一天下班回家后，给我讲了一个很长，很详细的故事，但是整个故事都没有重点，我觉得无聊透了，但我还是努力不表现出来。但她最终还是被她发现了。\u003c/p>\u003cp>她就是说我，对她漠不关心，一点也不在乎她，她每天都主动与我分享工作中遇到开心的不开心的事，而我还表现得不耐烦且我从来都不给她说我工作上的事。然后就是开始与我争吵，那段时间我们经常这样。\u003c/p>\u003cp>在这个例子中，我和我老婆都掉入了固定型思维模式中，一开始自己就在逃避自己觉得无聊的情况，并期待这无聊的情况会很快过去。我老婆可能认为我表现出的不耐烦就是为因我对她关心，并责备我。我们都陷入了固定型思维中，我在逃避，我老婆在责备。都并未寻找方法，努力改善。\u003c/p>\u003cp>好，我接下来看看运用成长型思维改善关系三步法，我们应该怎么做\u003c/p>\u003cp>第一步，直面现状。这个故事让自己感到无聊这一个问题确实存在，我好像在逃避这种无聊的状态\u003c/p>\u003cp>第二，分析原因。为什么老婆要给我讲这么长一个故事呢？他想给我表达什么？是不是想让我知道更多的细节呢？ 为什么老婆讲一个长一点的故事自己就会觉得无聊呢？\u003c/p>\u003cp>第三步，寻求改善。找到原因后就是尝试着做出一些改变了。比如跟对方说，亲爱的，你给我讲这么多是想让我知道整个事情的经过吗？你讲了这么多的细节，我不明白你的重点是什么？你可不可以直接告诉我为什么这事这么让你兴奋？等等\u003c/p>\u003cp>相信经过这样的三步，我们能更好处理这个问题，改善彼此的关系。\u003c/p>\u003cp>\u003cstrong>分\u003c/strong>\u003cstrong> \u003c/strong>\u003cstrong>组：\u003c/strong>\u003c/p>\u003cp>接下来我们会有分组学习和讨论，所以我们先来进行一个简单的分组。\u003c/p>","interaction":"\u003cp>\u003cstrong>A2\u003c/strong>\u003cstrong>催化学习者应用（\u003c/strong>\u003cstrong>7\u003c/strong>\u003cstrong>分钟）\u003c/strong>\u003c/p>\u003cp>好了，我例子讲完了，接下来我们要在现场来运用一下这个方法。具体怎么运用呢？《这样读书就够了》中介绍了一个重要的关于学习的研究结果：在大脑中过一次，等于实际应用了一次。\u003c/p>\u003cp>所以，接下来请每个人都想一想在未来一周或一个月内你可能会运用到成长型思维改善关系三步法的场景。\u003c/p>\u003cp>一听到改变关系，你第一个想到的是谁？是你丈夫？妻子？爸妈？或者是其他人。想想你们可能会发生什么事情影响你们的关系，这件事情发生了，你打算怎么做，你会和他说些什么？\u003c/p>\u003cp>\u003cstrong>请大家编一个小故事（剧本），写出整个事件的起因，经过，结果以及双方的对话。在这个故事中要体现成长型思维改善关系的三步法。\u003c/strong>\u003c/p>\u003cp>请大家把这个小故事（剧本）写在我给大家的卡卡片上，时间是5分钟，5分钟后我会请小伙伴来给我们分享他的故事（剧本）。\u003c/p>\u003cp>学习者案例：\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>小故事（剧本）\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>时间\u003c/p>\u003c/td>\u003ctd>\u003cp>本周末\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>地点\u003c/p>\u003c/td>\u003ctd>\u003cp>客厅 厨房\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>人物\u003c/p>\u003c/td>\u003ctd>\u003cp>我，弟弟，爸爸，妈妈\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>事\u003c/p>\u003cp>件\u003c/p>\u003cp>：\u003c/p>\u003cp>含\u003c/p>\u003cp>起\u003c/p>\u003cp>因\u003c/p>\u003cp>经\u003c/p>\u003cp>过\u003c/p>\u003cp>结\u003c/p>\u003cp>果\u003c/p>\u003c/td>\u003ctd>\u003cp>起因：之前爸爸、弟弟、我在客户看电视或玩耍，妈妈一个人在厨房做饭，经常抱怨我们三个不去给她帮忙做饭。经常抱怨我们，我之前就觉得做个饭嘛，哪里需要那么多人帮忙嘛。学过这个方法后啦，我打算在本周日去尝试运用：\u003c/p>\u003cp>本周日爸爸，弟弟，我在客厅看电视；妈妈在厨房做饭。我意识到不进去帮忙妈妈待会又会不开心了。于是，我就走进厨房，说：\u003c/p>\u003cp>“妈妈，我来帮你做饭，有什么需要我帮忙的吗？”\u003c/p>\u003cp>“出去，出去，谁要你帮忙”妈妈\u003c/p>\u003cp>我说“好，那我把饭碗洗了拿出去吧”，一会儿，我又进去对妈妈说“妈妈有你真幸福，辛苦了妈妈，我爱你！”\u003c/p>\u003cp>“油嘴滑舌的，个人出去，厨房本来都小，转都转不开了”妈妈故作镇静的说。\u003c/p>\u003cp>于是，我又拿着筷子出去了。\u003c/p>\u003cp>一会儿，我看妈妈菜炒好了，我就主动进去端菜并说：“妈，好香的菜啊！口水都要流出来了”\u003c/p>\u003cp>妈妈开心的笑了下，说“香就多吃点”\u003c/p>\u003cp>菜端上桌后，我们一家人开开心心的吃了起来\u003c/p>\u003cp>…………\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cstrong>结束语：\u003c/strong>\u003c/p>\u003cp>今天，我给大家分享了固定型思维和成长型思维，希望大家了解决定我们成功与否的不是能力与天赋，而是我们的思维方式！\u003c/p>\u003cp>\u003cstrong>好，我的分享到此结束，谢谢大家！\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1556352976000,"updated_at":1556352993000,"ria":true},{"id":7719,"topic":"夸孩子聪明，我错了吗？","learn_goal":"学习者通过学习后，可以在孩子教育过程中，应用成长思维方式教育","remark":"","level":"TF3-3","duration":50,"status":29,"type":0,"chaishujia":{"username":"吴佳音","city":"厦门"},"club":{"name":"厦门鹭岛抚琴分舵","city":"厦门"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家好，我叫佳音，用三个标签来介绍自己。\r\n专业——心理学：曾经主修的学业。\r\n职业——培训师：现在的谋生之道。\r\n副业——拆书家：未来的成长之路。\r\n今天我所定级的TF3-3，也是通往三级拆书家道路上的最后一个关卡。&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>【事件】先说说本次的主题：夸孩子聪明，我错了吗？\u003c/p>\u003cp>问：大家觉得这种夸奖是对还是错呢？\u003c/p>\u003cp>答：对、有条件的对、要小心的对……\u003c/p>\u003cp>我发现当我问完这句话后，大家都卡了一下。可能很多人突然发现这句话我经常说，但是似乎我从未真正考量过这句话是否正确。也就是说，大家也觉得夸孩子聪明有好的一面，但也有不足之处。\u003c/p>\u003cp>以前，我们小时候的教育模式多是“棍棒底下出孝子”，近些年，又开始风行“鼓励教育”，鼓励教育告诉我们，要多去发现孩子的闪光点，多去夸奖孩子，帮助孩子建立自信并且保护它，这一观点目前也为很多父母和老师所接受。\u003c/p>\u003cp>比如，夸孩子“你学得真快！”、“你真聪明！”、“你太有天赋了！”、“你都没怎么看书就考这么高的分，你简直就是个小天才！”……\u003c/p>\u003cp>【提问】大家觉得孩子除了接收到鼓励，还可能接收到哪些信息呢？\u003c/p>\u003cp>答：膨胀、天赋好、不努力……\u003c/p>\u003cp>【影响】可能是“我生来就很聪明”、“我从小就很有天赋，根本不需要什么努力。”、“妈妈喜欢聪明的我”、“聪明能够让我妈妈喜欢我，为了让妈妈一直喜欢我，我不能表现出不聪明。”…… \u003c/p>\u003cp>如果孩子们接收到的是这些信息，他们为了维护自己的聪明，就不敢犯错，不敢去挑战更有难度的任务，他们甚至会通过撒谎来显示自己的天赋和能力。而这些将大大限制了他们发展和进步的空间。\u003c/p>\u003cp>其实，不仅仅是夸奖，批评也一样，你传达的跟孩子接收到的可能并不对等。那么如何才能给予诚实而有建设性的建议，并且能够让孩子能准确接收到呢？\u003c/p>\u003cp>【解决】答案就在《终身成长》这本书中。\u003c/p>\u003cp>在介绍这本书前，先做一个问卷调查。\u003c/p>\u003cp>&nbsp; &nbsp; 【A1】\u003c/p>\u003cp>请大家仔细阅读表格中描述的每一句话，并与自己平时的做法进行对照，然后给自己打分，1分代表完全不符合，6分代表完全符合。\u003c/p>\u003cp>请不要犹豫,看懂题意后马上做答并计分。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>问题\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>1\u003c/strong>\u003c/p>\u003cp>\u003cstrong>完全\u003c/strong>\u003c/p>\u003cp>\u003cstrong>不符合\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>2\u003c/strong>\u003c/p>\u003cp>\u003cstrong>不符合\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>3\u003c/strong>\u003c/p>\u003cp>\u003cstrong>略不\u003c/strong>\u003c/p>\u003cp>\u003cstrong>符合\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>4\u003c/strong>\u003c/p>\u003cp>\u003cstrong>略微\u003c/strong>\u003c/p>\u003cp>\u003cstrong>符合\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>5\u003c/strong>\u003c/p>\u003cp>\u003cstrong>符合\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>6\u003c/strong>\u003c/p>\u003cp>\u003cstrong>完全\u003c/strong>\u003c/p>\u003cp>\u003cstrong>符合\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>1\u003c/strong>\u003cstrong>、我总是勇于尝试新鲜事物，并应用于工作与生活中。\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>2\u003c/strong>\u003cstrong>、我总是愿意付出时间与精力学习，并提升自身技能。\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>3\u003c/strong>\u003cstrong>、面对困难时，我仍愿意付出努力，以期能获得更好的结果。\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>4\u003c/strong>\u003cstrong>、面对挫折时，我总是会尝试去寻找不同的解决方式，以期有更好的结果。\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>5\u003c/strong>\u003cstrong>、面对失败，我总是会寻找存在的差距，提升自身技能，期许提高下次获得成功的几率。\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>6\u003c/strong>\u003cstrong>、面对成功，我总是会寻找存在的偶然因素，并努力转化为自身技能，期许下次的再次成功。\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>【I】大家可以计算下，自己所获得的分值。\u003c/p>\u003cp>请得分26（含）以上的伙伴举手示意一下，非常好。\u003c/p>\u003cp>分值在26分以上，说明你经常使用成长型思维模式处理问题。\u003c/p>\u003cp>请得分在14-16的伙伴举手示意一下。\u003c/p>\u003cp>分值是14—26，说明你具备成长型思维模式，但有时候会使用固定型思维模式处理问题。\u003c/p>\u003cp>若分值是14（含）以下，说明你经常使用固定型思维模式处理问题。\u003c/p>\u003cp>什么是固定型思维模式和成长型思维模式？大家可以一起来看下这个图例\u003c/p>\u003cp>这副图是来源于《终身成长》这本书中。\u003c/p>\u003cp>【解决】刚刚提到的夸孩子时，只是夸他聪明，将会传递给孩子固定型的思维模式。而成长型思维模式则会传递出“智力是可以提高的”，而非“智力是固定的”。\u003c/p>\u003cp>《终身成长》这本书中提出的固定型思维模式和成长型思维模式概念，并通过案例讲解帮助我们理解。这可以帮助我们在教育小孩的问题上，避免陷入固定型思维的负面结果。\u003c/p>\u003cp>今天我们将通过两个片段，更深入的了解什么是成长型思维、如何使用成长型思维处理困境、如何帮助孩子形成成长型思维。\u003c/p>\u003cp>&nbsp; &nbsp; 第一个片段是一个案例，面对同一个困境，固定型和成长型思维模式分别采取了不同的应对方式。接下来，请大家利用4分钟的时间进行阅读，阅读的过程中，也可以对照图例（固定型思维模式和成长型思维模式对比图）一并阅读。\u003c/p>","ratings_count":1,"texts":[{"id":11216,"quote":"\u003cp>《终身成长》P279——P282\u003c/p>\u003cp>这是一些思维模式练习，请与我一同面对一系列困境。在每个例子里，你会先看到固定型思维模式的反应，然后体验成长型思维模式的解決办法。\u003c/p>\u003cp>困境1：假设你报考了一所研究生院。你在志愿上只填了这一家学院，因为这是你唯一心仪的选择。你对录取充满自信，因为很多人都认为你在这个领域的研究工作独具创见，令人兴奋。但是，你的申请被拒绝了。\u003c/p>\u003cp>固定型思维模式的反应：一开始你告诉自己，竞争太激烈了，所以被拒绝不能反映你的真实水平。也许有太多条件优秀的申请者，研究生院无法全部接受。然后，你脑海深处那个声音开始说话了。那声音说，你是在骗自己，为自己找借口。它对你说，招生委员会认为你的研究工作不尽如人意。过了一阵，你对自己说，这可能是真的。你的工作也许真的平庸乏味，不值一提。他们发现了这一点。毕竟他们都是专家。对方已经做出了裁决一一你配不上这所学院。\u003c/p>\u003cp>在一番努力之后，你又说服自己相信了一开始的结论。这个结论也很合理，而且对你更有利。你感觉好一点了。在固定型思维模式下（在大多数认知疗法中也一样），事情到这一步就结束了。你重新找到了自尊，所以不用再多想了。但在成长型思维模式下，这只是一个开始：你之前只是在自说自话现在要开始学习和自我提高了。\u003c/p>\u003cp>成长型思维模式的解決办法：考虑好你的目标，然后想想你要怎么做才能实现它。你能采取哪些措施让自己获得成功？你能收集到什么信息？也许下次你该多申请几个学校。也许与此同时，你应该去广泛收集信息，让你的申请书更具竞争性：他们希望招收什么样的学生？他们最看重哪些经验？在进行下一次申请前，你要多积累这方面的经验。\u003c/p>\u003cp>这是一个真实的故事，我知道那位被拒绝的学生采取了哪些措施。她听取了一些有力的成长型思维模式的建议。几天后，她给那所学校打了一个电话。她找到了相关负责人，并把自己的情况告诉了他。她说：“我不想质疑您的決定。我只是想问一下，如果下次我想再申请这所学校，我该怎么改进自己的申请书。如果您能在这方面给我一些反馈和建议，我将感激不尽。”\u003c/p>\u003cp>没人能对这种期望获得有益反馈的真诚请求嗤之以鼻。几天后，那位负责人给她回了电话。学校同意接受她的申请了。原来，当时拒绝她其实也只是一念之差。在重新考虑过她的申请后，他们決定可以多招收一名学生。他们对她的主动性颇为欣赏，这也为她加了分。\u003c/p>\u003cp>为从失败的经验中吸取教训，在未来有所进步，她主动去寻找相关信息。在这个案例中，她其实并不需要完善自己的申请书。她终于能在新的研究生项目中澘心学习了。\u003c/p>\u003cp>可实行的计划与不可实行的计划\u003c/p>\u003cp>这位申请者最关键的反应就是给学校打电话收集更多信息，这并不容易。人们每天都计划着去做一些困难的事，但他们往往不会真的将其付诸行动。他们会想“我明天再做吧”，并发誓第二天一定要完成任务。但彼得・戈尔维策（ Peter Gollwitzer）及其同事们的研究却显示，誓言，甚至是强烈的誓言，往往是没有一点用的。明天之后还有明天。\u003c/p>\u003cp>有效的做法是制定一个清晰具体的计划：“明天在我体息的时候，我要喝杯茶，关上办公室的门给学校打电话。”或者換个例子：“周三早上，我起床刷牙后，要马上坐在书桌前开始写报告。”或者是：“今天晚上，吃过晚饭洗完碗后，我要和我的妻子在客厅坐下，和她谈话。我会对她说：‘亲爱的，我想和你说点事，我想这会让我们更幸福。’”\u003c/p>\u003cp>想想你要去做的某件事，去学习的某些知识，或是要面对的某个问题。先明确目标，然后制定一个具体的计划。你要在何时实行计划？你将在哪里实行计划？你准备怎样实行计划？要考虑到具体的细节。\u003c/p>\u003cp>这些具体的、可以设想的计划涉及你做事的时间地点和方式。这会让你保持高效的行动力，当然会提高成功的概率。\u003c/p>\u003cp>所以，不仅要制定一个成长型思维模式计划，更要设想具体细节，设想你要如何实行它。\u003c/p>\u003cp>…………\u003c/p>\u003cp>最关键的一点就是制定一个具体的、成长型导向的计划，并坚持不解地实行它。\u003c/p>","explains":"\u003cp>【学习目标】在跟随我完成本次的RIA现场学习后，学习者在面对困境或失败的情况下，能够用成长型思维模式（澄清），使用接受、明确目标、制定计划的方法（行为），应对困境（界定）。\u003c/p>\u003cp>片段中举了一个例子，当面对同样的拒绝时，不同思维模式的人表现出截然不同的反应。\u003c/p>\u003cp>【互动】\u003c/p>\u003cp>问：片段中固定型思维模式的反应是什么样的呢？\u003c/p>\u003cp>答：被拒绝不能反映你的真实水平、有太多条件优秀的申请者……\u003c/p>\u003cp>问：这些还是对自己的肯定，这并非失败。除了这些肯定自己的想法外，还有其他的反应吗？\u003c/p>\u003cp>答：不尽如人意/平庸乏味/你配不上这所学院……\u003c/p>\u003cp>问：有肯定也有否定，但最终的结论是什么呢？\u003c/p>\u003cp>答：被拒绝不能反映你的真实水平/有太多条件优秀的申请者……\u003c/p>\u003cp>总结：固定型思维模式的人更倾向于自我保护，所以虽然说服自己的过程中，有肯定有否定，甚至还会有些反复，但是最后还是倾向于肯定自己的想法——我很优秀，拒绝我是你们的损失。然后呢？就没有然后了，到此为止，放弃了。\u003c/p>\u003cp>【概念讲解】而在成长型思维模式下，这才只是一个开始。因为成长型思维模式相信头脑和天赋只是基本条件，而能力是可以通过专注和努力来发展提升的，最终解决问题。我们来看一下什么是用成长型思维模式处理困境问题？\u003c/p>\u003cp>比如，年初做工作计划，结果你的计划被老大批得一无是处，但你仍认为“这份计划非常完美，只是他不懂欣赏。”这是具备了成长型思维？不是，因为他并没有正视失败的结局。具备成长型思维，首先应该要有勇气接受并正视问题。\u003c/p>\u003cp>如果你认为“老大觉得工作计划该怎么改就怎么改吧，反正他说了算。”，这就是接受事实并愿意改变，这是具备成长型思维了吗？不是，因为他并没有明确目标，目标不是别人强加给你的，而是自己给自己的。如果确实自己的思路有偏差，就该及时调整。如果确实有待商榷，则应继续求证，并最终确定目标。所以具备成长型思维，不仅要有勇气接受并正视问题，而且要有明确的目标。\u003c/p>\u003cp>如果你认为“老大的格局确实比我高，考虑得比我全面，我赶紧改一改。不过，有个环节，我觉得等会还是要再重述下自己的观点。”这是接受并正视问题，且有明确的目标，这是具备成长型思维了吗？不是，因为他的计划不够具体，比如“重述观点”说明已经有过一次不成功的经验了，重述的成功率并不高。需要更充分的数据、资讯等信息，对观点进行重构，以增加成功率。\u003c/p>\u003cp>那么到底什么样的才是使用成长型思维模式处理问题呢？当工作计划被驳回时，如果你认为“老大的格局确实比我高，考虑得比我全面。我之前做的不完善甚至忽略的部分，需要再收集详尽的数据和资讯，才能真正完善这份计划。另外，有个环节，我还是需要将资料再整理下，重构下我的观点，再去跟老大沟通下。今天整理下需要的资料，需要其他同事支持的也要先沟通，争取明天汇总下资讯，便于后天更新完工作计划。”这里加上了具体的行动计划，这才是使用成长型思维模式处理问题的过程。\u003c/p>\u003cp>【HOW】如何使用成长型思维模式处理困境呢？\u003c/p>\u003cp>一是正视问题\u003c/p>\u003cp>接受自己的想法，无论这些想法是正面还是负面的，是积极的还是消极的。接受是处理问题的开始。因为只有不逃避，才能正视问题，并积极解决问题。正视问题是积极解决问题的开始。\u003c/p>\u003cp>二是明确目标\u003c/p>\u003cp>注意这是你自己的目标，而非他人给你制定或下达的目标。这是你今后能否坚持不懈的执行计划的关键。\u003c/p>\u003cp>三是制定可执行的计划\u003c/p>\u003cp>制定一个具体的、成长型导向的计划，并坚持不懈地实行它。为了达成目标，你需要收集相关的信息，寻找相应的措施，何时何地如何执行。越细致越具体，将会让成功率更高。\u003c/p>\u003cp>这里我举一个我运用成长型思维模式的例子：\u003c/p>\u003cp>先说说去年在我家娃眼里的排行榜，妈妈——奶奶——爸爸，如果把外公、外婆、舅舅也加入排行的话，妈妈——奶奶——爸爸——外公——外婆——舅舅——爸爸。总而言之，爸爸排名总是吊车尾。虽然有个说法是闺女是爸爸的前世情人，但这前世的情缘何时会被唤醒呢？如果没被唤醒会怎么样呢，估计就是“丧偶式育儿”。但这似乎一直只是我的问题，因为他们都觉得没问题，我自己也曾经认同如此，回头看审视自己已陷入固定型思维模式，如何运用成长型思维模式解决我爱人与女儿之间的关系呢？\u003c/p>\u003cp>首先是接受并正视问题：陪伴的时间太少、陪伴的质量太差……最终导致父女的关系不够亲密。\u003c/p>\u003cp>其次是明确目标：加深父女的亲密关系。\u003c/p>\u003cp>制定计划：\u003c/p>\u003cp>1、18年5月份的广州长隆野生动物之旅，17年带娃去珠海长隆的时候爸爸没时间，缺席了。但18年我一直等着爸爸的时间，甚至把原本四天的形成压缩成三天。出游的时候，爸爸特别重要，各种背、抱……这就是一个相对专注、集中的一种情感补给。\u003c/p>\u003cp>2、寻找父女的专属游戏\u003c/p>\u003cp>现在有两个游戏是他们父女俩的专属游戏，一是投影游戏，一是认字游戏。\u003c/p>\u003cp>投影游戏：她怕黑，所以我就去买了投影道具、手电筒，吃完饭后可以在小黑屋里玩会。在黑暗的环境里，爸爸的力量感还是比较有优势的。\u003c/p>\u003cp>认字游戏：爸爸的肢体语言比较丰富和夸张，很适合象形文字。\u003c/p>\u003cp>当然，这中间也踩了很多坑，但是多让爸爸参与，多尝试不同的活动，就可以慢慢寻找到属于他们的专属游戏。\u003c/p>\u003cp>陪伴的质量有质的飞跃，而时间呢？她现在开始会主动去找爸爸玩游戏，无形中，时间也多了不少。父女的关系自然也亲密有加。\u003c/p>\u003cp>这就是我使用这三步骤的过程，目前而言，我还是很满意我们家的家庭关系的。\u003c/p>\u003cp>&nbsp; &nbsp; 【异议预防】如果不使用成长型思维，继续保持现状可以吗？短时间看似乎问题不大，但如果是长时间维持现状呢？甚至时间长了以后，问题更严重了，是否还是你能承受的呢？如果这个问题可能会持续存在，甚至影响越来越大时，就应该防微杜渐，使用成长型思维模式处理困境。\u003c/p>","interaction":"\u003cp>A2 催化学习者应用 \u003c/p>\u003cp>【拆书家提问设计】\u003c/p>\u003cp>以上就是我对这个拆页的讲解。在一些重要的考试，如中考、高考等，在正式考试前，会有各种模拟考。这就是为了让考生能在正式考试中发挥出正常的水准。\u003c/p>\u003cp>为了让大家在今后能更好的运用今天所学到的方法，使用成长型思维模式处理困境。接下来我们将做一个分组讨论并演练，分为两组进行讨论。\u003c/p>\u003cp>请大家设想下是否有过这样的经历，如在公司干的累死累活，却不如写PPT的；在家里任劳任怨，管娃的吃喝拉撒管教育，却不如偶尔溜娃的那位……\u003c/p>\u003cp>只要你不希望持续存在，甚至越来越严重的困境都可以。面对这些困境，你将如何使用今天学到的方法进行突破呢？\u003c/p>\u003cp>【学习者编剧本】\u003c/p>\u003cp>请组内讨论下，尝试自己编一段小故事的剧本，几百字即可，设计出任务、情节变化和当时双方的对话、动作等，剧本中的对话用到今日所学。最后请将摘要写在一张纸上，时间五分钟。五分钟后我们将一位伙伴站起来讲讲他的剧本。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>小剧本\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>主题\u003c/p>\u003c/td>\u003ctd>\u003cp>托班能解决目前的问题，但也存在着很大的隐患。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>事件内容\u003c/p>\u003c/td>\u003ctd>\u003cp>一年级的小朋友比较闹腾，做作业也不自觉。目前送去托班（午托+晚托），每天都完成作业后才回家。大人小孩都很轻松，皆大欢喜。\u003c/p>\u003cp>但是周末的时候，辅导他做作业时，发现出错率极高，如同音字、组词等。我们目前很担心，他的知识掌握情况并不是很好。如果等到期末考试的时候没考好才发现问题，就糟糕了。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>人物角色\u003c/p>\u003c/td>\u003ctd>\u003cp>角色A：学生家长——曹志文&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 角色B：小白（一位朋友）\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>对白\u003c/p>\u003c/td>\u003ctd>\u003cp>角色A： 我很担心我们家小朋友的学习。\u003cbr> &nbsp; 角色B： 嗯，我能理解。但我们首先要确定下孩子目前的问题在哪。\u003cbr> &nbsp; 角色A：肯定是有问题的。\u003c/p>\u003cp>角色B：对啊，虽然我们现在花了钱，但是现在的各种机构鱼龙混杂，不能耽误了孩子。一是真实的问题要及时发现。（正视问题）二是明确下我们教育的目标，如查缺补漏等。（明确目标）三是制定个计划。（制定计划）\u003c/p>\u003cp>角色A：对的，计划很重要。\u003c/p>\u003cp>角色B：一是准备测试，通过测试了解孩子的真实水平。二是找方法，弥补缺漏的地方。三是要有时间观念，需要在规定的时间范围内完成。而且需要预见到可能存在的困难，提前准备好预案。\u003c/p>\u003cp>角色A：是的，需要回去好好研究下。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>【回应与反馈】\u003c/p>\u003cp>感谢志文的分享，在这么短的时间内，编的剧本还是分生动的。同时剧本中的对话也应用了我们刚刚所学，非常好，再次感谢志文的分享。\u003c/p>\u003cp>刚刚分享的是当我们自己面对困境或失败时，能够用成长型思维模式，使用接受、明确目标、制定计划的方法应对困境问题。\u003c/p>\u003cp>作为长辈/父母，我们需要使用成长型思维处理我们面临的困境。同时，我们也希望孩子也能拥有成长型思维，以便能更好的应对未来的各种挑战。\u003c/p>\u003cp>【提问互动】\u003c/p>\u003cp>问：是不是有成长型思维模式的父母就能教会孩子或者更准确的说是就能够潜移默化的影响孩子，让他们从小就具备成长型思维呢？\u003c/p>\u003cp>答：不一定。\u003c/p>\u003cp>问：为什么呢？\u003c/p>\u003cp>答：自己学会和教别人学会是两码事。\u003c/p>\u003cp>不可否认自己学会了才有可能教会孩子，但想要教会或潜移默化的影响孩子，这是需要方法的。日常生活中，亲子互动的场景非常多，今天时间关系，我们先聚焦在孩子面对失败向你寻求帮助时，我们应如何引导。\u003c/p>\u003cp>&nbsp; &nbsp; 接下来跟大家分享的是一个案例，当9岁小姑娘面对失败时，她的父亲如何引导她使用成长型思维处理困境的。接下来是阅读时间，请阅读完的伙伴举手示意我一下。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":11218,"quote":"\u003cp>\u003cstrong>《终身成长》\u003c/strong>\u003cstrong>P219\u003c/strong>\u003cstrong>——\u003c/strong>\u003cstrong>P221\u003c/strong>\u003c/p>\u003cp>对孩子成功的不当称赞所带来的问题，应该是我们面临的问题中最容易对付的。失败似乎是一个更棘手的问题。孩子们在遭遇失败时，已经够沮丧和痛苦了。让我们再回到这个问题上，这一次让我们说说在孩子面临失败时，父母所传达给孩子们的信息。\u003c/p>\u003cp>九岁的伊丽莎白第一次参加了体操运动会。她身材修长，柔韧性好，充满活力、非常适合练体操，她自己也非常热爱体操。当然，她对参加比赛有一点紧张，但是她的水平很高，并且对自己的表现很自信。她甚至已经想好要将她贏得的彩带挂在家里的哪个位置。\u003c/p>\u003cp>在第一个项目自由体操中，伊丽莎白第一个登场。尽管她表现得很不错，但在后来几个女孩出场之后，得分出现了变化，伊丽莎白输掉了比赛。在其他项目中，伊丽莎白同样表现得很好，但是依然没能贏得比赛。那天晚上比赛结束时，她一条彩带也没能得到，她感到很沮丧。\u003c/p>\u003cp>如果你是伊丽莎白的父母，你会怎么做？\u003c/p>\u003cp>1．告诉伊丽莎白，你认为她是最棒的。\u003c/p>\u003cp>2．告诉她是裁判的不公平让她丢掉了原本属于她的彩带。\u003c/p>\u003cp>3．安慰她说体操其实没那么重要。\u003c/p>\u003cp>4．告诉她她有足够的能力，下一次肯定能赢。\u003c/p>\u003cp>5．告诉她她本来就不该赢。\u003c/p>\u003cp>在当今社会中，对于如何增强孩子的自信心，存在着一种强有力的信息，这种信息的一个重要内容就是：保护孩子们免遭失败！但是这种做法或许能够暂时防止孩子们失望，但是从长远来看，却有着很大的危害。为什么这么说呢？\u003c/p>\u003cp>让我们从思维模式的角度看看对刚才五句话的五种可能的反应，倾听其中传达的信息：\u003c/p>\u003cp>第一种（你认为她是最棒的）：这种说法从根本上说并不是真心的。她并不是最好的——你知道这一点，她自己也清楚这一点，这对于她的恢复和进步一点帮助都没有。\u003c/p>\u003cp>第二种（她受到不公平待遇）：这是责备他人的做法。当事实的真相是，问题的根本在她的表现而不在裁判时，难道你希望她以后变成喜欢将自己的不足归咎于他人的人吗？\u003c/p>\u003cp>第三种（安慰她体操其实没那么重要）：这种说法会教给她，当她有什么事做不好时，贬低这些事情本身就对了。难道你真想告诉她这些吗？\u003c/p>\u003cp>第四种（她有能力）：这可能是所有信息里最危险的一个。难道是能力自动带领你走向成功的吗？如果是这样，伊丽莎白这次没能赢，为什么下一次就能赢呢？\u003c/p>\u003cp>第五种（告诉她她本来就不该贏）在这种情况下说这样的话的确有些无情。当然，你可以不用这么直白的方式表达，不过伊丽莎白具有成长型思维模式的父亲基本上就对她表达了这个意思。\u003c/p>\u003cp>下面是她父亲的原话：“伊丽莎白，我知道你的感受。你对比赛寄予了如此大的希望，而且拿出了自己最好的表现，但是依然没能贏你一定感到很失望。但是你要知道，你并没有付出100％的努力。有很多女孩练习体操的时间都比你长，而且比你更努力。如果这是你真\u003c/p>\u003cp>心想要的东西，那么你就要全身心地为此付出努力。”\u003c/p>\u003cp>他同样告诉伊丽莎白，如果她只是想拿体操当个乐趣，那也没有问题。但如果她想在比赛中有所成就，那么就必须付出更多。\u003c/p>\u003cp>伊丽莎白记住了父亲的话，她花了更多时间来反复练习和完善自己的全套动作，尤其是比较薄弱的部分。在下一次比赛中，全地区有80名女孩参加了角逐。伊丽莎白赢得了5个个人项目的彩带，并夺得这次比赛综合项目的总冠军，捧回家一个巨大的奖杯。到现在，她的房间里挂满了各种获奖证明，几乎覆盖了整个墙面。\u003c/p>\u003cp>其实，她的父亲不仅告诉了她真相，也同样教给她从失败中学习的方法，告诉她为了未来的成功需要付出全部努力。伊丽莎白感到失望时，她的父亲很同情她，但他没有给她虚伪的鼓励，因为那只会让她在未来感到更加失望。\u003c/p>\u003cp>我与很多教练交谈的时候，他们都会问我：“那些可塑之才都怎么了？这样的运动员都哪去了？”很多教练抱怨说，当他们给予运动员纠正性的反馈时，这些运动员都会抱怨自己的自信心受到了打击。有时这些运动员还会打电话回家向父母抱怨。他们似乎只希望教练告诉他们，自己多么有天赋，其他的什么也别说。\u003c/p>\u003cp>这些教练说，在过去，一场联赛或少儿足球赛结束后，父母们会在回家的路上与孩子们回顾和分析球赛，给他们提供一些有帮助的建议。而现在在回家路上，如果孩子们当天表现不好或者所在的球队输了，父母们会责怪教练和裁判。他们不愿意责怪孩子，怕伤害孩子的\u003c/p>\u003cp>自信心。\u003c/p>\u003cp>但是从上面伊丽莎白的例子中可以看出，孩子们需要诚实而有建设性的反馈。如果孩子们被“保护”起来，他们将无法从失败中很好地学习。他们会认为建议、指导和反馈是消极而具有破坏性的。回避建设性的批评并不会帮助孩子们建立自信，反而会危害他们的未来。\u003c/p>","explains":"\u003cp>【学习目标】在跟随我完成本次的RIA现场学习后，学习者能够按成长型思维做出诚实而有建设性的反馈（澄清），应用说感受、讲事实、提建议三步骤的方法（行为）应对孩子们（或他人）寻求自己帮助（界定）的问题。\u003c/p>\u003cp>这个片段中讲述了一个9岁的小女孩遭遇失败时，她的父亲是如何使用成长型思维处理的。在文中有提出了一个问题“如果你是伊丽莎白的父母，你会怎么做？”，同时，给出了五种回复的方式，并一一进行分析。前四种的处理方式归结起来就是：自我催眠、推卸责任，但这些并无法真正帮助到孩子。只是打着“保护孩子自信心”的旗帜，阻碍着孩子的成长，只有第五种才是使用成长型思维的处理方式。\u003c/p>\u003cp>有个成语叫忠言逆耳，要如何让这“忠言”听着更“顺耳”，如何让伊丽莎白愿意接受，甚至是乐意接受呢？他的父亲做了一个很好的表率，不仅使用了成长型思维帮女儿处理问题，而且做了一个诚实而有建设性的反馈。\u003c/p>\u003cp>【HOW】当孩子遭遇失败向你寻求帮助时，如何做出诚实而有建设性的反馈呢？可归结为以下三步骤。\u003c/p>\u003cp>一是说感受。比如“我知道你的感受”、“你对比赛给予了如此大的希望”……\u003c/p>\u003cp>二是讲事实。比如“你并没有付出100%的努力”、“有很多女孩练习体操的时间都比你长，而且比你更努力。”\u003c/p>\u003cp>三是提建议。比如他提了两个建议，一是“如果只是想拿体操当个乐趣，那也没有问题。”；二是“如果这是你真心想要的东西，那么你就要全身心地为此付出努力。”、“如果她想在比赛中有所成就，那么就必须付出更多。”\u003c/p>\u003cp>当然这三者的顺序并不是固定的，可能是感受与事实在前，建议在后；也可能是先给建议，再说明感受和事实。\u003c/p>\u003cp>我女儿从去年开始就很迷恋拼拼图，一开始是9块的，接着是16、32、48。从一开始拼木质的，到现在拼纸质的。从最早要选择她感兴趣的图案，到现在拼色块的。从以前的二维到现在尝试三维的，她对拼图一直保持着极高的热情。\u003c/p>\u003cp>对于她这个年龄层而言，拼图实际上是一个失败率非常高的游戏，要求观察细节选出正确的拼图，放置到正确的位置，放置的方向和角度要正确，很容易不小心碰到或者不小心把已经拼好的拼图弄坏了，只要有一块拼错，后面就会跟着一直错。\u003c/p>\u003cp>她玩游戏一般都是我陪着她拼，最开始9块都不会拼的时候，一不对，就开始在那发脾气，扔拼图。我一般会抱抱她，“你很生气，没拼对是吧。”、“就差一点点是吗？”、“没对准是吗？”……\u003c/p>\u003cp>等她的情绪慢慢停下来了，我会陪着她把拼图捡起来，“你很生气是吧，没把拼图们送回家是吗？”、“你是不是觉得很可惜，就差那么一点点”……\u003c/p>\u003cp>当她再次遇到问题的时候，我会先试着引导她：转个方向、再转一次、换个位置、换块拼图……甚至我会问她，是否需要妈妈帮忙。而我的帮忙一般是动口不动手。\u003c/p>\u003cp>现在不仅在拼拼图上，而且在搭积木、黏黏土……她情绪发泄的时间不长，而且当安抚完后，她会愿意再次去尝试，甚至自己会在那念叨着“太高了”、“太少了”……她开始有一个冷静后的自我分析的过程。虽然有时候她还是会有情绪失控的时候，但我看到的是失败后她仍旧勇于去尝试，也会尝试去分析，当然她现在也发现了自己的局限性，她开始会主动寻求帮助。\u003c/p>\u003cp>无论在这个过程中，她面对怎样的失败和挫折，她都能保持着非常高的热情。\u003c/p>\u003cp>【适用边界】这个方法不仅面对失败时可以给予孩子诚实而有建设性的反馈。当面对成功时，也同样适用，也会让他们从中学习到经验。\u003c/p>","interaction":"\u003cp>&nbsp;A3 促动参与 \u003c/p>\u003cp>【提出并明确问题】\u003c/p>\u003cp>【互动】问：刚才分享的是当孩子遭遇失败寻求帮助时，通过说感受、讲事实、提建议三步骤做出诚实而有建设性的反馈。那么大家觉得这三个步骤中，哪个步骤的难度最大呢？\u003c/p>\u003cp>答：说感受\u003c/p>\u003cp>【明确问题】\u003c/p>\u003cp>（提问）大家都认为“说感受”这个步骤最难，对吗？（互动）\u003c/p>\u003cp>答：（现场大多数人点头）对。\u003c/p>\u003cp>（确认问题）好的，大家都认为说感受这个步骤最难。\u003c/p>\u003cp>【引导分组讨论问题本质】\u003c/p>\u003cp>接下来请大家讨论下，你们为什么会觉得“说感受”难度这么大呢？换句话说，认为难的根本原因是什么？也就是说，问题的本质是什么？到底有哪些因素影响呢？\u003c/p>\u003cp>请大家5分钟讨论，讨论结束后，我将邀请小组进行分享。\u003c/p>\u003cp>学员小组讨论\u003c/p>\u003cp>【学员分享】\u003c/p>\u003cp>1、&nbsp; 说感受时，主观臆断，难以客观，对方不认可。\u003c/p>\u003cp>2、&nbsp; 没有参与其中，没有了解事情的经过，使用的感受描述，无法获得孩子认可。\u003c/p>\u003cp>3、&nbsp; 对方情绪没有平复，无法准确表达，影响我们判断感受。\u003c/p>\u003cp>4、孩子因为认知的问题，无法理解判断我们说描述的感受是否符合他自己的遭遇。\u003c/p>\u003cp>【回应与反馈】\u003c/p>\u003cp>感谢大家的总结，大家觉得刚刚大家总结出来的问题本质中，哪些词是有共性的呢？\u003c/p>\u003cp>学习者： 感受的认可、判断\u003c/p>\u003cp>嗯，大家有没有发现，我们和孩子之间对感受的认知是否一致、是否一下子说到心坎里获得对方的认可，才是关键？否则对方就会认为我们是敷衍，大家认同吗？（提问）\u003c/p>\u003cp>学习者：认同。\u003c/p>\u003cp>【明确问题本质】\u003c/p>\u003cp>（提问）那么，大家讨化出的问题本质就是，双方对感受的认知是否一致，是否准确的表达和理解认同感受，才是说出感受这个问题的本质。大家认可吗？\u003c/p>\u003cp>学习者：认可、同意、\u003c/p>\u003cp>（确认）好，就这个问题的本质，我们来讨论一下如何改善解决这个问题。【引导分组讨论解决方案】\u003c/p>\u003cp>首先说明一下，我们今天的时间有限，给大家的讨论时间也有限，大家在讨论的过程中，还是确认一下，我们讨论问题解决的目标是什么？不要讨论太散。比如：是不是讨论出一些方法，可以帮助孩子达到认同感受就可以呢？\u003c/p>\u003cp>学习者：可以的。\u003c/p>\u003cp>&nbsp; &nbsp; 好，请大家在6分钟左右，讨论如何让孩子们达到认同感受，给出你们建设性的建议，最后我们将请伙伴上来分享他们的成果。\u003c/p>\u003cp>【学员分享——讲解成果】\u003c/p>\u003cp>学员：\u003c/p>\u003cp>方法一：从小培养孩子对情绪的认知，比如从小通过具体的事例，描述小孩子正在经历的感受，让孩子从小认知“伤心”、“愤怒”、“嫉妒”的感受……便于孩子能准确表达，并且能准确理解大人的表述。\u003c/p>\u003cp>方法二：鼓励孩子们经常说出自己的感受，区分事实/评论/感受，可以借鉴非暴力沟通的方式进行表达。\u003c/p>\u003cp>&nbsp; &nbsp; 【回应与反馈】\u003c/p>\u003cp>&nbsp; &nbsp; 谢谢雪艳小组的发言，我说结一下。当我们在孩子遇到困境的问题时，我们可以通过说感受、讲事实、提建议的方式给孩子成长型思维模式的建议反馈，大家觉间最难的是：说感受。原因是我们所说的感受如果不能准确的表达被认同的话，就难以让孩子对我们产生信任。而表达感受不能准确的表达认同问题的本质是我们和孩子对对感受的认知是否一致。\u003c/p>\u003cp>&nbsp; &nbsp; 解决的方法有：从小培养孩子对感受的理解，鼓励孩子说出自己的感受，区分评论和事实，达到双方对感受理解一致性的问题。\u003c/p>\u003cp>&nbsp; &nbsp; 好的，非常感谢在座各位的参与，我们不仅仅探究出了问题的本质，还找出了匹配的方法进行解决，非常棒。\u003c/p>\u003cp>&nbsp; &nbsp; 【A2】布置任务——事后复盘\u003c/p>\u003cp>非常感谢大家的分享！\u003c/p>\u003cp>请问下大家，近期是否有遇到孩子/晚辈面对失败时，你需要给出反馈的情况？\u003c/p>\u003cp>答：有\u003c/p>\u003cp>今天的课程结束后，希望大家能认真做个复盘，总结下这个反馈是否诚实而有建设性，是否有体现出成长型思维模式。同时，规划下未来将如何使用成长型思维去提出反馈。\u003c/p>\u003cp>【徐雪艳分享】\u003c/p>\u003cp>&nbsp;我儿子今年6岁，在他5岁的时候我就希望他去学钢琴。他试了两次，都是哭着走出教室，我不忍心，就没逼他继续学。今年他6岁了，我又骗他去试一试，他去了5次后，又说不去了。他说“太难了”、“他不会”……我听了很生气，他怎么这么容易就放弃。但是我知道冲他发脾气没有什么用，甚至会有反效果。\u003c/p>\u003cp>我首先是肯定他，跟他说你已经很棒了。我问了其他小朋友的爸爸妈妈，其他小朋友都是上一节课后，要练习好几次才能记住，你没有练习都能记住。如果你再练习一下，肯定更棒，就不会觉得难了。要不你再去上一次课，然后练习五次，再去上一次课，看看有没有变简单？他后来同意再去试试，目前来说学习的效果还不错。\u003c/p>\u003cp>复盘：我觉得我所给予的反馈算是有建设性的，但诚实不诚实可能有点水分哈。我自认为我儿子是有固定思维的，而我的反馈具备了一定的成长型思维。我希望他明白，很多事情一开始不会，经过学习会从不会变成会，而且每个人都是这样的。这应该是一种更刻意去培养他成长型思维的反馈方式，以后也打算继续朝这个方向去做。\u003c/p>\u003cp>不过，我觉得我在“说感受”的方面还可以做得更好些，当他遇到挫折时，有一些负面的情绪是正常的，接受并引导他舒缓情绪也很重要。\u003c/p>\u003cp>【曹志文分享】\u003c/p>\u003cp>背景；我的孩子上小学一年级，前两天上课忘带笔记本，为了记录老师布置的作业，和同桌要了一张纸记录；在记录完后去上厕所期间，他的同桌私下收回了那张记录纸，等他回来被同桌告知，要把纸收回不想给他了。最后布置的作业被擦，他也来不及抄录；只能放学后和其他小朋友询问。这件事给他造成了很大困惑不知道如何处理。\u003c/p>\u003cp>我选择跟孩子聊这个事：\u003c/p>\u003cp>一说感受：这件事给你造成了很大困惑对不对？心里也是不舒服对不对。事后还给你造成了很多麻烦。你想知道怎么处理这种事吗？\u003c/p>\u003cp>二讲事实：孩子这是一个物权问题，首先你的同桌把纸给了你，那就成为了你的东西，他已无权收回，你要清楚这点。\u003c/p>\u003cp>孩子说：要纸的时候我说的是给，同桌收回的时候说借，不想借我了。\u003c/p>\u003cp>我说：无论是给还是借，你同桌都物权在未经过你同意前，私下收回。\u003c/p>\u003cp>（在这个过程中，给孩子模糊的是非观中，建立一个判断对错的标准。有了这个标准，孩子相信自己是对的，不再困惑）\u003c/p>\u003cp>三提建议：既然你同桌做错了，还给你造成了困扰。这件事情你不能默默的接受，要站出来处理。这么处理呢？能跟他打吗？\u003c/p>\u003cp>孩子：不能。\u003c/p>\u003cp>我说：很好，不能打。这时候就要靠说了。下次在遇到这种事，你得跟他说\u003c/p>\u003cp>一、说事实：这纸不论你是送给我还是借给我，都不能私自收回，要经过我的同意\u003c/p>\u003cp>二、说影响：你这么私下拿走，已经给我造成很大的麻烦，我把作业都记录在上面了\u003c/p>\u003cp>三、提建议：如果我们还是好朋友，请把纸还我，或者让我抄一份。如果你还是不还的话我就只能找老师帮忙解决了\u003c/p>\u003cp>在处理这件事情最好公开处理，有小朋友围观最好哈，能获得更多人支持。\u003c/p>\u003cp>Ending结尾\u003c/p>\u003cp>今天主要分享了两个方面的内容，一是在面对困境或失败的情况下，如何使用成长型思维模式更理性的分析并处理困境。\u003c/p>\u003cp>二是作为父母/长辈的我们如何以身作则，在潜移默化中，让孩子/晚辈也能慢慢形成成长型思维。\u003c/p>\u003cp>希望今天的分享对大家今后的工作和生活有所帮助，感谢大家今天的参与，我是拆书家佳音。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1556069036000,"updated_at":1559536373000,"ria":true},{"id":7333,"topic":"走向成长性思维模式","learn_goal":"用“通往成长型思维模式的5步骤”模板，写出行动方案并执行","remark":"通过今天学习的通往成长型思维的5个步骤，锻炼自己的能力，强化自己的思维，应对未来","level":"TF3-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"龚婷","city":"南昌"},"club":{"name":"南昌滕王阁分舵","city":"南昌"},"prologue":"【学习目标】（观察技能点4：学习目标中包含学习者要完成行为的具体内容和完成程度，现场学习设计清晰体现了该学习目标）\r\n当我们遇到未知，困难挑战，或者消极情况时，改用“通往成长型思维5步骤”模板，现场写出具体的行动方案。取代原来的迷茫，不知所措，抱怨，逃避等。并在后期的操作中按照行动方案执行。","ratings_count":1,"texts":[{"id":10776,"quote":"\u003cp>【图书介绍】\u003c/p>\u003cp>（观察技能点5：学习者场景介绍法中，能够清晰辨别出事件，提问，影响和解决4个步骤）\u003c/p>\u003cp>&nbsp; &nbsp; 事件：工业技术进步解决了手工业速度慢产量低的问题；汽车的出现，自行车行业进入将近20年的沉默期；90年代和21世纪的前几年，人类进入网络时代，电脑的推广，IT首次出现在人类历史上，离我们最近的这20年，我们强烈感觉到互联网改变了我们的生活，人工智能代替重复性可复制性的劳动力，线上交易方式冲击传统实体店，AI用于教育资源，线上产业的不断发展，我们的时代都在走向前所未有的繁荣。\u003c/p>\u003cp>&nbsp; &nbsp; 提问：身处这个vuca（瞬息万变的）时代，我们即是这个时代的受益者，也是这个时代的边缘者，往前一步是等待着你去开拓的新天地，原地踏步是被动等待被时代选择。我们是要去引领时代超越？还是被挑战牵绊？未来的改变带给在座的是害怕，担心，迷茫，忧虑，无所谓还是满满的自信，遇见机遇的兴奋，踌躇满志？我们还能怎么做，帮助自己不管在什么情况下，自己都不是被选择的那个？不是被out的那个？我们去哪里寻找那份别人拿不走的笃定，迎难而上？\u003c/p>\u003cp>&nbsp; &nbsp; 影响：相信大家都体会过长期不看书，当再次捡起书本阅读时，仅阅读速度理解能力都比经常读书思考的人慢一点的体会。同样如果我们还在用原来的方式等待新的事物或者挑战，随遇而安或者逃避，都不会拓展自己的能力，我们也很难遇到更好的伙伴，长此以往我们也会慢慢失去对新事物的学习能力和积极性。&nbsp;&nbsp;\u003c/p>\u003cp>&nbsp; &nbsp; 解决：本书《终身成长》，作者德伟克提出的成长型思维，获得全球最高教育奖“一丹”奖，书中介绍的成长型思维关注的是我要成长，迎接挑战，专注于个人的学习和提高。成长型思维是改变的起点，是不怕改变的法宝。&nbsp;只有自己不断改变，迭代，革新，与时俱进，我们才不害怕改变，不害怕任何瞬息万变的挑战，把不利因素转化成有利因素，抓住每一个机遇。\u003c/p>\u003cp>【A1】请大家自测\u003c/p>\u003cp>（观察技能点7：量表题清晰设置多个选项，学习者通过自测可以了解在某一个情况下自己的表现）\u003c/p>\u003cp>你是成长型思维的思考者吗？现在给大家发放一个自测题，请大家根据自己的实际情况填写，1分表示不符合，2分表示较少符合，3分表示比较符合,4分表示非常符合\u003c/p>\u003cp>【和学习者的互动/提问】拆书家：“超超,你的分数是多少？”超超：“19分。”拆书家：“大家都已经写完了，我们来讲解下测试题和分数说明。”\u003cbr>\u003c/p>\u003cp>【I】解释自测（解释量表题的意义）\u003c/p>\u003cp>这个测试是测试自己是成长型思维还是固定型思维。\u003c/p>\u003cp>≤9分，你是个成长型思维思考者，你一直都在努力成为一个更好的自己，敢于尝试。\u003c/p>\u003cp>10-19分，你大多数时候不太确定你自己到底是怎么想的，你的思维比较容易被左右，介于固定型和成长型思维之间。\u003c/p>\u003cp>≥20分+，你是个固定型思维模式的思考者，你不会轻易被说服，注重知识是否真的有用。\u003c/p>\u003cp>通过这个测试我们可以看到----------\u003c/p>\u003cp>面对困难，固定思维的人逃避，成长型思维的人欢迎。\u003c/p>\u003cp>面对变化，固定思维的人痛恨，成长思维的人拥抱。\u003c/p>\u003cp>面对机会，固定思维的人老师关注限制点，成长思维的人寻找机会。\u003c/p>\u003cp>面对改变，固定思维的人逃避，表现出无能为力，成长型思维凡事皆有可能。\u003c/p>\u003cp>面对批评质疑，固定思维的人不接受，反驳，成长型思维的珍视反馈，主动学习。\u003c/p>\u003cp>固定思维喜欢呆在舒适区，成长型思维喜欢探索新事物，\u003c/p>\u003cp>固定思维有时觉得努力是无用功，有些事情就是给有天赋的人准备的，成长型思维每次失败都是一堂课。\u003c/p>\u003cp>固定型思维的人学习止步于高考，成长型思维的人学习是终身事业。\u003c/p>\u003cp>固定思维模式更关心在乎的是别人如何看待自己，也就是我是什么；而成长型思维模式让你更关心能否提高自己和怎么提高自己，也就是我还能成为什么。\u003c/p>\u003cp>【适用边界】测试的分数高低不能说明思维的好坏，只是不同。也许你在学习思考方面是个固定思维者，但是你在艺术思维，语言思维，逻辑方面可能是个成长型思维思考者，人们在不同的场景中，思考方式是不一样的。\u003c/p>\u003cp>我们现场大多数的学习者测试的结果都是在10-19分这个档，你不像固定型思维思考者那样的固执执着难改变，但是需要了解什么是成长型思维帮助自己跳出舒适区，走进另一个新的世界。我相信来拆书帮互动的小伙伴，都是爱学习的伙伴，在座各位都有相当大的潜力成为成长型思维的思考者，接下来我们来阅读拆页，来学习下如何成为成长型思维的思考者。\u003c/p>\u003cp>【R】阅读原书拆页\u003c/p>","explains":"\u003cp>【I】拆书家讲解引导\u003c/p>\u003cp>（观察技能点6：拆书家有简短互动，并能精确控场，还要有举例子）\u003c/p>\u003cp>【预防异议】原书拆页因为是外来翻译文，有很多表达习惯和国内不一样，尤其是向其他国家读者用文字介绍新事物，就更晦涩难懂了，所以今天我用了5个步骤来讲讲当我们碰到困难挑战时，如何用成长型思维来思考呢？\u003c/p>\u003cp>第一步：“判断”。当你碰到问题时，你当下的情绪是红色还是绿色？【预防异议】不是谈论如何拥有成长型思维吗？为什么要先讲情绪呢？因为情绪会影响思维，引导思维，我们不能完全控制思维但是我们可以试着控制情绪。当你碰到困难时的反应是红色情绪时，你的行为很可能是逃避，愤怒等固定思维。反之，当你碰到挑战时的反应是绿色情绪时，你已经是一个成长型思维的拥有者了。情绪和思维的关系，就好比土壤和种子的关系。红色情绪种出固定型思维，健康的绿色土壤培养出成长型思维。【和学员互动/提问】我们来玩个游戏帮助大家区分这两种情绪。拆书家：“下面我来说一些我们常碰到的情绪，大家听到这个情绪时，用放在你们面前的红绿卡来代表你听到它时的感觉。”拆书家一个个说：“焦虑，愤怒，担心，逃避，彷徨，伤心，失落。”学习者都纷纷举起红色牌子。拆书家一个个说：“开心，满足，喜悦，希望，成就感。”学习者纷纷举绿色牌子。\u003c/p>\u003cp>【现场游戏互动照片】\u003c/p>\u003cp>当你碰到困难时的反应是红色情绪时，你很可能会采取固定思维思考出来的行动。反之，当你碰到挑战时反应是绿色情绪时，你已经是一个成长型思维的拥有者了。所以我们拥有成长型思维的第一步就是要先确定健康良好的情绪。\u003c/p>\u003cp>那当我如果是固定型思维思考的人，或者我对成长型思维的使用还不娴熟时，还有什么方法能帮助我用成长型思维思考呢？”别急，一步一步来。\u003c/p>\u003cp>第二步：“接纳”。接纳自己的红色情绪和固定型思维。【预防异议】接纳这步是最难的，因为有人觉得不采取行动，静观其变也是可以的，没什么不好的。难道采取行动就一定是好的吗？对于这个问题我们可以再开一堂拆书课来讲讲怎么接纳自己，但是今天时间的关系，就用一个问题来回答这个疑问“如果你觉得静观其变是好的，那为什么你还能想出更好的绿色情绪呢？所以不妨和我一起来改变行动，试着走出自己的舒适区，去走向更好的自己。”（这么做的好处）\u003c/p>\u003cp>第三步：“画像”。想象自己成功的样子是什么样的？别人看到那时成功的你是什么样的？跟现在有什么不一样？会说什么穿什么谈吐如何，记住这个样子。（这么做的好处）心理学上把这个叫未来画像，越具体生动，你会越来越像你想成为的那个样子。\u003c/p>\u003cp>第四步：“能力”。你要具备哪些能力才能要成为你想象中的样子，请列出至少2个。\u003c/p>\u003cp>第五步：“分享”。和一位挚友分享进度。如果可以的话，给自己一点压力，才会成长的更快。\u003c/p>\u003cp>从第一步判断--接纳--画像--能力--分享，这整个过程，就是在培养你的成长型思维思考的过程。\u003c/p>\u003cp>拆书家边讲解边用PPT展示\u003c/p>\u003cp>【举例】：当产品经理在卖产品遇到困难的时候，买家买东西没有诚意，一直讨价还价要最低价，经理可能会“你买不买，没钱还问东问西”“叹息，怎么这么烦”这就是一个固定型思维了。那么我们来看看例子怎么转变为成长型思维。\u003c/p>\u003cp>第一步判断：我的红色情绪会出现--我的变得不耐烦，语言甚至会有攻击性。\u003c/p>\u003cp>第二步接纳：红色情绪会阻碍我成功，我卖不出产品是小，影响买卖成交的因素很多。我还能做些什么来帮助我提高成交率呢？这比我怎么纠结卖出这一个单子更对我有帮助。\u003c/p>\u003cp>第三步画像：想象中我成功的样子：面带微笑，信心满满，能通过客户的1-2句话，明白对方的真正需求，加上精准的销售技巧，业绩总是第一。\u003c/p>\u003cp>第四步能力：我变成我想要的那个样子需要具备哪些能力？具体要做什么事情？1：多见不同的客户，允许自己多失败，记录下来失败的案例。2：复盘那些成功的客户案例，找到成功成交的点是什么？具不具备可复制性？3: 多听客户需要什么，再看看我能给什么。4:多向销售冠军们学习他们的销售思路。\u003c/p>\u003cp>第五步分享：我愿意把我自己的进度记录在我的微信上，让大家来监督，同时也让潜在客户看到我是认真工作的，负责任，对自己工作热爱的。\u003c/p>\u003cp>【适用边界】人们在不同的领域展现出不同的思维模式。我们每个人都是成长型和固定型的混合物，正常的人类都这样。\u003c/p>\u003cp>【预防异议】改用成长型思维看待问题就能解决我所有的问题吗？不能。影响成功与否的因素太多了，思维不是唯一因素，但是我们知道，因为这种思维模式而拥有了不同以往的生活--更加丰富的生活。因为这种思维模式，成为更加积极，更有勇气，更加开明的人。\u003c/p>","interaction":"\u003cp>【A3】促动参与\u003c/p>\u003cp>拆书家提问设计（逐字稿）：（观察技能点8：给出了一个预先设计好的非常具体，确定的场景，学习者可在此场景中演练或讨论或应用新技能，邀请一组当众表演或角色扮演）\u003c/p>\u003cp>（观察技能点9：学习者可以根据拆书家设定的案例场景，进行小组讨论，应用知识点并形成一个解决方案，或是应用知识点进行组内扮演）\u003c/p>\u003cp>现在，该由你来决定是否该做出改变了。刚刚从过年被七大姑八大姨催婚的小赵，终于逃回到正常的工作生活中，看着别人刚过完情人节，小赵也开始认真思考自己的人生大事，冷静下来想想七大姑八大姨对他催婚的话“眼光不要太高了，差不多就行了！”“你一年挣多少钱，婚房准备好了吗？”“你都老大不小了，再不结婚生孩子，等你孩子结婚你都得60了！”小赵的心情很低落，表情很无奈，碍于对长辈的礼貌也不好顶嘴，顶嘴也没用。顶嘴的最好方式就是带个女朋友回家。在被催婚被紧逼时，小赵怎么用成长型思维帮助自己成功结婚找到对象呢？接下来两两一组，一人扮演被催婚的小赵，一人扮演催婚的七大姑八大姨。\u003c/p>\u003cp>5分钟之后，我请学习者上台来分享。\u003c/p>\u003cp>【学习者案例分享】\u003c/p>\u003cp>梅雪扮演催婚的七大姑八大姨\u003c/p>\u003cp>谢超超扮演被催婚的小赵。\u003c/p>\u003cp>梅雪：“眼光不要太高了，差不多就行了！你都老大不小了，再不结婚生孩子，等你孩子结婚你都得60了！”\u003c/p>\u003cp>小赵：当我意识到我自己很烦躁，有点生气这些红色情绪出现时，带给我消极情绪。我改用成长型思维5步骤来思考。\u003c/p>\u003cp>第一步：判断。我的红色情绪是烦躁，生气。\u003c/p>\u003cp>第二步：接纳。我想成为更好的自己，也想找个女朋友成家立业了。\u003c/p>\u003cp>第三步：画像。我未来的样子是家庭美满，儿孙满堂，明年带个女朋友回家一起过年。\u003c/p>\u003cp>第四步：能力。1 多与异性接触，今年加大自己和异性接触的机会，多去有异性的场所。2提升自己的价值，沟通，懂得异性的心理，学会聊天。\u003c/p>\u003cp>第五步：分享。1 可以告诉身边的朋友有好的女孩子可以介绍给我 2 向家长汇报进度，让他们知道我有认真把这件事情提上日程\u003c/p>\u003cp>【学习者案例行动笔记】\u003c/p>\u003cp>【A2】催化应用\u003c/p>\u003cp>拆书家提问设计（逐字稿）：（观察技能点10：学习者根据指令，写出自己一个未来具体任务要做的应用，比如：某个特定任务，和人分享，事后复盘，找人陪练）\u003c/p>\u003cp>大家演练得非常棒！所以接下来给大家布置一个作业，请大家在接下来的一周时间，把通往成长型思维模式的5步骤在这两天内和一位亲友/同事分享今天所学的知识。\u003c/p>\u003cp>那么，有哪些要点可以分享呢？比如，可以聊聊5个步骤是什么；也可以说说它可以帮助我们解决什么样的问题等等。\u003c/p>\u003cp>你分享的要点越多，你措辞表达能力也会提高的越多，请大家现场写下你的分享行动时间，你会和谁分享，分享什么，写好后念出来，也可以拍照分享到我们今天的群里。\u003c/p>\u003cp>\u003cstrong>“\u003c/strong>通往成长型思维模式5步骤\u003cstrong>”\u003c/strong>\u003cstrong>“\u003c/strong>\u003cstrong>判断\u003c/strong>\u003cstrong>”；“\u003c/strong>\u003cstrong>接纳\u003c/strong>\u003cstrong>”；“\u003c/strong>\u003cstrong>画像\u003c/strong>\u003cstrong>”\u003c/strong>\u003cstrong>；“能力”；“\u003c/strong>\u003cstrong>分享\u003c/strong>\u003cstrong>”\u003c/strong>\u003cstrong>行动卡\u003c/strong>\u003c/p>\u003cp>\u003cstrong>分享日期： \u003c/strong>\u003c/p>\u003cp>\u003cstrong>分享内容： \u003c/strong>\u003c/p>\u003cp>\u003cstrong>分享对象： \u003c/strong>\u003c/p>\u003cp>请学习者桃子来分享下你的行动卡。\u003c/p>\u003cp>【结束语】走向成长性思维模式需要一个过程。希望大家能够回家坚持练习。\u003c/p>\u003cp>最后我们来看看本书作者德伟克给出的公式“-performance（表现）=ability（能力）*mind（思维）”，能力再强没有与之匹配的思维，也如作壁上观。希望大家通过今天学习的成长型思维思考的5个步骤，锻炼自己的能力，强化自己的思维，未来已来，让成长型思维帮助自己不断成长。改变也许艰难，但我从未见谁说过不值得。\u003c/p>\u003cp>好的，我们的拆书就到这里请大家用便签写下想对我说的话，谢谢大家今天的参与\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1551767643000,"updated_at":1551767643000,"ria":true},{"id":7153,"topic":"成长型思维","learn_goal":"学习者能区分成长型思维和固定型思维，并能用四步法转换","remark":"","level":"TF3-1","duration":20,"status":29,"type":0,"chaishujia":{"username":"李佩璇","city":"海口市"},"club":{"name":"海口花梨分舵","city":"海口"},"prologue":"\u003cp>【问候】：大家晚上好，欢迎大家来参加我们拆书帮海口花梨筹备分舵第48次线下拆书活动。&nbsp;\u003c/p>\u003cp>【自我介绍】：我是佩璇，现在更多的人叫我小满妈，我有三个身份标签，第一是我一名3岁女孩的妈妈，在成为妈妈之前，一直都从事了国际酒店管理工作8年时间；第二个身份标签，我是一名民间亲子阅读推广人，在我们家附近小区开了一家小小的绘本馆，有2年多的时间了；第三个身份标签，我是一名终身学习者，特别在成为妈妈以后发现要学的东西实在太多太多，我一直都在学习的路上，前不久刚通过二级拆书家的评定。在工作中，我喜欢把优质的童书分享给孩子和家长们，在拆书帮，我喜欢用RIA拆书法把一些致用类书籍带给爱学习的大家。&nbsp;\u003c/p>\u003cp>【分组】今天的活动会有小组讨论环节，从我右手边开始，请大家两两组成一组。&nbsp;&nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>【图书介绍】\u003cem>&nbsp;（技能点要求：&nbsp;实用类或理论类图书，场景法介绍书，事件场景-提问-影响-解决）\u003c/em>\u003c/p>\u003cp>\u003cstrong>事件场景：\u003c/strong>还记得我们上学考试时，面对复杂的题目、面对考试的分数、面对老师或者父母对你丢分题目的批评教育。\u003c/p>\u003cp>\u003cstrong>提问：\u003c/strong>你是怎么做的吗？复杂的题目你会直接跳过，还是尝试解答？考试的分数，你会把它视为最终的结果，还是了解自己每个学习阶段情况的指标？失误时他人的批评教育，对于你来说是指责还是学习的机会？\u003c/p>\u003cp>\u003cstrong>影响：\u003c/strong>&nbsp;如果你选择前者，证明你那时候处于固定型思维模式中，在这个世界里，最后的成绩意味着你的成败，而成功或失败是长久的，很难改变的。这样的思维模式就是你的一种信念，这种信念会给你带来无限的负面情绪，固步自封。\u003c/p>\u003cp>\u003cstrong>解决：\u003c/strong>在《终身成长》这本书中能看到成长型思维和固定型思维模式是如何影响你的想法和行为，当你处在固定型思维模式中，应该如何转变固有的思维方式，让你更享受于学习、成长的快乐，发现自己更多的可能性。\u003c/p>\u003cp>【学习目标】（技能点要求：&nbsp; 包含学习者可被观察到/被测量到的行为和动作，澄清与界定完成程度）\u003c/p>\u003cp>学完后，学习者能够描述出固定型思维和成长型思维的差异，在面对挑战、障碍或者批评出现固定型思维模式时，能够使用四步法将其转变为成长型思维模式，用积极的心态去迎接挑战、去克服障碍、去从批评中学习，提升自己。\u003c/p>","ratings_count":2,"texts":[{"id":10557,"quote":"\u003cp>&nbsp; \u003cem>（技能点要求：总内容未超过2页图书内页，只是What或Why的内容，或原书一个完成的案例，不包括How的内容。）\u003c/em>\u003c/p>\u003cp>\u003cem>\u003cbr>\u003c/em>\u003c/p>\u003cp>成长型思维模式能让人们—即使是被贴上否定标签的人—充分运用和开发自己的大脑。他们的头脑中不会充满局限性的思维，归属感薄弱，也不会担心其他人会来定义自己。\u003c/p>","explains":"\u003cp>\u003cem>（技能点要求：&nbsp; 要求：1、给出了具体行动建议或具体步骤，2、举出了案例，并通过换概念与匹配例子之间的对比，引出知识点逻辑、步骤和明确边界等）\u003c/em>\u003c/p>\u003cp>\u003cem>\u003cbr>\u003c/em>\u003c/p>\u003cp>原文中只有两句话，阐述了成长型思维模式是如何影响我们的想法和行动。那什么样的思维模式才算是成长型思维呢？\u003c/p>\u003cp>接下来我们一起来看三个案例：\u003c/p>\u003cp>案例1：【引出知识逻辑点1】\u003c/p>\u003cp>在大学一次班级活动中，老师推荐小A和小B为节目主持人，因为小A和小B在大学之前都说家乡话，普通话不够标准，小A害怕主持时说得不准确，引起同学老师的嘲笑，不敢接受这个任务。可是小B知道自己发音不准，但想正好可以多多练习来纠正自己发音，他愿意接受这个挑战。\u003c/p>\u003cp>你觉得哪位是具备成长型思维的人呢？是的，小B。\u003c/p>\u003cp>与成长型思维相对的是固定型思维，就像小A，固定型思维的人面对挑战时，他会避免挑战，他害怕失败，失败对于他来说是一辈子的事情。\u003c/p>\u003cp>而成长型思维的人他相信每个人都有无限可能性，他会迎接挑战，现在自己不会某项技能，但不代表永远不会，通过刻意练习都能成为某一领域的高手。\u003c/p>\u003cp>案例2：【引出知识逻辑点2】\u003c/p>\u003cp>面对一道作业中的难题，C同学瞄了两眼，发现题目又长，条件又复杂，直接放弃了，而D同学埋头苦算，尝试各种解法……你觉得哪位是成长型思维模式呢？是的，小D！\u003c/p>\u003cp>固定型思维的人在面对前行的阻碍时，会害怕自己受到伤害，为了保护自己，选择放弃。\u003c/p>\u003cp>而成长型思维的人碰到阻碍时，会坚持不懈，面对挫折，他们认为阻碍也是一次机会，一次学习成长的机会。\u003c/p>\u003cp>案例3：【引出知识逻辑点3】\u003c/p>\u003cp>E君和F君都在拆书帮打怪升级中，E君不能接受也不愿意面对师父对预备表的各种挑剔，各种技能点不达标的批评，认为这是“鸡蛋里挑骨头”，F君很期待师父的批评指正，因为师父让他看到自己还能做得更好的地方，他会很兴奋地去接受建议并且修改。\u003c/p>\u003cp>你们觉得哪位是成长型思维模式呢？是的，E君。\u003c/p>\u003cp>固定型思维的人在面对批评的时候，会直接忽视有用的负面反馈信息。\u003c/p>\u003cp>而成长型思维模式的人会从批评中学习到新知。\u003c/p>\u003cp>【引出行动建议】其实每个人的思维模式都是固定型和成长型思维模式的混合物，那当我们出现固定型思维模式时，怎么做可以将其转变呢？\u003c/p>\u003cp>1、 接受：固定型思维的产生是为了保护自己，让我们感到安全，请接受自己的固定型思维；\u003c/p>\u003cp>2、 观察：观察自己固定型思维模式产生的原因，是如何影响自己的想法和行为；\u003c/p>\u003cp>3、 命名：给这个固定型思维模式取个名字，像对待一个朋友一样；\u003c/p>\u003cp>4、 教育：用成长型思维教育他，并邀请他与你一起踏上成长的旅程。\u003c/p>\u003cp>【引出适用边界】无论你已为人父母，还是一名为自己奋斗的青年，无论你是一名公司管理人员还是普通老师教练，当你意识到自己或者亲人朋友面对新的挑战、遇到阻碍和挫折，或者他人的批评建议时，那个固定型思维模式又出来了，都可以运用这四步法帮助自己、帮助别人转变思维模式，积极面对这些。 \u003c/p>\u003cp>这让我想到刚加入拆书帮时，看到前辈们拆书时逻辑缜密，条理清晰的说辞，我觉得自己不擅长公众讲话，二级、三级拆书家离我还太遥远，都不敢开始。这时我意识到自己的固定型思维模式又出现了，于是我运用了这四步法让自己走出来，完成了自己都觉得不可能完成的事情，通过了二级拆书家的评定。\u003c/p>\u003cp>1、 接受：我的固定型思维模式是那些优秀的拆书家天生就是逻辑清晰、善于公众讲话的人，而我不是这样的人，也很难成为这样的人。\u003c/p>\u003cp>2、 观察：我的固定型思维模式产生的原因是之前没做过，对自己的不自信，造成我想选择逃避。\u003c/p>\u003cp>3、 命名：给这个固定型思维模式取了个名字，叫“小不点”。\u003c/p>\u003cp>4、 教育：小不点小不点，你知道吗？其实那些优秀的拆书家他们曾经也是从磕磕巴巴开始，不断练习才能达到现在这种水平，如果我愿意花些时间来刻意训练，也会取得进步的。\u003c/p>","interaction":"\u003cp>【A2催化应用】\u003cem>（技能点要求：&nbsp; 环节指令清晰，学习者可以根据指令，设计出一个包含人物角色、有起因经过结果、有对话的故事）\u003c/em>\u003c/p>\u003cp>在即将到来的春节假期中，你将会在生活、学习、孩子、亲人等各个方面，尤其在面对挑战、障碍、批评时，感受到固定型思维模式的产生和存在，编一个可能出现的情景剧，以人物对话为主，包括时间、地点、人物、事件的起因、经过和结果。注意，在这个剧本中，你将运用今天学到的四个步骤，去转变思维模式，让剧本中的人物，敢于面对挑战，或克服眼前的障碍或坦然面对批评。大家在学员用表上写下剧本的要点就好，独立编写，然后小组互相分享，最后我会找1-2位小伙伴来分享下你们的剧本。\u003c/p>\u003cp>【学习者分享】\u003c/p>\u003cp>森森（大四学生，在保险公司实习）\u003c/p>\u003cp>时间：后天\u003c/p>\u003cp>地点：在一位女士的家\u003c/p>\u003cp>人物：这位女士和森森\u003c/p>\u003cp>事情起因：这位女士邀请森森帮她规划一个保险配置，可是聊着聊着，却一直没有成交。\u003c/p>\u003cp>事情经过：这时候森森内心当中可能会有些自我攻击和自我谴责，是不是森森还太年轻了，销售的各方面技巧不够，无法打动人，这时候森森马上意识到自己陷入“固定型思维模式”中，这个时候需要让自己的思维模式加以转换，否则难以取得进展。\u003c/p>\u003cp>森森与自己内心的对白：\u003c/p>\u003cp>森森：森森你现在状况确实就是这样的，没有办法一次性很成功地打动到对方。\u003c/p>\u003cp>内心：是的，我接受了自己的固定型思维模式，请观察这种思维模式产生的原因。\u003c/p>\u003cp>森森：观察下自己，也许森森见的客户还不够多，这方面的技能还不够熟练。\u003c/p>\u003cp>内心：给你的固定型思维模式取个名字。\u003c/p>\u003cp>森森：我把我这种固定型思维模式叫“小森森”。\u003c/p>\u003cp>内心：你想跟小森森说点什么？\u003c/p>\u003cp>森森：小森森，我邀请你与我携起手来勇敢地向前走，哪块有问题我们回去就沟通哪块。\u003c/p>\u003cp>事情结果：我的思维模式得到了转变，重新获得正能量。\u003c/p>\u003cp>这样的一个过程就是将我原先自惜自爱的小森森能够把他转变成成长型思维模式大森森的一个过程。\u003c/p>\u003cp>【结语】谢谢森森给我们的分享，非常精彩！有人问我，你最希望你的孩子未来具备什么品质？我的回答是“成长型思维模式”，因为我相信具备成长型思维模式的人，他永远能找到属于自己的一片天地，并积极面对一切。\u003c/p>\u003cp>通过今天我的拆书分享，希望能对大家在前行的路上有所启发，谢谢大家的积极参与。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1548630228000,"updated_at":1549294451000,"ria":true},{"id":6699,"topic":"走向成长性思维","learn_goal":"学习使用成长型思维，四步落地，拥有更积极状态、更丰富的生活","remark":"当我们遇到困难或情绪消极时，改用成长型思维看待问题，用“通往成长型思维模式的四个步骤”落地，就会呈现不一样的生活，成为更有勇气和更开朗的人","level":"TF3-2","duration":25,"status":29,"type":0,"chaishujia":{"username":"龚婷","city":"南昌"},"club":{"name":"南昌滕王阁分舵","city":"南昌"},"prologue":"【学习目标】当我们遇到困难，或者情绪消极时，改用成长型思维看待问题，用“通往成长型思维模式的4步骤”具体落地，拥有不同以往的生活----更加丰富的生活，成为更积极，更有勇气，更加开明的人。","ratings_count":1,"texts":[{"id":10044,"quote":"\u003cp>【图书介绍】\u003c/p>\u003cp>（事件）：寒门难出贵子，一考定终身，我是学英语的，我毕业会更倾向于找英语专业的工作。而不会去电信公司，制药公司，更不会找会计，出纳的工作。\u003c/p>\u003cp>（提问）：这种想法挺普遍的，甚至我们有时候在别的事情上也常常会有类似的想法。但是所想的事情都能如你所愿吗？没有实现，你又是怎么做的呢？实现了，你又接着做了什么呢？（和学员互动，请学员回答）\u003c/p>\u003cp>（固定型思维模式）影响：刚刚讲的想法的背后关注更多的是我要成功，而并不是我要成长。这种思维我们叫固定型思维，妨碍了我们的发展和改变。\u003c/p>\u003cp>（解决）：本书《终身成长》，介绍的是另外一个相反的思维--成长型思维。成长型思维是改变的起点，专注于个人的学习和提高。\u003c/p>\u003cp>【A1请大家自测】\u003c/p>\u003cp>你是成长型思维的思考者吗？现在给大家发放一个自测题，请大家根据自己的实际情况填写，6分表示完全符合，1分表示不符合。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>《思维测试》检测\u003c/p>\u003cp>请大家根据自己的实际情况填写，6分表示完全符合，1分表示不符合。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>我可以学习新事物，但我的智力水平是很难改变的。\u003c/p>\u003c/td>\u003ctd>\u003cp>1 &nbsp;2 &nbsp;3 &nbsp;4 &nbsp;5 &nbsp;6 \u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>我比较讨厌微商，不管卖的是什么，我总是很难相信产品过硬。也不会去真正研究产品，因为产品看一眼就知道没他们说的那么传奇。\u003c/p>\u003c/td>\u003ctd>\u003cp>1 &nbsp;2 &nbsp;3 &nbsp;4 &nbsp;5 &nbsp;6 \u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>我可以换一种方式做事，但决定我自身的最重要的特质并不会真正改变。\u003c/p>\u003c/td>\u003ctd>\u003cp>1 &nbsp;2 &nbsp;3 &nbsp;4 &nbsp;5 &nbsp;6 \u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>我在求学阶段，喜欢一门课程的程度更多取决于我喜不喜欢这门课的任课老师。\u003c/p>\u003c/td>\u003ctd>\u003cp>1 &nbsp;2 &nbsp;3 &nbsp;4 &nbsp;5 &nbsp;6 \u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>如果有件事情对我来说易如反掌，却让其他人无从下手的时候，我觉得我自己很聪明。\u003c/p>\u003c/td>\u003ctd>\u003cp>1 &nbsp;2 &nbsp;3 &nbsp;4 &nbsp;5 &nbsp;6 \u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>总分： _______ 分。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>【I解释自测】\u003c/p>\u003cp>这个测试是测试自己是成长型思维还是固定型思维。得分越高，说明你是个固定型思维模式的思考者。得分越低说明你是个成长型思维思考的人。固定思维模式更关心在乎的是别人如何看待自己，也就是我是什么；而成长型思维模式让你更关心能否提高自己和怎么提高自己，也就是我还能成为什么。\u003c/p>\u003cp>【测试题的适用边界】测试的分数高低不能说明思维的好坏，只是不同。也许你在学习思考方面是个固定思维者，但是你在艺术思维，语言思维，逻辑思维方面可能是个成长型思维思考者，人们在不同的场景中，思考方式是不一样的。\u003c/p>\u003cp>【测试题适用边界的举例】比如，我妈做这个测试卷的得分是27，测试结果证明她在思考分析方面是个固定思维思考者，这也与她一直认为学语言必须从背单词开始的表象一致。但是她在沟通方面却没有固定的套路，见人说人话，哄得谁都开心，套路一套套。她在沟通方面反而是个成长型思维。\u003c/p>\u003cp>【R阅读原书拆页】\u003c/p>","explains":"\u003cp>【I拆书家讲解引导】\u003c/p>\u003cp>第一步，接受。接受你的固定型思维。固定型思维有哪些，比如批评。（观察技能点6：【I】环节拆书家有进行简短提问或互动，并能精确控场）拆书家：“学员何晓华，能请你举出1-2个固定思维吗？”学员何晓华：“挫折，阻碍，偏见，冥顽不灵，固步自封。”拆书家：“非常好，我们来看一张更加详细的图。左边是固定思维，右边是成长型思维。”我请面对面而坐的小伙伴，一一对应念下固定型思维和成长型思维。（观察技能点6：【I】环节拆书家有进行简短提问或互动，并能精确控场）\u003c/p>\u003cp>第二步，观察。察觉是什么事件会激发你的固定型思维。那个固定性思维模式会在什么时候回来？可能是你面对一个巨大的挑战，可能是遇到比自己更强的人改过了自己的锋芒的时候，当我犯懒癌的时候，可能是你为某事奋斗但是进入死胡同的时候。\u003c/p>\u003cp>第三步，命名。让我们给固定型思维模式起个名字。我们为什么要命名？在心理学上，这个叫“情绪画像”。把抽象的情绪变成具体的物体，能够让自己，听众更加直观视觉化你的情绪，以后你们去做心理咨询，和陌生人交流，用情绪画像的方法，能够快速让别人感受到你的情绪，甚至能快速给你共情。\u003c/p>\u003cp>第四步，教育。你现在知道了触发固定型思维的诱因，并痛苦的了解了自己的固定性思维模式人格对自己造成的影响。他有了自己的名字。那么现在还需要做什么呢？教育他！让他和你一起走过这段旅程。\u003c/p>\u003cp>【举例1】当销售在卖产品遇到困难的时候，买家没有诚意，一直讨价还价要最低价，这种情形下，我就会变得对客户（我的上帝）非常挑剔，我开始变得有攻击性，并自我保护，而不是去理解客户真正需要什么。作为销售，我要面对形形色色的客户，让客户改变是很困难的，只能我改变，我应该怎么改变？（第一步接受）我的固定思维是--“顾客在刁难我，就是不想诚心买在这里左右挑剔。”我允许我有这样的固定思维存在。（第二步观察，是什么时候这种固定思维会出来）当我真心对他人，而他人不领情甚至把我放在对立面时，也就是像图中所说的，当我遇到挑战时，我的固定思维就会出现。（第三步命名）我叫他容嬷嬷。容嬷嬷的形象多么的可恶，我不想成为容嬷嬷的受害者。（第四步教育）教育这个“容嬷嬷”（固定思维），我不会被你打败。首先，我要再次向客户表达我真诚地意见，其次，我要仔细聆听客户的潜在台词，他们到底需要什么？最后，试着用比较法把其他产品和我作对比，告诉客户，这个产品的优势。\u003c/p>\u003cp>【适用边界】人们在不同的领域展现出不同的思维模式。我们每个人都是成长型和固定型的混合物，正常的人类都这样。\u003c/p>\u003cp>【预防异议】改用成长型思维看待问题就能解决我所有的问题吗？不能。但是我们知道，因为这种思维模式而拥有了不同以往的生活--更加丰富的生活。因为这种思维模式，成为更加积极，更有勇气，更加开明的人。\u003c/p>","interaction":"\u003cp>【A3促动参与】\u003c/p>\u003cp>拆书家提问设计（逐字稿）：（观察技能点8：给出了一个预先设计好的非常具体，确定的场景，学习者可在此场景中演练或讨论或应用新技能，邀请一组当众表演或角色扮演）\u003c/p>\u003cp>现在，该由你来决定是否该做出改变了。你去上一门对你来说很重要的课，而且你非常喜欢这门课。手机里收到了绩效奖金，只有200元，绩效奖金你的全部发放是1000元。200元连出门加个油都不止这个价格。你非常失望，等到晚上准备回家的时候，你发现自己的车上贴了一张违章停车的罚单。你感到非常泄愤，打电话想给最好的朋友倾诉，但是却没有打通。你认为今天自己倒霉透了，请你用通往成长性思维模式的4步骤，来让自己走出困境。\u003c/p>\u003cp>5分钟之后，我请同学上台来分享下。\u003c/p>\u003cp>【学员现场展示】会员何晓华分享：（观察技能点9：学习者可以根据拆书家设定的案例场景，进行小组讨论，应用知识点并形成一个解决方案，或是应用知识点进行组内扮演）\u003c/p>\u003cp>第一步接受，人生不如意之事十有八九，谁碰到这种情况，都会有情绪，我当时认为自己就是倒霉，却没有想到一念天堂一念地狱，我可以改变想法来改变自己的处境。\u003c/p>\u003cp>第二步观察，当我在遇到挑战，挫折，接踵而至的失败时，我的固定思维会出来。我很多时候是自我保护，想把自己躲起来藏起来的，不想面对和解决，更别说主动。\u003c/p>\u003cp>第三步命名，我给我自己的情绪命名为冰山。\u003c/p>\u003cp>第四步教育，我要把这座冰山融化，首先，我要有热情，我要积极的去看待每一件事情，我会先找人事，要下我的绩效考核表格，看下我的绩效是哪里分数差了。其次，自认倒霉，不能为了省10元钱的停车费，侥幸心理，就停路面，下次还是规规矩矩停车。最后，手机没有电，这是情绪的累计爆发点，哪怕这通电话接通了，也不能怪朋友，说不定有人找自己也没找着正在发火呢，而是赶紧回家，洗洗睡了，结束这一天，。明天还有绩效，交款违章这么多事情做呢。\u003c/p>\u003cp>【A2催化应用】\u003c/p>\u003cp>拆书家提问设计（逐字稿）：（观察技能点10：学习者根据指令，写出自己一个未来具体任务要做的应用，比如：某个特定任务，和人分享，事后复盘，找人陪练）\u003c/p>\u003cp>【和人分享】大家演练得非常棒！所以接下来给大家布置一个作业，请大家在接下来的一周时间，把通往成长型思维模式的4步骤在这两天内和一位亲友/同事分享今天所学的知识。\u003c/p>\u003cp>那么，有哪些要点可以分享呢？比如，可以聊聊4个步骤是什么；也可以说说它可以帮助我们解决什么样的问题等等。你分享的要点越多，你措辞表达能力也会提高的越多，所以请大家在下面空白处里写下自己的分享计划，写好后拍照分享到我们今天的群里，方便我收集。也可以下次拆书课时把分享卡带来，换取礼物。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>\u003cstrong>&nbsp;分享行动卡\u003c/strong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>“\u003c/strong>通往成长性思维模式\u003cstrong>”\u003c/strong>\u003cstrong>4\u003c/strong>\u003cstrong>个步骤\u003c/strong>\u003cstrong>“\u003c/strong>\u003cstrong>接受\u003c/strong>\u003cstrong>”；“\u003c/strong>\u003cstrong>观察\u003c/strong>\u003cstrong>”；“\u003c/strong>\u003cstrong>命名\u003c/strong>\u003cstrong>”\u003c/strong>\u003cstrong>；“教育”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>分享日期： \u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>分享内容： \u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>分享对象： \u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>【结束语】走向成长性思维模式需要一个过程。希望大家能够回家坚持练习。改变也许艰难，但我从未见谁说过不值得。\u003c/p>\u003cp>好的，我们的拆书就到这里请大家用便签写下想对我说的话，谢谢大家今天的参与。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1544164189000,"updated_at":1544164189000,"ria":true},{"id":6208,"topic":"运用成长型思维不再执着于眼前的成败，从学习和成长中获得快乐","learn_goal":"站在新的角度看待问题，从学习和成长中获得快乐","remark":"","level":"TF3-1","duration":25,"status":30,"type":0,"chaishujia":{"username":"张琢","city":"武汉"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"大家好，我是张琢，一只水瓶座怪咖，任职于一家大型医药流通企业，从事HR的职业。我很喜欢我的工作，也很喜欢拆书，今天为大家带来3-1的拆页。\r\n【场景】\r\n大家可否还记得这样的场景：不论是小时候还是现在，参加考试的时候总希望自己能够拿到高分，如果成绩不理想，就会觉得是自己根本就不擅长这类型的知识，在这方面完全没有天分？\r\n【提问】\r\n每次遇到这样的事情，大家最后是怎么处理的呢？是否真觉得自己不行，放弃尝试了呢?\r\n【影响】\r\n这种想法真的很糟糕，不仅会对自己产生怀疑，对很多事情随随便便就放弃，还会导致与很多好的机会失之交臂。\r\n【解决】\r\n《终身成长》这本书就能扭转这种思维模式，帮助大家学会站在新的角度看待问题，不再执着于眼前的成败，从学习和成长中获得快乐。","ratings_count":1,"texts":[{"id":9488,"quote":"\u003cp>\u003cstrong>【\u003c/strong>学习目标】\u003c/p>\u003cp>在跟随我完成本次RIA现场学习之后，学习者能够在今后使用成长型思维模式对待一切事物，保持积极的心态去面对并解决问题。\u003c/p>\u003cp>R：\u003c/p>\u003cp>二种思维模式决定成功与失败的意义：\u003c/p>\u003cp>研究成果1：成长型思维认为成功源于尽自己最大的努力做事，来源于学习和自我提高。而对于那些固定型思维模式者来说，成功就是确立自己的优越性，目的就是这么单纯并简单。要成为了不起的大人物，比那些无名小卒更有价值的人。在固定思维模式里，努力没什么好骄傲的，努力会让你对自己的能力产生怀疑。\u003c/p>\u003cp>研究成果2：成长型思维模式者认为挫折可以给人动力，挫折可以告诉我们更多，它是一记警钟。而固定型思维模式中，挫折会给你贴上标签。\u003c/p>\u003cp>研究成果3：成长型思维模式者掌控者自己走向成功以及维持成功的过程。在固定型思维模式中，你无法掌控你的能力和动力。你指望你的天赋带你过关斩将，当天赋做不到的时候，好吧，你自己又能做些什么呢？你不是一个可以持续发展的人，你已经定型了，已经定型的人必须通过抱怨和责怪别人来保护他们自己。除了掌握自己的人生以外，他们什么都可以做。\u003c/p>\u003cp>有段时间，一位老师让她教的小学生们谈论自己固定型思维模式的诱因，并给他们的固定型思维模式思维模式人格起名字。班里的一个男孩不愿意去做这件事，其他很多事情他也一样不配合。不管老师怎么温柔的鼓励他，很多事情他都不愿意做。他坐在那里，一连好几个星期不说话，而其他同学则在忙着谈论或者画下他们的固定型思维模式人格，有胆小的Sally，懒惰的Larry、焦虑的Andy或者无助的Hanna。老师告诉这名学生，如果他准备好了，老师会在身边听他讲。有一天，突然，这个男孩说：“充满负能量的Dan。”“什么？”老师问。“充满负能量的Dan，”她重复道，“我做什么事都会错。我什么都做不对。所以所有人都对我不好。”每当他做作业的时候，充满负能量的Dan都会对他大喊，让他无法继续。这位老师立即走到他身边，帮助他和Dan一起学习，最终Dan的态度软了下来，给了他一些空间，让他去做他的作业。从此以后，他进步的非常快。\u003c/p>","explains":"\u003cp>【强化讲解概念】\u003c/p>\u003cp>在拆页中，作者给出了两个对立的概念，分别是“成长型思维模式”和“固定型思维模式”，我们来看看两者的区别，顾名思义，“成长型思维”是教我们用动态可持续的眼光去看待事物，而“固定型思维模式”则是让我们原地踏步、固地自封。\u003c/p>\u003cp>在这个拆页中，我们看到了成长性思维模式的定义和重要性，什么是成长型思维模式呢？\u003c/p>\u003cp>我们来看看下面的例子，小明和小张在一次期中考试中分别考了95分和92分，在班级里排中等水平，他们对考试结果分别有些截然不同的看法。\u003c/p>\u003cp>我们来看一下小明是怎么想的：\u003c/p>\u003cp>1、 即使我这么努力学习，还是只有95分，努力是白费的。——这是成长型思维模式吗？不是，因为成长型思维模式对努力的看法是熟能生巧，通过努力才能取得成功。\u003c/p>\u003cp>2、 我不想在看书考试了，让我逃避一下吧。——这是成长型思维模式吗？也不是，因为成长型思维模式对待阻碍的态度是积极正面的，坚持不懈不会轻易放弃。\u003c/p>\u003cp>3、 我的脑子太笨了，我没有学习的天赋，我是不可能取得成功的。——这是成长型思维模式吗？也不是，因为成长型思维模式对天赋的看法是：认为智力是可以提高的，不认为自己可以被定性。\u003c/p>\u003cp>我们再来看看小张是怎么想的：\u003c/p>\u003cp>1、 我要多练习，下次我会考得更高！——成长型思维模式，对努力的看法是：肯定自己的努力，通过练习，下次会考得更高；\u003c/p>\u003cp>2、 今天回去以后我要好好的思考为什么我这次没考好，一定不会放弃！——成长型思维模式，对阻碍的态度是：对阻碍态度积极正面，遇到挫折勇敢解决；\u003c/p>\u003cp>3、 可能我并不是很有天赋，但是不代表我不能把学习搞上去，我总有进步的机会！——成长型思维模式，对天赋的看法是：认为智力是可以提高的，总有进步的机会。\u003c/p>\u003cp>【步骤】\u003c/p>\u003cp>那么如何去培养成长型思维模式，来学会终身成长呢？需要做到以下几点：\u003c/p>\u003cp>1、 接受：承认并接纳自己的固定型思维模式（每个人的思维模式都是固定和成长的混合物）；\u003c/p>\u003cp>2、 观察：明确是什么激发了你的固定思维模式，它在什么时候存在?\u003c/p>\u003cp>3、命名：给这个固定型思维模式人格取个名字；\u003c/p>\u003cp>4、教育：给这个固定型思维人格上课，给出鼓励性的行动建议。\u003c/p>\u003cp>【反例】\u003c/p>\u003cp>17年去我们企业大学参加全国讲师的选拔，一段15分钟的PPT呈现让我战战兢兢，最后没有通过，我认为自己并不适合做培训，没有天赋，不可能成为一个好的讲师。\u003c/p>\u003cp>【正例】\u003c/p>\u003cp>接触了终身成长这本书以后，我运用这四个步骤去说服我自己：\u003c/p>\u003cp>1、 接受：接受我的脆弱，我接受认为自己不行的固定型思维模式，人都有不自信的时候；\u003c/p>\u003cp>2、 观察：当我在台上胆怯的时候，固定型思维模式就会出来；\u003c/p>\u003cp>3、 命名：给他取个名字叫“胆小鬼”；\u003c/p>\u003cp>4、 教育：我要跟自己说感到胆怯并不代表我天生不适合做讲师，失败了也只是一时的，我可以通过多去讲课训练自己，一定可以克服恐惧感，最终成为一个好讲师。\u003c/p>\u003cp>【预防性讲解】\u003c/p>\u003cp>是不是拥有了成长型思维，我就可以解决所有事情呢？\u003c/p>\u003cp>成长型思维并不是成功学，拥有这个思维只是让我们遇事变得更加积极，而不代表我们会战无不胜，不能强行将违背客观规律的事情做成功。\u003c/p>","interaction":"\u003cp>A2：\u003c/p>\u003cp>接下来一周内你会在哪些场景中运用到今天的知识点，将自己的固定型思维扭转为成长型思维呢？\u003c/p>\u003cp>请大家编写一段符合主题的小故事，几百字即可，设计出人物、情节变化（包括起因、经过、结果）和当时双方的对话动作等，简单写出摘要即可，时间4分钟，然后我们请一位小伙伴给我们讲讲他的剧本。\u003c/p>\u003cp>俊飞分享：\u003c/p>\u003cp>时间：下一周某天\u003c/p>\u003cp>地点：办公室\u003c/p>\u003cp>人物：我和领导\u003c/p>\u003cp>起因：工作上因循守旧，不喜欢太有挑战性的任务，但是领导总爱安排有挑战性的任务给我，他觉得自己无法完成，这份工作自己做不来。\u003c/p>\u003cp>经过：\u003c/p>\u003cp>运用今天学到的方法准备这么处理：\u003c/p>\u003cp>接受：接受自己害怕挑战和改变，我也不是个完美的人；\u003c/p>\u003cp>观察：事情太多应付不来的时候我就会对自己产生质疑；\u003c/p>\u003cp>命名：给他起名字“得过且过的施俊”；\u003c/p>\u003cp>教育：告诉自己要多跟领导沟通，在工作中加快效率，相信自己可以正面挑战，把工作做好！\u003c/p>\u003cp>结果：\u003c/p>\u003cp>放下心中对自己的质疑，勇敢的去跟领导沟通，解决问题！\u003c/p>\u003cp>总结：成长性思维模式帮助我们终身成长、不断进步，希望小伙伴们通过今天的学习，拆掉思维里的墙，运用更积极的眼光看待一切，谢谢！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1539390512000,"updated_at":1539390512000,"ria":true},{"id":5841,"topic":"转变思维，改变人生","learn_goal":"学会用思维模式识别表识别思维模式","remark":"楚霸王自刎乌江边，丧失了一切可能；魏璎珞“虽千万人唾面，也能唾面自干”实现华丽转变。是能力？还是性别？都不是，是思维模式！","level":"TF3-2","duration":30,"status":30,"type":0,"chaishujia":{"username":"宋福珍（豆豆）","city":"郑州"},"club":{"name":"郑州轩辕分舵","city":"郑州"},"prologue":"大家好，我是豆豆，致力于终身学习的二级拆书家，我们按照之前的分组继续学习。【分组】【事件】你报了一门你认为很重要的课程，你很喜欢这门课，每周都很用心的学习。老师今天公布了测试成绩，你只得到中等。你很失望，带着失落下课的准备回家的时候，发现自己的车上被贴了一张罚单。你感到很泄气，打电话给最好的朋友想要倾诉，但半天都没有打通。\r\n【提问】你会怎么想？会有什么样的心情？你接下来会怎么做？\r\n【影响】有人会给自己贴上一个标签，我真是太倒霉了，这个世界都跟我过不去。产生深深地无力感和失败感，感觉这门课自己没劲儿学了，反正学不好，干脆放弃了；而有人会认为不就是一个分数、一张罚单和一个没接通的电话，没啥大不了的，这次没考好，正好和老师交流交流，看看究竟哪里需要提升。朋友没接电话，也许是朋友有事儿呢，我的弄清楚他是否需要我帮忙呢！同样的事情，不同的思维模式，决定了一个人的想法和行为，也决定了人生的成败！\r\n【解决】《终身成长》——重新定义成功的思维模式这本书，分析了固定型思维模式和成长型思维模式在多个方面的差异，并且给出了具体的转换思维模式的办法，帮助大家讲固定型思维转换为成长型思维。","ratings_count":1,"texts":[{"id":9054,"quote":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>\u003cem>A1量表自测拆书技能点观察\u003c/em>\u003c/strong>\u003cstrong>\u003cem>7\u003c/em>\u003c/strong>\u003cstrong>\u003cem>：【\u003c/em>\u003c/strong>\u003cstrong>\u003cem>A1\u003c/em>\u003c/strong>\u003cstrong>\u003cem>】环节的量表题清晰设置了多个选项，学习者通过自测可以了解在某一种情况下自己的表现。\u003c/em>\u003c/strong>\u003c/p>\u003cp>拆书家提问设计（逐字稿）\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>为了帮助大家了解一下自己的思维模式，我们先来用1分钟的时间来做一个自测题，请仔细阅读题目，根据自己的情况为自己打分，1分非常不符合，6分为非常符合，每道题都打分后计算总分。\u003cbr>\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>思维模式自测题目\u003c/td>\u003c/tr>\u003ctr>\u003ctd>题目\u003c/td>\u003ctd>1分非常不符合，6分非常符合\u003c/td>\u003c/tr>\u003ctr>\u003ctd>1、作为新人我知道对公司的各项制度和流程都不熟悉，不能按照自己以前的想法办事儿，所以遇见不懂就去向前辈请教，喜欢死磕到底，直到自己能够完全握。\u003c/td>\u003ctd>1\u003c/td>\u003ctd>2\u003c/td>\u003ctd>3\u003c/td>\u003ctd>4\u003c/td>\u003ctd>5\u003c/td>\u003ctd>6\u003c/td>\u003c/tr>\u003ctr>\u003ctd>2、学开车的时候，教练经常吵我，每次我都能从他的大吼中感受到他的着急和对我的关心，一想到他是害怕我学不好出事故，我就能认真的揣摩他的指令，找到改善之处。\u003c/td>\u003ctd>1\u003c/td>\u003ctd>2\u003c/td>\u003ctd>3\u003c/td>\u003ctd>4\u003c/td>\u003ctd>5\u003c/td>\u003ctd>6\u003c/td>\u003c/tr>\u003ctr>\u003ctd>3、孩子考试没有考好，我会认真的陪伴孩子检查错误，在完成错题订正后给孩子颁发失败勋章，庆祝他又一次从失败中学到了经验。\u003c/td>\u003ctd>1\u003c/td>\u003ctd>2\u003c/td>\u003ctd>3\u003c/td>\u003ctd>4\u003c/td>\u003ctd>5\u003c/td>\u003ctd>6\u003c/td>\u003c/tr>\u003ctr>\u003ctd>4、看到公司的比赛通知我就踊跃报名了，我不担心比赛结果，我更看中比赛的方法是先培训再比赛，培训过程中能够收获新的知识，结果只是对自己培训技能的一次检验，过程比结果更重要。\u003c/td>\u003ctd>1\u003c/td>\u003ctd>2\u003c/td>\u003ctd>3\u003c/td>\u003ctd>4\u003c/td>\u003ctd>5\u003c/td>\u003ctd>6\u003c/td>\u003c/tr>\u003ctr>\u003ctd>5、我喜欢与比我优秀的同事打交道，向他们请教成功的秘诀，并主动运用到自己的工作和生活中。\u003c/td>\u003ctd>1\u003c/td>\u003ctd>2\u003c/td>\u003ctd>3\u003c/td>\u003ctd>4\u003c/td>\u003ctd>5\u003c/td>\u003ctd>6\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>\u003cem>I【\u003c/em>\u003c/strong>\u003cstrong>\u003cem>1\u003c/em>\u003c/strong>\u003cstrong>\u003cem>分钟解释一下自测的意义】\u003c/em>\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>这5道题是帮大家测一下思维模式，得分在20分以上的小伙伴举手，恭喜你，明你的思维习惯属于成长型思维，不怕失败，敢闯敢拼，享受成长本身带来的喜悦，\u003cstrong>刚刚有许多小伙伴都是终身学习者\u003c/strong>，记得待会儿要跟我们分享你的经验哦。得分在10-20分的小伙伴，举手，谢谢，这说明你可能正在养成成长型思维，今天的课程将帮助你巩固现有成果，更加清晰自己的思维模式。而得分在10一下的小伙伴，没关系，结果只是说明你现在的思维习惯偏向固定型思维，今天的课程是专门为你打造的。\u003c/p>\u003cp>【学习目标】\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>\u003cem>拆书技能点观察\u003c/em>\u003c/strong>\u003cstrong>\u003cem>4\u003c/em>\u003c/strong>\u003cstrong>\u003cem>：学习目标中包含学习者要完成行为的具体内容和完成程度，现场学习清晰体现了该学习目标。\u003c/em>\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>通过今天的学习，当我们在面对挑战犹豫纠结或面对失败想要放弃时，能够【澄清】运用思维模式识别表，识别【行为】自己的限制性想法，分析【行为】想法对自己产生的具体影响，反驳其中的（一项）限制性想法。【界定】\u003c/p>\u003cp>【R阅读原文】\u003cbr>\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>《终身成长》p308\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>请大家用3分钟时间阅读原文，阅读完毕后举手示意我。因为是图片方式，请大家在阅读的时候，画出重点和关键词。\u003c/p>","explains":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>\u003cem>拆书技能点观察\u003c/em>\u003c/strong>\u003cstrong>\u003cem>6\u003c/em>\u003c/strong>\u003cstrong>\u003cem>：【\u003c/em>\u003c/strong>\u003cstrong>\u003cem>I\u003c/em>\u003c/strong>\u003cstrong>\u003cem>】环节中拆书家有进行简短互动，并能精确控场。\u003c/em>\u003c/strong>\u003cstrong>【互动】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>[提问]\u003c/strong>在这个图片中，提到了两种思维模式，分别是？（固定性思维模式和成长型思维模式）\u003c/p>\u003cp>\u003cstrong>[提问]\u003c/strong>固定性思维和成长型思维的关键词是？（一成不变）（发展）对，固定性思维是一种用一成不变的观点看问题的僵化思维，这种思维模式以结果论成败，把个人的价值等同于事情本身，容易导致人们因为害怕失败而不敢尝试；而成长型思维是一种用发展的眼光看问题的思维模式，认为经过努力和练习，能力会得到充分的发展和提高，更加注重过程和自我提升。所以拥有成长型思维的人往往会积极主动面对挑战，面对失败能够坚持不懈，可以说拥有成长型思维的人，就拥有了把失败转变为财富的魔法。\u003c/p>\u003cp>[提问]ppt里面有几种说法，请大家选出其中的固定型思维模式和成长型思维模式分别是哪些呢？（12678是固定型思维3459是成长型思维）\u003c/p>\u003cp>看来大家对这两种思维模式掌握的非常好了，我有个好奇，大家都说自己是成长型思维，为什么面对孩子的各种行为我们还会憋气窝火呢？这是因为有时候，从知道到做到还有很大一段距离，我们认为自己是成长型思维，实际上却是固定型思维模式，事实上发现自己的思维模式并不是一件容易的事情，而觉察记录问题，才有可能解决问题，所谓觉察是改变的开始。那怎么样识别自己的思维模式是固定型还是成长型呢？具体就是观察工作和生活中那些让我们不痛快让我们难受让我们纠结的时候。痛苦纠结的背后，往往就隐藏着我们的固定性思维。\u003c/p>\u003cp>【行动步骤】当我们因为失败而痛苦，面对挑战而犹豫的时候，为了帮助大家识别自己的俄思维模式，我准备了一个思维模式识别表，四个栏目，1、找出诱因：就是去弄明白是什么引发了固定型思维模式。是害怕失败？担心批评？还是面对没经历过的事情所带来的挑战？或者是他人的反对，总之，一定要找到这个导致自己痛苦，纠结的具体的导火索。\u003c/p>\u003cp>第二栏，倾听声音，即找到原因后，给这原因起个形象的名字，试着把自己的固定化思维想象成一个“人”：比如发现自己是因为害怕失败而陷入了固定型思维模式，就可以给这种状态时候的固定思维起个名字，比如叫做纸老虎，然后一条一条的记录下来“纸老虎”出现的时候，都会说些什么。\u003c/p>\u003cp>第三栏，分析影响。比如记录下来“纸老虎”的说法后，一个一个的分析这些想法对自己造成了什么样的影响，当自己听到看到这些说法的时候，是什么心情，产生了什么样的行为，是有助于问题的解决呢，还是掩盖了问题，或者制造了更多的纠结、痛苦。\u003c/p>\u003cp>经过一段时间的训练之后，心有余力的小伙伴还可以试试第四步，跟自己的固定型思维对话，教育引导他陪你一起走找到解决办法，先接受人之常情，拥有想法正常，再来逐条进行反驳。\u003c/p>\u003cp>举个例子：\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>前段时间我们公司培训的时候，我作为复训学员，很想回答问题却不敢。这时候运用三个步骤，第一步，找到诱因：我发现是害怕失败引发了我的固定型思维，害怕失败让我犹豫不决。第二步，给自己的状态起了个名字叫做死要面子，我想回答问题的时候，“死要面子”就会在我脑袋里对我说：你看你都是高级内训师了，说错了老师会认为公司就这水平，同学们会认为你水平就这样，多丢人啊！第三步，分析影响，我发现死要面子一说话，我就更不敢尝试了，特别害怕死要面子说的是真的，特别害怕说错了别人真的嘲笑自己。大家看这是不是固定性思维模式？回答正确了我才有价值，回答错误了我就没价值了。所以，当时我进行了第四步，跟自己的死要面子对话。死要面子说：回答错了可丢人了。我首先接纳，是啊，谁不想回答正确呢？死要面子不吭声了，我趁热打铁：老师也不是天生就正确啊，我这不是刚开始学习嘛？死要面子：你看你都是高级内训师了！我：高级内训师就不能犯错了吗？谁规定的啊？死要面子无语了。经过自己的一番自我对话，我不那么害怕犯错了，在接下来的一天半的复训中，虽然回答错了好多次，老师的点评反馈让我知道了错在哪里，真正收获到了学习的乐趣。\u003c/p>","interaction":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>【A3】\u003cp>\u003cstrong>\u003cem>拆书技能点观察\u003c/em>\u003c/strong>\u003cstrong>\u003cem>8\u003c/em>\u003c/strong>\u003cstrong>\u003cem>：【\u003c/em>\u003c/strong>\u003cstrong>\u003cem>A3\u003c/em>\u003c/strong>\u003cstrong>\u003cem>】环节给出了一个非常具体、确定的场景，学习者可在此场景中演练或讨论或应用新学技能。\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cem>拆书技能点观察\u003c/em>\u003c/strong>\u003cstrong>\u003cem>9\u003c/em>\u003c/strong>\u003cstrong>\u003cem>：使用【\u003c/em>\u003c/strong>\u003cstrong>\u003cem>A3\u003c/em>\u003c/strong>\u003cstrong>\u003cem>】技能点的环节指令清晰，学习者可以根据拆书家设定的案例场景，进行小组讨论、应用知识点并形成一个解决方案，或是应用知识点进行组内角色扮演。\u003c/em>\u003c/strong>\u003c/p>\u003cp>现在，\u003cstrong>请大家想象一下，你打算去学习英语，已经报了一个培训班。在上课时，你的老师点名请你回答问题\u003c/strong>。\u003c/p>\u003cp>请大家在小组内讨论并记录,\u003cstrong>当你能回答出来问题和回答不出来问题的时候，会有什么样的思维模式，\u003c/strong>具体诱因是什么，你的想法是什么，这些想法对你产生了什么样的影响，你的心情是什么，你会有什么样的行为？写在思维模式识别表里面。已经拥有成长型思维模式的小伙伴，也可以尝试帮助小伙伴进行自我说服。\u003c/p>\u003cp>5分钟小组讨论后，我们将请人分享自己的思维模式识别表。根据现场情况，也可能请两位小伙伴现场用对话的方式，表现出整个过程。\u003c/p>\u003cp>【A3现场记录】：\u003c/p>\u003cp>学习者反馈的思维模式表\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>具体诱因\u003c/td>\u003ctd>形象命名\u003c/td>\u003ctd>具体想法\u003c/td>\u003ctd>分析影响\u003c/td>\u003ctd>说服教育\u003c/td>\u003c/tr>\u003ctr>\u003ctd>老师提出来的问题回答不出来的时候\u003c/td>\u003ctd>没面子\u003c/td>\u003ctd>\u003cp>1、老师故意提问，给难堪\u003c/p>\u003cp>；\u003c/p>\u003cp>2、这点问题都回答不出来，丢人；\u003c/p>\u003c/td>\u003ctd>\u003cp>对抗；\u003c/p>\u003cp>打击自信心\u003c/p>\u003c/td>\u003ctd>\u003cp>老师是想了解自己的能力\u003c/p>\u003cp>回答不出来回去找找原因\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>老师提的问题回答出来了\u003c/td>\u003ctd>嘚瑟\u003c/td>\u003ctd>我回答出来是因为我聪明\u003c/td>\u003ctd>沾沾自喜\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>A2\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>\u003cem>拆书技能点观察\u003c/em>\u003c/strong>\u003cstrong>\u003cem>10\u003c/em>\u003c/strong>\u003cstrong>\u003cem>：【\u003c/em>\u003c/strong>\u003cstrong>\u003cem>A2\u003c/em>\u003c/strong>\u003cstrong>\u003cem>】环节指令清晰，学习者可以根据指令，写出自己未来的一个具体的要做的应用（比如：某个特定任务、和人分享、事后复盘或找人陪练）\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cem>【找人分享】\u003c/em>\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>今天我们一起学习了固定性思维模式和成长型思维模式，并且学习了如何识别自己的固定性思维模式，请大家在接下来的一周内，完成一张思维模式识别表，并将完成的思维模式识别表发送在群里。\u003c/p>\u003cp>【结束语】知不足，然后才能有进步。了解了自己的思维模式，才能找出改善的空间，任何时候，改变都不晚。感谢大家的参与，祝大家都能在今后的生活中，运用成长型思维模式，创造更美好的未来。谢谢大家，我的拆书到此结束。\u003c/p>\u003cp>____________________________________________\u003c/p>\u003cp>学习者作业反馈\u003c/p>\u003cp>文文玫瑰，晚上十一点反馈作业\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1534692671000,"updated_at":1534692671000,"ria":true},{"id":5496,"topic":"如何打破固定型思维，让自己具有成长型思维","learn_goal":"能够识别【行为】固定型思维，通过转变思维的四个步骤【澄清】","remark":"","level":"TF3-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"瞌睡的猫","city":"无锡"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>大家好，我是瞌睡的猫，一名不甘现状、不断尝试、不断挑战的80后宝妈。很高兴今天能跟大家在一起共同交流学习！\r\n今天我们的拆书有一个即兴编剧本的环节。我们先分一下组，这边一组，这边一组。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>通在跟随我完成本次RIA现场学习后，学习者能够\u003cstrong>识别【行为】\u003c/strong>固定型思维，通过转变思维的四个步骤\u003cstrong>【澄清】\u003c/strong>，将固定型思维转变为成长型思维，【界定】。 \u003c/p>\u003cp>\u003cstrong>【图书介绍】\u003c/strong>\u003c/p>\u003cp>【事件场景】前几天给我女儿报名绘画班的时候，老师问她要不要考级，她说不要，我问她为什么的时候，她悄悄告诉我“如果考不过，多丢人啊”，因为害怕丢人，所以她学了绘画好几年都不愿意去考级。\u003c/p>\u003cp>这让我想到上个月我们领导让我的同事小村去参加比赛，他说“我不去，那么多人竞争，去了肯定是当炮灰”，因为结果未知，所以他连参加的欲望都没有。\u003c/p>\u003cp>【提问】我想，大家在工作和生活中肯定也遇到过结果未知或者前途不明的情况，面对这样的情况，大家是怎么处理的呢？是勇敢的接受挑战还是回避以避免失败。\u003c/p>\u003cp>【影响】我发现很多人会采取回避的态度，这是典型的固定型思维。\u003c/p>\u003cp>其实因为害怕失败而不敢去尝试，会让我们错失很多的机会，慢慢地我们就会安于现状不思进取，变成工作和生活中的平庸者甚至失败者。\u003c/p>\u003cp>【解决】固定型思维会给我们的工作、生活甚至人生都带来不良影响，那么我们应该如何改变才能让它有利于我们呢？今天我带来的《终身成长》这本书就给了我们答案。\u003c/p>\u003cp>这本书给我们分析了人的两种思维方式——固定型思维和成长型思维的特点、优劣以及利害，并且告诉了我们如何将固定型思维转变成成长型思维。通过今天的学习，我们可以学会改变固定思维，利用成长型思维，更好地达成人生和职业目标。\u003c/p>","ratings_count":1,"texts":[{"id":8666,"quote":"\u003cp>请想象一下，尽可能生动地去想，你是一个年轻人，经历了非常糟糕的一天:你去上一门对你来说很重要的课，而且你非常喜欢这门课。你的教授公布了期中考试成绩，你得了C＋。你非常失望，等到晚上准备回家的时候，你发现自己的车上贴了一张违章停车罚单。你感到非常泄气，打电话给最好的朋友想要倾诉，但是却没有打通。\u003c/p>\u003cp>你会怎么想？你会有什么样的感受？你会怎么做？\u003c/p>\u003cp>当我问固定型思维模式者时，他们是这样对我说的:“我感到被拒绝了。”“我是个失败者。”“我是个傻瓜\u003c/p>\u003cp>我感到自己很没用而且愚蠢——所有人都比我优秀。”“我太差劲了。”换句话说，他们会把发生的事当作一个衡量自己的能力和价值的直接的标尺。\u003c/p>\u003cp>他们会这样看待自己的生活:“我的人生太可悲了。”“我没有人生。”“楼上的那个人不喜欢我。”“这个世界跟我过不去。”“有人想要毁掉我。”“没有人爱我，所有人都恨我。“生活是不公平的，所有的努力都是白费。”“生活太糟糕了，我太傻了。”“我身上没发生过什么好事。”“我是地球上最不幸的人。”\u003c/p>\u003cp>可这是什么生死攸关的大事或者毁灭性的大灾难吗？还是只是个分数、一张罚单和一通不顺心的电话？\u003c/p>\u003cp>是这些人太自卑吗，还是说他们是实实在在的悲观主义者？不其实这些无法应对困难的人同样感到自己有价值，他们同样乐观觉得自己聪明而有吸引力，他们和那些有着成长型思维模式的人是一样的。\u003c/p>\u003cp>但他们是如何应对这些烦心事的呢？“我不应该浪费这么多时间和精力去办一件事。”（换句话说，不会再让任何人来评判我。）“什么都不做。”“待在床上。”“去喝酒。”“吃东西。”“找机会冲别人大吼。”“吃巧克力。”“边听音乐边郁闷。”“躲到壁橱里坐着。”“找人打一架。”“哭。”“摔东西。”“还能怎么办？”\u003c/p>\u003cp>还能怎么办！你知道，在模拟这个情景时候，我特意将成绩写成了C＋而不是F，只把考试设定成期中考试而不是期末考试，你的车只是被贴了罚单而不是被毁了，打电话给朋友倾诉之举只是没有成功，你并没有被朋友直接拒绝。没有什么灾难性或不可逆转的事情发生，但仅仅是在这些情况的影响下，固定型思维模式者就已经产生了这种彻底的失败感和无力感。\u003c/p>","explains":"\u003cp>\u003cstrong>【I】拆书家讲解引导\u003c/strong>\u003c/p>\u003cp>【概念混淆】\u003c/p>\u003cp>在这个拆页里，大家看到了两个相对的词：固定型思维模式和成长型思维模式。这两种思维模式之间有什么区别呢？\u003c/p>\u003cp>朋友晓莉认为人的才智能力、身份阶层都是天生的，怎么努力都改变不了；小六则认为人的智力水平不会永远处于一个水平线，也可以通过奋斗改变自己的阶层。大家认为他们哪个是固定型思维，哪个是成长型思维？ ——固定型思维认为才智能力天生注定，不可改变。\u003c/p>\u003cp>单位每次有比赛需要人参加，同事小波都说“我不去，你们谁想去谁去”，小胡面对各种比赛或者任务，总是很干脆的说“好的，我试试”。大家认为他们哪个是固定型思维，哪个是成长型思维？ ————固定型思维害怕接受挑战，尤其是自己没有十足把握的挑战。\u003c/p>\u003cp>亲戚家两个孩子，都在读高中，一个考试成绩一出来就特别关注成绩，考得好还好，考得不好就垂头丧气一蹶不振，还怪这怪那的，却不从自身找原因；另一个，相较成绩，他更关注自己为什么会错，并且会认真听老师讲，争取下次有进步。大家认为他们哪个是固定型思维，哪个是成长型思维？ ————固定型思维更关注成功而不是成长，抗挫折能力也更弱。\u003c/p>\u003cp>通过上述案例我们发现了固定型思维和成长型思维有三点区别：对自身的认识不一样、面对挑战的态度不一样、对待挫折的复原力不一样。（表格展示）\u003c/p>\u003cp>现在我们的心里应该对固定型思维有了一个大质的轮廓。固定型思维的核心就是人能力无法改变。具体说来就是，他们急于证明自己却又害怕风险和挑战，不愿（不屑）努力，他们认为挑战和努力会暴露自己的不足。失败的时候，他们会产生挫败感，对自己丧失信心，甚至会将一次的失败扩大到对自我的否定，对人生的否定，会将“失败从一种行为转变为一种身份”；成功时，他们会觉得自己高人一筹。\u003c/p>\u003cp>【案例澄清】\u003c/p>\u003cp>说一个我自己的案例。\u003c/p>\u003cp>去年单位要报名参评市教学能手。我们组长让我报名了，我也答应了。后来去教科室又问了一下这件事情，主任说现在只有你和XX两个人报名，你们先在学校PK一下，然后再上报。\u003c/p>\u003cp>听他这么说，我就决定放弃报名了。因为我和XX实力差不多，但是XX是领导，我觉得上面肯能会有偏向，我肯定只能当炮灰了，所以我就放弃了这次参评的机会。\u003c/p>\u003cp>因为结果的不确定性，因为害怕失败，害怕失败暴露不足，所以我放弃了一次非常好的锻炼自己的机会，这就是典型的固定型思维。\u003c/p>\u003cp>【正确理解及行动步骤】：\u003c/p>\u003cp>不同的思维方式对人的影响很大，无论是对待自己还是对待他人，无论是对待工作还是对待生活，无论是对待另一半还是教育孩子，不同的思维模式都会导致不同的行动，不同的结果。那么如何将固定型思维转变成成长型思维呢？\u003c/p>\u003cp>1.识别并接纳。识别并接受固定思维的存在，因为我们每个人都是两种思维的综合体。\u003c/p>\u003cp>2.观察根源及影响。观察你的固定型思维是如何产生的，对自己产生了什么样的影响。\u003c/p>\u003cp>3.命名时刻警醒自己。给固定型思维模式起一个让自己印象深刻的名字，你喜欢怎么称呼它就怎么称呼它。（命名是为了让它变得鲜活，让自己随时意识到脑中有这样一个小怪兽的存在）\u003c/p>\u003cp>4.教育并转变思维。最后告诉它自己希望的选择是什么，教育它用不同的方法去想问题，多想对自己有益的方面，带着它一起踏上成长型思维模式之旅。\u003c/p>\u003cp>【案例讲解关键点】：\u003c/p>\u003cp>如果应用这四个步骤，刚才情景中的我应该怎么做呢？\u003c/p>\u003cp>首先我发现自己是因为害怕失败，害怕暴露不足而放弃参评的决定【识别】，不过我会告诉自己有固定型思维的存在是很正常的现象【接受】，因为每一个人身上都会或多或少的有两种思维的影子。\u003c/p>\u003cp>然后观察是什么激发了我的固定型思维。原来是因为在学校会有两个人的PK赛，固定型思维对我说“你们两实力相当，而且他是学校中层，领导肯定会偏向他，所以你最终肯定是不能去参加比赛的，而且即使出去比赛，也未必能够成功。”因为我在生活中见过很多事情并不像表面那样的公平，所以我会觉得他比我多一层领导的身份，所以我肯定PK不过他，这才有了我的固定型思维。【根源】然后我就觉得既然花时间和精力去努力的结果可能只是当炮灰，不如不要努力了，不要白费力气了，所以我就决定放弃参评的资格。【影响】\u003c/p>\u003cp>我觉得这个固定思维太讨厌了，让我失去了一次机会，以后我就叫它捣蛋鬼。【命名】\u003c/p>\u003cp>我觉得我应该告诉他，我希望自己去参加一次这样的评比，我觉得可以换一个角度考虑问题：虽然有可能会失败，但是也有成功的机会啊，而且一旦成功对于我后面评高级是非常有利的；即使失败，也得到了一次锻炼和接受专家点评的机会，对于我后续的发展也是非常有利的。【教育并转变思维】\u003c/p>\u003cp>这样我就可以将固定型思维转变成成长型思维了，我就会带着勇气和期待去接受这次挑战了。\u003c/p>\u003cp>【适用边界】：\u003c/p>\u003cp>当我们觉得自己资质平平怎么努力都没有用的时候，当我们拒绝新事物新挑战害怕失败时，当我们面对挫折，不知道如何摆脱内心阻碍时，当我们遭遇失败责备他人或者找借口时，当我们获得成功自以为是觉得自己高人一筹时， 我们就可以反思是否是固定型思维限制了自己并且采用转换的四个步骤，把它转化成为成长型思维。\u003c/p>","interaction":"\u003cp>【拆书家提问设计】：\u003cbr>\u003c/p>\u003cp>听我讲了这么半天，下面请大家在自己脑中真正模拟下“将固定型思维转变为成长型思维”的过程，从而增强我们今后应用的能力。\u003c/p>\u003cp>怎么做呢？\u003c/p>\u003cp>以现实生活为基础，设计一个剧本，比如领导要让你接手你没有接触过的新工作啦，你的另一半因为项目失败而一蹶不振啦，你朋友觉得自己资质平平怎么努力都没有用啦，或者孩子学习小提琴，一段时间后因为越来越难就想放弃啦等等。\u003c/p>\u003cp>【要求】设计一组对话，可以是实体的我和内心的我的一段对话，也可以是你作为一个疏导者，对方是一个被疏导者的对话。要求运用到将固定型思维转变为成长型思维的4个步骤，让原本具有固定型思维的人能够改变思维，做出积极的行动。\u003c/p>\u003cp>【格式】\u003c/p>\u003cp>事情的起因：\u003c/p>\u003cp>主要人物：\u003c/p>\u003cp>具体对话：\u003c/p>\u003cp>结果/行动：\u003c/p>\u003cp>给大家5分钟，之后请小组来分享自己的剧本。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>采薇：起因是这样的，有一个小伙伴让我去给他们一个80人的团体做一个拆书课。我因为有点胆小，而且觉得自己预备的还不够充分，于是就拒绝了他。今天遇到莹莹，她就来引导我。莹莹说如果你总是这样的话，你的拆书技能能有精进吗？\u003c/p>\u003cp>我说哦，好像是不能。所以我发现我自己好像是有一个固定型思维。\u003c/p>\u003cp>接下来莹莹就问我，是否想精进。他问我，如果这样想，对你拆书有好处吗？我觉得好像确实没有什么好处。\u003c/p>\u003cp>他说你能给你的固定思维起一个名字吗？\u003c/p>\u003cp>我说可以呀，就叫胆小鬼吧。\u003c/p>\u003cp>他说，那你希望怎样做你的拆书，才能有一个更好的成长呢？我说，那还是立刻去准备预备表吧。这周我就会去花时间把这个预备表做起来。这就是我们的一个对话。\u003c/p>\u003cp>【适当点评】采薇转述的对话基本用到了我们刚刚分享的四个步骤，而且也得出了明确的行动方向。\u003c/p>\u003cp>【结束语】今天我们一起学会了如何识别固定型思维，并且在产生固定型思维的时候，能够通过四个步骤将它转变为成长型思维。将固定型思维转变为成长型思维是一个漫长的过程，希望大家在接下来的一个月，能够有意识的观察自己身上存在的固定型思维，坚持运用这四个步骤，将它转化为成长型思维，让自己更好的成长，成长为更好的自己。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1531190853000,"updated_at":1531191247000,"ria":true}]};